INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('dui-dwi', 'FL', '316.193', 'Driving Under the Influence', '2nd Degree Misdemeanor (first, no aggravators); 1st Degree Misdemeanor (BAC .15+ or minor present); 3rd Degree Felony (third within 10 years or fourth+)', NULL, '6 months (first); 9 months (BAC .15+/minor, first); 5 years (third within 10 yrs or fourth+)', '$1,000 (first); $2,000 (BAC .15+/minor); $5,000 (third/subsequent)', '{"Defendant drove or was in actual physical control of a vehicle","While driving, defendant was under the influence of alcoholic beverages, chemical substances, or controlled substances","Influence impaired defendant''s normal faculties, OR defendant had a BAC of .08 or higher"}', '8 hours imprisonment or community service (first offense); 10 days imprisonment if BAC .15+ or minor present', '{"BAC .15 or higher","Minor in vehicle","Third conviction within 10 years (3rd degree felony)","Fourth or subsequent conviction (3rd degree felony)","Serious bodily injury (3rd degree felony under § 316.193(3)(c)2)","Death resulting (DUI manslaughter — 2nd degree felony under § 316.193(3)(c)3)"}', 'Implied consent statute § 316.1932. Administrative license suspension separate from criminal penalties. Ignition interlock required for repeat offenses and first-offense BAC .15+.'),
  ('dui-first-offense', 'FL', '316.193(2)(a)', 'Driving Under the Influence — First Offense', '2nd Degree Misdemeanor', NULL, '6 months', '$1,000', '{"Defendant drove or was in actual physical control of a vehicle","While driving, defendant was under the influence of alcohol or controlled substances","Normal faculties impaired OR BAC .08 or higher","No prior DUI convictions"}', 'Not less than 8 hours imprisonment or community service; 50 hours community service', '{"BAC .15 or higher (9-month max, $2,000 fine)","Minor in vehicle (same enhancement)"}', 'Probation up to 1 year. Vehicle impoundment 10 days. 50 hours community service required. First offense is 2nd degree misdemeanor in FL absent aggravating factors.'),
  ('dui-repeat-offense', 'FL', '316.193(2)(b)', 'Driving Under the Influence — Repeat Offense', '1st Degree Misdemeanor (second); 3rd Degree Felony (third within 10 years or fourth+)', '10 days (second offense); 30 days (third within 10 years)', '9 months (second); 5 years (third within 10 years or fourth+)', '$2,000 (second); $5,000 (third/subsequent)', '{"Defendant drove or was in actual physical control of a vehicle","While driving, defendant was under the influence","Normal faculties impaired OR BAC .08 or higher","One or more prior DUI convictions"}', '10 days (second offense); 30 days (third within 10 years)', '{"Third conviction within 10 years (3rd degree felony mandatory)","Fourth conviction regardless of time (3rd degree felony)","Prior DUI manslaughter (permanent revocation)"}', 'Mandatory ignition interlock 1 year on second offense; 2 years if BAC .15+. Permanent license revocation possible for fourth or subsequent.'),
  ('dui-drugs', 'FL', '316.193(1)(b)', 'DUI — Chemical or Controlled Substance', '2nd Degree Misdemeanor (first offense); escalates same as alcohol DUI', NULL, '6 months (first); same escalation as alcohol DUI on subsequent offenses', '$1,000', '{"Defendant drove or was in actual physical control of a vehicle","While driving, defendant was under the influence of a chemical substance listed in § 877.111 or a controlled substance under Chapter 893","Influence impaired defendant''s normal faculties"}', NULL, '{"Prescription drugs taken outside prescribed manner","Multiple substances combined","Prior DUI conviction"}', 'Florida has no per se drug impairment limit. Prosecution must prove impairment of normal faculties. Drug Recognition Expert (DRE) testimony commonly used. DREC evaluation results admissible.'),
  ('reckless-driving', 'FL', '316.192', 'Reckless Driving', '2nd Degree Misdemeanor (no injury/damage); 1st Degree Misdemeanor (with property damage/personal injury)', NULL, '90 days (first, no injury); 6 months (second+ or with damage); 5 years (serious bodily injury — 3rd degree felony)', '$500 (first); $1,000 (second+); $5,000 (serious bodily injury)', '{"Defendant drove a vehicle in Florida","Defendant drove with willful or wanton disregard for the safety of persons or property"}', NULL, '{"Property damage or personal injury (1st degree misdemeanor)","Serious bodily injury (3rd degree felony)","Second or subsequent conviction ($1,000 minimum fine)"}', 'Willful and wanton disregard is a higher standard than mere negligence. Commonly charged alongside or as lesser-included of DUI. Racing on public roads is a separate offense under § 316.191.'),
  ('hit-and-run', 'FL', '316.061 / 316.027', 'Leaving the Scene of a Crash', '2nd Degree Misdemeanor (property damage only); 3rd Degree Felony (injury); 2nd Degree Felony (serious bodily injury); 1st Degree Felony (death)', NULL, '60 days (property); 5 years (injury); 15 years (serious bodily injury); 30 years (death)', '$500; $5,000; $10,000; $10,000', '{"Defendant was the driver of a vehicle involved in a crash","The crash resulted in property damage, injury, or death","Defendant knew or reasonably should have known of the crash","Defendant willfully failed to stop and remain at the scene or provide required information"}', '4 years (death — § 316.027(2)(c))', '{"Serious bodily injury (2nd degree felony)","Death (1st degree felony, 4-year mandatory minimum)","Prior conviction"}', '§ 316.027 governs crashes with injury/death; § 316.061 governs property-only crashes. Mandatory 4-year minimum for death with failure to stop under § 316.027(2)(c).'),
  ('vehicular-homicide', 'FL', '782.071', 'Vehicular Homicide', '2nd Degree Felony; 1st Degree Felony (failure to stop and render aid)', NULL, '15 years (2nd degree); 30 years (with failure to stop)', '$10,000', '{"Defendant operated a motor vehicle","The operation caused the death of a human being or viable fetus","Operation was reckless — showing conscious disregard for the safety of others"}', NULL, '{"Failure to stop and render aid (upgrades to 1st degree felony)","Multiple victims","Prior convictions"}', 'Distinguished from DUI manslaughter (§ 316.193(3)) — vehicular homicide does not require alcohol/drug impairment as a primary element. Both can be charged for the same incident.'),
  ('vehicular-manslaughter', 'FL', '316.193(3)(c)3', 'DUI Manslaughter', '2nd Degree Felony; 1st Degree Felony (leaving scene)', '4 years (mandatory minimum)', '15 years (2nd degree); 30 years (1st degree)', '$10,000', '{"Defendant operated a motor vehicle while under the influence","Operation caused the death of a human being or viable unborn child"}', '4 years (§ 775.082); permanent driver license revocation', '{"Leaving scene (1st degree felony, 30-year max)","BAC .15 or higher","Prior DUI conviction"}', 'Level 8 offense under Florida''s Criminal Punishment Code — state prison presumptive. Mandatory 4-year minimum cannot be suspended. Permanent revocation of driver''s license.'),
  ('driving-on-suspended', 'FL', '322.34', 'Driving While License Suspended, Revoked, or Cancelled', '2nd Degree Misdemeanor (first); 1st Degree Misdemeanor (second); 3rd Degree Felony (HTO or third+)', NULL, '60 days (first); 1 year (second); 5 years (HTO/third+)', '$500; $1,000; $5,000', '{"Defendant drove a motor vehicle on a public road or highway","Defendant''s license or driving privilege was suspended, revoked, or cancelled","Defendant had knowledge of the suspension (or constructive notice via mail)"}', NULL, '{"Habitual Traffic Offender (HTO) designation — 3rd degree felony","Suspension for DUI (elevated penalties)","Prior conviction within 5 years"}', 'HTO under § 322.264 requires 3+ major violations within 5 years. Knowledge established by proof DMV sent suspension notice. Civil citation available for some violations.'),
  ('fleeing-eluding', 'FL', '316.1935', 'Fleeing or Attempting to Elude a Law Enforcement Officer', '3rd Degree Felony (basic); 2nd Degree Felony (high speed/reckless); 1st Degree Felony (serious bodily injury or death)', NULL, '5 years (basic); 15 years (high speed); 30 years (injury/death)', '$5,000', '{"Defendant was the operator of a motor vehicle","A law enforcement officer in an authorized patrol vehicle with visible emergency lights and siren activated ordered defendant to stop","Defendant willfully fled or attempted to elude the officer"}', '3 years (§ 316.1935(4) — high-speed fleeing causing serious injury or death)', '{"High speed or reckless driving (2nd degree felony)","Serious bodily injury resulting (2nd degree felony)","Death resulting (1st degree felony)"}', 'Both siren and lights must be activated. Mandatory 3-year minimum for high-speed fleeing causing serious injury. License revocation mandatory.'),
  ('open-container', 'FL', '316.1936', 'Possession of Open Container of Alcoholic Beverage in Vehicle', '2nd Degree Misdemeanor', NULL, '60 days', '$500', '{"Defendant was the operator or passenger of a vehicle on a public highway","A container of alcoholic beverage with broken seal, missing cap, or partially removed contents was in the passenger area","Defendant possessed the open container"}', NULL, '{}', 'Trunk, locked glove box, or behind last upright rear seat in vehicles without trunks are exceptions. Civil infraction option for passengers in some circumstances.'),
  ('refusing-breath-test', 'FL', '316.1932', 'Implied Consent — Refusal to Submit to Test', 'Civil infraction (first); 1st Degree Misdemeanor (second or subsequent refusal)', NULL, '1 year (criminal second refusal)', '$1,000', '{"Defendant was lawfully arrested for DUI","Officer requested defendant submit to breath, blood, or urine test","Defendant was informed of consequences of refusal","Defendant refused to submit"}', NULL, '{"Second or subsequent refusal (1st degree misdemeanor criminal charge)","Commercial vehicle refusal"}', 'First refusal: 12-month administrative license suspension. Second refusal: 18-month administrative suspension PLUS 1st degree misdemeanor. Refusal admissible as evidence of consciousness of guilt.'),
  ('drug-possession', 'FL', '893.13(6)(a)', 'Possession of Controlled Substance', '1st Degree Misdemeanor (Schedule III-IV small amount); 3rd Degree Felony (Schedule I-II)', NULL, '1 year (misdemeanor); 5 years (3rd degree felony)', '$1,000; $5,000', '{"Defendant knew of the presence of the substance","Defendant had actual or constructive possession","The substance was a controlled substance under Chapter 893"}', NULL, '{"Within 1,000 feet of school, park, or other protected location (§ 893.13(1)(c)) — 1st degree felony","Within 200 feet of public housing","Amount triggering trafficking threshold (§ 893.135)"}', 'Florida eliminated knowledge-of-illicit-nature element (§ 893.101). Knowledge of presence sufficient. Drug Court available for eligible defendants.'),
  ('drug-possession-marijuana', 'FL', '893.13(6)(b)', 'Possession of Cannabis', '1st Degree Misdemeanor (20 grams or less); 3rd Degree Felony (more than 20 grams)', NULL, '1 year (20g or less); 5 years (over 20g)', '$1,000; $5,000', '{"Defendant knew of the presence of the cannabis","Defendant had actual or constructive possession","Substance was cannabis as defined in § 893.02"}', NULL, '{"More than 20 grams (felony threshold)","Within 1,000 feet of school","25+ lbs triggers trafficking (§ 893.135)"}', 'Medical marijuana defense available under Art. X, § 29 and § 381.986 for licensed holders. Recreational marijuana remained illegal (Amendment 3 failed Nov 2024). Many counties have civil citation ordinances for small amounts.'),
  ('drug-possession-cocaine', 'FL', '893.13(6)(a)', 'Possession of Cocaine', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant knew of the presence of cocaine","Defendant had actual or constructive possession","Substance was cocaine — Schedule II under § 893.03"}', '3 years (if 28 grams — trafficking threshold under § 893.135)', '{"28g+ trafficking (3-year mandatory minimum)","200g+ (7-year mandatory minimum)","400g+ (15-year mandatory minimum)","Within 1,000 feet of school (2nd degree felony)"}', 'Cocaine is Schedule II. Simple possession under 28g is 3rd degree felony. Lab confirmation required. Chain of custody is a critical defense issue.'),
  ('drug-possession-meth', 'FL', '893.13(6)(a)', 'Possession of Methamphetamine', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant knew of the presence of methamphetamine","Defendant had actual or constructive possession","Substance was methamphetamine — Schedule II"}', '3 years (14 grams trafficking threshold under § 893.135(1)(d))', '{"14g+ trafficking (3-year mandatory minimum)","28g+ (7-year mandatory minimum)","200g+ (15-year mandatory minimum)","Within 1,000 feet of school"}', 'Meth trafficking thresholds lower than cocaine. Prior drug conviction can trigger habitual offender sentencing.'),
  ('drug-possession-opioids', 'FL', '893.13(6)(a)', 'Possession of Heroin, Fentanyl, or Opioids', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant knew of the presence of the opioid substance","Defendant had actual or constructive possession","Substance was a Schedule I or II opioid (heroin, fentanyl, oxycodone, etc.)"}', '3 years (4 grams fentanyl/heroin trafficking under § 893.135)', '{"Fentanyl 4g+ trafficking (3-year mandatory minimum)","14g+ (7-year minimum)","28g+ (15-year minimum)","Fentanyl causing death (1st degree murder per § 782.04(1)(a)2.z — 2023 law)","Within 1,000 feet of school"}', '2023 law: delivering fentanyl that causes death can be charged as 1st degree murder. Fentanyl and fentanyl analogs share the 4-gram trafficking threshold. Heroin threshold is also 4 grams.'),
  ('drug-possession-prescription', 'FL', '893.13(7)(a)1', 'Possession of Prescription Drug Without Valid Prescription', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant possessed a prescription drug","Defendant did not have a valid prescription from a licensed practitioner","OR Defendant obtained the prescription by fraud, misrepresentation, or deception"}', NULL, '{"Doctor shopping (multiple prescriptions from different practitioners)","Large quantity","Distribution or sale"}', 'Valid prescription is an affirmative defense. Pill bottle with someone else''s name does not establish a valid prescription for the defendant.'),
  ('drug-trafficking', 'FL', '893.135', 'Drug Trafficking', '1st Degree Felony', '3 years (minimum varies by substance and amount)', 'Life (certain substances/amounts)', '$500,000', '{"Defendant knowingly sold, purchased, manufactured, delivered, or brought into Florida, or was in actual or constructive possession of a controlled substance","The quantity met or exceeded the trafficking threshold for that substance"}', '3 years (cocaine 28g, heroin/fentanyl 4g, meth 14g, cannabis 25 lbs); escalates to 7, 15, 25 years, or life based on quantity', '{"Highest quantity tier (capital trafficking — life or 25-year minimum)","Use of minor in trafficking","Near school","Substantial assistance cooperation (§ 893.135(4)) — only way to mitigate mandatory minimum"}', 'Mandatory minimums cannot be suspended, deferred, or withheld. Knowledge of illicit nature is NOT an element per § 893.101. Substantial assistance is the primary mitigation route.'),
  ('drug-distribution', 'FL', '893.13(1)(a)', 'Sale, Manufacture, or Delivery of Controlled Substance', '2nd Degree Felony (Schedule I-II); 3rd Degree Felony (Schedule III-IV)', NULL, '15 years (Schedule I-II); 5 years (Schedule III-IV)', '$10,000', '{"Defendant sold, manufactured, or delivered a controlled substance","OR Defendant possessed a controlled substance with intent to sell, manufacture, or deliver","Substance was a controlled substance under Chapter 893"}', NULL, '{"Within 1,000 feet of school, park, or playground (1st degree felony)","Within 1,000 feet of place of worship (1st degree felony)","Sale to minor (1st degree felony)","Within 200 feet of public housing"}', 'Location-enhanced charges carry significantly higher penalties. Constructive possession plus indicia (scales, bags, cash, messages) supports intent charge.'),
  ('drug-manufacturing', 'FL', '893.13(1)(a)', 'Manufacturing Controlled Substance', '2nd Degree Felony (Schedule I-II); 3rd Degree Felony (Schedule III-IV)', NULL, '15 years', '$10,000', '{"Defendant manufactured a controlled substance","Substance was a controlled substance under Chapter 893","Defendant acted knowingly"}', NULL, '{"Meth lab with child present","Use of hazardous waste","Fire or explosion resulting"}', 'Manufacturing includes production, preparation, propagation, compounding, or processing. Marijuana cultivation included. Meth lab contamination may implicate additional environmental liability.'),
  ('drug-paraphernalia', 'FL', '893.147', 'Use or Possession of Drug Paraphernalia', '1st Degree Misdemeanor', NULL, '1 year', '$1,000', '{"Defendant used or possessed with intent to use drug paraphernalia","Paraphernalia was used or intended to be used in connection with a controlled substance","Defendant acted knowingly"}', NULL, '{"Sale to minor (3rd degree felony)","Manufacture or distribution (3rd degree felony)"}', 'Paraphernalia defined broadly in § 893.145 — pipes, syringes, rolling papers, scales. Intent inferred from proximity to drugs, residue, and statements.'),
  ('prescription-fraud', 'FL', '831.02', 'Uttering a Forged Prescription', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant uttered, published, or passed a forged prescription","Defendant knew the prescription was forged","Defendant acted with intent to injure or defraud"}', NULL, '{"Multiple forged prescriptions (each counts separately)","Doctor shopping in combination","Opioid prescriptions"}', 'Also prosecuted under § 893.13(7)(a) for obtaining controlled substance by fraud. Both charges often filed simultaneously. Pharmacy surveillance footage commonly used.'),
  ('drug-possession-with-intent', 'FL', '893.13(1)(a)2', 'Possession with Intent to Sell or Deliver', '2nd Degree Felony (Schedule I-II); 3rd Degree Felony (Schedule III-V)', NULL, '15 years (Schedule I-II); 5 years (Schedule III-V)', '$10,000', '{"Defendant possessed a controlled substance","Defendant possessed with specific intent to sell or deliver","Substance was a controlled substance under Chapter 893"}', NULL, '{"Near school/park/church (1st degree felony)","Large quantity","Packaging in individual units"}', 'Intent proven circumstantially through quantity, packaging, scales, cash, and text messages. Actual sale need not be proven.'),
  ('murder-first-degree', 'FL', '782.04(1)', 'Murder in the First Degree', 'Capital Felony; Life Felony', 'Life without parole (if death penalty not sought)', 'Death', NULL, '{"Defendant unlawfully killed a human being","The killing was premeditated (prior deliberation and reflection), OR","The killing occurred during perpetration or attempted perpetration of an enumerated felony (felony murder)"}', 'Life without possibility of parole', '{"Law enforcement officer victim","Multiple victims","Heinous, atrocious, or cruel manner","Prior capital felony conviction","Victim under 12","Hate crime motivation","Drug-induced homicide (fentanyl) added 2023"}', 'Post-Hurst v. Florida (2016) — jury must unanimously recommend death. Felony murder predicate felonies listed in § 782.04(1)(a)2. Fentanyl-induced death added as predicate 2023.'),
  ('murder-second-degree', 'FL', '782.04(2)', 'Murder in the Second Degree', '1st Degree Felony (Punishable by Life)', NULL, 'Life', NULL, '{"Defendant unlawfully killed a human being","The killing was by an act imminently dangerous to another evincing a depraved mind","Defendant had no premeditated design to cause death"}', '16.75 years (Criminal Punishment Code Level 10 scoresheet)', '{"Firearm possession (10-20-Life — § 775.087)","Discharge of firearm (20-year mandatory minimum)","Death by firearm (25-year mandatory minimum)","Victim under 18"}', 'Depraved mind murder requires conduct that was extremely dangerous and showed no regard for human life. Less culpable mental state than 1st degree but often charged together as alternative counts.'),
  ('voluntary-manslaughter', 'FL', '782.07', 'Manslaughter', '2nd Degree Felony', NULL, '15 years', '$10,000', '{"Defendant killed a human being","Killing was the result of culpable negligence, OR","Killing occurred in sudden heat of passion resulting from adequate provocation"}', NULL, '{"Firearm use (10-20-Life)","Victim under 18 (aggravated manslaughter — 1st degree felony)","Victim elderly or disabled (aggravated manslaughter)","Law enforcement officer victim (aggravated manslaughter)"}', 'Aggravated manslaughter provisions in § 782.07(2)-(4) carry 30-year maximum. Florida treats voluntary and involuntary manslaughter under same statute.'),
  ('involuntary-manslaughter', 'FL', '782.07', 'Manslaughter by Culpable Negligence', '2nd Degree Felony', NULL, '15 years', '$10,000', '{"Defendant killed a human being","Death resulted from defendant''s culpable negligence","Culpable negligence is gross and flagrant, showing reckless disregard for human life"}', NULL, '{"Victim under 18 (aggravated manslaughter of a child — 1st degree felony)","Victim elderly or disabled","Law enforcement officer"}', 'Culpable negligence standard is higher than civil negligence — more than simple carelessness. Child abuse resulting in death typically charged as aggravated manslaughter of a child.'),
  ('aggravated-assault', 'FL', '784.021', 'Aggravated Assault', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant intentionally and unlawfully threatened by word or act to do violence to the victim","Defendant appeared to have the ability to carry out the threat","The act created a well-founded fear in the victim that violence was imminent","The assault was made with a deadly weapon without intent to kill, OR with intent to commit a felony"}', '3 years (10-20-Life if firearm carried); 20 years (firearm discharged)', '{"10-20-Life firearm enhancement","Victim is law enforcement (2nd degree felony)","Victim under 12 (1st degree felony)","Hate crime designation"}', 'Assault in Florida requires NO physical contact — it is the threat plus reasonable fear. Battery (§ 784.03) requires actual contact.'),
  ('simple-assault', 'FL', '784.011', 'Assault', '2nd Degree Misdemeanor', NULL, '60 days', '$500', '{"Defendant intentionally and unlawfully threatened by word or act to do violence to the victim","Defendant appeared to have the ability to carry out the threat","The act created a well-founded fear in the victim that violence was imminent"}', NULL, '{"Victim is law enforcement (felony upgrade)","Use of weapon (elevates to aggravated assault)"}', 'Simple assault requires no physical contact — purely threat-based. Often filed with disorderly conduct.'),
  ('battery', 'FL', '784.03', 'Battery', '1st Degree Misdemeanor', NULL, '1 year', '$1,000', '{"Defendant actually and intentionally touched or struck the victim against the victim''s will","OR Defendant intentionally caused bodily harm to the victim"}', NULL, '{"Prior battery conviction (felony battery — 3rd degree felony)","Victim is law enforcement, firefighter, healthcare worker (felony battery)","Strangulation (§ 784.041 — 3rd degree felony)","Victim pregnant or elderly"}', 'Battery requires actual physical contact; assault does not. Domestic battery (§ 741.028) requires mandatory arrest. Prior battery conviction raises to 3rd degree felony.'),
  ('aggravated-battery', 'FL', '784.045', 'Aggravated Battery', '2nd Degree Felony', NULL, '15 years', '$10,000', '{"Defendant intentionally touched or struck the victim","Defendant intentionally or knowingly caused great bodily harm, permanent disability, or permanent disfigurement","OR Defendant used a deadly weapon during the battery"}', '10 years (§ 775.087 10-20-Life if firearm used)', '{"10-20-Life firearm enhancement","Victim is law enforcement (1st degree felony)","Victim elderly or disabled (1st degree felony — § 784.08)","Victim pregnant","Hate crime"}', 'Great bodily harm is a higher standard than bodily harm. Aggravated battery on pregnant woman is 1st degree felony under § 784.045(1)(b).'),
  ('robbery', 'FL', '812.13', 'Robbery', '2nd Degree Felony (no weapon); 1st Degree Felony (weapon); Life Felony (firearm or deadly weapon)', NULL, '15 years (no weapon); 30 years (with weapon); Life (firearm/deadly weapon)', '$10,000', '{"Defendant took money or other property from the victim or victim''s custody","Defendant used force, violence, assault, or putting in fear","Defendant intended to permanently or temporarily deprive the victim of the property"}', '10 years (10-20-Life if firearm carried)', '{"10-20-Life firearm enhancement","Victim elderly or disabled","Home invasion robbery (1st degree felony — § 812.135)","Multiple victims"}', 'Home invasion robbery (§ 812.135) is a 1st degree felony with potential life sentence. Carjacking (§ 812.133) is a separate charge.'),
  ('armed-robbery', 'FL', '812.13(2)(a)', 'Robbery with a Firearm or Deadly Weapon', 'Life Felony', '10 years (10-20-Life)', 'Life', '$15,000', '{"Defendant took money or other property from the victim","Defendant used force, violence, assault, or putting in fear","Defendant carried a firearm or other deadly weapon during the robbery"}', '10 years (§ 775.087); 20 years if firearm discharged; 25 years if death or serious bodily injury', '{"Firearm discharged (20-year mandatory minimum)","Death or serious bodily injury (25-year mandatory minimum)","Multiple victims","Mask worn"}', 'Life felony — maximum life imprisonment. 10-20-Life mandatory minimums cannot be suspended. Firearm need not be loaded or functional for enhancement to apply.'),
  ('kidnapping', 'FL', '787.01', 'Kidnapping', '1st Degree Felony (Punishable by Life)', NULL, 'Life', NULL, '{"Defendant forcibly, secretly, or by threat confined, abducted, imprisoned, or restrained the victim against his or her will","Defendant did so without lawful authority","Defendant intended to: hold for ransom, use as shield/hostage, commit or facilitate a felony, inflict bodily harm, terrorize, or interfere with government functions"}', 'Life if victim under 13 and defendant also convicted of sexual battery', '{"Victim under 13 (life felony; capital if sexual battery also charged)","Firearm use (10-20-Life)","Victim law enforcement"}', 'False imprisonment (§ 787.02) is the lesser offense without the felony-intent requirement. Movement must be more than incidental to separate kidnapping from false imprisonment.'),
  ('arson', 'FL', '806.01', 'Arson', '1st Degree Felony (occupied structure or dwelling); 2nd Degree Felony (unoccupied structure)', NULL, '30 years (1st degree); 15 years (2nd degree)', '$10,000', '{"Defendant willfully and unlawfully, or while committing a felony, by fire or explosion","Damaged or caused to be damaged any dwelling, structure, or vehicle","With intent or while the damage was intentional"}', NULL, '{"Occupied dwelling (1st degree felony)","Death resulting (murder charge)","Firefighter injured","Insurance fraud motivation"}', '§ 806.01(1) — 1st degree felony for occupied structure or any dwelling. § 806.01(2) — 2nd degree felony for unoccupied structure.'),
  ('attempted-murder', 'FL', '777.04; 782.04', 'Attempted First or Second Degree Murder', '1st Degree Felony (attempt 1st degree); Life Felony (with firearm)', NULL, '30 years (1st degree attempt); Life (with firearm)', '$10,000', '{"Defendant attempted to commit first or second degree murder","Defendant had premeditated intent to kill (for attempted 1st degree)","Defendant committed an overt act toward commission of the murder"}', '10 years (10-20-Life if firearm used)', '{"10-20-Life firearm enhancement","Victim is law enforcement","Multiple victims targeted","Hate crime"}', 'Attempt statute § 777.04. Attempted 2nd degree charged when premeditation absent. Attempted murder of law enforcement carries enhanced penalties.'),
  ('assault-with-deadly-weapon', 'FL', '784.021(1)(a)', 'Aggravated Assault with a Deadly Weapon', '3rd Degree Felony', '3 years (if firearm — 10-20-Life)', '5 years; 20 years if firearm discharged', '$5,000', '{"Defendant intentionally threatened to do violence to the victim","Defendant appeared to have the ability to carry out the threat","Threat created well-founded fear in the victim","Defendant used a deadly weapon without intent to kill"}', '3 years minimum (firearm carried); 20 years (firearm discharged)', '{"10-20-Life firearm enhancement","Victim is law enforcement (2nd degree felony)","Victim under 12"}', 'No actual contact required — assault is threat-based in Florida. Deadly weapon includes knife, bat, vehicle, or any object used to threaten death or great bodily harm.'),
  ('theft-larceny', 'FL', '812.014', 'Theft', '2nd Degree Misdemeanor (under $100); 1st Degree Misdemeanor ($100-$749); 3rd Degree Felony ($750-$19,999); 2nd Degree Felony ($20,000-$99,999); 1st Degree Felony ($100,000+)', NULL, '60 days; 1 year; 5 years; 15 years; 30 years', '$500; $1,000; $5,000; $10,000; $10,000', '{"Defendant knowingly obtained or used, or endeavored to obtain or use, the property of another","Defendant intended to temporarily or permanently deprive the owner of a right to the property or a benefit from it","OR Defendant appropriated the property to his or her own use or to a person not entitled to the use"}', NULL, '{"Prior theft conviction (escalates charge level)","Theft from elderly person (§ 812.0145)","Emergency equipment (1st degree felony regardless of value)","Grand theft of law enforcement equipment"}', 'Florida raised felony threshold from $300 to $750 in 2019. Second petit theft conviction = 3rd degree felony. Restitution available. Civil demand allowed for shoplifting under § 772.11.'),
  ('grand-theft', 'FL', '812.014(2)', 'Grand Theft', '3rd Degree Felony ($750-$19,999); 2nd Degree Felony ($20,000-$99,999); 1st Degree Felony ($100,000+)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; $10,000', '{"Defendant knowingly obtained or used property of another","With intent to deprive the owner of the property","Value of property was $750 or more"}', NULL, '{"Theft from elderly (mandatory restitution + enhanced penalties)","Motor vehicle (§ 812.014(2)(c)5 — automatic grand theft)","Emergency equipment (1st degree felony regardless of value)"}', 'Special categories regardless of value: firearm, law enforcement badge, stop sign, will, vehicle with person inside. Cargo theft under § 812.019.'),
  ('petty-theft', 'FL', '812.014(3)', 'Petit Theft', '2nd Degree Misdemeanor (under $100); 1st Degree Misdemeanor ($100-$749)', NULL, '60 days; 1 year', '$500; $1,000', '{"Defendant knowingly obtained or used property of another","With intent to deprive the owner","Value of property was under $750"}', NULL, '{"Prior theft conviction escalates charge level","Two prior petit theft convictions = 3rd degree felony"}', 'Third petit theft offense becomes 3rd degree felony. Civil demand letters from merchants allowed under § 772.11.'),
  ('shoplifting', 'FL', '812.015', 'Retail Theft', '2nd Degree Misdemeanor (under $100); 1st Degree Misdemeanor ($100-$749); 3rd Degree Felony ($750+ or prior conviction)', NULL, '60 days; 1 year; 5 years', '$500; $1,000; $5,000', '{"Defendant took possession of or carried away merchandise","OR Defendant altered/removed a price tag, transferred merchandise, or removed a shopping cart","Defendant intended to deprive the merchant of possession or full retail value"}', NULL, '{"Organized retail theft (§ 812.015(8)) — 2nd degree felony","Value $750+ (grand theft rules apply)","Use of booster bag or demagnetizing device"}', 'Merchant detention privilege under § 812.015(3). Organized retail theft ring (3+ people, multiple stores) is 2nd degree felony.'),
  ('burglary', 'FL', '810.02', 'Burglary', '3rd Degree Felony (unoccupied structure/conveyance); 2nd Degree Felony (occupied structure or dwelling); 1st Degree Felony (armed or assault/battery during)', NULL, '5 years (3rd); 15 years (2nd); 30 years / Life (1st)', '$5,000; $10,000; $15,000', '{"Defendant entered a dwelling, structure, or conveyance","At the time of entering, defendant had intent to commit an offense therein","AND defendant entered without permission OR remained after permission was withdrawn"}', NULL, '{"Occupied at time of entry (2nd degree felony minimum)","Armed during burglary (1st degree felony)","Assault or battery during (1st degree felony — life eligible)","Prior burglary conviction"}', 'Burglary in Florida does not require nighttime or breaking — any unlawful entry with criminal intent. Remaining concealed in structure also qualifies.'),
  ('residential-burglary', 'FL', '810.02(3)(a)', 'Burglary of a Dwelling', '2nd Degree Felony (unoccupied); 1st Degree Felony (occupied or assault/battery inside)', NULL, '15 years (2nd); 30 years (1st)', '$10,000', '{"Defendant entered or remained in a dwelling","Entry was without permission or consent","Defendant intended to commit an offense inside the dwelling"}', NULL, '{"Occupied at time of entry (1st degree felony)","Armed entry (1st degree felony)","Assault or battery inside (life felony)"}', 'Dwelling means any building actually used as a place of abode. Attached garage and curtilage qualify.'),
  ('commercial-burglary', 'FL', '810.02(3)(b)', 'Burglary of a Structure', '3rd Degree Felony (unoccupied); 2nd Degree Felony (occupied or assault/battery)', NULL, '5 years (3rd); 15 years (2nd)', '$5,000; $10,000', '{"Defendant entered or remained in a structure (not a dwelling)","Without permission or consent","Defendant intended to commit an offense inside"}', NULL, '{"Structure occupied at time of entry (2nd degree felony)","Armed entry","Prior burglary"}', 'Structure means any building that is not a dwelling (stores, warehouses, schools). Burglary of a conveyance (car) — separate 3rd degree felony.'),
  ('motor-vehicle-theft', 'FL', '812.014(2)(c)5', 'Grand Theft of a Motor Vehicle', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant knowingly obtained or used a motor vehicle belonging to another","Defendant intended to permanently or temporarily deprive the owner","The vehicle was a motor vehicle (all qualify — no value threshold)"}', NULL, '{"Organized scheme to defraud (§ 812.019)","Carjacking — force or violence (§ 812.133 — life felony)"}', 'Motor vehicle theft is automatically grand theft (3rd degree felony) regardless of value. Carjacking (§ 812.133) requires force or violence — 1st degree felony (life eligible with firearm).'),
  ('receiving-stolen-property', 'FL', '812.019', 'Dealing in Stolen Property', '2nd Degree Felony (trafficking); 3rd Degree Felony (dealing)', NULL, '15 years (trafficking); 5 years (dealing)', '$10,000', '{"Defendant trafficked in, or endeavored to traffic in, property that defendant knew or should have known was stolen","OR Defendant received, retained, concealed, or withheld from the true owner stolen property"}', NULL, '{"Organizer or supervisor of trafficking ring (1st degree felony)","Prior conviction","Electronic equipment"}', '§ 812.025 prohibits charging both theft and dealing in stolen property from the same transaction. ''Should have known'' standard allows circumstantial evidence of knowledge.'),
  ('vandalism', 'FL', '806.13', 'Criminal Mischief', '2nd Degree Misdemeanor (under $200); 1st Degree Misdemeanor ($200-$999); 3rd Degree Felony ($1,000+)', NULL, '60 days; 1 year; 5 years', '$500; $1,000; $5,000', '{"Defendant willfully and maliciously injured or damaged real or personal property belonging to another","Defendant had no right to damage the property"}', NULL, '{"Religious property damage $1,000+ (2nd degree felony)","Graffiti on school property","Damage to utility or communications equipment"}', 'Restitution is mandatory. Value is replacement or repair cost.'),
  ('trespassing', 'FL', '810.08', 'Trespass in Structure or Conveyance', '2nd Degree Misdemeanor (without warning); 1st Degree Misdemeanor (after warning); 3rd Degree Felony (with weapon)', NULL, '60 days; 1 year; 5 years', '$500; $1,000; $5,000', '{"Defendant willfully entered or remained in a structure or conveyance","Defendant was not authorized, licensed, or invited","OR Defendant remained after permission was withdrawn"}', NULL, '{"Armed with dangerous weapon (3rd degree felony)","School grounds during school hours (3rd degree felony)","Prior conviction"}', 'Trespass in a structure (§ 810.08) vs. trespass on property (§ 810.09) are separate charges. School trespass during hours is automatic 3rd degree felony.'),
  ('criminal-mischief', 'FL', '806.13', 'Criminal Mischief', '2nd Degree Misdemeanor (under $200); 1st Degree Misdemeanor ($200-$999); 3rd Degree Felony ($1,000+)', NULL, '60 days; 1 year; 5 years', '$500; $1,000; $5,000', '{"Defendant willfully and maliciously injured or damaged real or personal property belonging to another","Defendant had no legal right to damage the property"}', NULL, '{"Religious property (elevated to 2nd degree felony)","Graffiti on school property","Damage to utility or communications equipment"}', 'Florida uses ''criminal mischief'' not ''vandalism.'' Restitution mandatory. Graffiti specifically addressed in § 806.13(3).'),
  ('domestic-violence', 'FL', '741.28; 741.283', 'Domestic Violence', '1st Degree Misdemeanor minimum (domestic battery); escalates with underlying charge', '5 days county jail (if great bodily harm inflicted or prior DV conviction)', 'Depends on underlying charge', 'Depends on underlying charge', '{"Defendant committed assault, aggravated assault, battery, aggravated battery, sexual assault, stalking, kidnapping, false imprisonment, or any offense resulting in physical injury or death","The victim is a family or household member as defined in § 741.28"}', '5 days county jail if great bodily harm inflicted, deadly weapon used/threatened, or prior DV conviction', '{"Child present during incident (mandatory BIP counseling)","Prior domestic violence conviction (mandatory 5-day jail minimum)","Violation of injunction (separate criminal charge)"}', 'Mandatory arrest in Florida (§ 741.2901) — officer must arrest if probable cause exists regardless of victim''s wishes. No-contact order automatic upon arrest. Prosecutor can proceed without victim cooperation.'),
  ('domestic-battery', 'FL', '784.03; 741.283', 'Domestic Battery', '1st Degree Misdemeanor', '5 days county jail (great bodily harm or prior DV conviction)', '1 year', '$1,000', '{"Defendant actually and intentionally touched or struck the victim against the victim''s will","OR Defendant intentionally caused bodily harm","Victim is a family or household member (spouse, former spouse, cohabitant, parent of common child)"}', '5 days county jail minimum when great bodily harm inflicted or prior DV conviction', '{"Aggravated domestic battery (2nd degree felony)","Strangulation (§ 784.041 — 3rd degree felony)","Child present","Violation of injunction"}', 'Strangulation during domestic battery is a separate felony under § 784.041. First offense diversion programs available in some counties.'),
  ('child-endangerment', 'FL', '827.03(2)(d)', 'Negligent Treatment or Maltreatment of a Child', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant is a caregiver for a child under 18","Defendant willfully or negligently failed to provide care, supervision, or services to maintain child''s mental or physical health","OR Defendant failed to protect the child from abuse or exploitation"}', NULL, '{"Great bodily harm (2nd degree felony)","Permanent disability (2nd degree felony)","Death resulting (1st degree felony)"}', '§ 827.03 is Florida''s child abuse and neglect statute. DCF involvement is separate from criminal proceedings. Mandatory reporters who fail to report face 3rd degree felony under § 39.205.'),
  ('child-abuse', 'FL', '827.03(1)(b)', 'Child Abuse', '3rd Degree Felony (without great bodily harm); 1st Degree Felony (with great bodily harm)', NULL, '5 years (3rd); 30 years (1st degree with great bodily harm)', '$5,000', '{"Defendant intentionally committed an act that could reasonably be expected to result in physical or mental injury to a child","OR Defendant actively encouraged another to commit such an act"}', NULL, '{"Great bodily harm resulting (1st degree felony)","Torture or malicious punishment (aggravated child abuse — 1st degree felony)","Prior child abuse conviction"}', 'Aggravated child abuse (§ 827.03(2)(a)) — 1st degree felony includes torture, malicious punishment, or great bodily harm. Florida has mandatory minimum sentencing for sexual child abuse.'),
  ('violation-protective-order', 'FL', '741.31', 'Violation of Injunction for Protection Against Domestic Violence', '1st Degree Misdemeanor (first violation); 3rd Degree Felony (subsequent violation or aggravated acts)', NULL, '1 year (misdemeanor); 5 years (felony)', '$1,000; $5,000', '{"A domestic violence injunction was entered against defendant","Defendant had knowledge of the injunction","Defendant willfully violated a specific term of the injunction"}', NULL, '{"Second or subsequent violation within 5 years (3rd degree felony)","Violation by electronic communication","New act of violence during violation"}', 'Injunction violations prosecuted separately from any new criminal charges arising from the same incident. Florida has multiple injunction types: domestic violence, sexual violence, dating violence, repeat violence, stalking.'),
  ('stalking', 'FL', '784.048', 'Stalking', '1st Degree Misdemeanor (basic); 3rd Degree Felony (aggravated)', NULL, '1 year (basic); 5 years (aggravated)', '$1,000; $5,000', '{"Defendant willfully, maliciously, and repeatedly followed, harassed, or cyberstalked the victim","The conduct caused substantial emotional distress","The conduct served no legitimate purpose"}', NULL, '{"Credible threat made (aggravated stalking — 3rd degree felony)","Victim under 16 (3rd degree felony)","Violation of injunction while stalking (3rd degree felony)"}', 'Cyberstalking (§ 784.048(1)(d)) includes electronic harassment across multiple platforms including doxxing and harassment campaigns.'),
  ('elder-abuse', 'FL', '825.102', 'Abuse, Aggravated Abuse, or Neglect of an Elderly Person or Disabled Adult', '3rd Degree Felony (abuse/neglect); 2nd Degree Felony (great bodily harm); 1st Degree Felony (aggravated)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; $10,000', '{"Victim is an elderly person (65+) or disabled adult","Defendant intentionally inflicted physical or psychological injury","OR Defendant committed an intentional act reasonably expected to result in injury","OR Defendant actively encouraged another to commit such act"}', NULL, '{"Great bodily harm resulting (2nd degree felony)","Torture or malicious punishment (aggravated — 1st degree felony)","Financial exploitation (separate § 825.103 charge)","Caregiver relationship"}', 'Financial exploitation of elderly (§ 825.103) prosecuted separately. Mandatory reporting requirements for caregivers. Elder financial fraud aggressively prosecuted in Florida due to large elderly population.'),
  ('weapons-possession', 'FL', '790.01', 'Carrying a Concealed Weapon', '1st Degree Misdemeanor (non-firearm); 3rd Degree Felony (firearm, prohibited person)', NULL, '1 year (non-firearm); 5 years (firearm)', '$1,000; $5,000', '{"Defendant knowingly carried a weapon or firearm concealed from ordinary sight","Defendant was a prohibited person OR was carrying in a prohibited location","Conduct occurred post-July 1, 2023 (permitless carry) and defendant was ineligible"}', NULL, '{"10-20-Life if used in commission of violent crime","Convicted felon in possession (separate felony charge)","Machine gun or short-barreled weapon (2nd degree felony)"}', 'Florida enacted permitless carry (Constitutional Carry) effective July 1, 2023 (HB 543). Eligible persons no longer need a permit. Remaining crimes focus on prohibited persons, prohibited places, and prohibited weapons types.'),
  ('felon-in-possession', 'FL', '790.23', 'Felons and Delinquents Possessing Firearms or Weapons', '2nd Degree Felony', NULL, '15 years', '$10,000', '{"Defendant has been convicted of a felony or adjudicated delinquent for a would-be felony","Defendant knowingly had in his or her care, custody, possession, or control any firearm or electric weapon","OR Defendant carried a concealed weapon"}', '3 years (§ 775.087 if used in commission of another felony)', '{"10-20-Life if used in commission of violent crime","Federal prosecution under 18 U.S.C. § 922(g) often concurrent","Prior felon-in-possession conviction"}', 'Actual or constructive possession both sufficient. Restoration of civil rights does not automatically restore firearm rights in Florida.'),
  ('illegal-discharge', 'FL', '790.15', 'Discharging Firearms in Public', '1st Degree Misdemeanor (basic); 2nd Degree Felony (from vehicle — drive-by)', NULL, '1 year (basic); 15 years (from vehicle)', '$1,000; $10,000', '{"Defendant knowingly discharged a firearm","In a public place, on a highway, or over any public highway or occupied premises","In a manner or direction that exposed persons or property to risk"}', '3 years minimum (§ 775.087 if in commission of a felony)', '{"Discharge from vehicle on public road (2nd degree felony)","Drive-by shooting (§ 790.19 — 2nd degree felony)","Injury resulting"}', 'Drive-by shooting under § 790.19 carries separate penalties. Celebratory gunfire (New Year''s) prosecuted under this statute.'),
  ('possession-prohibited-weapon', 'FL', '790.221', 'Possession of Short-Barreled Rifle, Short-Barreled Shotgun, or Machine Gun', '2nd Degree Felony', NULL, '15 years', '$10,000', '{"Defendant had in his or her possession, ownership, or custody a short-barreled rifle, short-barreled shotgun, or machine gun","Defendant knew the weapon was operable"}', NULL, '{"10-20-Life if used in commission of violent crime","Federal NFA violations concurrent"}', 'Florida law makes possession of NFA items a 2nd degree felony even if federally registered — creating conflict with federal NFA compliance. Silencers/suppressors also regulated under § 790.222.'),
  ('wire-fraud', 'FL', '817.034', 'Florida Communications Fraud Act', '3rd Degree Felony (under $300); 2nd Degree Felony ($300-$19,999); 1st Degree Felony ($20,000+)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; $10,000', '{"Defendant engaged in a scheme to defraud","Defendant obtained property by means of false or fraudulent representation","Defendant communicated via wire, radio, electromagnetic, or photooptical systems"}', NULL, '{"Organized scheme ($20,000+ — 1st degree felony)","Elderly victim (§ 825.103 parallel charge)","Multiple victims"}', 'State-level communications fraud act. Federal wire fraud (18 U.S.C. § 1343) also commonly prosecuted concurrently. Pattern of activity can result in organized fraud charges under § 817.034(4).'),
  ('identity-theft', 'FL', '817.568', 'Criminal Use of Personal Identification Information', '3rd Degree Felony (basic); 2nd Degree Felony (10-19 victims or fraud over $5,000); 1st Degree Felony (20+ victims or fraud over $50,000)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; $10,000', '{"Defendant willfully and without authorization fraudulently used personal identification information","The information belonged to an individual or fictitious individual","Defendant used it to obtain or attempt to obtain any benefit, compensation, credit, or access"}', NULL, '{"10-19 victims (2nd degree felony)","20+ victims (1st degree felony)","Victim elderly","Using another''s identity to avoid arrest"}', 'Florida''s identity theft statute is broad — covers use of others'' information to obtain benefits of any kind. Victim counts across multiple incidents can be aggregated for enhanced charges.'),
  ('embezzlement', 'FL', '812.014', 'Theft by Employee or Trustee (Embezzlement)', '3rd Degree Felony (under $20,000); 2nd Degree Felony ($20,000-$99,999); 1st Degree Felony ($100,000+)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; $10,000', '{"Defendant was entrusted with property by another","Defendant knowingly obtained or used the property","With intent to temporarily or permanently deprive the owner","Defendant was in a position of trust or had authorized access"}', NULL, '{"Employee theft from employer (§ 812.015(8))","Public employee (ethics charges concurrent)","Breach of fiduciary duty"}', 'Florida does not have a specific embezzlement statute — prosecuted as theft under § 812.014. Mandatory restitution under § 775.089.'),
  ('forgery', 'FL', '831.01', 'Forgery', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant falsely made, altered, forged, or counterfeited a public record, certificate, deed, will, contract, note, check, or other instrument","Defendant acted with intent to injure or defraud any person"}', NULL, '{"Uttering forged instrument (§ 831.02 — separate charge)","Multiple instruments","Government documents"}', 'Florida separates forgery (making the false instrument — § 831.01) from uttering (passing it — § 831.02). Both are 3rd degree felonies.'),
  ('bad-checks', 'FL', '832.05', 'Worthless Check or Draft', '1st Degree Misdemeanor (under $150); 3rd Degree Felony ($150+)', NULL, '1 year; 5 years', '$1,000; $5,000', '{"Defendant drew, made, uttered, issued, or delivered a check or draft","Defendant knew at the time of issuance that there were insufficient funds","Defendant had intent to defraud"}', NULL, '{"Pattern of worthless checks (organized scheme)","Payroll check"}', 'Written demand providing 7 days to pay is prerequisite to prosecution under § 832.07. Diversion programs available for first offenders.'),
  ('insurance-fraud', 'FL', '817.234', 'Insurance Fraud', '3rd Degree Felony (under $20,000); 2nd Degree Felony ($20,000-$100,000); 1st Degree Felony ($100,000+)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; $10,000', '{"Defendant knowingly presented or caused to be presented a false or fraudulent claim for payment of a loss or injury","The claim was under any insurance policy","Defendant acted with intent to defraud"}', NULL, '{"PIP (Personal Injury Protection) fraud","Staged accident","Healthcare provider billing fraud","Hurricane or property damage fraud"}', 'Florida is a major PIP insurance fraud state. Office of Insurance Regulation and Division of Insurance Fraud actively prosecute. Organized fraud rings common.'),
  ('credit-card-fraud', 'FL', '817.61', 'Fraudulent Use of Credit Cards', '3rd Degree Felony (two or more transactions totaling $100+ within 6 months)', NULL, '5 years', '$5,000', '{"Defendant used a credit card or account number","Defendant knew the card was stolen, forged, expired, revoked, or obtained by fraud","Defendant used it to obtain money, goods, services, or anything of value"}', NULL, '{"Multiple victims or cards","Card skimming device (§ 817.625 — 2nd degree felony)","Identity theft concurrent charge"}', 'Credit card skimming devices (§ 817.625) are separately punishable as 2nd degree felony.'),
  ('money-laundering', 'FL', '896.101', 'Money Laundering', '3rd Degree Felony ($300-$19,999); 2nd Degree Felony ($20,000-$99,999); 1st Degree Felony ($100,000+)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; Twice the value laundered', '{"Defendant knowingly conducted or attempted to conduct a financial transaction","The transaction involved proceeds from a specified unlawful activity","Defendant knew the property was proceeds of criminal activity","Defendant intended to promote criminal activity, avoid reporting, or conceal the nature of the proceeds"}', NULL, '{"Pattern of activity","Use of financial institution","Structuring (smurfing) to avoid reporting"}', 'Florida money laundering statute mirrors federal § 1956. Often prosecuted with drug trafficking, fraud, or organized crime. Civil forfeiture separate under Chapter 932.'),
  ('fraud-general', 'FL', '817.034', 'Organized Scheme to Defraud', '3rd Degree Felony (under $300); 2nd Degree Felony ($300-$19,999); 1st Degree Felony ($20,000+)', NULL, '5 years; 15 years; 30 years', '$5,000; $10,000; $10,000', '{"Defendant engaged in a scheme to defraud","Defendant obtained or attempted to obtain property or money by means of false or fraudulent pretenses","The false representations were intentional and material"}', NULL, '{"Communications fraud pattern (§ 817.034(4))","Elderly victim","Multiple victims"}', 'Catch-all fraud statute. Florida RICO (§ 895.03) available for pattern of fraud across multiple incidents.'),
  ('securities-fraud', 'FL', '517.301', 'Fraudulent Transactions — Securities', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant offered or sold a security","Defendant made a false statement of material fact or omitted a material fact necessary to make the statement not misleading","Defendant acted with willful intent to defraud"}', NULL, '{"Multiple investors (separate counts)","Aggregate investment over $50,000","Use of interstate commerce (federal prosecution concurrent)"}', 'Florida OFR and AG Economic Crimes Division prosecute. Federal SEC prosecution often concurrent. Ponzi scheme charges typically aggregated.'),
  ('sexual-assault', 'FL', '794.011', 'Sexual Battery', 'Capital Felony (victim under 12, offender 18+); Life Felony (physical force, victim 12+); 1st or 2nd Degree Felony (other circumstances)', 'Life without parole (capital)', 'Death (capital); Life (life felony)', NULL, '{"Defendant committed a sexual act upon or with the victim","Defendant used force or coercion without consent","OR Victim was under 12 years of age","OR Victim was physically or mentally incapacitated"}', 'Life without parole (victim under 12, offender 18+)', '{"Victim under 12 (capital offense)","Position of authority","Weapon used","Multiple victims","Jimmy Ryce Act civil commitment after sentence"}', 'Victim under 12 + defendant 18+ = capital felony. Mandatory sex offender registration and community notification under Chapter 943. Florida''s rape shield law (§ 794.022) limits victim history evidence.'),
  ('rape', 'FL', '794.011(4)', 'Sexual Battery with Physical Force Likely to Cause Serious Personal Injury', 'Life Felony', NULL, 'Life', NULL, '{"Defendant committed a sexual act upon or with the victim","Defendant used or threatened to use a deadly weapon OR used force likely to cause serious personal injury","Without consent of the victim"}', 'Level 9 under Criminal Punishment Code — state prison mandatory', '{"Weapon use","Multiple offenders","Victim under 18","Drugging the victim","Prior sex offense conviction"}', 'Florida does not use ''rape'' in its statutes — charged as sexual battery under § 794.011. Rape shield law § 794.022 restricts victim''s prior sexual history evidence.'),
  ('indecent-exposure', 'FL', '800.03', 'Exposure of Sexual Organs', '1st Degree Misdemeanor', NULL, '1 year', '$1,000', '{"Defendant exposed or exhibited his or her sexual organs","The exposure occurred in a public place or in a private place exposed to public view","Defendant acted in a vulgar or indecent manner"}', NULL, '{"Victim is a minor (lewd or lascivious exhibition under § 800.04 — 2nd degree felony)","School or place where children are present","Prior sex offense conviction"}', 'If victim is under 16, charge typically elevated to lewd or lascivious exhibition (§ 800.04). Sex offender registration may be required depending on circumstances and victim age.'),
  ('solicitation-prostitution', 'FL', '796.07', 'Prohibiting Prostitution and Related Acts', '2nd Degree Misdemeanor (first offense solicitation); 1st Degree Misdemeanor (second); 3rd Degree Felony (third+ or near school/church)', NULL, '60 days; 1 year; 5 years', '$500; $1,000; $5,000', '{"Defendant solicited, induced, enticed, or procured another to commit prostitution","OR Defendant agreed to engage in prostitution for compensation","OR Defendant engaged in prostitution"}', NULL, '{"Third or subsequent offense (3rd degree felony)","Within 1,000 feet of school or church","Minor victim (mandatory sex offender registration)"}', '2014 reform made purchasing sex a 3rd degree felony. John School diversion programs available. Human trafficking (§ 787.06) charged when victim is trafficked.'),
  ('sex-offense-contact', 'FL', '800.04', 'Lewd or Lascivious Offenses Committed Upon or in Presence of Persons Under 16', '2nd Degree Felony (victim 12-15); 1st Degree Felony (victim under 12)', NULL, '15 years; 30 years', '$10,000', '{"Defendant was 18 years of age or older","Defendant intentionally touched in a lewd or lascivious manner the breasts, genitals, genital area, or buttocks","Victim was under 16 years of age"}', 'State prison presumptive for all levels', '{"Victim under 12 (1st degree felony)","Prior sex offense conviction","Position of authority over victim"}', 'Four subsections: molestation (§ 800.04(4)), conduct (§ 800.04(5)), exhibition (§ 800.04(6)), battery. Battery version — victim 12-15 is 2nd degree; under 12 is 1st degree.'),
  ('sex-offense-digital', 'FL', '847.0135', 'Computer Pornography and Traveling to Meet a Minor', '3rd Degree Felony (solicitation); 2nd Degree Felony (traveling)', NULL, '5 years (solicitation); 15 years (traveling)', '$5,000; $10,000', '{"Defendant knowingly used a computer or online service to solicit, lure, or entice a child under 16","Defendant believed the minor to be under 16","Solicitation was for sexual conduct"}', NULL, '{"Traveling to meet (2nd degree felony — § 847.0135(4))","Sending obscene material to minor (§ 847.0133)","Prior conviction"}', 'Traveling to meet (§ 847.0135(4)) is a separate 2nd degree felony where actual travel occurs. FDLE conducts regular undercover operations. Federal charges commonly concurrent.'),
  ('child-exploitation', 'FL', '827.071', 'Sexual Performance by a Child / Child Pornography', '2nd Degree Felony (possessing); 1st Degree Felony (producing, promoting, distributing)', 'State prison mandatory', '15 years (possession); 30 years (production/distribution)', '$10,000', '{"Defendant knowingly possessed, controlled, or intentionally viewed material depicting a child under 18 engaging in sexual conduct","OR Defendant produced, promoted, financed, distributed, or possessed with intent to promote such material"}', 'State prison presumptive', '{"Distribution or production (1st degree felony)","Victim under 12","100+ images","Federal prosecution concurrent under 18 U.S.C. § 2256"}', 'Mandatory lifetime sex offender registration. FDLE actively investigates. Federal charges typically pursued concurrently.'),
  ('failure-to-register', 'FL', '943.0435', 'Sex Offender Registration — Failure to Register', '3rd Degree Felony (first offense); 2nd Degree Felony (subsequent)', NULL, '5 years; 15 years', '$5,000; $10,000', '{"Defendant was a sex offender required to register under Florida law","Defendant failed to initially register, update registration, or report as required","Defendant knew or should have known of the obligation"}', NULL, '{"Sexual predator designation (higher frequency reporting)","Failure to register and leaving the state","Second or subsequent violation (2nd degree felony)"}', 'Florida has strict registration requirements — twice annual updates, report within 48 hours of address change. Cannot reside within 1,000 feet of school, park, playground, or bus stop.'),
  ('statutory-rape', 'FL', '794.05', 'Unlawful Sexual Activity with Certain Minors', '2nd Degree Felony', NULL, '15 years', '$10,000', '{"Defendant is 24 years of age or older","Defendant engaged in sexual activity with a person who is 16 or 17 years of age","The minor was not the defendant''s spouse at the time"}', NULL, '{"Defendant in position of authority over minor","Prior sex offense conviction"}', 'Florida''s age of consent is 18. § 794.05 specifically addresses 24+ adults with 16-17 year olds. ''Romeo and Juliet'' provision (§ 943.04354) allows registry removal for defendants within 4 years of victim''s age.'),
  ('sexual-battery', 'FL', '794.011', 'Sexual Battery', 'Capital Felony through 2nd Degree Felony (depends on circumstances)', NULL, 'Life / Death', NULL, '{"Defendant committed oral, anal, or vaginal penetration, or digital/object penetration","Without consent of victim","OR by use of force, threat, or coercion"}', 'State prison mandatory for all felony levels', '{"Victim under 12 + defendant 18+ (capital)","Physical force likely to cause serious injury (life felony)","Victim mentally incapacitated","Position of authority"}', 'Florida''s primary sexual offense statute. Impaired consent through intoxication (voluntary or involuntary) is a critical issue. Florida rape shield law limits victim history evidence.'),
  ('disorderly-conduct', 'FL', '877.03', 'Breach of the Peace; Disorderly Conduct', '2nd Degree Misdemeanor', NULL, '60 days', '$500', '{"Defendant engaged in an act that corrupted the public morals or outraged the sense of public decency","OR Defendant affected the peace and quiet of persons who witnessed the act","OR Defendant engaged in brawling, fighting, or tumultuous conduct"}', NULL, '{"During a state of emergency (3rd degree felony)","At a funeral or memorial service"}', 'Florida''s disorderly conduct requires actual public disturbance — mere offensive speech alone insufficient under First Amendment. Disorderly intoxication (§ 856.011) is a separate, lesser offense.'),
  ('resisting-arrest', 'FL', '843.02', 'Resisting Officer Without Violence', '1st Degree Misdemeanor', NULL, '1 year', '$1,000', '{"Defendant resisted, obstructed, or opposed a law enforcement officer","The officer was engaged in the lawful execution of any legal duty","Defendant''s resistance was without violence"}', NULL, '{"With violence (3rd degree felony under § 843.01)","Injury to officer"}', 'Resisting with violence (§ 843.01) is a 3rd degree felony. Lawfulness of the arrest is a contested defense issue in Florida courts.'),
  ('obstruction-justice', 'FL', '918.13', 'Tampering with or Fabricating Physical Evidence', '3rd Degree Felony', NULL, '5 years', '$5,000', '{"Defendant knew or had reasonable grounds to believe a criminal trial or proceeding was pending or would be instituted","Defendant altered, destroyed, concealed, or removed any record, document, or thing","With intent to impair its availability as evidence"}', NULL, '{"Witness intimidation (§ 914.22 — 3rd degree felony)","Jury tampering (1st degree felony)","Suborning perjury"}', 'Witness tampering (§ 914.22) carries enhanced penalties when used to obstruct major felony prosecutions.'),
  ('contempt-of-court', 'FL', '38.23', 'Indirect Contempt of Court', '2nd Degree Misdemeanor (indirect contempt); Criminal contempt varies', NULL, '60 days or indefinite until compliance (civil contempt)', '$500', '{"A lawful court order was in effect","Defendant had knowledge of the order","Defendant willfully and intentionally disobeyed the order"}', NULL, '{"Violation of domestic violence injunction (separate criminal charge under § 741.31)","Repeat violations"}', 'Direct contempt handled summarily by the court. Indirect contempt requires show cause hearing.'),
  ('public-intoxication', 'FL', '856.011', 'Disorderly Intoxication', '2nd Degree Misdemeanor', NULL, '60 days', '$500', '{"Defendant was intoxicated in a public place","AND Defendant endangered the safety of another person or property, OR caused a public disturbance"}', NULL, '{"Prior conviction within 12 months (mandatory treatment program referral)","Second conviction (public detoxification program)"}', 'Florida requires both intoxication AND endangerment/public disturbance. Mere public intoxication alone is NOT a crime in Florida — this distinguishes it from many other states.'),
  ('loitering', 'FL', '856.021', 'Loitering or Prowling', '2nd Degree Misdemeanor', NULL, '60 days', '$500', '{"Defendant loitered or prowled in a place, at a time, or in a manner not usual for law-abiding individuals","Circumstances warranted justifiable and reasonable alarm or immediate concern for the safety of persons or property"}', NULL, '{"Near schools or playgrounds","Prior drug or theft conviction"}', 'Florida requires an objective reasonable officer standard. Defendant must be given opportunity to dispel alarm before arrest. Vagueness challenges frequently raised.'),
  ('disturbing-peace', 'FL', '877.03', 'Breach of the Peace', '2nd Degree Misdemeanor', NULL, '60 days', '$500', '{"Defendant engaged in conduct that corrupted public morals","OR Defendant outraged the sense of public decency","OR Defendant affected the peace and quiet of persons who witnessed the act"}', NULL, '{"During state of emergency","At school event or near place of worship"}', 'Florida uses breach of peace and disorderly conduct interchangeably under § 877.03. Physical conduct required — offensive speech alone is insufficient.'),
  ('failure-to-appear', 'FL', '843.15', 'Failure to Appear', '1st Degree Misdemeanor (misdemeanor underlying); 3rd Degree Felony (felony underlying)', NULL, '1 year; 5 years', '$1,000; $5,000', '{"Defendant was released on bail or recognizance","Defendant was required to appear before a court for any criminal proceeding","Defendant willfully failed to appear as required"}', NULL, '{"Bond forfeiture (civil consequence)","Underlying felony charge increases FTA to felony"}', 'FTA charge runs consecutive to underlying charge. Willfulness is an element — defendant must have known of the hearing. Bond forfeiture is a separate civil proceeding.'),
  ('false-report', 'FL', '817.49', 'False Reports of Commission of Crimes', '1st Degree Misdemeanor', NULL, '1 year', '$1,000', '{"Defendant made a report to a law enforcement agency of a crime","The report was false","Defendant knew the report was false at the time of making it"}', NULL, '{"False report involving terrorism (3rd degree felony under § 790.163)","False bomb threat (3rd degree felony)","Multiple false reports"}', 'False domestic violence allegations commonly prosecuted under this statute. Restitution to law enforcement for investigation costs available.'),
  ('criminal-threat', 'FL', '836.10', 'Written Threats to Kill or Do Bodily Injury', '2nd Degree Felony', NULL, '15 years', '$10,000', '{"Defendant composed or sent any letter, inscription, or electronic record","The communication threatened to kill or do bodily injury to another person","OR Defendant made such threat via electronic communication to a school, school official, or student"}', NULL, '{"School shooting threat (escalated prosecution)","Multiple victims named","Use of social media"}', 'Unlike assault (§ 784.011), actual present ability to carry out the threat is not required. School threats receive aggressive prosecution in Florida.'),
  ('harassment', 'FL', '784.048(1)(a)', 'Harassment (Course of Conduct)', '1st Degree Misdemeanor (as component of stalking charge)', NULL, '1 year', '$1,000', '{"Defendant engaged in a course of conduct directed at a specific person","The conduct caused substantial emotional distress","The conduct served no legitimate purpose"}', NULL, '{"Repeated course of conduct (escalates to stalking)","Electronic communications (cyberstalking)"}', 'Florida addresses harassment primarily through § 784.048 (stalking). Standalone harassment charges are typically charged within the stalking framework.'),
  ('probation-violation', 'FL', '948.06', 'Violation of Probation or Community Control', 'Not a separate offense — defendant faces original sentencing exposure', NULL, 'Maximum sentence for original offense', NULL, '{"Defendant was placed on probation or community control","Defendant willfully and substantially violated a condition of probation or community control"}', NULL, '{"New law violation (substantive — typically warrants revocation)","Technical violation (failure to report, positive drug test, curfew)","Multiple simultaneous violations"}', 'VOP hearings use preponderance of evidence standard. Hearsay admissible. Defendant may be held without bail pending VOP hearing.'),
  ('probation-violation-technical', 'FL', '948.06(2)(a)', 'Technical Violation of Probation', 'Not a separate class — faces original offense sentencing', NULL, 'Maximum for original offense', NULL, '{"Defendant was on probation","Defendant violated a technical condition: failure to report, failure to pay fees, curfew violation, failed drug test, unauthorized travel, etc."}', NULL, '{"Pattern of technical violations","Underlying offense severity"}', 'Florida 2019 reform (SB 2534) — technical violations for certain non-violent offenders may result in sanctions short of revocation. Structured sanctions grid available.'),
  ('probation-violation-substantive', 'FL', '948.06(2)(b)', 'Substantive Violation of Probation (New Law Violation)', 'Not a separate class — faces original sentencing plus prosecution for new offense', NULL, 'Maximum for original offense plus separate prosecution for new offense', NULL, '{"Defendant was on probation","Defendant committed a new criminal offense while on probation"}', NULL, '{"New offense is a felony (almost always results in revocation)","Violent new offense","New offense against same victim"}', 'Substantive violations almost always result in full revocation. Florida courts may impose maximum of original sentence consecutively with the new sentence.'),
  ('community-control-violation', 'FL', '948.101', 'Violation of Community Control', 'Not a separate class — faces original sentencing exposure', NULL, 'Maximum for original offense', NULL, '{"Defendant was placed on community control (house arrest)","Defendant willfully and substantially violated a condition","Common violations: leaving approved residence, failure to appear for check-in, unauthorized absences"}', NULL, '{"New law violation","Electronic monitoring violation (ankle bracelet)","Absconding"}', 'Community control is a stricter alternative to probation. GPS monitoring standard. Violations treated similarly to probation violations but often result in immediate incarceration.'),
  ('parole-violation', 'FL', '947.141', 'Violation of Parole', 'Not a separate criminal offense — administrative revocation with re-imprisonment on original sentence', NULL, 'Remainder of original sentence', NULL, '{"Defendant was released on parole by the Florida Commission on Offender Review","Defendant violated one or more conditions of parole","The Florida Commission on Offender Review issued a warrant"}', NULL, '{"New law violation","Contact with victim","Absconding"}', 'Florida abolished parole for offenses committed on or after October 1, 1983, with limited exceptions. For pre-1983 offenses, Florida Commission on Offender Review (FCOR) handles. Most modern supervision is probation or community control.'),
  ('supervised-release-violation', 'FL', '948.06', 'Violation of Supervised Release / Conditional Release', 'Not a separate criminal offense — administrative revocation', NULL, 'Remainder of original sentence', NULL, '{"Defendant was released on conditional release or post-prison supervisory release","Defendant violated one or more conditions of supervised release"}', NULL, '{"New law violation","Absconding"}', 'Florida''s conditional release (§ 947.1405) applies to offenders serving violent felony sentences. Supervised community release under FCOR. Violations result in return to prison.'),
  ('conspiracy', 'FL', '777.04(3)', 'Criminal Conspiracy', 'One degree below the target offense', NULL, 'One degree below target offense maximum', 'Same as one degree below target offense', '{"Defendant agreed with one or more persons to commit an offense","At least one party did an overt act in furtherance of the agreement","Defendant had specific intent to commit the target offense"}', NULL, '{"Conspiracy to commit trafficking (follows trafficking mandatory minimums under § 893.135)","Florida RICO enterprise","Multiple overt acts"}', 'Florida conspiracy carries penalty one degree below completed offense, EXCEPT drug trafficking conspiracies carry same mandatory minimums as trafficking. Unlike federal law, Florida requires an overt act.'),
  ('self-defense', 'FL', '776.012; 776.013', 'Justifiable Use of Force / Stand Your Ground', 'Affirmative defense — not a charged offense', NULL, NULL, NULL, '{"Defendant was not the initial aggressor","Defendant reasonably believed force was necessary to prevent imminent death or great bodily harm","OR Defendant was in his or her dwelling and an intruder forcibly entered (Castle Doctrine)","Defendant had a right to be in the place where force was used (Stand Your Ground)"}', NULL, '{}', 'Florida''s Stand Your Ground law (§ 776.013) — no duty to retreat when in a place where defendant has a right to be. Pre-trial immunity hearing under § 776.032. After 2017 amendment, prosecution bears burden of disproving immunity by clear and convincing evidence at pre-trial hearing.'),
  ('other', 'FL', '775.082', 'Penalties for Felonies and Misdemeanors', 'Varies by underlying offense classification', NULL, 'Life (1st degree PBL); 30 years (1st degree felony); 15 years (2nd degree); 5 years (3rd degree); 1 year (1st degree misdemeanor); 60 days (2nd degree misdemeanor)', 'Varies', '{}', NULL, '{"Habitual Felony Offender (§ 775.084) — enhanced sentences","Habitual Violent Felony Offender","Three-Time Violent Felony Offender","Prison Releasee Reoffender (PRR) — mandatory maximum sentence","10-20-Life (§ 775.087)"}', 'Florida''s Criminal Punishment Code (§ 921.002) governs felony sentencing with a scoresheet system. Prison Releasee Reoffender (PRR) requires mandatory maximum if offense committed within 3 years of release. Habitual offender designations significantly extend sentences.')
INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('dui-dwi', 'GA', 'O.C.G.A. § 40-6-391', 'Driving Under the Influence of Alcohol or Drugs', 'Misdemeanor (1st/2nd offense); Felony (3rd+ within 10 years)', '24 hours imprisonment (1st offense)', '12 months (misdemeanor); 5 years (3rd offense felony)', '$1,000 (misdemeanor); $5,000 (felony)', '{"Drove or was in actual physical control of a moving vehicle","On a public road, highway, or private property open to the public","While under the influence of alcohol or drugs to the extent it was less safe to drive","OR with BAC of 0.08% or more (0.04% for CDL holders; 0.02% for drivers under 21)"}', '24 hours jail (1st); 72 hours jail (2nd); 15 days jail (3rd felony)', '{"Child under 14 in vehicle: additional misdemeanor under O.C.G.A. § 40-6-391(l)","BAC 0.15% or higher: mandatory ignition interlock device","3rd offense within 10 years: felony classification","4th+ offense: felony regardless of look-back period"}', 'Administrative license suspension (ALS) separate from criminal penalties. Implied consent under § 40-5-55 requires chemical test.'),
  ('dui-first-offense', 'GA', 'O.C.G.A. § 40-6-391', 'DUI — First Offense', 'Misdemeanor', '24 hours imprisonment', '12 months imprisonment', '$1,000', '{"First DUI conviction within 10-year look-back period","Drove or was in actual physical control of a moving vehicle","Under influence to extent less safe to drive OR BAC 0.08%+"}', '24 hours jail; 40 hours community service; 12 months probation; DUI Risk Reduction Program', '{"BAC 0.15%+: ignition interlock device required","Child passenger under 14: child endangerment charge added"}', 'License suspended 1 year. Minimum 24 hours must be served; balance may be probated. Clinical evaluation required.'),
  ('dui-repeat-offense', 'GA', 'O.C.G.A. § 40-6-391', 'DUI — Repeat Offense', 'Misdemeanor (2nd); Felony (3rd+ within 10 years)', '72 hours mandatory (2nd); 15 days mandatory (3rd felony)', '12 months (2nd misdemeanor); 5 years (3rd felony)', '$1,000 (2nd); $5,000 (3rd+)', '{"Prior DUI conviction(s) within applicable look-back period","Drove or was in actual physical control of a moving vehicle","Under influence to extent less safe OR BAC 0.08%+"}', '72 hours mandatory jail (2nd); 15 days mandatory jail (3rd felony)', '{"Habitual violator designation possible on 3rd offense","Ignition interlock mandatory on 2nd+ offense","5-year license revocation on habitual violator designation"}', '10-year look-back period for felony classification on 3rd offense. 4th offense is always felony.'),
  ('dui-drugs', 'GA', 'O.C.G.A. § 40-6-391(a)(2)-(6)', 'DUI — Under the Influence of Drugs', 'Misdemeanor (1st/2nd); Felony (3rd+)', '24 hours imprisonment', '12 months (misdemeanor); 5 years (felony)', '$1,000 (misdemeanor); $5,000 (felony)', '{"Drove or was in actual physical control of a moving vehicle","Under the influence of any controlled substance, marijuana, or other drug","To the extent it was less safe to drive","OR per se: blood or urine shows presence of Schedule I-IV controlled substance under § 40-6-391(a)(6)"}', '24 hours jail (1st offense)', '{"Any prior DUI within 10 years elevates penalties","Drug paraphernalia in vehicle: additional charges"}', 'Per se DUI-drugs: any detectable amount of Schedule I-IV substance in blood/urine — no impairment proof required.'),
  ('reckless-driving', 'GA', 'O.C.G.A. § 40-6-390', 'Reckless Driving', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant operated a vehicle","On a public road, highway, or private property open to the public","In reckless disregard for the safety of persons or property"}', NULL, '{"Resulting serious injury or death: vehicular homicide charges under § 40-6-393","Repeat offense: points accumulation leads to license suspension"}', '4 points assessed on driver''s license. Frequently charged alongside DUI.'),
  ('hit-and-run', 'GA', 'O.C.G.A. § 40-6-270', 'Duty to Stop at or Return to Scene of Accident', 'Felony (injury/death); Misdemeanor (property damage only)', '1 year (felony with injury)', '5 years (felony); 12 months (misdemeanor)', '$5,000 (felony); $1,000 (misdemeanor)', '{"Defendant was operating a vehicle involved in an accident","Accident resulted in injury, death, or property damage","Defendant failed to immediately stop at or return to the scene","Defendant failed to provide identifying information and render reasonable aid"}', NULL, '{"Death resulting: minimum 3 years imprisonment","Serious injury: minimum 1 year imprisonment"}', 'Duty to stop, render aid, and exchange information. Property-damage-only hit-and-run is misdemeanor.'),
  ('vehicular-homicide', 'GA', 'O.C.G.A. § 40-6-393', 'Homicide by Vehicle', 'Felony (1st degree); Misdemeanor (2nd degree)', '3 years (1st degree felony)', '15 years (1st degree felony); 12 months (2nd degree misdemeanor)', '$5,000', '{"Defendant operated a motor vehicle","In violation of O.C.G.A. § 40-6-391 (DUI), racing, or fleeing statute","Such violation was the proximate cause of death of another person"}', '3 years for 1st degree', '{"Multiple deaths: consecutive sentences possible","DUI-related: mandatory minimum 3 years"}', '1st degree requires underlying DUI, racing, or fleeing as predicate. 2nd degree involves other traffic violations.'),
  ('vehicular-manslaughter', 'GA', 'O.C.G.A. § 40-6-393(b)', 'Homicide by Vehicle in the Second Degree', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant operated a motor vehicle","In violation of a traffic law other than DUI, racing, or fleeing","Such violation was the proximate cause of death of another person"}', NULL, '{"Reckless driving as predicate: potential 1st degree elevation"}', 'Second-degree homicide by vehicle covers negligent or traffic-violation-related deaths that don''t involve DUI or racing.'),
  ('driving-on-suspended', 'GA', 'O.C.G.A. § 40-5-121', 'Driving on Suspended or Revoked License', 'Misdemeanor (1st/2nd); Felony (3rd+)', '2 days mandatory (1st offense)', '12 months (misdemeanor); 5 years (felony)', '$1,000 (misdemeanor); $5,000 (felony)', '{"Defendant drove a motor vehicle on a public road","Defendant''s driver''s license or privilege to drive was suspended or revoked","Defendant had actual or constructive knowledge of the suspension"}', '2 days jail (1st); 10 days (2nd); felony 3rd offense', '{"Habitual violator under § 40-5-58: felony with 5-year revocation","Driving during DUI-related suspension: aggravated penalty"}', 'Habitual violator: 3rd major violation within 5 years = 5-year revocation and felony charge.'),
  ('fleeing-eluding', 'GA', 'O.C.G.A. § 40-6-395', 'Fleeing or Attempting to Elude a Police Officer', 'Misdemeanor (basic); Felony (aggravated)', NULL, '12 months (misdemeanor); 5 years (felony)', '$5,000', '{"Law enforcement officer gave a visible or audible signal to stop","Officer was in uniform or marked vehicle","Defendant willfully failed or refused to stop or fled"}', NULL, '{"High-speed chase endangering others: felony under § 40-6-395(b)","Serious injury or death: vehicular homicide charges added"}', 'Aggravated form charged when driver travels 30+ mph over limit, enters oncoming traffic, or runs traffic control devices.'),
  ('open-container', 'GA', 'O.C.G.A. § 40-6-253', 'Open Container of Alcoholic Beverage in Motor Vehicle', 'Misdemeanor', NULL, '12 months imprisonment', '$200', '{"Defendant operated or was a passenger in a moving vehicle on a public highway","An open container of alcohol was possessed or accessible in the passenger area","Container had been opened or had broken seal or partially removed contents"}', NULL, '{}', 'Locked trunk or locked glove box exempted. Does not apply to passengers in chartered buses, taxis, or limousines.'),
  ('refusing-breath-test', 'GA', 'O.C.G.A. § 40-5-67.1', 'Refusal of Chemical Test — Implied Consent', 'Administrative (license suspension); refusal admissible at trial', NULL, '1-year license suspension (1st refusal); 3-year suspension (2nd refusal within 5 years)', NULL, '{"Defendant was lawfully arrested for DUI","Law enforcement officer read the Georgia Implied Consent Notice","Defendant refused to submit to the designated chemical test"}', NULL, '{"2nd refusal within 5 years: 3-year license suspension"}', 'Refusal admissible as evidence of consciousness of guilt at trial. No standalone criminal charge; triggers administrative ALS.'),
  ('drug-possession', 'GA', 'O.C.G.A. § 16-13-30(a)', 'Possession of Controlled Substance', 'Felony (Schedule I-IV); Misdemeanor (Schedule V)', NULL, '15 years (Schedule I-II, 1st offense); 30 years (2nd offense); 5 years (Schedule III-V)', NULL, '{"Defendant knowingly and willfully possessed a controlled substance","Substance was listed on the Georgia controlled substance schedule","Defendant had actual or constructive possession"}', NULL, '{"Near school, park, or public housing within 1,000 feet: mandatory 2-year add-on","Large quantity: trafficking presumption under § 16-13-31","Prior drug conviction: enhanced maximum"}', 'Marijuana treated separately under § 16-13-2. Trafficking thresholds trigger mandatory minimums under § 16-13-31.'),
  ('drug-possession-marijuana', 'GA', 'O.C.G.A. § 16-13-2', 'Possession of Marijuana', 'Misdemeanor (1 oz or less); Felony (more than 1 oz)', NULL, '12 months (1 oz or less); 10 years (1 oz to 10 lbs)', '$1,000 (misdemeanor); $5,000 (felony)', '{"Defendant possessed marijuana","Amount was 1 oz or less (misdemeanor) or more than 1 oz (felony)","Possession was knowing and willful"}', NULL, '{"More than 10 lbs: trafficking under § 16-13-31 with mandatory minimums","Near drug-free school zone: enhanced penalty"}', 'Medical marijuana oil (low-THC cannabis oil) permitted under § 16-12-191 with valid Low THC Oil Registry card.'),
  ('drug-possession-cocaine', 'GA', 'O.C.G.A. § 16-13-30(a)', 'Possession of Cocaine', 'Felony', NULL, '15 years (1st offense); 30 years (2nd offense)', NULL, '{"Defendant knowingly possessed cocaine (Schedule II controlled substance)","Amount was below 28g trafficking threshold","Possession was actual or constructive"}', NULL, '{"28g or more: cocaine trafficking under § 16-13-31 with mandatory 10-year minimum","Near drug-free school zone: 2-year mandatory add-on"}', 'Trafficking thresholds: 28g+ = 10 yrs mandatory; 200g+ = 15 yrs mandatory; 400g+ = 25 yrs mandatory.'),
  ('drug-possession-meth', 'GA', 'O.C.G.A. § 16-13-30(a)', 'Possession of Methamphetamine', 'Felony', NULL, '15 years (1st offense); 30 years (2nd offense)', NULL, '{"Defendant knowingly possessed methamphetamine (Schedule II)","Amount was below 28g trafficking threshold","Possession was actual or constructive"}', NULL, '{"28g or more: meth trafficking mandatory minimum 10 years","200g or more: 15-year mandatory minimum","400g or more: 25-year mandatory minimum"}', 'Meth trafficking under § 16-13-31(e). Children present at meth lab triggers child endangerment charge.'),
  ('drug-possession-opioids', 'GA', 'O.C.G.A. § 16-13-30(a)', 'Possession of Opioids or Narcotics', 'Felony', NULL, '15 years (1st offense); 30 years (2nd offense)', NULL, '{"Defendant knowingly possessed an opioid narcotic controlled substance (Schedule I-II)","No valid prescription or prescription was fraudulently obtained","Possession was actual or constructive"}', NULL, '{"4g or more heroin: trafficking mandatory minimum 5 years","14g+ heroin: 10-year mandatory minimum","28g+ heroin: 25-year mandatory minimum"}', 'Fentanyl treated as Schedule II. Distribution causing death may support felony murder under § 16-5-1(b).'),
  ('drug-possession-prescription', 'GA', 'O.C.G.A. § 16-13-30(a); § 16-13-72', 'Possession of Prescription Drug Without Valid Prescription', 'Felony (Schedule II-IV); Misdemeanor (Schedule V)', NULL, '15 years (Schedule II); 5 years (Schedule III-IV)', NULL, '{"Defendant possessed a prescription controlled substance","Defendant lacked a valid, current prescription for the substance","Substance was on Georgia''s controlled substance schedule"}', NULL, '{"Forged or altered prescription: fraud charges under § 16-13-73","Large quantity: trafficking presumption"}', 'Prescription Drug Monitoring Program (PDMP) data under § 16-13-57 frequently used as evidence.'),
  ('drug-trafficking', 'GA', 'O.C.G.A. § 16-13-31', 'Drug Trafficking', 'Felony', '5 years (cocaine 28g+); 10 years (meth 28g+); 5 years (heroin 4g+)', '30 years', '$1,000,000', '{"Defendant knowingly possessed, sold, delivered, or manufactured a controlled substance","Quantity met or exceeded the statutory trafficking threshold for the specific substance","Defendant had knowledge of the nature of the substance"}', '5-25 years depending on substance and quantity; no parole, probation, or suspended sentence on mandatory term', '{"Trafficking within drug-free zone: additional mandatory time","Leadership role: enhanced sentence"}', 'No parole, probation, or suspended sentence on the mandatory minimum portion. Thresholds vary by substance.'),
  ('drug-distribution', 'GA', 'O.C.G.A. § 16-13-30(b)', 'Distribution or Sale of Controlled Substance', 'Felony', '1 year', '30 years', NULL, '{"Defendant sold, delivered, distributed, or dispensed a controlled substance","Substance was on the controlled substance schedule","Defendant acted knowingly and intentionally"}', '1 year', '{"Distribution within 1,000 feet of school, park, or public housing: mandatory additional 2-year term","Distribution to a minor: enhanced penalty","Prior distribution conviction: enhanced maximum"}', 'Drug-free zone enhancement under § 16-13-32.4 adds mandatory 2 years consecutive.'),
  ('drug-manufacturing', 'GA', 'O.C.G.A. § 16-13-30(b)', 'Manufacturing Controlled Substance', 'Felony', '1 year', '30 years', NULL, '{"Defendant manufactured, produced, prepared, or processed a controlled substance","Substance was listed on the controlled substance schedule","Acts were knowing and intentional"}', '1 year', '{"Meth lab with children present: child endangerment added under § 16-12-1","Trafficking quantity manufactured: trafficking charges"}', 'Meth lab cleanup costs may be assessed against defendant under GA environmental statutes.'),
  ('drug-paraphernalia', 'GA', 'O.C.G.A. § 16-13-32.2', 'Possession of Drug Paraphernalia', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant possessed an object defined as drug paraphernalia (pipes, syringes, scales, etc.)","Defendant intended to use paraphernalia in connection with a controlled substance"}', NULL, '{"Sale of paraphernalia to minor: felony under § 16-13-32.1"}', 'Intent inferred from proximity to drugs, residue, and circumstantial evidence.'),
  ('prescription-fraud', 'GA', 'O.C.G.A. § 16-13-73', 'Fraudulent Prescription for Controlled Substance', 'Felony', NULL, '10 years', NULL, '{"Defendant obtained or attempted to obtain a controlled substance by fraud","Methods included forged prescription, false name, false statement to practitioner, or doctor-shopping","Defendant acted with knowledge of the fraudulent nature of the act"}', NULL, '{"Healthcare provider fraud: professional license revocation","Multiple fraudulent prescriptions: charges may stack per occurrence"}', 'PDMP enrollment required for Schedule II-IV dispensing; patterns are reportable to law enforcement.'),
  ('drug-possession-with-intent', 'GA', 'O.C.G.A. § 16-13-30(b)', 'Possession of Controlled Substance with Intent to Distribute', 'Felony', '1 year', '30 years', NULL, '{"Defendant possessed a controlled substance","Defendant intended to distribute, sell, or deliver the substance","Intent inferred from quantity, packaging, scales, cash, or other circumstantial evidence"}', '1 year', '{"Near school, park, or public housing: additional 2-year mandatory term","With firearm: additional weapons charges","Trafficking quantity: trafficking threshold charges"}', 'Intent proven circumstantially — scales, individual baggies, large cash, and cell phone records all relevant.'),
  ('murder-first-degree', 'GA', 'O.C.G.A. § 16-5-1(a)', 'Murder — Malice Murder', 'Felony', 'Life imprisonment', 'Death penalty or life without parole', NULL, '{"Defendant caused the death of another human being","With malice aforethought, either express or implied","The killing was unlawful"}', 'Life imprisonment', '{"Statutory aggravating circumstances: death penalty eligible","Law enforcement officer victim: aggravated sentence","Multiple victims: consecutive life sentences"}', 'Georgia has the death penalty. Felony murder under § 16-5-1(b) charged when death occurs during commission of a felony.'),
  ('murder-second-degree', 'GA', 'O.C.G.A. § 16-5-1(c)', 'Murder in the Second Degree', 'Felony', '10 years', '30 years', NULL, '{"Defendant caused the death of another person","During commission of cruelty to children in the second degree under § 16-5-70(b)","Without malice aforethought"}', '10 years', '{}', 'Georgia second-degree murder is limited to child cruelty as predicate. General felony murder is § 16-5-1(b).'),
  ('voluntary-manslaughter', 'GA', 'O.C.G.A. § 16-5-2', 'Voluntary Manslaughter', 'Felony', '1 year', '20 years', NULL, '{"Defendant caused the death of another person","While in a sudden, violent, and irresistible passion","Resulting from serious provocation sufficient to excite such passion in a reasonable person","No cooling-off period elapsed between provocation and killing"}', '1 year', '{}', 'Heat-of-passion reduces murder to voluntary manslaughter. Provocation must be legally sufficient under GA case law.'),
  ('involuntary-manslaughter', 'GA', 'O.C.G.A. § 16-5-3', 'Involuntary Manslaughter', 'Felony (during commission of unlawful act); Misdemeanor (lawful act in unlawful manner)', NULL, '10 years (felony); 12 months (misdemeanor)', NULL, '{"Defendant caused the death of another person","Without malice or intent to kill","During commission of an unlawful act other than a felony (felony version)","OR during a lawful act performed in an unlawful manner lacking due caution (misdemeanor version)"}', NULL, '{}', 'Vehicular manslaughter charged separately as Homicide by Vehicle under § 40-6-393.'),
  ('aggravated-assault', 'GA', 'O.C.G.A. § 16-5-21', 'Aggravated Assault', 'Felony', '1 year', '20 years', NULL, '{"Defendant attempted to commit a violent injury upon another person, or committed an act placing another in reasonable apprehension of immediately receiving violent injury","With a deadly weapon or object likely to or actually resulting in serious bodily injury","OR with intent to rob, rape, or murder","OR by discharging a firearm from a motor vehicle toward a person or occupied building"}', '3 years if firearm used; 5 years if victim is public safety officer', '{"Victim is law enforcement officer: mandatory minimum 5 years no parole","Family violence context: family violence felony designation","Gang-related: RICO enhancement under § 16-14-4"}', 'Mandatory 3 years if victim is public safety officer or crime committed at public transit station under § 16-5-21(b).'),
  ('simple-assault', 'GA', 'O.C.G.A. § 16-5-20', 'Simple Assault', 'Misdemeanor; High and Aggravated Misdemeanor (certain circumstances)', NULL, '12 months imprisonment', '$5,000 (high and aggravated misdemeanor)', '{"Defendant attempted to commit a violent injury to another person","OR committed an act placing another in reasonable apprehension of immediately receiving a violent injury","Defendant had apparent present ability to carry out the act"}', NULL, '{"Victim is elder (65+): high and aggravated misdemeanor","Victim is pregnant and defendant knew: high and aggravated misdemeanor","Committed on public transit: high and aggravated misdemeanor"}', 'No physical contact required — apprehension of injury alone is sufficient for assault in Georgia.'),
  ('battery', 'GA', 'O.C.G.A. § 16-5-23.1', 'Battery', 'Misdemeanor (1st offense); Felony (2nd+ offense against same victim)', NULL, '12 months (misdemeanor); 5 years (felony 2nd offense same victim)', '$1,000', '{"Defendant intentionally caused substantial physical harm to another person","OR intentionally made physical contact of an insulting or provoking nature with another person","Act was knowing and intentional"}', NULL, '{"Second battery conviction against same victim: felony","High and aggravated misdemeanor if against elder, pregnant woman, or committed on public transit"}', 'Simple battery under § 16-5-23 requires only insulting physical contact. Battery § 16-5-23.1 requires substantial physical harm.'),
  ('aggravated-battery', 'GA', 'O.C.G.A. § 16-5-24', 'Aggravated Battery', 'Felony', '1 year', '20 years', NULL, '{"Defendant maliciously caused bodily harm to another person","By depriving them of a member of the body","OR by rendering a member of the body useless","OR by seriously disfiguring the body or a member thereof"}', '5 years if victim is a public safety officer', '{"Victim is law enforcement or public safety officer: mandatory minimum 5 years","Use of caustic substance: enhanced penalty"}', 'Serious disfigurement includes permanent scarring. Permanent loss of use of a limb qualifies.'),
  ('robbery', 'GA', 'O.C.G.A. § 16-8-40', 'Robbery', 'Felony', '1 year', '20 years', NULL, '{"Defendant took property of another","From the person or immediately from the presence of another","By use of force, intimidation, threat, or placing the victim in fear","With intent to commit theft"}', NULL, '{"Victim 65 or older: mandatory minimum 5 years","Armed robbery: enhanced charge under § 16-8-41"}', 'Distinct from theft — requires taking from person or presence with force or fear. Sudden snatching charged separately under § 16-8-40(b).'),
  ('armed-robbery', 'GA', 'O.C.G.A. § 16-8-41', 'Armed Robbery', 'Felony', '10 years', '20 years or life', NULL, '{"Defendant took property of another","From the person or immediately from the presence of another","By use of an offensive weapon or any replica having the appearance of such a weapon","With intent to commit theft"}', '10 years mandatory; no parole, probation, or suspended sentence on the mandatory portion', '{"Firearm used: no parole or early release on minimum term","Victim 65 or older: additional mandatory time","Multiple victims: consecutive sentences"}', 'Imitation or replica firearm qualifies as offensive weapon. Home invasion robbery treated as armed robbery.'),
  ('kidnapping', 'GA', 'O.C.G.A. § 16-5-40', 'Kidnapping', 'Felony', '10 years', '20 years; life if victim is child under 14 and unrelated to defendant', NULL, '{"Defendant abducted or stole away any person without lawful authority","Held such person against their will","Act involved movement of the victim (asportation)"}', '10 years; life if victim is child under 14 and defendant is not a parent', '{"Ransom demand: mandatory life imprisonment","Sexual assault during kidnapping: consecutive charges"}', 'Slight movement (asportation) sufficient. Parental kidnapping charged separately under § 16-5-45.'),
  ('arson', 'GA', 'O.C.G.A. § 16-7-60', 'Arson in the First Degree', 'Felony', '1 year', '20 years', NULL, '{"Defendant knowingly damaged by fire or explosive","Any building, structure, or dwelling","Without consent of the owner OR with intent to defraud insurer"}', NULL, '{"Person endangered or harmed: enhanced penalty","Insurance fraud motive: fraud charges added","Second-degree arson (§ 16-7-61): non-dwelling property, 1-10 years"}', 'Second-degree arson covers vehicles and personal property. Third-degree (§ 16-7-62) covers woodland and brush fires.'),
  ('attempted-murder', 'GA', 'O.C.G.A. § 16-4-1; § 16-5-1', 'Attempted Murder', 'Felony', '1 year', '30 years', NULL, '{"Defendant took a substantial step toward committing murder","With the specific intent to commit murder","The act was beyond mere preparation"}', NULL, '{"Firearm used: mandatory additional time under § 17-10-6.1","Victim is law enforcement: enhanced penalty","Gang-related: RICO enhancements"}', 'Attempted felony punishable by 1-30 years. Courts impose substantial sentences for attempted murder.'),
  ('assault-with-deadly-weapon', 'GA', 'O.C.G.A. § 16-5-21(a)(2)', 'Aggravated Assault with a Deadly Weapon', 'Felony', '1 year', '20 years', NULL, '{"Defendant committed an assault on another person","With a deadly weapon or any object which, when used offensively, is likely to or actually does result in serious bodily injury"}', '3 years if a firearm was used; 5 years if victim is a public safety officer', '{"Firearm used: mandatory minimum 3 years no parole","Victim is law enforcement: mandatory minimum 5 years no parole","Vehicle used as deadly weapon: qualifies"}', 'Vehicle can constitute a deadly weapon when used to strike a person.'),
  ('theft-larceny', 'GA', 'O.C.G.A. § 16-8-2', 'Theft by Taking', 'Felony (value $1,500+); Misdemeanor (value under $1,500)', NULL, '10 years (felony); 12 months (misdemeanor)', '$1,000 (misdemeanor)', '{"Defendant unlawfully took or appropriated property belonging to another person","With intention of depriving the owner of the property"}', NULL, '{"Value $5,000-$24,999: 1-5 years felony range","Value $25,000+: 2-10 years felony range","Theft from elder: aggravating factor"}', 'GA felony threshold is $1,500. Multiple items may be aggregated if part of a common scheme.'),
  ('grand-theft', 'GA', 'O.C.G.A. § 16-8-2', 'Theft by Taking — Felony Amount', 'Felony', '1 year', '10 years', NULL, '{"Defendant unlawfully took property of another","Property value was $1,500 or more","With intent to deprive owner permanently"}', NULL, '{"Value $25,000+: 2-10 years mandatory range","Theft from elder: enhanced sentencing"}', 'Georgia does not use ''grand theft'' as a formal label — this is felony theft by taking under § 16-8-2.'),
  ('petty-theft', 'GA', 'O.C.G.A. § 16-8-2', 'Theft by Taking — Misdemeanor Amount', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant unlawfully took property of another","Property value was under $1,500","With intent to deprive owner permanently"}', NULL, '{"Prior theft convictions: aggregate charges may reach felony threshold"}', 'Georgia does not use ''petty theft'' as a formal label — this is misdemeanor theft by taking.'),
  ('shoplifting', 'GA', 'O.C.G.A. § 16-8-14', 'Shoplifting', 'Misdemeanor (under $500, 1st/2nd offense); Felony ($500+ or 3rd+ offense)', NULL, '12 months (misdemeanor); 10 years (felony)', '$1,000', '{"Defendant concealed or took possession of merchandise of a retail establishment","OR altered or transferred a price tag or moved merchandise between containers","With intent to deprive the merchant of possession or full retail value"}', NULL, '{"Organized retail crime with 3+ participants: felony regardless of value","3rd conviction within 5 years: felony","Booster bag or electronic shielding device used: enhanced charge"}', 'Civil demand statute allows merchants separate recovery. Merchant detention privilege under § 16-8-14(d).'),
  ('burglary', 'GA', 'O.C.G.A. § 16-7-1', 'Burglary', 'Felony', '1 year', '20 years', NULL, '{"Defendant entered or remained within a building, structure, vehicle, railroad car, watercraft, or aircraft","Without authority","With intent to commit a felony or theft therein"}', '1 year (1st degree residential); 2 years (2nd offense)', '{"Residential dwelling (1st degree): minimum 1 year mandatory","Prior burglary conviction: 2-year minimum","Armed during burglary: additional weapons charges"}', 'No breaking-and-entering required — unlawful remaining with felonious intent is sufficient.'),
  ('residential-burglary', 'GA', 'O.C.G.A. § 16-7-1(b)', 'Burglary in the First Degree — Residential', 'Felony', '1 year', '20 years', NULL, '{"Defendant entered or remained in a dwelling house of another","Without authority","With intent to commit a felony or theft therein"}', '1 year mandatory', '{"Victim present in dwelling at time of burglary: significant sentencing enhancement","2nd burglary offense: 2-year minimum"}', 'Dwelling must be used for habitation. Unoccupied vacation home still qualifies as a dwelling.'),
  ('commercial-burglary', 'GA', 'O.C.G.A. § 16-7-1(c)', 'Burglary in the Second Degree — Commercial', 'Felony', '1 year', '5 years', NULL, '{"Defendant entered or remained within a building or structure other than a dwelling","Without authority","With intent to commit a felony or theft therein"}', NULL, '{"Prior burglary: enhanced sentence","Weapon possessed: additional charges"}', 'Second-degree burglary covers commercial structures. Carries lesser penalty than residential burglary.'),
  ('motor-vehicle-theft', 'GA', 'O.C.G.A. § 16-8-2; § 40-4-20', 'Theft of Motor Vehicle', 'Felony', '1 year', '10 years', NULL, '{"Defendant unlawfully took or appropriated a motor vehicle belonging to another person","With intent to permanently deprive the owner of possession"}', NULL, '{"Carjacking (vehicle taken from person by force): armed robbery charges","Vehicle used in commission of another felony: additional charges"}', 'Joyriding without intent to permanently deprive is lesser offense of theft by conversion under § 16-8-7.'),
  ('receiving-stolen-property', 'GA', 'O.C.G.A. § 16-8-7', 'Theft by Receiving Stolen Property', 'Felony ($1,500+); Misdemeanor (under $1,500)', NULL, '10 years (felony); 12 months (misdemeanor)', NULL, '{"Defendant received, disposed of, or retained stolen property","Defendant knew or should have known the property was stolen","Intent to deprive the rightful owner"}', NULL, '{"Value over $25,000: enhanced felony sentence","Motor vehicle: automatic felony regardless of value"}', 'Knowledge inferred from suspicious circumstances. Recent possession of stolen property creates an inference.'),
  ('vandalism', 'GA', 'O.C.G.A. § 16-7-22; § 16-7-23', 'Criminal Damage to Property', 'Felony (1st degree, $500+ or reckless safety disregard); Misdemeanor (2nd degree, under $500)', NULL, '10 years (1st degree felony); 12 months (2nd degree misdemeanor)', NULL, '{"Defendant intentionally or knowingly caused damage to property of another","Without consent of the owner","Damage equaled $500 or more (1st degree) OR defendant acted with reckless disregard for safety"}', NULL, '{"Public utility or critical infrastructure: enhanced penalty","Religious institution: potential hate crime enhancement under § 17-10-17"}', 'First-degree under § 16-7-22 requires $500+ damage or reckless endangerment. Second-degree under § 16-7-23.'),
  ('trespassing', 'GA', 'O.C.G.A. § 16-7-21', 'Criminal Trespass', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant entered the land or premises of another person","For an unlawful purpose OR without being invited, licensed, or privileged to do so","OR remained on property after being asked to leave by an authorized person"}', NULL, '{"Critical infrastructure trespass: felony under § 16-7-23.3"}', 'Notice may be posted signs, verbal notice, or prior written notice. Physical force or breaking not required.'),
  ('criminal-mischief', 'GA', 'O.C.G.A. § 16-7-22; § 16-7-23', 'Criminal Damage to Property (Criminal Mischief)', 'Felony or Misdemeanor depending on damage amount', NULL, '10 years (felony); 12 months (misdemeanor)', NULL, '{"Defendant intentionally damaged property of another","Without the owner''s consent"}', NULL, '{}', 'Georgia uses ''criminal damage to property'' rather than ''criminal mischief.'' Damage amount determines classification.'),
  ('domestic-violence', 'GA', 'O.C.G.A. § 16-5-23.1; § 19-13-1', 'Family Violence Battery', 'Misdemeanor (1st offense); Felony (2nd+ offense against any family or household member)', NULL, '12 months (misdemeanor); 5 years (felony)', '$1,000', '{"Defendant committed battery against a family member or household member","Victim was spouse, former spouse, parent, child, person sharing same household, or person having child in common","Act was intentional and caused substantial physical harm or physical contact of insulting or provoking nature"}', NULL, '{"2nd+ family violence conviction: felony classification","Aggravated assault or aggravated battery in family violence: felony on first offense"}', 'Mandatory arrest policy in many GA jurisdictions. State may proceed without victim cooperation.'),
  ('domestic-battery', 'GA', 'O.C.G.A. § 16-5-23.1(f)', 'Family Violence Battery (Domestic Battery)', 'Misdemeanor (1st offense); Felony (2nd+ offense)', NULL, '12 months (misdemeanor); 5 years (felony)', '$1,000', '{"Defendant intentionally caused substantial physical harm or made provoking contact","Against a family or household member as defined in the Family Violence Act"}', NULL, '{"Violation of TPO concurrent: additional charge","Child witness: aggravating sentencing factor"}', 'Family violence designation triggers federal firearms prohibition under 18 U.S.C. § 922(g)(9).'),
  ('child-endangerment', 'GA', 'O.C.G.A. § 16-12-1', 'Contributing to the Delinquency or Deprivation of a Minor', 'Misdemeanor; Felony if serious injury or death results', NULL, '12 months (misdemeanor); 20 years (felony with serious injury or death)', '$1,000', '{"Defendant caused or encouraged a minor to violate any law","OR committed acts causing or likely to cause a minor to become delinquent, unruly, or deprived","Victim was a child under 18"}', NULL, '{"DUI with child under 14 in vehicle: additional misdemeanor under § 40-6-391(l)","Serious injury or death resulting: felony charges"}', 'Child cruelty under § 16-5-70 more appropriate when physical abuse is involved.'),
  ('child-abuse', 'GA', 'O.C.G.A. § 16-5-70', 'Cruelty to Children', 'Felony', '5 years (1st degree)', '20 years (1st degree); 10 years (2nd degree)', NULL, '{"Defendant maliciously caused a child under 18 cruel or excessive physical or mental pain (1st degree)","OR parent or guardian willfully deprived a child of necessary sustenance to the extent health was jeopardized (2nd degree)","Act was knowing and intentional"}', '5 years (1st degree cruelty to children)', '{"Death resulting from abuse: murder or felony murder charges","Pattern of repeated abuse: aggravating sentencing factor"}', '1st degree requires malicious intent. 2nd degree under § 16-5-70(b) involves willful deprivation.'),
  ('violation-protective-order', 'GA', 'O.C.G.A. § 16-5-95', 'Violation of Protective Order', 'Misdemeanor (1st offense); High and Aggravated Misdemeanor (2nd offense); Felony (3rd+ offense)', NULL, '12 months (misdemeanor); $5,000 fine (aggravated); 5 years (felony)', '$5,000', '{"A valid protective order or temporary protective order had been issued against the defendant","Defendant had actual knowledge of the order","Defendant willfully violated specific terms of the order"}', NULL, '{"Violence committed during violation: additional assault or battery charges","3rd violation: felony classification"}', 'Order must be properly served, or defendant must have actual knowledge. Constructive knowledge insufficient in Georgia.'),
  ('stalking', 'GA', 'O.C.G.A. § 16-5-90', 'Stalking', 'Misdemeanor (1st offense); Felony (2nd+ offense or aggravated)', NULL, '12 months (misdemeanor); 10 years (felony)', '$1,000', '{"Defendant followed, placed under surveillance, or contacted another person","Without consent and for the purpose of harassing and intimidating that person","Contact occurred at or near their home, workplace, school, or location they regularly frequent"}', NULL, '{"2nd conviction: felony","Aggravated stalking (§ 16-5-91) — violation of court order: felony, 1-10 years"}', 'Aggravated stalking charged when defendant violates bond, protective order, or probation/parole condition.'),
  ('harassment', 'GA', 'O.C.G.A. § 16-11-39.1', 'Harassing Communications', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant made telephonic, electronic, or written contact with another person","With intent to harass, annoy, or alarm that person","Contact was unwanted"}', NULL, '{"Threat of violence included: terroristic threats charge under § 16-11-37","2nd offense: enhanced misdemeanor"}', 'Separate from stalking which requires a surveillance or following pattern.'),
  ('elder-abuse', 'GA', 'O.C.G.A. § 16-5-102', 'Exploitation of Elder Person or Disabled Adult', 'Felony', '1 year', '20 years', NULL, '{"Defendant knowingly and willfully exploited, abused, or neglected an elder person (65+) or disabled adult","OR a caretaker neglected the basic needs of a person in their care","Act caused physical or financial harm"}', NULL, '{"Caregiver in position of trust: enhanced sentencing","Financial exploitation over $1,500: felony theft charges added"}', 'Mandatory reporting required for healthcare workers and care facilities.'),
  ('weapons-possession', 'GA', 'O.C.G.A. § 16-11-127; § 16-11-127.1', 'Carrying Weapon in Unauthorized Location', 'Misdemeanor or Felony depending on location', NULL, '12 months (misdemeanor); 5 years (felony — school zone)', '$1,000', '{"Defendant carried or possessed a firearm or weapon","In a location where carrying is prohibited (schools, government buildings, courts, polling places)","With knowledge of possession"}', NULL, '{"Carrying in school safety zone: felony under § 16-11-127.1","Armed during commission of felony: mandatory add-on under § 17-10-6.1"}', 'Georgia enacted permitless carry (HB 218, April 2022) for eligible persons. Prohibited locations still constitute offenses.'),
  ('felon-in-possession', 'GA', 'O.C.G.A. § 16-11-131', 'Possession of Firearm or Knife by Convicted Felon', 'Felony', '1 year', '10 years', NULL, '{"Defendant was convicted of a felony","Defendant received, possessed, or transported any firearm or knife with blade 3 inches or more","Defendant had actual or constructive possession with knowledge"}', '1 year mandatory; 5 years if prior conviction was a violent felony', '{"Prior violent felony: mandatory 5 years no probation","Federal concurrent: 18 U.S.C. § 922(g)(1)"}', 'Rights restoration possible only through full pardon. Also applies to certain family violence misdemeanants.'),
  ('concealed-carry-violation', 'GA', 'O.C.G.A. § 16-11-127', 'Carrying in Prohibited Location — Weapons Carry License Context', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant carried a weapon in a location prohibited by statute","Location included courthouse, polling place, government building, or school zone","Defendant had knowledge of the prohibited status of the location"}', NULL, '{"School zone: felony under § 16-11-127.1"}', 'Georgia permits constitutional/permitless carry since April 2022. Carrying in specific prohibited locations remains an offense.'),
  ('illegal-discharge', 'GA', 'O.C.G.A. § 16-11-103', 'Discharge of Firearm Near Public Highway or Street', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant discharged a firearm","On or within 50 yards of a public road or highway","Across, into, or upon the road or right-of-way"}', NULL, '{"Shooting from a vehicle toward another: aggravated assault charges","Injury to another: battery or aggravated battery charges"}', 'Separate provisions for discharge in incorporated areas. Reckless discharge covered under O.C.G.A. § 16-11-104.'),
  ('weapons-trafficking', 'GA', 'O.C.G.A. § 16-11-126; Federal: 18 U.S.C. § 922', 'Trafficking in Firearms', 'Felony', '1 year', '10 years (state); enhanced federal penalties', NULL, '{"Defendant transferred, sold, or disposed of a firearm to a person known to be a prohibited possessor","OR engaged in unlicensed dealing in firearms as a business","With knowledge of the prohibited nature of the transaction"}', NULL, '{"Straw purchase for felon: federal charges","Ghost guns or untraceable firearms: enhanced federal penalty"}', 'Large-scale firearms trafficking typically prosecuted federally under 18 U.S.C. § 922.'),
  ('possession-prohibited-weapon', 'GA', 'O.C.G.A. § 16-11-121; § 16-11-123', 'Possession of Machine Gun, Sawed-Off Firearm, or Silencer', 'Felony', '2 years', '10 years', NULL, '{"Defendant possessed a machine gun, sawed-off rifle, sawed-off shotgun, or silencer","Weapon was not properly registered under the National Firearms Act","Defendant had actual or constructive possession with knowledge"}', '2 years', '{"Use in commission of a crime: additional charges","Federal NFA violation: concurrent federal felony charges"}', 'NFA-registered weapons are legal. State felony applies to unregistered NFA items.'),
  ('wire-fraud', 'GA', 'O.C.G.A. § 16-9-93; Federal: 18 U.S.C. § 1343', 'Computer Fraud / Wire Fraud', 'Felony', '1 year', '15 years (state); 20 years (federal)', NULL, '{"Defendant used a computer or telecommunications device","To obtain money, property, or services through fraudulent means","With intent to defraud"}', NULL, '{"Financial institution victim: enhanced federal penalties","Large monetary amount: enhanced sentence","Identity theft component: additional charges"}', 'GA Computer Systems Protection Act under § 16-9-90 et seq. Federal wire fraud typically prosecuted in federal court.'),
  ('identity-theft', 'GA', 'O.C.G.A. § 16-9-121', 'Financial Identity Fraud', 'Felony', '1 year', '10 years', NULL, '{"Defendant used the identifying information of another person","Without that person''s consent","With intent to defraud","To obtain credit, goods, services, money, or to commit any felony"}', NULL, '{"10 or more victims: enhanced felony penalty","Elder victim (65+): enhanced penalty"}', '§ 16-9-121 covers financial identity fraud. § 16-9-122 covers identity fraud for non-financial purposes.'),
  ('embezzlement', 'GA', 'O.C.G.A. § 16-8-4', 'Theft by Conversion (Embezzlement)', 'Felony ($1,500+); Misdemeanor (under $1,500)', NULL, '10 years (felony); 12 months (misdemeanor)', NULL, '{"Defendant lawfully obtained funds or property entrusted to them by another","Defendant converted the property to their own use","With intent to defraud the owner","Defendant was in a position of trust with respect to the property"}', NULL, '{"Public official or fiduciary: enhanced sentencing","Large amounts: enhanced felony tier"}', 'Trust relationship distinguishes embezzlement from ordinary theft.'),
  ('forgery', 'GA', 'O.C.G.A. § 16-9-1', 'Forgery', 'Felony', '1 year', '15 years', NULL, '{"Defendant made, altered, or possessed a writing","With intent to defraud","Writing appeared to be made by another person, or was falsely dated or fraudulently made to represent a different transaction"}', NULL, '{"Currency or government documents: enhanced penalty","Identity theft connected: additional charges"}', 'First-degree forgery (§ 16-9-1): checks, credit cards, government IDs. Second-degree (§ 16-9-2): other commercial documents.'),
  ('counterfeiting', 'GA', 'O.C.G.A. § 16-9-1; Federal: 18 U.S.C. § 471', 'Counterfeiting', 'Felony', '1 year (state)', '15 years (state); 20 years (federal currency counterfeiting)', NULL, '{"Defendant made, possessed, or uttered counterfeit currency, securities, or other instruments","With intent to defraud","Items resembled genuine currency, securities, or instruments"}', NULL, '{"Federal currency counterfeiting: exclusive federal jurisdiction","Large amounts: enhanced federal penalty"}', 'Currency counterfeiting is primarily a federal offense. State forgery statute covers counterfeit checks and documents.'),
  ('bad-checks', 'GA', 'O.C.G.A. § 16-9-20', 'Deposit Account Fraud (Bad Checks)', 'Misdemeanor (under $1,500); Felony ($1,500+)', NULL, '12 months (misdemeanor); 10 years (felony)', '$1,000', '{"Defendant drew, made, uttered, or delivered a check or draft","Defendant knew at the time of issuance there were insufficient funds or no account","With intent to defraud the recipient"}', NULL, '{"Multiple returned checks: aggregated value may reach felony threshold"}', '10-day notice provision: payment within 10 days of returned check notice may negate criminal intent.'),
  ('tax-fraud', 'GA', 'O.C.G.A. § 48-7-2; Federal: 26 U.S.C. § 7201', 'Tax Fraud / Tax Evasion', 'Felony (state); Felony (federal)', '1 year (state)', '5 years (state); 5 years (federal tax evasion)', '$100,000 (state); $250,000 (federal)', '{"Defendant willfully failed to file a required tax return or pay taxes owed","OR willfully made false or fraudulent statements on a tax return","Act was knowing and intentional"}', NULL, '{"Large amount evaded: enhanced sentencing","Federal concurrent prosecution: 26 U.S.C. § 7201","Money laundering of tax proceeds: additional charge"}', 'GA Department of Revenue enforces state tax crimes. IRS handles federal tax evasion.'),
  ('insurance-fraud', 'GA', 'O.C.G.A. § 33-1-9', 'Insurance Fraud', 'Felony (claim over $1,000); Misdemeanor (claim under $1,000)', NULL, '10 years (felony); 12 months (misdemeanor)', '$10,000 (felony)', '{"Defendant presented or caused to be presented a false or fraudulent claim to an insurer","OR made false statements in connection with an insurance application or claim","With intent to defraud the insurer","Claim was material to the insurance decision"}', NULL, '{"Healthcare insurance fraud: enhanced penalties","Organized fraud ring: RICO charges possible","Arson for insurance: additional arson charges"}', 'Georgia Insurance Fraud Prevention Act under § 33-1-9. Insurance Commissioner investigates.'),
  ('credit-card-fraud', 'GA', 'O.C.G.A. § 16-9-33', 'Credit Card Fraud', 'Felony (over $100 or 2+ transactions within 6 months)', NULL, '10 years', NULL, '{"Defendant used a credit card or credit card number without the cardholder''s authorization","With intent to defraud the cardholder or issuer","Obtained goods, services, or money thereby"}', NULL, '{"Identity theft component: additional charges","Card skimming device used: enhanced penalty"}', 'Georgia Credit Card Crime Law at § 16-9-31 et seq. covers manufacture, use, and trafficking in fraudulent cards.'),
  ('money-laundering', 'GA', 'O.C.G.A. § 7-1-922', 'Money Laundering', 'Felony', NULL, '20 years or twice the value laundered, whichever is greater', '$250,000 or twice the amount laundered', '{"Defendant conducted a financial transaction involving proceeds of specified unlawful activity","Defendant knew the proceeds were derived from unlawful activity","With intent to promote unlawful activity OR to conceal the nature or source of the proceeds"}', NULL, '{"RICO connection: additional charges","Drug trafficking proceeds: federal parallel prosecution under 18 U.S.C. § 1956"}', 'GA Banking and Finance Code § 7-1-922 is the state provision. Large cases typically prosecuted federally.'),
  ('fraud-general', 'GA', 'O.C.G.A. § 16-8-3', 'Theft by Deception', 'Felony ($1,500+); Misdemeanor (under $1,500)', NULL, '10 years (felony); 12 months (misdemeanor)', NULL, '{"Defendant obtained property of another by deceit","Defendant created or confirmed a false impression as to a past or present fact","Victim relied on the deception","Defendant intended to deprive victim of the property"}', NULL, '{"Elder victim (65+): enhanced penalty","Internet or wire used: computer fraud charges may be added"}', 'Theft by deception under § 16-8-3. Covers false pretenses and fraudulent misrepresentation.'),
  ('bank-fraud', 'GA', 'O.C.G.A. § 16-9-1; Federal: 18 U.S.C. § 1344', 'Bank Fraud', 'Felony', '1 year (state)', '15 years (state); 30 years (federal)', '$1,000,000 (federal)', '{"Defendant knowingly executed or attempted to execute a scheme to defraud a financial institution","OR to obtain moneys or property owned by a financial institution by means of false pretenses","With intent to defraud"}', NULL, '{"During financial crisis or emergency: enhanced federal penalty","Identity theft component: additional charges"}', 'Bank fraud typically prosecuted federally under 18 U.S.C. § 1344. State charges used for local institution cases.'),
  ('securities-fraud', 'GA', 'O.C.G.A. § 10-5-51; Federal: 15 U.S.C. § 78j', 'Securities Fraud', 'Felony', '1 year (state)', '10 years (state); 20 years (federal)', '$5,000,000 (federal)', '{"Defendant made an untrue statement of a material fact or omitted a material fact","In connection with the offer, purchase, or sale of a security","With intent to deceive and defraud investors"}', NULL, '{"Ponzi scheme: enhanced federal charges","Large number of victims: enhanced penalty"}', 'Georgia Securities Act of 2008 governs state securities fraud. SEC handles federal securities fraud.'),
  ('sex-offense-contact', 'GA', 'O.C.G.A. § 16-6-22.1', 'Sexual Battery', 'Misdemeanor (1st offense); Felony (subsequent offense or victim under 16)', NULL, '12 months (1st misdemeanor); 1-25 years (felony)', NULL, '{"Defendant intentionally made physical contact with the intimate parts of another person","Without the consent of that person"}', '25 years if victim is under 16 (aggravated form); sex offender registration required', '{"Victim under 16: mandatory sex offender registration","Prior sex offense: enhanced mandatory sentence"}', 'Sexual battery (§ 16-6-22.1) is misdemeanor for first offense. Aggravated sexual battery (§ 16-6-22.2) — object penetration — always felony.'),
  ('sexual-assault', 'GA', 'O.C.G.A. § 16-6-22.2', 'Aggravated Sexual Battery', 'Felony', '25 years if victim under 16', 'Life imprisonment', NULL, '{"Defendant intentionally penetrated the sexual organ or anus of another person with a foreign object","Without the consent of that person"}', '25 years mandatory minimum if victim is under 16; lifetime sex offender registration', '{"Prior sex offense: life imprisonment","Victim under 10: mandatory life"}', 'Aggravated sexual battery covers penetration with a foreign object. Rape (§ 16-6-1) covers penile penetration.'),
  ('rape', 'GA', 'O.C.G.A. § 16-6-1', 'Rape', 'Felony', '25 years', 'Life imprisonment', NULL, '{"Defendant had carnal knowledge of a female","Forcibly and against her will","OR victim was under 10 years of age (per se regardless of consent)"}', '25 years mandatory; lifetime sex offender registration', '{"Victim under 16: life imprisonment possible","Prior rape conviction: mandatory life imprisonment"}', 'GA rape statute covers penile-vaginal penetration. Other penetration offenses covered by aggravated sexual battery (§ 16-6-22.2).'),
  ('indecent-exposure', 'GA', 'O.C.G.A. § 16-6-8', 'Public Indecency', 'Misdemeanor (1st/2nd offense); Felony (3rd+ offense)', NULL, '12 months (misdemeanor); 5 years (3rd+ offense felony)', '$1,000', '{"Defendant performed an act of sexual intercourse or exposed genitals in a lewd and lascivious manner","In a public place","In the presence of or likely to be observed by another person"}', NULL, '{"3rd conviction: felony and sex offender registration may be required","Exposure to a minor: enhanced charges"}', 'Third conviction may trigger sex offender registration under § 42-1-12.'),
  ('solicitation-prostitution', 'GA', 'O.C.G.A. § 16-6-9; § 16-6-10; § 16-6-11', 'Prostitution, Pimping, and Pandering', 'Misdemeanor (prostitution/solicitation); Felony (pimping, pandering by compulsion)', NULL, '12 months (prostitution/solicitation); 10 years (pandering by compulsion)', '$1,000', '{"Defendant performed or offered to perform sexual acts for money or other consideration (prostitution)","OR solicited another person to perform sexual acts for money (solicitation)","Exchange of consideration was part of the transaction"}', NULL, '{"Minor victim: trafficking in persons charges under § 16-5-46","Promoting prostitution or pimping: felony"}', 'Sex trafficking of minors charged as trafficking in persons under § 16-5-46 regardless of force or coercion.'),
  ('sex-offense-digital', 'GA', 'O.C.G.A. § 16-6-22.2; § 16-12-100.2', 'Aggravated Sexual Battery / Computer or Electronic Pornography', 'Felony', '1 year', '25 years (aggravated sexual battery); 20 years (child exploitation via digital means)', NULL, '{"Defendant used electronic or digital means to engage in or facilitate a sexual offense","OR digitally penetrated a victim without consent","Acts were knowing and intentional"}', NULL, '{"Child victim: child exploitation statutes apply","Online solicitation of minor: O.C.G.A. § 16-12-100.2"}', 'Online solicitation of a child for sexual purposes under § 16-12-100.2 — separate statute.'),
  ('child-exploitation', 'GA', 'O.C.G.A. § 16-12-100', 'Sexual Exploitation of Children', 'Felony', '5 years', '20 years per count', NULL, '{"Defendant employed, used, persuaded, or coerced a minor to engage in sexually explicit conduct for visual depiction","OR knowingly possessed, distributed, or transmitted visual depictions of minors in sexually explicit conduct","Minor was under 18 years of age"}', '5 years mandatory; lifetime sex offender registration', '{"Production: higher sentencing range than possession","Large quantity: each image or video may be a separate count","Federal concurrent: 18 U.S.C. § 2252"}', 'Federal charges typically concurrent. Internet transmission explicitly covered.'),
  ('failure-to-register', 'GA', 'O.C.G.A. § 42-1-12', 'Failure to Register as a Sex Offender', 'Felony', '1 year', '30 years', NULL, '{"Defendant was required to register as a sex offender under Georgia law","Defendant failed to register or failed to update registration within required time","Defendant had actual notice of the registration requirement"}', '1 year; 5-year minimum for 2nd offense', '{"2nd offense: mandatory minimum 5 years","Absconding from supervision jurisdiction: 10-year minimum"}', 'Residency restrictions under § 42-1-15 also apply (school, church, park proximity).'),
  ('statutory-rape', 'GA', 'O.C.G.A. § 16-6-3', 'Statutory Rape', 'Felony', '1 year', '20 years; life if defendant is 21+ and victim is under 14', NULL, '{"Defendant had sexual intercourse with another person under 16 years of age","Consent is not a defense","Defendant was 21 or older (for enhanced mandatory minimum)"}', '10 years mandatory if defendant is 21+ and victim is under 14', '{"Defendant 21+ with victim under 14: 10-year mandatory minimum","Position of trust or authority: aggravating factor"}', 'No close-in-age exemption in GA. Any sexual intercourse with a person under 16 is statutory rape regardless of defendant''s age.'),
  ('sexual-battery', 'GA', 'O.C.G.A. § 16-6-22.1', 'Sexual Battery', 'Misdemeanor (1st offense against adult); Felony (subsequent offense or victim under 16)', NULL, '12 months (misdemeanor); 1-25 years (felony)', NULL, '{"Defendant intentionally made physical contact with the intimate parts of another person","Without the consent of that person"}', NULL, '{"Victim under 16: felony with possible mandatory registration","Position of authority over victim: aggravating factor"}', 'Intimate parts defined as genitals, buttocks, groin, inner thighs, or female breasts.'),
  ('disorderly-conduct', 'GA', 'O.C.G.A. § 16-11-39', 'Disorderly Conduct', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant acted in a violent, tumultuous, or boisterous manner","OR used obscene language in the presence of a minor causing reasonable fear of injury","OR acted in a manner creating loud and unreasonable noise disturbing the tranquility of others","OR used fighting words likely to provoke an immediate breach of peace"}', NULL, '{}', 'Must be applied carefully to avoid First Amendment violations. Fighting words doctrine governs speech-based charges.'),
  ('resisting-arrest', 'GA', 'O.C.G.A. § 16-10-24', 'Obstruction of a Law Enforcement Officer', 'Misdemeanor (non-violent obstruction); Felony (violent obstruction)', NULL, '12 months (misdemeanor); 5 years (felony violent)', '$1,000', '{"Defendant knowingly and willfully obstructed or hindered a law enforcement officer","In the lawful discharge of the officer''s official duties","By act or omission"}', NULL, '{"Violence against officer: felony, 1-5 years","Injury caused to officer: aggravated penalty"}', 'Providing a false name to an officer also constitutes obstruction. Non-violent refusal may still qualify as misdemeanor obstruction.'),
  ('obstruction-justice', 'GA', 'O.C.G.A. § 16-10-24; § 16-10-32', 'Obstruction of Justice', 'Misdemeanor or Felony depending on conduct', NULL, '5 years (felony); 12 months (misdemeanor)', '$5,000', '{"Defendant obstructed, hindered, or opposed a law enforcement officer or judicial proceeding","Act was knowing and intentional","Officer or proceeding was lawful"}', NULL, '{"Evidence tampering under § 16-10-94: separate felony","Witness intimidation under § 16-10-93: felony"}', 'False statements to officers during investigation covered under § 16-10-20.'),
  ('contempt-of-court', 'GA', 'O.C.G.A. § 15-1-4', 'Contempt of Court', 'Misdemeanor', NULL, '20 days imprisonment (criminal contempt) per occurrence', '$500 per occurrence', '{"Defendant was subject to a valid court order","Defendant willfully failed to comply or engaged in conduct disrupting judicial proceedings","Court had jurisdiction to issue the order"}', NULL, '{"Repeated contempt: consecutive penalties"}', 'Direct contempt (in court) vs. indirect contempt (outside court). Criminal contempt requires proof beyond reasonable doubt.'),
  ('public-intoxication', 'GA', 'O.C.G.A. § 16-11-41', 'Public Drunkenness', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant appeared in a public place in an intoxicated condition caused by alcohol or drugs","Intoxication manifested by boisterous or indecent conduct, or loud and profane discourse"}', NULL, '{}', 'Simple intoxication in public is not a crime in GA without the disorderly conduct element.'),
  ('loitering', 'GA', 'O.C.G.A. § 16-11-36', 'Loitering or Prowling', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant loitered or prowled in a place, at a time, or in a manner not usual for law-abiding individuals","Under circumstances that warranted alarm for the safety of persons or property in the vicinity","Defendant refused to identify themselves and explain their presence when requested by an officer"}', NULL, '{}', 'Officer must request identification before arrest. Defendant must have opportunity to explain before being arrested.'),
  ('disturbing-peace', 'GA', 'O.C.G.A. § 16-11-34', 'Unlawful Assembly / Disturbing the Peace', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant, together with others, engaged in tumultuous conduct","OR incited others to engage in tumultuous or unlawful conduct","Conduct created a public disturbance"}', NULL, '{}', 'Riot charges under § 16-11-33 for 2+ persons using force or violence. Incitement to riot under § 16-11-31.'),
  ('failure-to-appear', 'GA', 'O.C.G.A. § 17-6-12; § 16-10-51', 'Failure to Appear', 'Misdemeanor (misdemeanor underlying charge); Felony (felony underlying charge)', NULL, '12 months (misdemeanor underlying); 5 years (felony underlying)', NULL, '{"Defendant was released on bail or bond for a pending criminal matter","Defendant had notice of the scheduled court appearance","Defendant failed to appear without lawful excuse"}', NULL, '{"Flight across state lines: federal failure to appear under 18 U.S.C. § 3146"}', 'Criminal FTA is a standalone offense. Bench warrant issued upon failure to appear.'),
  ('false-report', 'GA', 'O.C.G.A. § 16-10-26', 'False Report of a Crime', 'Misdemeanor', NULL, '12 months imprisonment', '$1,000', '{"Defendant made a report to law enforcement or emergency services","Defendant knew the report was false","Report described a crime or emergency that did not occur"}', NULL, '{"Swatting: enhanced penalty under § 16-10-26.1 (added 2019)"}', 'False fire or bomb threats charged separately under § 16-10-33.'),
  ('criminal-threat', 'GA', 'O.C.G.A. § 16-11-37', 'Terroristic Threats and Acts', 'Felony (threat of violence); Misdemeanor (threat to property)', '1 year (felony)', '5 years (felony); 12 months (misdemeanor)', '$1,000', '{"Defendant threatened to commit a crime of violence against another person or group","OR threatened to release a hazardous substance with intent to terrorize","Threat placed victim in reasonable apprehension of serious bodily injury"}', NULL, '{"Threat against a school: enhanced penalty","Electronic transmission: cyberstalking or cyberterrorism enhancement"}', 'Threats of violence are felony under § 16-11-37(b). Bomb threats may be misdemeanor.'),
  ('probation-violation', 'GA', 'O.C.G.A. § 42-8-38', 'Probation Revocation', 'Depends on original underlying offense', NULL, 'Balance of original suspended sentence', NULL, '{"Defendant was lawfully placed on probation","Defendant violated a condition of probation","Violation was willful"}', NULL, '{"New criminal offense while on probation: revocation plus new charges"}', 'Court may modify, continue, or revoke. Preponderance of evidence standard at revocation hearing.'),
  ('probation-violation-technical', 'GA', 'O.C.G.A. § 42-8-38', 'Technical Probation Violation', 'Administrative — probation revocation', NULL, 'Revocation of remaining probated sentence', NULL, '{"Defendant was on probation","Defendant failed to comply with a non-criminal technical condition such as failure to report, failure to pay fines, or positive drug test"}', NULL, '{}', 'GA reformed technical violations to limit revocation for non-criminal violations. Short confinement periods may apply.'),
  ('probation-violation-substantive', 'GA', 'O.C.G.A. § 42-8-38', 'Substantive Probation Violation — New Criminal Offense', 'Probation revocation plus new criminal charge', NULL, 'Balance of original sentence + new sentence', NULL, '{"Defendant was on probation","Defendant committed a new criminal offense while on probation","New offense constitutes a violation of probation conditions"}', NULL, '{}', 'Revocation hearing uses preponderance standard. New criminal charge uses beyond reasonable doubt standard.'),
  ('parole-violation', 'GA', 'O.C.G.A. § 42-9-51', 'Parole Revocation', 'Administrative — parole revocation', NULL, 'Return to prison for remainder of original sentence', NULL, '{"Defendant was on parole","Defendant violated conditions of parole","Georgia Board of Pardons and Paroles determined violation warranted revocation"}', NULL, '{}', 'GA Board of Pardons and Paroles has exclusive authority over parole revocation.'),
  ('community-control-violation', 'GA', 'O.C.G.A. § 42-8-34.1', 'Violation of Special Probation / Intensive Probation', 'Depends on original offense', NULL, 'Revocation of remaining sentence', NULL, '{"Defendant was on intensive probation or special conditions probation","Defendant violated specific conditions of the intensive supervision program","Violation was willful"}', NULL, '{}', 'Georgia uses intensive probation supervision (IPS) for high-risk offenders. Violation triggers revocation hearing.'),
  ('conspiracy', 'GA', 'O.C.G.A. § 16-4-8', 'Criminal Conspiracy', 'Same felony class as target offense; Misdemeanor if target offense is misdemeanor', NULL, 'Same maximum as completed target offense', NULL, '{"Two or more persons agreed to commit an offense","Defendant was a party to the agreement","At least one overt act was committed in furtherance of the conspiracy","Defendant had specific intent to carry out the objective"}', NULL, '{"Drug trafficking conspiracy: mandatory minimums of underlying trafficking statute apply","RICO predicate: gang statute enhancement under § 16-14-4"}', 'Overt act required in Georgia. Each co-conspirator liable for acts of others in furtherance. Withdrawal is an affirmative defense.'),
  ('rico', 'GA', 'O.C.G.A. § 16-14-4', 'Georgia RICO — Racketeer Influenced and Corrupt Organizations', 'Felony', '1 year', '20 years', '$25,000 or three times the proceeds derived', '{"Defendant was associated with an enterprise","Defendant conducted or participated in the affairs of the enterprise through a pattern of racketeering activity","Pattern consisted of at least two predicate acts within a 4-year period","Predicate acts were defined criminal offenses under § 16-14-3"}', '1 year', '{"Gang activity as enterprise: concurrent street gang terrorism charges under § 16-15-4","Murder as predicate: life imprisonment possible","Asset forfeiture: mandatory"}', 'Georgia RICO is broader than federal RICO. Widely used in gang prosecutions. Asset forfeiture available.'),
  ('self-defense', 'GA', 'O.C.G.A. § 16-3-21; § 16-3-23; § 16-3-23.1', 'Justification — Self-Defense / Stand Your Ground', 'Affirmative defense — not an offense', NULL, NULL, NULL, '{"Defendant used force against another person","Defendant reasonably believed force was necessary to defend against imminent unlawful force","Defendant was not the initial aggressor","Under Stand Your Ground: no duty to retreat if defendant is in any place they have a legal right to be"}', NULL, '{}', 'Georgia has a broad Stand Your Ground law. Immunity hearing available before trial under § 16-3-24.2. Castle Doctrine under § 16-3-23 provides additional protection inside the home.'),
  ('other', 'GA', 'Various O.C.G.A. provisions', 'Miscellaneous Georgia Criminal Offenses', 'Varies', NULL, 'Varies by specific offense', NULL, '{"Elements specific to each offense as defined under the Georgia Official Code Annotated"}', NULL, '{}', 'Catch-all for Georgia offenses not otherwise enumerated. Consult the specific O.C.G.A. section for elements, penalties, and defenses.')
INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('dui-dwi', 'IL', '625 ILCS 5/11-501', 'Driving Under the Influence of Alcohol, Other Drug or Drugs, Intoxicating Compound or Compounds or Any Combination Thereof', 'Class A Misdemeanor (1st/2nd offense); Class 4 Felony (3rd offense)', NULL, '1 year (misdemeanor); 3 years (Class 4 felony)', '$2,500 (misdemeanor); $25,000 (felony)', '{"Operated a motor vehicle","On a public highway or other public or private property used for vehicular travel","While under the influence of alcohol (BAC 0.08+) or other drugs or combination that rendered the person incapable of safely driving"}', '100 hours community service or 5 days imprisonment for second offense', '{"Aggravated DUI (Class 4 Felony): 3rd+ offense, DUI without valid license, DUI in school zone","Class 2 Felony: DUI causing great bodily harm","Class 1 Felony: DUI causing death","BAC 0.16+ doubles minimum fine on first offense","Presence of child under 16 in vehicle: additional Class 6 Felony charge"}', 'Illinois DUI law includes 11 separate bases for DUI under 625 ILCS 5/11-501(a). Statutory summary suspension of driving privileges applies automatically on arrest.'),
  ('dui-first-offense', 'IL', '625 ILCS 5/11-501', 'Driving Under the Influence — First Offense', 'Class A Misdemeanor', NULL, '1 year', '$2,500', '{"First DUI conviction or supervision","Operated a motor vehicle while impaired by alcohol or drugs"}', NULL, '{"If BAC 0.16+: mandatory minimum $500 fine and 100 hours community service","If transporting child under 16: additional Class 6 Felony (720 ILCS 5/12-3.05)"}', 'First offense DUI is eligible for court supervision, which avoids a conviction on record if successfully completed. Minimum 1-year statutory summary suspension.'),
  ('dui-repeat-offense', 'IL', '625 ILCS 5/11-501', 'Driving Under the Influence — Repeat Offense', 'Class A Misdemeanor (2nd); Class 4 to Class 2 Felony (3rd+)', '5 days imprisonment or 240 hours community service (2nd offense)', '1 year (2nd); 3 to 7 years (3rd+ felony)', '$2,500 (2nd); $25,000 (felony)', '{"Prior DUI conviction or supervision on record","Current DUI offense proven under 625 ILCS 5/11-501"}', '5 days or 240 community service hours for 2nd offense', '{"3rd offense: Class 4 Felony (3-year revocation)","4th offense: Class 4 Felony (lifetime revocation)","5th offense: Class 1 Felony","6th+ offense: Class X Felony"}', 'Illinois maintains a lifetime look-back for prior DUI offenses. 3rd+ offense results in permanent felony record.'),
  ('dui-drugs', 'IL', '625 ILCS 5/11-501(a)(4),(5),(6),(7)', 'Driving Under the Influence of Drugs or Intoxicating Compound', 'Class A Misdemeanor (1st); Class 4 Felony (3rd+)', NULL, '1 year (misdemeanor); 3 years (felony)', '$2,500 (misdemeanor)', '{"Operated a motor vehicle","While under the influence of any drug or combination of drugs that rendered driver incapable of safely driving","OR with presence of cocaine, heroin, methamphetamine, or cannabis metabolite exceeding statutory thresholds"}', NULL, '{"Same felony escalation as alcohol DUI for repeat offenses","Cannabis DUI threshold: 5 nanograms THC per mL blood or 10 ng per mL other bodily substance"}', 'Per se drug DUI under 11-501(a)(6) applies to cannabis. Zero-tolerance for other controlled substances under 11-501(a)(5).'),
  ('reckless-driving', 'IL', '625 ILCS 5/11-503', 'Reckless Driving', 'Class A Misdemeanor; Class 4 Felony if great bodily harm results', NULL, '1 year (misdemeanor); 3 years (felony)', '$2,500', '{"Operated a vehicle on any highway or private property used for vehicle traffic","With willful or wanton disregard for the safety of persons or property","OR used an incline in a highway to cause the vehicle to become airborne"}', NULL, '{"Class 4 Felony if reckless driving causes great bodily harm, permanent disability, or disfigurement","Aggravated if committed in a school zone"}', NULL),
  ('hit-and-run', 'IL', '625 ILCS 5/11-401', 'Motor Vehicle Accident Involving Death or Personal Injuries — Duty to Stop', 'Class 4 Felony (injury); Class 1 Felony (death)', NULL, '3 years (Class 4); 15 years (Class 1)', '$25,000', '{"Driver of a vehicle involved in an accident resulting in injury or death","Failed to immediately stop at the scene","Failed to provide name, address, and vehicle registration information","Failed to render reasonable assistance to injured persons"}', NULL, '{"Class 1 Felony if accident caused death","Immediate revocation of driving privileges"}', 'Property-damage-only hit and run is a separate offense under 625 ILCS 5/11-402 (Class A Misdemeanor).'),
  ('vehicular-homicide', 'IL', '720 ILCS 5/9-3', 'Reckless Homicide — Motor Vehicle', 'Class 3 Felony; Class 2 Felony (aggravated)', NULL, '5 years (Class 3); 7 years (Class 2)', '$25,000', '{"Operated a motor vehicle in a reckless manner","Unintentional killing of another person resulted","Acts constituted conscious disregard of a substantial and unjustifiable risk"}', NULL, '{"Class 2 Felony (aggravated): two or more deaths result","DUI-related death charged separately under 625 ILCS 5/11-501(d) as aggravated DUI Class X","School zone or construction zone: enhanced penalties"}', 'DUI-related vehicular death is typically charged as aggravated DUI causing death under 625 ILCS 5/11-501(d) rather than reckless homicide, though both may be charged.'),
  ('vehicular-manslaughter', 'IL', '720 ILCS 5/9-3', 'Involuntary Manslaughter — Motor Vehicle (Reckless Homicide)', 'Class 3 Felony', NULL, '5 years', '$25,000', '{"Operated a motor vehicle in a reckless manner","Caused the unintentional death of another person"}', NULL, '{"Aggravated: Class 2 Felony for death in school zone or construction zone"}', 'Illinois does not separately title vehicular manslaughter — the offense falls under the reckless homicide statute.'),
  ('driving-on-suspended', 'IL', '625 ILCS 5/6-303', 'Driving While Driver''s License, Permit, or Privilege to Operate a Motor Vehicle is Suspended or Revoked', 'Class A Misdemeanor; up to Class 4 Felony (3rd+ offense or revoked for DUI)', NULL, '1 year (misdemeanor); 3 years (felony)', '$2,500 (misdemeanor); $25,000 (felony)', '{"Operated a motor vehicle","While driver''s license, permit, or privilege to operate was suspended or revoked"}', '10 days imprisonment or 30 days community service for 2nd violation during DUI suspension', '{"Class 4 Felony: 4th+ offense or when suspension/revocation is for DUI conviction","Class 2 Felony: 4th conviction when revocation was for reckless homicide or aggravated DUI"}', NULL),
  ('fleeing-eluding', 'IL', '625 ILCS 5/11-204', 'Fleeing or Attempting to Elude a Police Officer', 'Class A Misdemeanor; Class 4 Felony (aggravated)', NULL, '1 year (misdemeanor); 3 years (Class 4 felony)', '$2,500', '{"Driver of a vehicle on a highway","Willfully failed or refused to obey a direction to stop by a police officer driving an authorized emergency vehicle with siren or lights engaged"}', NULL, '{"Aggravated (Class 4 Felony): reckless driving during flight, exceeding speed limit by 21+ mph, disobeying 2+ traffic control devices","Class 3 Felony if aggravated AND caused bodily harm or accident"}', NULL),
  ('open-container', 'IL', '625 ILCS 5/11-502', 'Possession of Alcoholic Beverage in Motor Vehicle', 'Class A Misdemeanor', NULL, '1 year', '$2,500', '{"Transported or possessed an alcoholic beverage in a motor vehicle","While operating the vehicle on a highway","Container had a broken seal, partially removed contents, or was open"}', NULL, '{}', 'Passengers may be charged as well. Exceptions exist for passengers in buses, taxis, and limousines.'),
  ('refusing-breath-test', 'IL', '625 ILCS 5/11-501.1', 'Implied Consent — Refusal of Chemical Testing', 'Civil/Administrative (not a separate criminal charge)', NULL, 'Administrative suspension only', NULL, '{"Arrested for DUI","Refused to submit to or failed to complete chemical testing (breath, blood, or urine)"}', NULL, '{"First refusal: 12-month statutory summary suspension","Second+ refusal: 36-month suspension","Refusal may be used as evidence at DUI trial"}', 'Refusal is an administrative violation triggering statutory summary suspension, not a separate criminal charge in Illinois.'),
  ('drug-possession', 'IL', '720 ILCS 570/402', 'Possession of Controlled Substance', 'Class 4 Felony (small amounts); up to Class X Felony (large amounts)', NULL, '1 to 3 years (Class 4); 6 to 30 years (Class X)', '$25,000', '{"Knowingly possessed a controlled substance","Substance was listed in Schedules I through V of the Illinois Controlled Substances Act","Without a valid prescription or other lawful authority"}', '6 years for 100 to 400g Class X amounts', '{"Class 1 Felony: heroin, cocaine, or opioids 15+ grams","Class X Felony: heroin or cocaine 100+ grams (mandatory 6 to 30 years)","Enhanced if possession within 1,000 feet of school"}', 'Illinois removed cannabis possession from this statute for amounts under 30g. See 720 ILCS 550/4 for cannabis.'),
  ('drug-possession-marijuana', 'IL', '720 ILCS 550/4; 410 ILCS 705/10-10', 'Possession of Cannabis', 'Civil infraction (under 30g); Class A Misdemeanor (30 to 100g); Class 4 Felony (100 to 500g)', NULL, 'Civil fine (under 10g); 1 year (30 to 100g); 3 years (100 to 500g)', '$200 civil (under 10g); $2,500 misdemeanor; $25,000 felony', '{"Possessed cannabis","Amount exceeded legal adult-use limits (30g flower for non-registered users)"}', NULL, '{"500g to 2,000g: Class 3 Felony","2,000g to 5,000g: Class 2 Felony","5,000g+: Class 1 Felony","Enhanced penalties within 1,000 feet of school"}', 'Illinois legalized recreational cannabis in 2020. Adults 21+ may possess up to 30g flower, 5g concentrate, 500mg THC in products.'),
  ('drug-possession-cocaine', 'IL', '720 ILCS 570/402(c)', 'Possession of Cocaine', 'Class 4 Felony (under 15g); Class 1 Felony (15 to 100g); Class X Felony (100g+)', NULL, '1 to 3 years (Class 4); 4 to 15 years (Class 1); 6 to 30 years (Class X)', '$25,000', '{"Knowingly possessed cocaine or a substance containing cocaine","Amount falls within charged quantity bracket"}', '6 years (100 to 400g); 9 years (400 to 900g); 12 years (900g+)', '{"Class X with 6-year minimum: 100 to 400g","Class X with 9-year minimum: 400 to 900g","Class X with 12-year minimum: 900g+"}', NULL),
  ('drug-possession-meth', 'IL', '720 ILCS 646/60', 'Methamphetamine Possession', 'Class 3 Felony (under 5g); Class 2 Felony (5 to 15g); up to Class X Felony (100g+)', NULL, '2 to 5 years (Class 3); 3 to 7 years (Class 2); 6 to 30+ years (Class X)', '$25,000', '{"Knowingly possessed methamphetamine or a substance containing methamphetamine"}', '6 years (100 to 400g meth); escalating mandatory minimums for larger amounts', '{"Class X for 100g+: mandatory 6 to 30 years","Enhanced if within 1,000 feet of school, daycare, or public park"}', 'Illinois Methamphetamine Control and Community Protection Act (720 ILCS 646) governs meth offenses separately from the general Controlled Substances Act.'),
  ('drug-possession-opioids', 'IL', '720 ILCS 570/402(c)', 'Possession of Heroin or Opioid Controlled Substances', 'Class 4 Felony (under 15g); Class 1 Felony (15 to 100g); Class X Felony (100g+)', NULL, '1 to 3 years (Class 4); 4 to 15 years (Class 1); 6 to 30 years (Class X)', '$25,000', '{"Knowingly possessed heroin, fentanyl, or a Schedule I or II opioid controlled substance","Without a valid prescription"}', '6 years (100 to 400g heroin); 9 years (400 to 900g); 12 years (900g+)', '{"Fentanyl: Class X triggered at lower thresholds due to mixture weight calculations under 720 ILCS 570/402(c)"}', NULL),
  ('drug-possession-prescription', 'IL', '720 ILCS 570/402(c)', 'Possession of Prescription Controlled Substance Without Valid Prescription', 'Class 4 Felony', NULL, '3 years', '$25,000', '{"Knowingly possessed a Schedule II through V prescription controlled substance","Without a valid prescription issued in the defendant''s name"}', NULL, '{"Higher felony class based on weight — same Schedule II drug thresholds apply"}', NULL),
  ('drug-trafficking', 'IL', '720 ILCS 570/401', 'Manufacture or Delivery of Controlled Substances', 'Class 1 Felony (small amounts); Class X Felony (large amounts)', NULL, '4 to 15 years (Class 1); 6 to 30 years to natural life (Class X)', '$250,000 or street value, whichever is greater', '{"Knowingly delivered a controlled substance to another person","OR possessed with intent to deliver","Substance was a Schedule I or II controlled substance"}', '6 years (Class X cocaine or heroin 100g+)', '{"Class X with extended term: delivery within 1,000 feet of school or public park","Enhanced if delivery to person under 18","Continuing narcotics conspiracy under 720 ILCS 570/405.2"}', '720 ILCS 570/401 lists specific substance thresholds with escalating felony classes.'),
  ('drug-distribution', 'IL', '720 ILCS 570/401', 'Delivery of Controlled Substances', 'Class 2 Felony (small delivery); Class X Felony (large amounts)', NULL, '3 to 7 years (Class 2); 6 to 30 years (Class X)', '$250,000', '{"Knowingly delivered a controlled substance to another person","Without legal authority to distribute"}', NULL, '{"Near school zone: enhanced classification","To person under 18: Class X regardless of quantity"}', 'Same statute as drug trafficking; distinction based on quantity thresholds in 720 ILCS 570/401 subsections.'),
  ('drug-manufacturing', 'IL', '720 ILCS 570/401; 720 ILCS 646/15', 'Manufacture of Controlled Substances', 'Class 1 to Class X Felony depending on substance', NULL, '4 to 15 years (Class 1); 6 to 30 years (Class X)', '$250,000', '{"Manufactured, produced, prepared, or processed a controlled substance","OR possessed chemicals and equipment with intent to manufacture"}', NULL, '{"Meth manufacturing: Class X offense under 720 ILCS 646/15 (6 to 30 years)","Manufacturing within 1,000 feet of school: Class X mandatory"}', 'Meth manufacturing is governed by the Methamphetamine Control and Community Protection Act (720 ILCS 646). All other manufacturing falls under the Controlled Substances Act.'),
  ('drug-paraphernalia', 'IL', '720 ILCS 600/3.5', 'Possession of Drug Paraphernalia', 'Civil violation (first offense); Class A Misdemeanor (subsequent)', NULL, '$200 fine (first offense); 1 year (subsequent)', '$200 (first offense); $2,500 (subsequent)', '{"Possessed drug paraphernalia with intent to use for introducing a controlled substance into the body","OR to pack, store, contain, or conceal a controlled substance"}', NULL, '{}', 'Illinois revised paraphernalia law in 2016. First offense is civil infraction. Needle and syringe possession for personal use decriminalized under 720 ILCS 635.'),
  ('prescription-fraud', 'IL', '720 ILCS 570/406', 'Fraudulent Acquisition of Prescription Controlled Substance', 'Class 3 Felony', NULL, '5 years', '$25,000', '{"Obtained or attempted to obtain a controlled substance by fraud, deceit, misrepresentation, or subterfuge","OR forged or altered a prescription","OR impersonated a licensed practitioner"}', NULL, '{"Class 2 Felony if value exceeds $500 or multiple prescriptions obtained","Professional license revocation for licensed practitioners"}', NULL),
  ('drug-possession-with-intent', 'IL', '720 ILCS 570/401', 'Possession of Controlled Substance with Intent to Deliver', 'Class 1 Felony (small amounts); Class X Felony (large amounts)', NULL, '4 to 15 years (Class 1); 6 to 30 years (Class X)', '$250,000', '{"Possessed a controlled substance","Intent to deliver inferred from quantity, packaging, scales, currency, or other circumstantial evidence"}', NULL, '{"Same enhancements as delivery charges under 720 ILCS 570/401"}', 'Illinois treats possession with intent as equivalent to delivery under the same statute and sentencing schedule.'),
  ('murder-first-degree', 'IL', '720 ILCS 5/9-1', 'First Degree Murder', 'Class M Felony (most serious felony in Illinois)', '20 years', '60 years; natural life for aggravated circumstances', '$25,000', '{"Killed an individual without lawful justification","AND either: (1) intended to kill or do great bodily harm; (2) knew act would cause death; OR (3) was attempting or committing a forcible felony (felony murder)"}', '20 years; 60 years for killing law enforcement or during predicate felony', '{"Natural life (no parole): multiple murders, murder for hire, torture, murder of officer or firefighter, murder during armed robbery, murder of witness","Death penalty abolished in Illinois (2011)","Truth-in-sentencing: must serve 100% of sentence"}', 'Illinois abolished the death penalty in 2011. Natural life imprisonment is the maximum.'),
  ('murder-second-degree', 'IL', '720 ILCS 5/9-2', 'Second Degree Murder', 'Class 1 Felony', '4 years', '20 years', '$25,000', '{"Elements of first degree murder are present","AND at the time of killing defendant was acting under sudden and intense passion resulting from serious provocation","OR defendant believed circumstances justified the killing but that belief was unreasonable (imperfect self-defense)"}', '4 years', '{"If victim was officer or firefighter: minimum sentence increases","Prior felony convictions increase sentencing range"}', 'Second degree murder is an affirmative mitigating defense to first degree murder. Defendant must present evidence by preponderance of the evidence.'),
  ('voluntary-manslaughter', 'IL', '720 ILCS 5/9-2', 'Second Degree Murder (encompasses voluntary manslaughter concept)', 'Class 1 Felony', '4 years', '20 years', '$25,000', '{"Intentional killing","Under sudden and intense passion resulting from serious provocation by the victim"}', '4 years', '{}', 'Illinois does not use the term ''voluntary manslaughter'' — the concept is subsumed in Second Degree Murder under 720 ILCS 5/9-2.'),
  ('involuntary-manslaughter', 'IL', '720 ILCS 5/9-3', 'Involuntary Manslaughter', 'Class 3 Felony; Class 2 Felony (with deadly weapon)', NULL, '5 years (Class 3); 7 years (Class 2)', '$25,000', '{"Unintentionally killed an individual","Acts were performed recklessly — conscious disregard of a substantial and unjustifiable risk of death"}', NULL, '{"Class 2 Felony if committed with a firearm or other deadly weapon"}', NULL),
  ('aggravated-assault', 'IL', '720 ILCS 5/12-2', 'Aggravated Assault', 'Class A Misdemeanor to Class 3 Felony depending on victim or weapon', NULL, '5 years', '$25,000', '{"Committed an assault (placing a person in reasonable apprehension of receiving a battery)","AND used a deadly weapon, discharged a firearm from a vehicle, acted from disguise, targeted a protected-class victim, or acted in a public place"}', NULL, '{"Class 3 Felony: assault with firearm, against police, firefighter, EMT, teacher, or elderly person","Class 2 Felony: discharge of firearm or specific aggravating victim categories","Class 1 Felony: firearm discharge causing injury"}', '720 ILCS 5/12-2 lists 15+ categories of aggravating factors.'),
  ('simple-assault', 'IL', '720 ILCS 5/12-1', 'Assault', 'Class C Misdemeanor', NULL, '30 days', '$1,500', '{"Engaged in conduct that placed another in reasonable apprehension of receiving a battery","Without lawful authority"}', NULL, '{}', 'Illinois assault does not require physical contact. Battery (720 ILCS 5/12-3) is the completed physical contact offense.'),
  ('battery', 'IL', '720 ILCS 5/12-3', 'Battery', 'Class A Misdemeanor', NULL, '1 year', '$2,500', '{"Knowingly, without legal justification","Made physical contact of insulting or provoking nature with an individual","OR caused bodily harm to an individual"}', NULL, '{"Aggravated Battery (720 ILCS 5/12-3.05): Class 3 to Class X felony depending on aggravating factor"}', NULL),
  ('aggravated-battery', 'IL', '720 ILCS 5/12-3.05', 'Aggravated Battery', 'Class 3 Felony to Class X Felony depending on circumstances', NULL, '30 years (Class X with firearm discharge)', '$25,000', '{"Committed a battery","AND: caused great bodily harm, permanent disability, or disfigurement; used a deadly weapon; victim was a protected class; committed on a public way; used a caustic substance; OR discharged a firearm"}', NULL, '{"Class X Felony: battery with firearm causing great bodily harm","15-year mandatory add-on if personally discharged a firearm causing great bodily harm (720 ILCS 5/33A-2)"}', '720 ILCS 5/12-3.05 contains 20+ categories. Firearm discharge add-ons are mandatory consecutive under 720 ILCS 5/33A-2.'),
  ('robbery', 'IL', '720 ILCS 5/18-1', 'Robbery', 'Class 2 Felony; Class 1 Felony (victim 60+ or disabled)', NULL, '7 years (Class 2); 15 years (Class 1)', '$25,000', '{"Knowingly took property from the person or presence of another","By use of force or by threatening the imminent use of force"}', NULL, '{"Class 1 Felony: victim is 60 years of age or older or is a disabled person"}', NULL),
  ('armed-robbery', 'IL', '720 ILCS 5/18-2', 'Armed Robbery', 'Class X Felony', '6 years', '30 years', '$25,000', '{"Committed a robbery","While carrying on or about person a dangerous weapon","OR while indicating by words or actions possession of a dangerous weapon"}', '6 years', '{"15-year mandatory add-on if armed with a firearm","20-year mandatory add-on if firearm discharged","25-year to natural life add-on if firearm discharge caused great bodily harm or death"}', 'Mandatory consecutive sentencing enhancements under 720 ILCS 5/33A-2 apply to firearm use.'),
  ('kidnapping', 'IL', '720 ILCS 5/10-1', 'Kidnapping', 'Class 2 Felony; Class X Felony (aggravated)', NULL, '7 years (Class 2); 30 years (Class X)', '$25,000', '{"Knowingly and secretly confined another against their will","OR by force or threat took another from one place to another"}', NULL, '{"Aggravated Kidnapping (Class X, 720 ILCS 5/10-2): ransom demand, weapon use, victim under 13, infliction of great bodily harm, victim is police officer"}', NULL),
  ('arson', 'IL', '720 ILCS 5/20-1', 'Arson', 'Class 2 Felony; Class 1 Felony (residential or occupied structure)', NULL, '7 years (Class 2); 15 years (Class 1)', '$25,000', '{"By means of fire or explosive","Knowingly damaged or destroyed any real or personal property","Value over $150 OR which was a dwelling"}', NULL, '{"Aggravated Arson (Class X, 720 ILCS 5/20-1.1): person present, fire in place of worship, fire in school","Residential Arson is a Class 1 Felony minimum"}', NULL),
