  ('petty-theft', 'IL', '720 ILCS 5/16-1', 'Theft — Misdemeanor Value', 'Class A Misdemeanor (under $500)', NULL, '1 year', '$2,500', '{"Same elements as theft","Property value under $500"}', NULL, '{"Elevates to Class 4 Felony if defendant has a prior theft conviction"}', NULL),
