  ('motor-vehicle-theft', 'IL', '625 ILCS 5/4-103', 'Possession of Stolen Motor Vehicle', 'Class 2 Felony', NULL, '7 years', '$25,000', '{"Knowingly possessed a stolen motor vehicle","OR concealed knowledge that vehicle was stolen","Without owner''s consent"}', NULL, '{"Class 1 Felony: chop shop operation or VIN alteration (625 ILCS 5/4-103.2)"}', 'Unauthorized vehicle taking also charged under 720 ILCS 5/16-1 (theft) or 625 ILCS 5/4-102 (unauthorized use of vehicle).'),
  ('receiving-stolen-property', 'IL', '720 ILCS 5/16-1(a)(4)', 'Theft — Obtaining Control Over Stolen Property', 'Class A Misdemeanor (under $500); Class 3 to Class 1 Felony (based on value)', NULL, '1 year (misdemeanor); up to 15 years (Class 1 felony)', '$25,000', '{"Obtained control over stolen property","Knowing the property to be stolen or under circumstances that would reasonably induce belief it was stolen"}', NULL, '{}', 'Illinois does not have a separate receiving stolen property statute — it falls within the general theft statute as subsection (a)(4).'),
