  ('criminal-mischief', 'IL', '720 ILCS 5/21-1', 'Criminal Damage to Property', 'Class A Misdemeanor to Class 1 Felony', NULL, '1 year (misdemeanor) to 15 years (Class 1 felony)', '$25,000', '{"Knowingly damaged or destroyed the property of another","OR knowingly started a fire on another''s land without consent"}', NULL, '{}', 'Illinois calls this ''Criminal Damage to Property'' — same statute (720 ILCS 5/21-1) as vandalism.'),
  ('domestic-violence', 'IL', '720 ILCS 5/12-3.2', 'Domestic Battery', 'Class A Misdemeanor (1st offense); Class 4 Felony (2nd+ or against pregnant victim)', NULL, '1 year (misdemeanor); 3 years (felony)', '$2,500 (misdemeanor); $25,000 (felony)', '{"Intentionally or knowingly caused bodily harm","OR made physical contact of insulting or provoking nature","With a family or household member"}', NULL, '{"Class 4 Felony: second or subsequent offense or committed against pregnant victim","Class 3 Felony: third+ offense","Aggravated Domestic Battery (720 ILCS 5/12-3.3): Class 2 Felony for strangulation or great bodily harm"}', 'Illinois Domestic Violence Act (750 ILCS 60) provides civil remedies. Mandatory no-contact order on arrest.'),
  ('domestic-battery', 'IL', '720 ILCS 5/12-3.2', 'Domestic Battery', 'Class A Misdemeanor (1st); Class 4 Felony (2nd+)', NULL, '1 year (misdemeanor); 3 years (felony)', '$2,500', '{"Intentionally or knowingly caused bodily harm to family or household member","OR made physical contact of insulting or provoking nature with family or household member"}', NULL, '{"Aggravated Domestic Battery (720 ILCS 5/12-3.3): Class 2 Felony for strangulation or great bodily harm"}', 'Conviction requires completion of a domestic battery counseling program.'),
