  ('child-abuse', 'IL', '720 ILCS 5/12C-20', 'Aggravated Battery to a Child', 'Class X Felony', '6 years', '30 years', '$25,000', '{"Intentionally or knowingly caused great bodily harm, permanent disability, or disfigurement","To a child under 13 years of age"}', '6 years', '{"Natural life if child dies as a result"}', 'Illinois DCFS administrative proceedings run parallel to criminal prosecution.'),
  ('violation-protective-order', 'IL', '720 ILCS 5/12-3.4', 'Violation of Order of Protection', 'Class A Misdemeanor (1st); Class 4 Felony (2nd+ or stalking violation)', NULL, '1 year (misdemeanor); 3 years (felony)', '$2,500 (misdemeanor); $25,000 (felony)', '{"Order of protection was in effect","Defendant had actual knowledge of the order","Committed an act in violation of the order''s specific terms"}', NULL, '{"Class 4 Felony: second+ violation or violation involving stalking or surveillance","Class 3 Felony: second+ violation involving domestic battery"}', 'Order of protection issued under the Illinois Domestic Violence Act (750 ILCS 60) or Civil No Contact Order Act.'),
  ('stalking', 'IL', '720 ILCS 5/12-7.3', 'Stalking', 'Class 4 Felony (1st); Class 3 Felony (2nd+)', NULL, '3 years (Class 4); 5 years (Class 3)', '$25,000', '{"On at least 2 separate occasions","Followed, monitored, observed, surveilled, threatened, or communicated to or about a specific person","Knowing that conduct would cause a reasonable person to fear for their safety","Actually caused the victim to fear for their safety"}', NULL, '{"Aggravated Stalking (720 ILCS 5/12-7.4): Class 3 Felony — violates court order, uses weapon, victim under 18","Class 1 Felony for certain aggravated circumstances"}', NULL),
