  ('bank-fraud', 'IL', '720 ILCS 5/17-1; 720 ILCS 5/17-3', 'Deceptive Practices — Bank or Financial Institution Fraud', 'Class 1 Felony (large amounts)', NULL, '15 years', '$25,000', '{"Knowingly executed or attempted to execute a scheme to defraud a financial institution","By means of false or fraudulent pretenses, representations, or promises","To obtain money, funds, or other property under the custody of a financial institution"}', NULL, '{}', 'Bank fraud is typically prosecuted federally under 18 U.S.C. 1344. Illinois state prosecution uses deceptive practices statute.'),
  ('sexual-assault', 'IL', '720 ILCS 5/11-1.20', 'Criminal Sexual Assault', 'Class 1 Felony; Class X Felony (aggravated)', '4 years', '15 years (Class 1); 30 years (Class X)', '$25,000', '{"Committed an act of sexual penetration","By use of force or threat of force","OR knew victim was unable to give knowing consent","OR was related to victim under 18, was a family member, or held a position of trust or authority over the victim"}', '4 years (Class 1); 6 years (Class X)', '{"Aggravated Criminal Sexual Assault (720 ILCS 5/11-1.30): Class X — weapon displayed, great bodily harm inflicted, victim under 9, perpetrator over 17 and victim under 13"}', 'Truth-in-sentencing: must serve 85% of sentence. SORA registration required.'),
  ('rape', 'IL', '720 ILCS 5/11-1.20', 'Criminal Sexual Assault', 'Class 1 Felony; Class X Felony (aggravated)', '4 years', '30 years (aggravated)', '$25,000', '{"Committed an act of sexual penetration","By use of force or threat of force","Without consent of victim"}', '4 years', '{"Predatory Criminal Sexual Assault (720 ILCS 5/11-1.40): Class X — penetration of victim under 13 by perpetrator 17 or older; mandatory 6 to 60 years"}', 'Illinois eliminated the term ''rape'' in 1984. The offense is Criminal Sexual Assault under 720 ILCS 5/11-1.20.'),
