  ('child-exploitation', 'IL', '720 ILCS 5/11-20.1', 'Child Pornography', 'Class 1 Felony (possession); Class X Felony (production or distribution)', '4 years (Class 1); 6 years (Class X)', '15 years (Class 1); 30 years (Class X)', '$25,000', '{"Photographed, filmed, videotaped, created, or possessed a depiction of a child under 18","Engaged in sexual conduct or depicted in a lewd manner","OR disseminated such material"}', '4 years (possession); 6 years (production)', '{"Each image or video counts as a separate offense","Mandatory SORA registration for life","Mandatory consecutive sentences for multiple counts"}', 'Non-probationable. Lifetime sex offender registration required.'),
