  ('statutory-rape', 'IL', '720 ILCS 5/11-1.50', 'Criminal Sexual Abuse', 'Class 4 Felony; Class A Misdemeanor (certain age combinations)', NULL, '3 years (Class 4); 1 year (misdemeanor)', '$25,000', '{"Committed an act of sexual conduct or sexual penetration","With a person between 13 and 17 years of age","Defendant was at least 5 years older than the victim"}', NULL, '{"Aggravated Criminal Sexual Abuse (720 ILCS 5/11-1.60): Class 2 Felony — victim under 13, defendant in position of trust or authority, defendant is family member"}', 'Consensual sex between a 13 to 16 year old and someone less than 5 years older is not criminal in Illinois.'),
  ('sex-offense-contact', 'IL', '720 ILCS 5/11-1.50', 'Criminal Sexual Abuse', 'Class A Misdemeanor to Class 2 Felony', NULL, '1 year (misdemeanor); 7 years (Class 2 felony)', '$25,000', '{"Committed an act of sexual conduct (touching)","By force or threat of force","OR with a person incapable of giving knowing consent"}', NULL, '{"Aggravated Criminal Sexual Abuse (720 ILCS 5/11-1.60): Class 2 Felony"}', 'Sexual conduct (touching) vs. sexual penetration determines criminal sexual abuse vs. criminal sexual assault.'),
  ('sexual-battery', 'IL', '720 ILCS 5/11-1.50', 'Criminal Sexual Abuse (equivalent to sexual battery)', 'Class A Misdemeanor to Class 2 Felony', NULL, '7 years', '$25,000', '{"Committed an act of sexual conduct by force or threat","OR with a victim unable to give knowing consent"}', NULL, '{}', 'Illinois does not use the term ''sexual battery.'' Criminal Sexual Abuse (720 ILCS 5/11-1.50) covers equivalent conduct.'),
