  ('obstruction-justice', 'IL', '720 ILCS 5/31-4', 'Obstructing Justice', 'Class 4 Felony', NULL, '3 years', '$25,000', '{"Knowingly destroyed, altered, concealed, or disguised physical evidence","OR planted false evidence","OR furnished false information","With intent to prevent apprehension or obstruct prosecution of any person for any crime"}', NULL, '{"Class 3 Felony if obstruction relates to a Class 1, 2, or X felony case"}', NULL),
  ('contempt-of-court', 'IL', '720 ILCS 5/32-1', 'Contempt of Court', 'Class A Misdemeanor (direct); Class 4 Felony (indirect or continuing)', NULL, '1 year (misdemeanor); 3 years (felony)', '$2,500', '{"Knowingly failed to comply with a court order or perform a court-ordered duty","OR disrupted court proceedings","OR willfully disobeyed a lawful process or order of court"}', NULL, '{}', 'Courts retain inherent contempt power for immediate sanctions up to 6 months without a formal charge.'),
  ('loitering', 'IL', '720 ILCS 5/11-14.1; 720 ILCS 5/36-3', 'Loitering for Drug or Sexual Purposes', 'Class B Misdemeanor (basic); Class A Misdemeanor (drug or sex purpose loitering)', NULL, '6 months (Class B); 1 year (Class A)', '$1,500 (Class B); $2,500 (Class A)', '{"Remained in a public place with intent to engage in drug activity or solicit a sexual act","OR remained in a place without lawful purpose after being asked to leave by an officer"}', NULL, '{}', 'Basic loitering ordinances are typically municipal. State loitering statutes focus on drug or sex-purpose loitering.'),
  ('disturbing-peace', 'IL', '720 ILCS 5/26-1', 'Disorderly Conduct — Disturbing the Peace', 'Class C Misdemeanor', NULL, '30 days', '$1,500', '{"Knowingly engaged in fighting, threatening, or violent behavior","OR created unreasonable noise or disturbance","That provoked a breach of the peace"}', NULL, '{}', 'Illinois consolidates disturbing the peace under the disorderly conduct statute.'),
  ('failure-to-appear', 'IL', '720 ILCS 5/32-10', 'Bail Jumping — Failure to Appear', 'Class 4 Felony (felony underlying case); Class A Misdemeanor (misdemeanor case)', NULL, '3 years (felony); 1 year (misdemeanor)', '$25,000', '{"Released on bail or personal recognizance","Knowingly failed to appear before the court as required by conditions of release","With intent to avoid prosecution"}', NULL, '{}', 'Under the SAFE-T Act (2021), Illinois moved to a no-cash-bail system. Failure to appear remains a criminal offense.'),
  ('false-report', 'IL', '720 ILCS 5/26-1(a)(4)', 'Disorderly Conduct — False Report of Emergency', 'Class 4 Felony', NULL, '3 years', '$25,000', '{"Transmitted a false report","That a fire, explosion, crime, catastrophe, or other emergency was occurring","To any law enforcement agency, fire department, or emergency management agency"}', NULL, '{"Felony counts for each separate false report transmitted"}', NULL),
  ('criminal-threat', 'IL', '720 ILCS 5/12-6', 'Intimidation', 'Class 3 Felony; Class 2 Felony (aggravated)', NULL, '5 years (Class 3); 7 years (Class 2)', '$25,000', '{"Communicated to another a threat to perform an action prohibited by law","With intent to cause that person to perform or omit an act against their will","OR with intent to cause fear in that person"}', NULL, '{"Aggravated Intimidation (720 ILCS 5/12-6.1): Class 2 Felony if against public officials or crime victims","Threatening a Public Official (720 ILCS 5/12-9): Class 4 Felony"}', NULL),
  ('probation-violation', 'IL', '730 ILCS 5/5-6-4', 'Violation of Probation or Conditional Discharge', 'Dependent on underlying offense class', NULL, 'Full sentence of underlying offense', NULL, '{"Was serving a term of probation or conditional discharge","Violated one or more conditions of probation","Violation proven by preponderance of the evidence"}', NULL, '{"New criminal offense during probation: presumption against continued probation","Court may impose original sentence or modify conditions"}', 'Violations heard by the sentencing judge. Standard of proof is preponderance. Defendant may be held without bail pending hearing.'),
  ('probation-violation-technical', 'IL', '730 ILCS 5/5-6-4', 'Technical Violation of Probation', 'Administrative — depends on underlying offense', NULL, 'Full remaining probation sentence', NULL, '{"Failed to report to probation officer as required","Failed drug or alcohol test","Failed to complete required community service hours","Failed to pay fines or restitution","OR other non-criminal condition violation"}', NULL, '{}', 'Under the SAFE-T Act, court must consider less restrictive alternatives before revoking probation for technical violations.'),
  ('probation-violation-substantive', 'IL', '730 ILCS 5/5-6-4', 'Substantive Violation of Probation — New Criminal Offense', 'Underlying offense class', NULL, 'Full original sentence', NULL, '{"Committed a new criminal offense while on probation","New offense proven by preponderance or separate criminal conviction"}', NULL, '{"May result in revocation and imposition of original sentence plus new sentence running consecutively"}', NULL),
  ('supervised-release-violation', 'IL', '730 ILCS 5/3-3-9', 'Violation of Mandatory Supervised Release', 'Administrative revocation proceeding', NULL, 'Return to IDOC for balance of sentence', NULL, '{"Was on mandatory supervised release (MSR)","Violated one or more conditions of MSR","Violation proven by preponderance at Prisoner Review Board hearing"}', NULL, '{}', 'In Illinois, parole is called Mandatory Supervised Release (MSR). Violations heard by Prisoner Review Board, not courts.'),
  ('parole-violation', 'IL', '730 ILCS 5/3-3-9', 'Violation of Mandatory Supervised Release (Parole)', 'Administrative — Prisoner Review Board proceeding', NULL, 'Return to IDOC for remainder of sentence', NULL, '{"Released on MSR following IDOC sentence","Violated conditions of release (new offense, failed drug test, absconded, etc.)"}', NULL, '{}', 'Illinois uses ''Mandatory Supervised Release'' rather than ''parole.'' Revocation is administrative through the Prisoner Review Board.'),
  ('conspiracy', 'IL', '720 ILCS 5/8-2', 'Conspiracy', 'One class below the most serious offense that is the object of the conspiracy', NULL, 'One class below target offense maximum', '$25,000', '{"With intent that an offense be committed","Agreed with one or more other persons to commit or attempt to commit an offense","AND any one of them performed an overt act in furtherance of the agreement"}', NULL, '{"Conspiracy to commit a Class X Felony is a Class 1 Felony","No overt act required for Class X conspiracy if target is drug trafficking"}', NULL),
  ('self-defense', 'IL', '720 ILCS 5/7-1', 'Use of Force in Defense of Person — Affirmative Defense', 'Affirmative defense — not a criminal charge', NULL, NULL, NULL, '{"Defendant reasonably believed use of force was necessary","To defend against another''s imminent use of unlawful force","Force used was not greater than reasonably necessary to prevent the harm"}', NULL, '{}', 'Illinois self-defense is an affirmative defense. Defendant must produce some evidence; state must disprove beyond reasonable doubt. Castle Doctrine codified at 720 ILCS 5/7-2.'),
  ('other', 'IL', 'N/A', 'Other Illinois Criminal Offense', 'Varies', NULL, 'Varies', NULL, '{}', NULL, '{}', 'Placeholder for Illinois charges not covered by specific taxonomy entries. Consult 720 ILCS 5 (Criminal Code of 2012) and other Illinois compiled statutes.')
INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('dui-first-offense', 'MI', 'MCL 257.625(1)', 'Operating While Intoxicated — First Offense', '93-day Misdemeanor', '0 days', '93 days', '$500', '{"Operating a motor vehicle","Upon a highway or other place open to the general public","While under the influence of alcoholic liquor OR with BAC of 0.08% or more"}', 'None for first offense', '{"BAC 0.17%+ (Super Drunk/High BAC): 180 days jail, $700 fine — MCL 257.625(1)(c)","Child under 16 in vehicle: additional 93-day misdemeanor charge — MCL 257.625(7)","Prior OWI within 7 years: second offense felony"}', 'Michigan uses ''Operating While Intoxicated'' (OWI), not DUI/DWI. License suspension 30-180 days. Mandatory vehicle immobilization. Ignition interlock may be required.'),
  ('dui-second-offense', 'MI', 'MCL 257.625(9)(b)', 'Operating While Intoxicated — Second Offense', '1-year Misdemeanor', '5 days', '1 year', '$1,000', '{"Operating a motor vehicle while intoxicated","Prior conviction for OWI, OWVI, or OUIN within 7 years"}', '5 days jail or 30 days community service', '{"Third offense within 10 years: Class E Felony","BAC 0.17%+ on second offense: enhanced penalties","Child in vehicle at time of offense: additional charges"}', 'License revocation minimum 1 year. Vehicle immobilization 90-180 days. Ignition interlock required upon reinstatement.'),
  ('dui-third-offense', 'MI', 'MCL 257.625(9)(c)', 'Operating While Intoxicated — Third or Subsequent Offense', 'Class E Felony', '1 year', '5 years', '$5,000', '{"Operating a motor vehicle while intoxicated","Two or more prior OWI convictions"}', '30 days jail or 60 days community service', '{"Prior felony OWI conviction: enhanced sentencing","Serious injury resulting: Class D Felony — MCL 257.625(5)","Death resulting: Class B Felony — MCL 257.625(4)"}', 'License revocation. Vehicle forfeiture possible. Habitual offender provisions apply.'),
  ('dui-drugs', 'MI', 'MCL 257.625(8)', 'Operating While Intoxicated by Controlled Substance', '93-day Misdemeanor', '0 days', '93 days', '$500', '{"Operating a motor vehicle","While under the influence of a controlled substance","OR with any amount of a Schedule 1 controlled substance in blood (per se rule)"}', 'None for first offense', '{"Prior OWI within 7 years: second offense penalties","Death resulting: Class B Felony"}', 'Michigan has a zero-tolerance per se law for any Schedule 1 controlled substance or cocaine in blood regardless of impairment (OUIN — Operating with presence of drugs). Separate from impairment-based OWI.'),
  ('dui-felony-injury', 'MI', 'MCL 257.625(5)', 'Operating While Intoxicated Causing Serious Impairment of a Body Function', 'Class D Felony', '0 years', '5 years', '$5,000', '{"Operating a motor vehicle while intoxicated","Causing an accident","Resulting in serious impairment of a body function of another person"}', 'None statutory', '{"Prior OWI record: consecutive sentencing possible","Death caused: Class B Felony — MCL 257.625(4)"}', '''Serious impairment'' defined as substantial limitation of important body function. License revocation.'),
  ('vehicular-homicide', 'MI', 'MCL 257.625(4)', 'Operating While Intoxicated Causing Death', 'Class B Felony', '0 years', '15 years', '$10,000', '{"Operating a motor vehicle while intoxicated","Causing the death of another person"}', 'None statutory', '{"Emergency responder killed: enhanced sentencing","Multiple deaths: consecutive sentences per victim"}', 'License revocation. Vehicle forfeiture. Also known as ''OWI Causing Death.'' Prosecutors may also charge second-degree murder if egregious facts.'),
  ('reckless-driving', 'MI', 'MCL 257.626', 'Reckless Driving', 'Misdemeanor (up to 93 days for first; 6 months for injury)', '0 days', '93 days', '$500', '{"Operating a vehicle","In willful or wanton disregard for the safety of persons or property"}', 'None', '{"Causing serious injury: up to 2 years — MCL 257.626b","Causing death: up to 15 years — MCL 257.626b"}', '6 points on driving record. License suspension possible. Distinguished from careless driving (civil infraction).'),
  ('driving-on-suspended', 'MI', 'MCL 257.904', 'Driving While License Suspended, Revoked, or Denied', 'Misdemeanor', '0 days', '93 days first offense; 1 year second offense', '$500 first; $1,000 second', '{"Operating a motor vehicle upon a highway","While operator''s license is suspended, revoked, denied, or never obtained"}', 'None', '{"Second offense within 7 years: 1-year misdemeanor","OWI-related suspension: enhanced penalties","Third or subsequent: possible felony"}', 'Vehicle may be immobilized. Prior OWI-related suspension adds additional penalties.'),
  ('drug-possession-marijuana', 'MI', 'MCL 333.27955', 'Unlawful Use/Possession of Marijuana (Under MRTMA)', 'Civil Infraction (small amounts); Misdemeanor (over limits)', 'Civil fine', 'Misdemeanor penalties for violations over MRTMA limits', '$100 civil infraction', '{"Possession of marijuana","In excess of 2.5 ounces in public or 10 ounces at home","OR transfer to minor"}', 'None', '{"Possession near school: additional penalties","Transfer to minor: Class E or D Felony — MCL 333.7401c"}', 'Adult recreational marijuana is legal in Michigan under MRTMA (MCL 333.27951 et seq.) up to 2.5 oz publicly, 10 oz at home. Exceedances are civil infractions or misdemeanors depending on amount. Medical use governed by MMMA.'),
  ('drug-possession', 'MI', 'MCL 333.7403', 'Possession of a Controlled Substance', 'Class E Felony (Schedule 1/2 narcotics); Misdemeanor (others)', '0 years', '4 years (Schedule 1/2); 2 years (Schedule 3/4); 1 year (Schedule 5)', '$25,000', '{"Knowing possession","Of a controlled substance","Not authorized by law"}', 'None for simple possession', '{"Possession of 25+ grams heroin/cocaine: possession with intent presumed","Prior drug conviction: additional sentencing points","In drug-free school zone: double penalties"}', 'Michigan Sentencing Guidelines apply. First-time offenders may be eligible for Holmes Youthful Trainee Act (HYTA) or 7411 deferral. Drug courts widely available.'),
  ('drug-possession-with-intent', 'MI', 'MCL 333.7401', 'Delivery/Manufacture/Possession with Intent — Controlled Substance', 'Class A-E Felony (varies by substance and amount)', '1 year', 'Life (Class A — 1000+ grams cocaine/heroin)', '$1,000,000', '{"Delivery, manufacture, or possession with intent to deliver","A controlled substance","Knowingly and intentionally"}', 'Varies by quantity; life for 1,000+ grams cocaine/heroin', '{"1,000+ grams cocaine/heroin: life or any term of years — Class A","450-999 grams: up to 30 years — Class B","50-449 grams: up to 20 years — Class C","25-49 grams: up to 4 years — Class E","Delivery to minor: double penalty — MCL 333.7410","In drug-free school zone: 2-year mandatory consecutive — MCL 333.7410a"}', 'Michigan''s drug trafficking law has quantity-based tiers. Large-scale trafficking carries life sentences. ''Delivery'' includes constructive transfer.'),
  ('drug-trafficking', 'MI', 'MCL 333.7401(2)(a)(i)', 'Delivery/Manufacture — 1,000+ Grams (High-Level Trafficking)', 'Class A Felony', '0 years (guidelines; mandatory for certain quantities)', 'Life imprisonment', '$1,000,000', '{"Delivery or manufacture of a controlled substance","1,000 or more grams of mixture containing cocaine, heroin, or methamphetamine","Knowingly and intentionally"}', 'Life or any term of years (judicial discretion within Class A)', '{"Prior drug felony: enhanced minimum","Use of firearm: consecutive penalty — MCL 750.227b","Leadership role: sentencing enhancement"}', 'Highest drug trafficking tier. Federal prosecution often pursued concurrently. Asset forfeiture applies.'),
  ('drug-manufacturing', 'MI', 'MCL 333.7401(2)(b)(ii)', 'Manufacture of Methamphetamine', 'Class B Felony', '0 years', '20 years', '$25,000', '{"Manufacturing methamphetamine","Or possessing precursor chemicals with intent to manufacture","Knowingly and intentionally"}', 'None statutory', '{"Manufacturing in presence of minor: additional 2-year consecutive — MCL 333.7401d","Manufacturing causing injury: aggravated charges","Prior conviction: sentencing enhancement"}', 'Separate offense for meth labs. Environmental cleanup liability. Methamphetamine lab in presence of minor is standalone offense under MCL 333.7401d.'),
  ('drug-paraphernalia', 'MI', 'MCL 333.7451', 'Possession/Sale of Drug Paraphernalia', 'Misdemeanor', '0 days', '90 days', '$5,000', '{"Possession of drug paraphernalia","With intent to use in connection with controlled substance violation"}', 'None', '{"Sale of paraphernalia to minor: misdemeanor — MCL 333.7453","Combination with possession charge: consecutive possible"}', 'Michigan''s paraphernalia statute is part of the Public Health Code. Items must have drug-related purpose.'),
  ('murder-first-degree', 'MI', 'MCL 750.316', 'Murder — First Degree (Premeditated)', 'Life Felony', 'Life without parole', 'Life without parole', 'No statutory fine', '{"Killing of a human being","With premeditation and deliberation","OR during perpetration of an enumerated felony (felony murder)"}', 'Mandatory life without parole (LWOP)', '{"Victim is law enforcement: LWOP mandatory","Multiple victims: consecutive LWOP terms","Juvenile offenders: Miller v. Alabama applies — individualized sentencing"}', 'Michigan abolished the death penalty in 1847. LWOP is the maximum. Felony murder (during robbery, CSC, arson, etc.) also first degree. Juveniles subject to Miller hearing.'),
  ('murder-second-degree', 'MI', 'MCL 750.317', 'Murder — Second Degree', 'Class A Felony (Life)', 'Life or any term of years', 'Life', 'No statutory fine', '{"Killing of a human being","With malice aforethought","Without premeditation or during non-enumerated felony"}', 'None (life or any term)', '{"Prior murder conviction: life mandatory","Use of firearm: 2-year mandatory consecutive — MCL 750.227b","Gang-related: sentencing enhancement"}', 'Includes depraved heart murder. No death penalty in Michigan. ''Malice aforethought'' can be implied from circumstances. Sentencing allows judge discretion on term.'),
  ('voluntary-manslaughter', 'MI', 'MCL 750.321', 'Manslaughter — Voluntary', 'Class C Felony', '0 years', '15 years', '$7,500', '{"Killing of a human being","Without malice","In the heat of passion caused by adequate provocation","Before cooling off"}', 'None', '{"Use of firearm: 2-year consecutive minimum — MCL 750.227b","Prior violent felony: sentencing enhancement","Domestic victim: aggravating factor"}', 'Michigan manslaughter statute is general. Heat of passion must be reasonable. Cooling off period negates defense.'),
  ('involuntary-manslaughter', 'MI', 'MCL 750.329', 'Manslaughter — Involuntary (with firearm)', 'Class C Felony', '0 years', '15 years', '$7,500', '{"Killing of a human being","By pointing or aiming a firearm","Without intent to kill"}', 'None', '{"Gross negligence (without firearm): common law manslaughter","OWI causing death: separate MCL 257.625(4)"}', 'MCL 750.329 specifically covers firearm-related involuntary manslaughter. General negligent manslaughter is common law in Michigan. Vehicular manslaughter prosecuted under OWI statute.'),
  ('simple-assault', 'MI', 'MCL 750.81', 'Assault and Battery', '93-day Misdemeanor', '0 days', '93 days', '$500', '{"An act intended to cause harmful or offensive contact","OR an attempt to commit battery","Against another person"}', 'None', '{"Domestic violence: 93-day misdemeanor (same statute, different track)","Second DV offense: 1-year misdemeanor — MCL 750.81(4)","Third DV offense: Class E Felony — MCL 750.81(5)"}', 'Michigan combines assault and battery into one offense. Simple assault is the uncompleted act; battery is the completed touching. Both charged under MCL 750.81.'),
  ('aggravated-assault', 'MI', 'MCL 750.81a', 'Assault — Infliction of Serious or Aggravated Injury', '1-year Misdemeanor', '0 days', '1 year', '$1,000', '{"Assault or battery","Infliction of a serious or aggravated injury","Without a weapon"}', 'None', '{"Against pregnant woman: Class E Felony — MCL 750.81d(3)","Against utility/transit worker: Class E Felony","Strangulation: Class D Felony (up to 10 years) — MCL 750.84(1)(b)"}', 'Serious injury without a weapon. More severe charges apply with weapons or specific victims. Strangulation is separately enhanced under MCL 750.84.'),
  ('assault-with-deadly-weapon', 'MI', 'MCL 750.82', 'Felonious Assault (Assault with a Dangerous Weapon)', 'Class F Felony', '0 years', '4 years', '$2,000', '{"An assault","With a dangerous weapon","Without intending to commit murder or great bodily harm"}', 'None', '{"With intent to murder or do great bodily harm: AWIGBH — Class D Felony — MCL 750.84","In weapon-free school zone: additional 2-year consecutive — MCL 750.82(2)","Against law enforcement: enhanced felony"}', '''Dangerous weapon'' broadly construed — includes vehicles, glass bottles, dogs. AWIGBH under MCL 750.84 is more serious (Class D, up to 10 years).'),
  ('robbery', 'MI', 'MCL 750.530', 'Robbery', 'Class C Felony', '0 years', '15 years', '$15,000', '{"In the course of committing a larceny","Use of force or violence against any person","OR putting person in fear of immediate force or violence"}', 'None', '{"Armed robbery (dangerous weapon): Class B Felony — MCL 750.529","Carjacking: Class A Felony — MCL 750.529a","Victim injury: sentencing enhancement","Use of firearm: 2-year consecutive — MCL 750.227b"}', 'Unarmed robbery. Michigan requires force ''in the course of committing'' — includes immediately before or after larceny. Armed robbery carries up to life under MCL 750.529.'),
  ('armed-robbery', 'MI', 'MCL 750.529', 'Armed Robbery', 'Class B Felony', '0 years', 'Life', 'No cap specified', '{"Robbery","While armed with a dangerous weapon","OR while representing oneself to be armed"}', '2-year consecutive for firearm use under MCL 750.227b', '{"Carjacking (armed): Class A Felony up to life — MCL 750.529a","Victim seriously injured: increased sentence","Gang involvement: sentencing enhancement"}', 'Carrying or claiming to have a weapon both qualify. Firearm possession charge runs consecutive under 750.227b. Carjacking is distinct and more severe.'),
  ('kidnapping', 'MI', 'MCL 750.349', 'Kidnapping', 'Class A Felony (Life)', 'Life or any term of years', 'Life', '$50,000', '{"Knowingly restraining another person","With intent to hold for ransom, use as shield/hostage, engage in criminal sexual conduct, inflict bodily injury, terrorize, or interfere with governmental functions","OR secret confinement"}', 'None (life or any term)', '{"Victim is minor: presumptive life","Death of victim: LWOP or life","Crossing state lines: federal prosecution likely"}', 'MCL 750.349b covers ''unlawful imprisonment'' as lesser offense (Class D). Secret confinement kidnapping unique to Michigan. Jury must be instructed on lesser.'),
  ('carjacking', 'MI', 'MCL 750.529a', 'Carjacking', 'Class A Felony', 'Life or any term of years', 'Life', 'No cap specified', '{"In the course of committing a larceny of a motor vehicle","Use or threat of force or violence against the person","Or putting person in fear"}', 'None (life or any term)', '{"Armed with firearm: 2-year consecutive — MCL 750.227b","Victim injury: sentencing enhancement","Vehicle used in crime: additional charges"}', 'Separate from armed robbery. Specific to motor vehicle taking. Can be charged alongside other offenses arising from same conduct.'),
  ('burglary', 'MI', 'MCL 750.110', 'Breaking and Entering — Building (Burglary)', 'Class D Felony', '0 years', '10 years', '$5,000', '{"Breaking and entering any building, tent, hotel, office, store, or other structure","With intent to commit a felony or larceny therein"}', 'None', '{"Home invasion (dwelling): Class B or C Felony — MCL 750.110a","Armed: additional firearm penalty","Prior B&E conviction: sentencing enhancement"}', 'Michigan uses ''Breaking and Entering'' rather than burglary. Home invasion is more severe. Constructive breaking (entering through open door with intent) is sufficient.'),
  ('home-invasion', 'MI', 'MCL 750.110a', 'Home Invasion — First, Second, Third Degree', 'Class B Felony (1st degree); Class C Felony (2nd); Class D Felony (3rd)', '0 years', '20 years (1st); 15 years (2nd); 5 years (3rd)', '$5,000', '{"Breaking and entering a dwelling","OR entering without permission","With intent to commit felony, larceny, or assault while therein","1st degree: armed with dangerous weapon or another person present"}', 'None', '{"Victim injured during home invasion: enhanced sentencing","Armed: additional 2-year consecutive — MCL 750.227b","Prior home invasion: sentencing enhancement"}', 'Three degrees based on aggravating factors. First degree is the most serious — armed or occupied dwelling. Occupied dwelling home invasion is Class B (up to 20 years).'),
  ('theft-larceny', 'MI', 'MCL 750.356', 'Larceny', 'Class H Felony ($1,000-$20,000); Misdemeanor (under $1,000)', '0 days', '5 years ($20,000+); 2 years ($1,000-$20,000); 1 year ($200-$1,000); 93 days (under $200)', '$10,000 (felony)', '{"Taking and carrying away","Property of another person","With intent to permanently deprive the owner of the property"}', 'None', '{"$20,000+: Class F Felony (up to 5 years) — MCL 750.356(4)(a)","From a person (larceny from person): Class G Felony — MCL 750.357","Habitual offender: enhanced sentencing","Organized retail theft: additional charges — MCL 752.1084"}', 'Michigan larceny is threshold-based: <$200 (93-day), $200-$1,000 (1 year), $1,000-$20,000 (Class H/5 years), $20,000+ (Class F/10 years). Note: thresholds raised 2024.'),
  ('motor-vehicle-theft', 'MI', 'MCL 750.413', 'Taking Motor Vehicle Without Authority (TMVA)', 'Class D Felony', '0 years', '5 years', '$10,000', '{"Taking or using a motor vehicle","Without authority of owner","With intent to steal or permanently deprive"}', 'None', '{"Carjacking (force used): Class A Felony — MCL 750.529a","Prior auto theft: sentencing enhancement","Organized auto theft ring: enhanced charges — MCL 750.535a"}', 'Michigan uses ''Taking Motor Vehicle Without Authority'' (TMVA). Joyriding (temporary use without permission) is a separate misdemeanor under MCL 750.414.'),
  ('shoplifting', 'MI', 'MCL 750.356c', 'Retail Fraud — First, Second, Third Degree', 'Class H Felony (1st); Misdemeanor (2nd/3rd)', '0 days', '5 years (1st degree); 1 year (2nd); 93 days (3rd)', '$10,000 (1st degree)', '{"While in a store in which goods are offered for sale","Altering price, concealing goods, or removing merchandise","With intent to steal or pay less than the full price"}', 'None', '{"Organized retail fraud: Class F Felony — MCL 752.1084","Fraud device/tool used: enhanced charge","Prior retail fraud conviction: degree enhancement"}', 'Retail fraud degrees based on value: 1st ($1,000+, felony), 2nd ($200-$1,000), 3rd (under $200). Michigan-specific terminology. Civil demand for damages also possible.'),
  ('arson', 'MI', 'MCL 750.72', 'Arson — Burning of a Dwelling House', 'Class A Felony (Life)', 'Life or any term of years', 'Life', '$20,000', '{"Willful and malicious burning","Of a dwelling house","Whether occupied or not"}', 'None (life or any term)', '{"Person present and injured: aggravated arson","Firefighter injured: enhanced penalty","Insurance fraud arson: additional fraud charges"}', 'Burning a dwelling is the most serious arson. MCL 750.73 (burning real property, non-dwelling) is Class D. MCL 750.74 (burning personal property) is Class E-H.'),
  ('vandalism', 'MI', 'MCL 750.377a', 'Malicious Destruction of Property (MDOP)', 'Class F-H Felony or Misdemeanor (threshold-based)', '0 days', '10 years ($20,000+); 5 years ($1,000-$20,000); 1 year ($200-$1,000); 93 days (under $200)', '$15,000 (felony)', '{"Wilfully and maliciously","Destroying, injuring, or damaging","Property of another person"}', 'None', '{"Religious institution: mandatory minimum applies — MCL 750.377b","School property: enhanced — MCL 380.1300","Graffiti: separate civil liability"}', 'Michigan''s vandalism/property damage statute uses value thresholds same as larceny. Restitution mandatory. Bias-motivated MDOP subject to ethnic intimidation enhancement.'),
  ('domestic-violence', 'MI', 'MCL 750.81(2)', 'Domestic Violence — Assault and Battery', '93-day Misdemeanor (1st); 1-year Misdemeanor (2nd); Class E Felony (3rd+)', '0 days', '93 days (1st); 1 year (2nd); 5 years (3rd+)', '$500 (1st); $1,000 (2nd); $5,000 (3rd+)', '{"Assault or assault and battery","Against a person who is a spouse, former spouse, dating partner, or co-habitant","OR parent of a common child"}', 'None', '{"Strangulation: Class D Felony — MCL 750.84(1)(b)","Aggravated DV (serious injury): 1-year or Class E Felony","Violation of PPO: contempt or criminal charge"}', 'Michigan tracks DV offenses separately for enhancement purposes. Third conviction creates felony regardless of severity. Mandatory arrest policy in most jurisdictions. Firearm prohibition upon conviction.'),
  ('stalking', 'MI', 'MCL 750.411h', 'Stalking', 'Misdemeanor (1 year); Class E Felony if aggravated', '0 days', '1 year; 5 years (aggravated)', '$1,000; $10,000 (aggravated)', '{"A willful course of conduct","Involving repeated or continuing harassment of another individual","That would cause a reasonable person to feel terrorized, frightened, or harassed"}', 'None', '{"Aggravated stalking (violation of PPO, prior conviction, under 18 victim): Class E Felony — MCL 750.411i","Cyberstalking: same statute applies to electronic communications","Victim safety plan violation: additional penalties"}', 'Michigan''s cyberstalking provisions include electronic communications, emails, and social media. ''Course of conduct'' requires at least 2 acts.'),
  ('violation-protective-order', 'MI', 'MCL 600.2950', 'Violation of Personal Protection Order (PPO)', 'Misdemeanor (93-day) or Contempt', '0 days', '93 days', '$500', '{"Existence of a Personal Protection Order","Respondent had knowledge of the order","Conduct prohibited by the order occurred"}', 'None', '{"Second violation: 1-year misdemeanor","Assault during violation: separate felony charges","Criminal contempt proceedings also available: up to 93 days"}', 'Michigan PPOs are civil orders enforced criminally. Violation triggers both criminal prosecution and contempt. Armed respondents subject to federal gun prohibition.'),
  ('child-abuse', 'MI', 'MCL 750.136b', 'Child Abuse — First Through Fourth Degree', 'Class B Felony (1st); Class D Felony (2nd); Class G Felony (3rd); Misdemeanor (4th)', '0 days', 'Life (1st degree); 10 years (2nd); 2 years (3rd); 1 year (4th)', '$5,000', '{"Intentionally or knowingly causing physical harm to a child","OR cruel punishment/torture (1st degree)","OR omission causing harm (2nd-4th degree)"}', 'None (1st degree life or any term)', '{"Child death resulting: murder charges","Pattern of abuse: sentencing enhancement","Prior child abuse conviction: enhanced degree"}', 'Michigan has four degrees of child abuse. 1st degree (Life) requires intent to cause serious physical harm or torture. Mandatory reporters include all adults in Michigan under MCL 722.623.'),
  ('child-neglect', 'MI', 'MCL 722.633', 'Child Neglect / Failure to Provide — Criminal', 'Misdemeanor to Class E Felony (depends on harm)', '0 days', '2 years (if serious harm); otherwise 93 days to 1 year', '$2,000', '{"Parent, guardian, or person with legal custody","Fails to provide adequate food, clothing, shelter, or medical care","To a child under age 18"}', 'None', '{"Serious physical harm results: Class E Felony","Death of child: murder or manslaughter","Prior CPS history: sentencing enhancement"}', 'Criminal neglect separate from CPS/civil neglect proceedings. Both may run concurrently. Child endangerment also charged under MCL 750.136b(4th degree).'),
  ('felon-in-possession', 'MI', 'MCL 750.224f', 'Possession of a Firearm by a Felon (PFWDVRO)', 'Class G Felony', '0 years', '5 years', '$5,000', '{"Possession or use of a firearm","By a person convicted of a specified felony","Within the specified period after completing sentence"}', 'None statutory', '{"Certain violent felony prior: lifetime ban","Federal prosecution concurrent: 18 U.S.C. § 922(g)","Use in crime: additional charges"}', 'Michigan''s felon-in-possession applies for 3 years after completion of sentence for specified felonies (firearms, CSC, etc.), or permanently for violent felonies. Different from federal lifetime ban.'),
  ('concealed-carry-violation', 'MI', 'MCL 750.227', 'Carrying a Concealed Weapon (CCW)', 'Class E Felony', '0 years', '5 years', '$2,500', '{"Carrying a pistol concealed on person","OR in a vehicle","Without a valid Concealed Pistol License (CPL)"}', 'None', '{"Prior felony: sentence enhancement","In weapon-free school zone: additional 2-year consecutive","Used in crime: additional charges"}', 'Michigan is a shall-issue CPL state. CPL holders exempt. Open carry of pistol in vehicle without CPL is still unlawful under MCL 750.227. Separate provisions for long guns.'),
  ('felony-firearm', 'MI', 'MCL 750.227b', 'Felony Firearm — Possession During Commission of Felony', '2-year mandatory consecutive Felony (escalating)', '2 years mandatory consecutive', '5 years (second); life (third)', '$2,500', '{"Carrying or having in possession a firearm","At the time of commission or attempt of a felony","Regardless of whether the firearm was used"}', '2 years consecutive (first); 5 years consecutive (second); life (third+)', '{"Second felony firearm offense: 5-year mandatory consecutive","Third felony firearm offense: life imprisonment","No parole/probation on mandatory term"}', 'Michigan''s felony firearm statute is extremely powerful — mandatory consecutive sentence cannot be suspended or paroled. Simply possessing firearm during felony triggers it. Most influential Michigan gun law in practice.'),
  ('assault-firearm', 'MI', 'MCL 750.82 / MCL 750.227b', 'Assault with a Firearm (Felonious Assault + Felony Firearm)', 'Class F Felony + 2-year mandatory consecutive', '2 years mandatory (felony firearm)', '4 years (felonious assault) + 2 years mandatory consecutive (felony firearm)', '$4,500 combined', '{"Felonious assault with firearm as dangerous weapon","PLUS: possession of firearm at time of felony"}', '2 years consecutive mandatory for felony firearm component', '{"Intent to kill: assault with intent to murder — MCL 750.83","Great bodily harm: AWIGBH — MCL 750.84","Law enforcement victim: enhanced penalties"}', 'In practice, assault with firearm charges are filed as both MCL 750.82 (felonious assault) and MCL 750.227b (felony firearm). The 2-year mandatory runs consecutive.'),
  ('identity-theft', 'MI', 'MCL 445.65', 'Identity Theft', 'Class F Felony (information theft); Class E Felony (financial harm)', '0 years', '5 years (identity theft); additional up to 5 years for use', '$25,000', '{"Obtaining personal identifying information of another","Without authorization","With intent to fraudulently use to obtain money, credit, goods, services, or other property"}', 'None', '{"Elderly victim: sentencing enhancement","Multiple victims: consecutive charges","Financial losses over $20,000: Class D Felony"}', 'Michigan Identity Theft Protection Act (MCL 445.61 et seq.). Both identity theft (obtaining information) and identity fraud (using information) are separate offenses. Restitution mandatory.'),
  ('credit-card-fraud', 'MI', 'MCL 750.157n', 'Fraudulent Use of Credit/Debit Card', 'Misdemeanor ($500-) to Class G Felony ($1,000+)', '0 days', '4 years (felony); 1 year (misdemeanor)', '$2,000 (misdemeanor); $4,000 (felony)', '{"Using a credit or debit card","With knowledge that the card is stolen, revoked, or used without authorization","With intent to defraud"}', 'None', '{"Skimming device use: additional charges — MCL 750.157s","Organized fraud scheme: additional charges — MCL 750.218","Identity theft combined: concurrent charges"}', 'Michigan credit card fraud governed by MCL 750.157m-157q. Skimming is separately criminalized. Restitution mandatory.'),
  ('insurance-fraud', 'MI', 'MCL 500.4503', 'Insurance Fraud', 'Class F Felony ($1,000-$10,000); Class D Felony ($10,000+)', '0 years', '4 years (under $10,000); 10 years ($10,000+)', '$50,000', '{"Presenting, or causing to be presented","A claim for insurance benefits","Knowing the claim to contain materially false information"}', 'None', '{"Staged accident (auto insurance): additional charges","Healthcare fraud: federal prosecution possible","Multiple fraudulent claims: multiple counts"}', 'Auto insurance fraud is prevalent in Michigan. Michigan also has specific auto no-fault fraud provisions. Workers'' comp fraud under MCL 418.821.'),
  ('embezzlement', 'MI', 'MCL 750.174', 'Embezzlement', 'Class H Felony ($1,000-$20,000) to Class B Felony ($100,000+)', '0 years', '20 years ($100,000+); 10 years ($50,000-$100,000); 5 years ($20,000-$50,000); 1 year (under $1,000)', '3x amount embezzled', '{"Having property entrusted to one''s care","By virtue of employment or position of trust","Fraudulent conversion of that property for own use"}', 'None', '{"Public official: mandatory restitution","Financial institution: enhanced penalties","Multiple victims: additional counts"}', 'Michigan embezzlement has value-based tiers. Public official embezzlement may trigger additional penalties and forfeiture. Fiduciary breaches also subject to civil liability.'),
  ('fraud-welfare', 'MI', 'MCL 400.60', 'Welfare Fraud / Public Assistance Fraud', 'Misdemeanor to Felony (amount-based)', '0 days', '4 years (felony)', '$10,000', '{"Making a false statement or misrepresentation","In connection with an application for public assistance","With intent to fraudulently obtain benefits"}', 'None', '{"SNAP fraud: federal prosecution possible","Medicaid fraud: Class D Felony — MCL 400.606","Organized benefits fraud: enhanced charges"}', 'Public assistance fraud covers food stamps (SNAP), TANF, Medicaid. Restitution and benefit ineligibility are common consequences. DHHS administrative sanctions run separately.'),
  ('csc-first-degree', 'MI', 'MCL 750.520b', 'Criminal Sexual Conduct — First Degree', 'Class A Felony (Life)', '25 years (if victim under 13) to Life', 'Life', '$25,000', '{"Sexual penetration","With another person","Under circumstances set out in MCL 750.520b (age, force, coercion, incapacity, domestic relationship)"}', '25-year mandatory minimum if victim under 13 at time of offense', '{"Victim under 13: mandatory 25-year minimum — MCL 750.520b(2)(b)","Multiple acts: consecutive sentencing","Prior CSC conviction: enhanced mandatory","Use of weapon or force: aggravating factor"}', 'CSC-1 is Michigan''s most serious sexual assault offense. Life or any term of years. Sex offender registration mandatory (Tier 3 — lifetime). Romeo and Juliet provisions do NOT apply to CSC-1.'),
  ('csc-second-degree', 'MI', 'MCL 750.520c', 'Criminal Sexual Conduct — Second Degree', 'Class C Felony', '0 years', '15 years', '$15,000', '{"Sexual contact (not penetration)","With another person","Under circumstances described in MCL 750.520c"}', 'None', '{"Victim under 13: enhanced sentencing","Prior CSC conviction: significant enhancement","Use of weapon or threats: aggravating factor"}', 'CSC-2 covers sexual contact (touching intimate parts). Tier 2 sex offender registration (25 years). Defenses include age proximity under MCL 750.520e.'),
  ('csc-third-degree', 'MI', 'MCL 750.520d', 'Criminal Sexual Conduct — Third Degree', 'Class C Felony', '0 years', '15 years', '$15,000', '{"Sexual penetration","With another person","Under circumstances defined in MCL 750.520d (victim age 13-15, force, coercion, incapacity)"}', 'None', '{"Multiple acts: consecutive sentencing","Position of trust over victim: aggravating factor","Victim age 13-15 with actor 5+ years older: sex offender registration Tier 2"}', 'CSC-3 involves penetration with victim aged 13-15 or involving force/coercion. Similar elements to CSC-1 but lesser circumstances. Sex offender registration required.'),
  ('csc-fourth-degree', 'MI', 'MCL 750.520e', 'Criminal Sexual Conduct — Fourth Degree', '2-year Misdemeanor', '0 days', '2 years', '$500', '{"Sexual contact","With another person","Under circumstances enumerated in MCL 750.520e (limited force, victim age, incapacity)"}', 'None', '{"Prior CSC conviction: Class D Felony","Position of authority: aggravating factor","Victim mental or physical incapacity: enhanced sentencing"}', 'Highest-level misdemeanor CSC. Two-year Misdemeanor. Tier 1 sex offender registration (15 years). Romeo and Juliet exception if actor is less than 4 years older than 13-15 year old victim.'),
  ('indecent-exposure', 'MI', 'MCL 750.335a', 'Indecent Exposure', 'Misdemeanor (1 year); Class H Felony (aggravated)', '0 days', '1 year; 2 years (aggravated with fondling)', '$1,000; $2,000 (aggravated)', '{"Knowingly making any open or indecent exposure of person","Or of the person of another","In public or in a private place where others may see"}', 'None', '{"Fondling while exposing: Class H Felony — MCL 750.335a(2)(b)","Prior conviction: enhanced sentencing","In front of child: aggravating factor"}', 'Aggravated indecent exposure (fondling while exposing) is a felony. Sex offender registration may be required depending on circumstances and prior record.'),
  ('solicitation-prostitution', 'MI', 'MCL 750.449', 'Soliciting/Accosting for Immoral Purposes', 'Misdemeanor (93 days to 2 years depending on circumstances)', '0 days', '93 days (solicitation); 2 years (accosting minor)', '$500 to $2,000', '{"Soliciting, enticing, or accosting another person","For the purpose of prostitution, lewdness, or assignation","In a public place or visible from a public place"}', 'None', '{"Soliciting a minor: Class D Felony — MCL 750.449a","Human trafficking: separate charges — MCL 750.462a","Using a vehicle: additional civil forfeiture"}', 'Michigan''s solicitation law. Johns may be charged under MCL 750.449a. Human trafficking prosecution increasingly common. Diversion programs available in some counties.'),
  ('sex-trafficking', 'MI', 'MCL 750.462e', 'Labor or Sex Trafficking', 'Class B Felony (forced); Class C Felony (financial benefit)', '0 years', '20 years (Class B); 15 years (Class C)', '$20,000', '{"Recruiting, enticing, harboring, transporting, providing, obtaining, or maintaining a person","Through force, fraud, or coercion","For labor or commercial sexual activity"}', 'None', '{"Victim under 18: Class A Felony (Life) — MCL 750.462f","Victim under 13: enhanced mandatory","Use of controlled substance to facilitate: additional charges"}', 'Michigan Human Trafficking Act (MCL 750.462a et seq.). Minor victims cannot consent — no defense of consent. Traffickers subject to asset forfeiture. SARO designation available to victims.'),
  ('public-intoxication', 'MI', 'MCL 436.1703', 'Minor in Possession of Alcohol (MIP) / Disorderly Person', 'Misdemeanor (90 days)', '0 days', '90 days', '$100 first; $200 second; $500 third+', '{"Person under age 21","Possession, purchase, or consumption of alcohol","OR adult who is visibly intoxicated in public and creating a disturbance"}', 'None', '{"Using false ID to obtain alcohol: separate charge — MCL 436.1701","Furnishing alcohol to minor: Class A Misdemeanor — MCL 436.1701","Repeat offense: higher fine tier"}', 'Michigan does not have a standalone public intoxication statute for adults. Adults charged under disorderly person statute (MCL 750.167). MIP is age-specific under Liquor Control Code.'),
  ('disorderly-conduct', 'MI', 'MCL 750.167', 'Disorderly Person / Disorderly Conduct', '90-day Misdemeanor', '0 days', '90 days', '$500', '{"A person who is intoxicated in a public place and creates a disturbance","OR window peeper, brawler, loiterer for immoral purpose","OR engages in indecent, insulting, or obscene conduct"}', 'None', '{"Repeated disorderly conduct: sentencing enhancement","Combined with assault: separate charges"}', 'Michigan''s disorderly person statute covers numerous minor offenses. No separate ''disorderly conduct'' statute — all under MCL 750.167. Civil infractions for minor disturbances.'),
  ('trespassing', 'MI', 'MCL 750.552', 'Trespassing / Entering Premises Without Permission', 'Misdemeanor (90 days) to Class E Felony (if armed)', '0 days', '90 days (simple); 5 years (armed trespass — MCL 750.552a)', '$250 (simple); $5,000 (armed)', '{"Entering or remaining upon property of another","Without permission","After being forbidden to do so"}', 'None', '{"Armed trespass: Class E Felony — MCL 750.552a","Critical infrastructure: enhanced felony","Prior trespass on same property: sentencing enhancement"}', 'Simple trespass is 90-day misdemeanor. Trespass while armed is Class E Felony. Critical infrastructure trespass (pipelines, utilities) carries enhanced felony penalties.'),
  ('resisting-arrest', 'MI', 'MCL 750.81d', 'Resisting or Obstructing a Police Officer', '2-year Misdemeanor; Class D Felony if injury', '0 days', '2 years; 4 years (officer injured); 15 years (death)', '$2,000; $5,000 (injury); $15,000 (death)', '{"Knowingly and willfully","Assault, batter, wound, resist, obstruct, oppose, or endanger","A person the defendant knows is performing official duties (law enforcement, EMT, firefighter)"}', 'None', '{"Officer injured: Class D Felony (up to 4 years)","Officer seriously injured: Class C Felony (up to 10 years)","Officer killed: Class B Felony (up to 20 years)"}', 'Michigan''s ''resisting and obstructing'' is broader than resisting arrest — covers any interference with official duties. Verbal obstruction may suffice. Widely charged.'),
  ('obstruction-justice', 'MI', 'MCL 750.505', 'Common Law Obstruction of Justice', 'Class G Felony (5 years)', '0 years', '5 years', '$10,000', '{"An act or omission","That tends to impede or obstruct the administration of justice","With intent to obstruct"}', 'None', '{"Witness tampering: separate charge — MCL 750.122","Evidence destruction: separate charge — MCL 750.483a","Bribery of official: separate charge — MCL 750.117"}', 'Michigan uses common law obstruction. Specific statutes for witness intimidation (MCL 750.122), jury tampering, and evidence destruction. False police report under MCL 750.411a.'),
  ('perjury', 'MI', 'MCL 750.422', 'Perjury', 'Class E Felony (15-year max)', '0 years', '15 years', '$15,000', '{"Making a false statement","Under oath in a judicial or quasi-judicial proceeding","With knowledge of falsity and intent to mislead"}', 'None', '{"False affidavit: MCL 750.423 (15 years)","Subornation of perjury: MCL 750.425 (5 years)","Perjury causing wrongful conviction: aggravating factor"}', 'Michigan perjury carries up to 15 years — higher than many states. Subornation of perjury (procuring others to perjure) is a separate 5-year felony.'),
  ('bribery', 'MI', 'MCL 750.117', 'Bribery of Public Officer or Employee', 'Class E Felony', '0 years', '10 years', '$10,000 or 3x bribe amount', '{"Giving, offering, or promising","A benefit to a public officer or employee","With intent to influence their official action"}', 'None', '{"Receiving bribe (official): same penalties — MCL 750.118","Judicial bribery: enhanced","Commercial bribery: MCL 750.125 (1-year misdemeanor)"}', 'Both giving and receiving bribery are separate offenses. Commercial bribery (private sector) is a misdemeanor. Kickback schemes may be charged as embezzlement or conspiracy.'),
  ('money-laundering', 'MI', 'MCL 750.411k', 'Money Laundering', 'Class C Felony', '0 years', '20 years', '$500,000 or 2x amount laundered', '{"Conducting a financial transaction","Involving proceeds from a specified unlawful activity","With knowledge that the property represents proceeds of unlawful activity","With intent to conceal or disguise origin"}', 'None', '{"Federal money laundering concurrent: 18 U.S.C. § 1956","Drug trafficking underlying: sentencing enhancement","Financial institution involved: additional penalties"}', 'Michigan Money Laundering statute. Federal charges frequently concurrent. Asset forfeiture available. Structuring (avoiding reporting requirements) also chargeable.'),
  ('criminal-enterprise', 'MI', 'MCL 750.159i', 'Michigan Racketeer Influenced and Corrupt Organizations (RICO) — Conducting Criminal Enterprise', 'Class B Felony', '0 years', '20 years', '$100,000 or 3x gain', '{"A pattern of racketeering activity","Conducted through or in connection with an enterprise","With intent to benefit the enterprise"}', 'None', '{"Enterprise spanning multiple states: federal RICO concurrent","Murder predicate: enhanced sentencing","Leadership role: enhanced guidelines"}', 'Michigan RICO under MCL 750.159f et seq. Forfeiture of enterprise assets. Civil RICO also available to plaintiffs. Requires 2+ related racketeering acts within 10 years.'),
  ('gang-participation', 'MI', 'MCL 750.411u', 'Street Gang Membership — Criminal Street Gang Activity', 'Class D Felony', '0 years', '10 years', '$5,000', '{"Participation in a criminal street gang","By committing or attempting to commit a crime for the benefit of, at the direction of, or in association with the gang"}', 'None', '{"Crime near school: additional consecutive sentence","Crime involving firearms: enhanced penalties","Leadership: higher charge tier"}', 'Michigan Criminal Street Gang statutes under MCL 750.411t et seq. Gang membership alone not criminal — must commit a crime for the gang. Sentencing enhancement for underlying crimes.'),
  ('hazing', 'MI', 'MCL 750.411t', 'Hazing', 'Misdemeanor to Class E Felony', '0 days', '1 year (simple); 5 years (if serious injury)', '$1,000 to $5,000', '{"Knowing and willful acts","As a condition or precondition of joining a group or organization","That involves physical harm, degradation, or endangerment"}', 'None', '{"Death resulting: manslaughter or murder charges","Serious injury: felony hazing — MCL 750.411t(1)(b)","Organizational officer involved: leadership enhancement"}', 'Michigan Hazing Act covers schools, colleges, and organizations. ''Matt Araiza''s Law'' amendments. Organization may face civil and criminal liability.'),
  ('probation-violation', 'MI', 'MCL 771.4', 'Probation Violation', 'Revocation hearing; penalty up to maximum of underlying offense', '0 days', 'Maximum of original offense', 'No additional statutory fine', '{"Defendant on probation","Willful violation of a probation condition","Established by preponderance of evidence at violation hearing"}', 'None', '{"Technical violation: judge has discretion — no statutory limit","New criminal offense: may result in maximum sentence","Absconding: warrant issued, detention pending hearing"}', 'Michigan probation violations proceed before sentencing judge. No jury. Preponderance standard. Court can continue probation, modify conditions, or sentence to maximum. Technical violators may be eligible for Swift and Sure Sanctions program.'),
  ('parole-violation', 'MI', 'MCL 791.240', 'Parole Violation', 'Administrative proceeding; return to prison possible', 'Varies', 'Remainder of sentence', 'None', '{"Parolee violating conditions of parole","Including new criminal conduct, absconding, or technical violations"}', 'None', '{"New felony while on parole: return to prison plus new sentence","Absconding: maximum penalty at hearing"}', 'MDOC Parole Board has jurisdiction. Parole violations handled administratively. Parolee has due process rights (Morrissey v. Brewer). Michigan DOC may impose dipping, electronic monitoring, or return.'),
  ('escape-custody', 'MI', 'MCL 750.193', 'Escaping from Custody', 'Class G Felony (if convicted of felony); Misdemeanor (if awaiting trial on misdemeanor)', '0 years', '5 years (felony custody); 2 years (misdemeanor custody)', '$5,000', '{"Breaking from or escaping lawful custody","Of a prison, jail, or detention facility","OR escape from officer during transfer"}', 'None', '{"Use of force or weapon: additional assault charges","Escape by prisoner serving life: enhanced penalty","Multiple escape attempts: consecutive sentences"}', 'MCL 750.193 covers escaping from custody of any confinement facility. Constructive escape (failure to return from work release) under MCL 800.74.'),
  ('false-report', 'MI', 'MCL 750.411a', 'False Report of a Felony or Misdemeanor', 'Misdemeanor to Class F Felony', '0 days', '93 days (minor false report); 4 years (false report of felony); additional if resources expended', '$500 to $2,000', '{"Knowing and wilful","Reporting to law enforcement a crime that did not occur","OR providing false information in a police report"}', 'None', '{"False bomb threat: Class D Felony — MCL 750.544","Resources expended in response: restitution mandatory","Terrorism false report: Class B Felony"}', 'False felony report is Class F (4 years). False misdemeanor report is 93-day misdemeanor. Restitution for emergency response costs. False school bomb threat is separate enhanced offense.'),
  ('cybercrime', 'MI', 'MCL 752.795', 'Unauthorized Access to Computer Systems', 'Class E Felony', '0 years', '5 years', '$10,000', '{"Intentionally and without authorization","Accessing, altering, damaging, or destroying","A computer program, network, or data"}', 'None', '{"Financial damage over $10,000: Class D Felony","Government systems: enhanced federal charges","Ransomware deployment: additional counts"}', 'Michigan Computer Crime Law (MCL 752.791 et seq.). Federal CFAA charges frequently concurrent. Cyberbullying covered by separate statute (MCL 750.411x).'),
  ('cyberbullying', 'MI', 'MCL 750.411x', 'Cyberbullying', 'Misdemeanor (93 days); Class E Felony if serious harm', '0 days', '93 days; 1 year (2nd+); 5 years (bodily harm); Life (if death)', '$500 to $10,000', '{"Intentional posting of a message or statement","In a public media forum about a minor","Knowing the message is false, with intent to emotionally harm or extort"}', 'None', '{"Victim suffers serious bodily harm: Class E Felony","Victim commits suicide: Class B Felony or Life","Prior cyberbullying: 1-year misdemeanor"}', 'Michigan''s cyberbullying statute enacted 2018 (Matt Epling Law). Applies to minors. Adult cyberstalking under MCL 750.411h. Specific to false statements posted publicly about a minor.'),
  ('wire-fraud', 'MI', 'MCL 750.218 (state) / 18 U.S.C. § 1343 (federal)', 'Obtaining Money by False Pretenses / Wire Fraud', 'Class D Felony (state, $50,000+); federal: up to 20 years', '0 years', '10 years (state); 20 years (federal)', '$15,000 (state); $250,000 (federal)', '{"A scheme or artifice to defraud","Using electronic communications, wire, radio, or television","Obtaining money or property by false or fraudulent pretenses"}', 'None (state)', '{"Financial institution as victim: 30 years federal","Emergency (disaster fraud): enhanced federal","Amounts over $1M: state Class C Felony"}', 'State false pretenses under MCL 750.218; federal wire fraud under 18 U.S.C. § 1343. Federal prosecution typical for large schemes or interstate conduct.'),
  ('tax-evasion', 'MI', 'MCL 205.27', 'Tax Fraud / Failure to File — Michigan Income Tax', 'Misdemeanor to Class E Felony', '0 days', '4 years (tax evasion); 1 year (failure to file)', '$5,000', '{"Willful failure to file a required tax return","OR willful understatement or failure to pay taxes","With intent to evade tax obligation"}', 'None', '{"Fraudulent claim: enhanced penalties","Business/corporate tax fraud: corporate officer liability","Federal concurrent prosecution: IRS criminal division"}', 'Michigan Treasury administers state tax fraud. Federal IRS charges frequently concurrent. Sales tax fraud (MCL 205.111) is separate.'),
  ('extortion', 'MI', 'MCL 750.213', 'Extortion / Malicious Threats', 'Class E Felony', '0 years', '20 years', '$20,000', '{"Malicious threats to extort money","OR threats to injure another''s property, reputation, or person","With intent to compel compliance"}', 'None', '{"Amount extorted over $20,000: enhanced sentencing","Threat of violence: additional assault or terroristic threat charges","Use of computer/internet: cybercrime charges added"}', 'Michigan extortion carries up to 20 years — more severe than many states. Blackmail (threatening exposure of information) falls under this statute. Separate from robbery.'),
  ('receiving-stolen-property', 'MI', 'MCL 750.535', 'Receiving and Concealing Stolen Property', 'Class H Felony ($1,000+) to Class D Felony ($20,000+); Misdemeanor (under $1,000)', '0 days', '10 years ($20,000+); 5 years ($1,000-$20,000); 1 year (under $1,000)', '$5,000 (felony)', '{"Buying, receiving, possessing, or concealing stolen, embezzled, or converted property","With knowledge that it was stolen, embezzled, or converted","Intending to defraud the owner"}', 'None', '{"Organized auto theft ring: MCL 750.535a","Prior receiving stolen property conviction: sentencing enhancement","Commercial fencing operation: additional charges"}', 'Value-based tiers same as larceny. Motor vehicle receiving stolen property enhanced under MCL 750.535(5). Proof of knowledge often circumstantial.'),
  ('forgery', 'MI', 'MCL 750.248', 'Forgery of Public Records and Official Documents', 'Class F Felony', '0 years', '14 years', '$10,000', '{"Fraudulently making, altering, or forging","A public record, official document, court record, instrument, or writing","With intent to defraud"}', 'None', '{"Uttering forged instrument: separate charge — MCL 750.249","Financial documents: enhanced penalties","Government document fraud: federal charges possible"}', 'Michigan has multiple forgery statutes. MCL 750.248 (public records/court docs — 14 years), MCL 750.249 (private instruments — 14 years), MCL 750.250 (bank notes — 5 years). Uttering (using forged doc) is separate.'),
  ('conspiracy', 'MI', 'MCL 750.157a', 'Conspiracy', 'Same maximum as the substantive offense conspired to commit', '0 years', 'Same as underlying offense (Life if murder conspiracy)', 'Same as underlying offense', '{"An agreement between two or more persons","To do an illegal act or a legal act in an illegal manner","With intent to commit the substantive offense"}', 'None (follows underlying offense)', '{"Drug conspiracy: quantity-based thresholds apply","Federal conspiracy concurrent: 18 U.S.C. § 371","RICO conspiracy: additional enhancement"}', 'Michigan conspiracy carries same maximum as the substantive offense. No overt act required for conspiracy in Michigan (split from federal law which requires overt act for § 371). Withdrawal defense possible.'),
  ('attempt', 'MI', 'MCL 750.92', 'Attempt to Commit a Felony', 'Reduced from substantive offense (generally 5 years max for felony, 2 years for misdemeanor)', '0 years', '5 years for felony attempt; 2 years for misdemeanor attempt; Life if attempted murder', 'Varies', '{"Intent to commit a specific crime","AND an overt act done toward committing that crime","Falling short of completing the intended offense"}', 'None (unless underlying offense has mandatory)', '{"Attempted murder: assault with intent to murder — MCL 750.83 (Life)","Attempted armed robbery: Class C Felony","Near-completion of offense: sentencing enhancement"}', 'Michigan attempt generally punished at reduced level. Attempted murder is separately codified as ''Assault with Intent to Murder'' under MCL 750.83 (up to Life). General attempt statute MCL 750.92.'),
  ('aiding-abetting', 'MI', 'MCL 767.39', 'Aiding and Abetting', 'Same as the principal offense', 'Same as principal', 'Same as principal', 'Same as principal', '{"The defendant assisted the principal","In the commission of the offense","With knowledge that the principal intended to commit a crime","AND intending to aid"}', 'Same as principal', '{"Active participation increases culpability","Weapon possession during aiding: felony firearm may attach","Getaway driver: same liability as principal"}', 'Michigan law makes aiders and abettors equally guilty as principals. No separate ''accessory before the fact'' distinction. Accessories after the fact are charged separately (MCL 750.505).'),
  ('hit-run-injury', 'MI', 'MCL 257.617', 'Leaving the Scene of an Accident Involving Personal Injury or Death', 'Class D Felony (injury); Class B Felony (death)', '0 years', '5 years (injury); 15 years (death)', '$5,000 (injury); $10,000 (death)', '{"Operating a motor vehicle involved in an accident","Resulting in injury or death to a person","Failing to stop, render aid, and provide information"}', 'None', '{"OWI at time of accident: concurrent charges","Death resulting: Class B Felony","Prior leaving scene: sentencing enhancement"}', 'Duty to stop, render reasonable assistance, and provide identification. Property damage only: misdemeanor under MCL 257.618. Separate criminal culpability from underlying negligence.'),
  ('elder-abuse', 'MI', 'MCL 750.145n', 'Vulnerable Adult Abuse — First Through Fourth Degree', 'Class D Felony (1st); Class F Felony (2nd); Class H Felony (3rd); Misdemeanor (4th)', '0 days', '10 years (1st); 4 years (2nd); 2 years (3rd); 1 year (4th)', '$5,000', '{"A caregiver for a vulnerable adult","Intentionally or knowingly causes physical or mental harm","OR willful neglect of duty to provide care"}', 'None', '{"Financial exploitation concurrent: MCL 750.174a","Death of vulnerable adult: enhanced murder/manslaughter","Healthcare setting: licensing consequences"}', 'Michigan Vulnerable Adults Act. ''Vulnerable adult'' includes elderly or disabled persons under care. Mandatory reporting by caregivers. Financial exploitation of vulnerable adult is a separate offense.'),
  ('financial-exploitation-elder', 'MI', 'MCL 750.174a', 'Financial Exploitation of a Vulnerable Adult', 'Class D Felony ($1,000+) to Class C Felony ($100,000+)', '0 years', '10 years ($100,000+); 5 years ($1,000-$100,000)', '$100,000', '{"Obtaining money or property","From a vulnerable adult","Through undue influence, fraud, coercion, or breach of fiduciary duty"}', 'None', '{"Caregiver position of trust: sentencing enhancement","Embezzlement concurrent: MCL 750.174","Restitution mandatory"}', 'Michigan''s financial elder abuse statute. ''Vulnerable adult'' includes those 18+ who are disabled or 65+ with limited capacity. Civil remedies also available (3x damages).'),
  ('terroristic-threats', 'MI', 'MCL 750.543m', 'Threat of Terrorism', 'Class B Felony (20 years)', '0 years', '20 years', '$20,000', '{"Threatening to commit an act of terrorism","By any means of communication","With specific intent to terrorize"}', 'None', '{"Actual bomb/weapon present: terrorism execution charges — Class A","School threat: additional charges under school safety laws","Federal prosecution: 18 U.S.C. § 875 concurrent"}', 'Michigan Anti-Terrorism Act (MCL 750.543b et seq.). School threats separately enhanced under MCL 750.543m and school safety laws. Causing evacuation (MCL 750.543p) is additional charge.'),
  ('weapons-carrying-prohibited', 'MI', 'MCL 750.227c', 'Carrying Pistol — Prohibited Places', 'Class A Misdemeanor (up to 90 days) or higher depending on location', '0 days', '90 days misdemeanor; felony if in school', '$100', '{"Carrying a pistol or dangerous weapon","Into a prohibited place","Without legal authority"}', 'None', '{"School zone: Class E Felony — MCL 750.237a","Courthouse: additional contempt charges","Legislative buildings: enhanced penalties"}', 'Michigan''s pistol-free zones include schools, courts, casinos, stadiums, hospitals. CPL holders not exempt from all zones (courts, polling places, churches by policy). School zone felony under MCL 750.237a.'),
  ('weapons-school-zone', 'MI', 'MCL 750.237a', 'Weapons — Weapon-Free School Zone Offense', 'Class G Felony to Class E Felony', '0 years', '2 years (possessing weapon at school); additional consecutive 2 years for crime in zone', '$5,000', '{"Possessing a dangerous weapon","On school property or in a vehicle on school property","Without school authorization"}', 'None for simple possession (discretionary)', '{"Crime committed in school zone: mandatory 2-year consecutive sentence","Firearm involved: felony firearm may also attach","Pointing weapon at student: additional assault charges"}', 'Weapon-free school zone enhancement adds consecutive 2 years for crimes committed with weapons in or near schools. Zero tolerance school discipline policies run separately.'),
  ('bomb-threat', 'MI', 'MCL 750.543m / MCL 750.544', 'Bomb Threat / False Report of Explosive', 'Class D Felony', '0 years', '10 years', '$10,000 plus restitution', '{"Making a false report or threat","Of a bomb, explosive, or other destructive device","Knowing the report is false or the threat is not real"}', 'None', '{"School bomb threat: separate enhanced provision under school safety","Resources expended: mandatory restitution","Multiple threats: additional counts"}', 'False bomb threat is a felony in Michigan. Restitution for emergency response costs is mandatory. Juveniles frequently charged. Repeat school threats trigger habitual offender provisions.'),
  ('animal-cruelty', 'MI', 'MCL 750.50', 'Animal Cruelty / Killing or Torturing an Animal', 'Class H Felony (first); Class F Felony (repeat or extreme cruelty)', '0 years', '4 years (first felony); 2 years (misdemeanor)', '$5,000 (felony); $1,000 (misdemeanor)', '{"Intentionally killing, maiming, or torturing an animal","OR using an animal in a fighting operation","OR abandonment causing death"}', 'None', '{"Animal fighting: Class H Felony — MCL 750.49","Second conviction: Class F Felony (4 years)","Cat or dog: enhanced penalties over other animals"}', 'Michigan animal cruelty law enhanced 2007. Animal fighting is separately criminalized. Domestic violence animal abuse connection often used in prosecution strategy.'),
  ('retail-fraud', 'MI', 'MCL 750.356c', 'Retail Fraud — Organized', 'Class F Felony', '0 years', '5 years', '$10,000', '{"Two or more persons acting in concert","Committing retail fraud","With total value exceeding $1,000"}', 'None', '{"Organized retail theft ring: MCL 752.1081 enhanced penalties","Prior retail fraud: degree enhancement","Fraud device used: additional charges"}', 'Organized retail fraud creates felony liability where individual thefts might be misdemeanors. Michigan Organized Retail Crime Act (MCL 752.1081 et seq.) provides additional enforcement.'),
  ('assault-police-officer', 'MI', 'MCL 750.81d', 'Assaulting, Battering, Wounding, Resisting, or Obstructing Officer', '2-year Misdemeanor to Class B Felony', '0 days', '2 years (simple); 4 years (injury); 10 years (serious injury); 20 years (death)', '$2,000 to $20,000', '{"Assaulting, battering, wounding, resisting, obstructing, opposing, or endangering","A person the defendant knows or has reason to know is performing official duties","Including law enforcement, EMTs, corrections officers, firefighters"}', 'None', '{"Officer seriously injured: Class C Felony","Officer killed: Class B Felony","Use of weapon: felony firearm may apply"}', 'MCL 750.81d covers broad category of interference with officers and emergency responders. Even verbal obstruction may qualify. Enhanced penalties scale with resulting harm.'),
  ('fleeing-eluding', 'MI', 'MCL 750.479a', 'Fleeing and Eluding — Operating Vehicle to Avoid Police', 'Class G Felony (1st); Class F Felony (2nd); Class D Felony (3rd/4th)', '0 years', '2 years (1st); 4 years (2nd); 10 years (3rd/4th with injury or reckless driving)', '$5,000', '{"Operating a motor vehicle","Willfully failing to obey a police officer''s signal to stop","While the officer is in uniform and the vehicle is marked"}', 'None', '{"Sustained high-speed chase: 3rd degree — Class F","Causing injury or extreme recklessness: 4th degree — Class D","Prior fleeing conviction: degree enhancement"}', 'Michigan has four degrees of fleeing and eluding. 1st degree (2 years) is base, escalating with risk factors. Combined with OWI or reckless driving in many cases.'),
  ('hate-crime', 'MI', 'MCL 750.147b', 'Ethnic Intimidation (Hate Crime)', '2-year Misdemeanor (simple); up to Class C Felony (injury)', '0 days', '2 years (intimidation); escalates based on underlying crime', '$5,000', '{"Malicious use of violence, property damage, or harassment","Motivated by the victim''s race, color, religion, gender, or national origin","With intent to intimidate or harm"}', 'None', '{"Underlying assault: combined sentencing","Bias-motivated property destruction: mandatory sentencing enhancement","Multiple victims targeted: additional counts"}', 'Michigan Ethnic Intimidation Act (MCL 750.147b). Does not include sexual orientation (gap in Michigan law as of writing). Civil remedies under Elliott-Larsen Civil Rights Act also available.'),
  ('human-trafficking', 'MI', 'MCL 750.462c', 'Forced Labor or Services', 'Class B Felony', '0 years', '20 years', '$20,000', '{"Recruiting, harboring, transporting, providing, or obtaining a person","By force, fraud, or coercion","For the purpose of forced labor or services"}', 'None', '{"Victim under 18: Class A Felony — MCL 750.462f","Use of controlled substance to facilitate: additional charges","Leadership role: enhanced sentencing"}', 'Michigan Human Trafficking Act (MCL 750.462a et seq.). Civil cause of action available to victims (MCL 750.462n). Asset forfeiture. Federal parallel prosecution under 18 U.S.C. § 1589.'),
  ('possession-explosives', 'MI', 'MCL 750.200', 'Manufacturing or Possessing Explosives', 'Class D Felony', '0 years', '15 years', '$10,000', '{"Manufacturing, possessing, transporting, or delivering","Any explosive or incendiary device","Without lawful authority or license"}', 'None', '{"Intent to terrorize: Class B Felony under MCL 750.543n","Used in crime: additional charges","Near school: mandatory consecutive enhancement"}', 'Michigan explosives possession statute. Licensed mining/commercial use exempt. Molotov cocktails and improvised explosive devices clearly covered. Federal concurrent prosecution under 18 U.S.C. § 844.'),
  ('impersonating-officer', 'MI', 'MCL 750.215', 'Impersonating a Police Officer', 'Class G Felony', '0 years', '4 years', '$2,000', '{"Pretending to be a peace officer or public official","Without lawful authority","While exercising authority claimed from that position"}', 'None', '{"Assault or fraud committed while impersonating: additional charges","Use of official-looking badge/vehicle: sentencing enhancement","Traffic stop impersonation: enhanced penalties"}', 'Using a fake badge or wearing law enforcement uniform while acting as officer. Separate from impersonating public employees (MCL 750.217). High-profile cases involve fake traffic stops.'),
  ('criminal-contempt', 'MI', 'MCL 600.1701', 'Criminal Contempt of Court', 'Misdemeanor (up to 93 days per count)', '0 days', '93 days (indefinite for civil contempt until compliance)', '$7,500', '{"Willful disobedience of a court order","OR conduct that disrupts, obstructs, or interferes with judicial proceedings"}', 'None', '{"Contempt of PPO: also criminal charge under MCL 600.2950","Repeated contempt: multiple consecutive counts","Jury present: direct contempt — immediate sanction"}', 'Michigan contempt is 93 days per count, but multiple counts can stack. Civil contempt for compliance continues until defendant complies. Criminal contempt for past conduct ends with sentence.'),
  ('unlawful-imprisonment', 'MI', 'MCL 750.349b', 'Unlawful Imprisonment', 'Class D Felony', '0 years', '15 years', '$15,000', '{"Knowingly restraining another person","Under circumstances that do not amount to kidnapping","Without legal authority and without consent"}', 'None', '{"Kidnapping (if all elements met): Class A Felony — MCL 750.349","Victim is minor: enhanced sentencing","Use of force or weapon: additional charges"}', 'Lesser offense to kidnapping. No specific intent to ransom or harm required. Used when kidnapping cannot be proven. Often charged with other offenses.'),
  ('mortgage-fraud', 'MI', 'MCL 565.451', 'Mortgage Fraud', 'Class E Felony to Class B Felony (amount-based)', '0 years', '20 years ($100,000+); 15 years ($50,000-$100,000); 5 years (under $50,000)', '$100,000', '{"Making a materially false statement","In connection with a mortgage loan application or real estate transaction","With intent to defraud a lender or purchaser"}', 'None', '{"Multiple loan applications: multiple counts","Bank fraud: federal prosecution concurrent","Real estate professional involved: licensing action"}', 'Michigan Mortgage Fraud Act. Straw buyer arrangements and appraisal fraud commonly charged. Federal bank fraud under 18 U.S.C. § 1344 frequently concurrent.'),
  ('illegal-dumping', 'MI', 'MCL 324.8905', 'Littering / Open Dumping', 'Civil infraction to Misdemeanor; Felony for large-scale dumping', 'Civil fine', '5 years (open dumping — felony)', '$10,000 (felony); $500 (misdemeanor)', '{"Knowingly depositing solid waste","On property without authorization","Other than a licensed waste disposal facility"}', 'None', '{"Hazardous waste: enhanced felony — MCL 324.11122","Large volume (7+ cubic yards): Class G Felony","Corporate dumping: officer liability"}', 'Regulated under Michigan Natural Resources and Environmental Protection Act. Hazardous waste dumping is separately enhanced. Local ordinance violations run concurrently.'),
  ('noise-ordinance', 'MI', 'MCL 750.167(1)(e)', 'Disorderly Person — Disturbing the Peace', '90-day Misdemeanor', '0 days', '90 days', '$500', '{"Willful and malicious conduct","In disruption of a lawful assembly or public peace","OR using profane or indecent language in public"}', 'None', '{"Near school or church: local ordinance enhancement","Repeat conduct: sentencing enhancement"}', 'Michigan disturbing the peace under MCL 750.167. Most jurisdictions also have local noise ordinances as civil infraction alternative. First Amendment considerations apply to pure speech.'),
  ('stalking-cyber', 'MI', 'MCL 750.411s', 'Cyberstalking', 'Misdemeanor (2 years); Class E Felony if aggravated', '0 days', '2 years; 5 years (aggravated)', '$2,000; $10,000 (aggravated)', '{"A willful course of conduct","Involving repeated electronic communications","That would cause a reasonable person to feel terrorized, frightened, or harassed"}', 'None', '{"Violation of PPO: aggravated — MCL 750.411t","Prior stalking conviction: aggravated charge","Victim under 18: aggravated stalking"}', 'Michigan''s electronic stalking statute under MCL 750.411s. Different from cyberbullying (MCL 750.411x) which targets minors specifically. ''Course of conduct'' requires 2+ acts.'),
  ('aggravated-stalking', 'MI', 'MCL 750.411i', 'Aggravated Stalking', 'Class E Felony', '0 years', '5 years', '$10,000', '{"Stalking (course of conduct causing reasonable fear)","PLUS: violation of PPO, prior stalking conviction, victim under 18, or making credible threat"}', 'None', '{"Prior aggravated stalking: enhanced sentencing","Use of weapon: additional charges","Child victim: sex offender registration if elements met"}', 'Aggravated stalking requires base stalking plus one aggravating factor. PPO violation concurrent with stalking creates presumptive aggravated charge. Sex offender registration may apply if victim is minor.'),
  ('jury-tampering', 'MI', 'MCL 750.120a', 'Juror Tampering / Jury Tampering', 'Class E Felony', '0 years', '5 years', '$5,000', '{"Willfully communicating with a juror","In relation to the juror''s duties","With intent to influence a verdict or decision"}', 'None', '{"Bribery of juror: additional bribery charges — MCL 750.120","Organized tampering scheme: conspiracy charges","During capital case: enhanced sentencing"}', 'Juror tampering includes contact with juror or potential juror. Obstruction of justice may also be charged concurrently. Social media contact with jurors increasingly prosecuted.'),
  ('witness-tampering', 'MI', 'MCL 750.122', 'Intimidation of a Witness or Victim', 'Class F Felony (4 years); Class C Felony (15 years) if serious harm', '0 years', '4 years (intimidation only); 15 years (if serious injury results)', '$10,000', '{"Intimidating, interfering with, or bribing a witness or victim","With intent to obstruct justice or prevent testimony","In a pending or prospective criminal proceeding"}', 'None', '{"Assault of witness: additional charges and enhanced sentencing","Gang-related intimidation: gang enhancement","Prior witness tampering: habitual offender sentencing"}', 'Victim intimidation and witness tampering are combined under MCL 750.122. Serious injury to witness elevates to Class C Felony. Applies to prospective (not just pending) proceedings.'),
  ('prostitution', 'MI', 'MCL 750.448', 'Prostitution', 'Misdemeanor (93 days to 2 years depending on circumstances)', '0 days', '93 days (first); 1 year (second); 2 years (third+)', '$500 to $2,000', '{"Engaging in sexual acts","For hire or compensation","With another person"}', 'None', '{"Near school: enhanced penalties","HIV positive and engaging in prostitution: felony — MCL 333.5210","Trafficking component: Class B/C Felony — MCL 750.462a"}', 'Michigan''s prostitution laws apply to both selling and buying sex. Prior to 2023 reforms, sellers faced more enforcement than buyers. Human trafficking laws increasingly used for exploitation cases.'),
  ('pandering', 'MI', 'MCL 750.455', 'Pandering / Pimping', 'Class C Felony (15 years)', '0 years', '15 years', '$10,000', '{"Procuring, inducing, or enticing a person","To become a prostitute or to engage in sexual acts for hire","Through persuasion, promises, threats, or violence"}', 'None', '{"Victim under 18: Class B Felony (human trafficking) — MCL 750.462f","Violence used: additional assault charges","Drug use to control victim: additional charges"}', 'Pandering (procuring) and keeping a house of prostitution (MCL 750.452) are separate offenses. Human trafficking charges increasingly used for exploitation of adults and minors.'),
  ('possession-child-pornography', 'MI', 'MCL 750.145c(4)', 'Possession of Child Sexually Abusive Material (CSAM)', 'Class E Felony', '0 years', '4 years', '$10,000', '{"Knowingly possessing","Any child sexually abusive material","Knowing or having reason to know it is child sexually abusive material"}', 'None', '{"Production or distribution: Class B or C Felony — MCL 750.145c(2)/(3)","Using a computer to distribute: enhanced federal charges","Prior CSAM conviction: enhanced sentencing"}', 'Michigan uses ''child sexually abusive material'' (CSAM). Production is Class B Felony (20 years). Distribution is Class C Felony (7 years). Tier 3 sex offender registration (lifetime). Federal parallel prosecution common.'),
  ('production-child-pornography', 'MI', 'MCL 750.145c(2)', 'Production of Child Sexually Abusive Material (CSAM)', 'Class B Felony', '0 years', '20 years', '$100,000', '{"Persuading, inducing, enticing, coercing, or forcing a child","To engage in sexually explicit conduct","For the purpose of producing child sexually abusive material"}', 'None', '{"Child under 13: enhanced federal prosecution","Prior CSAM conviction: mandatory enhancement","Distribution of material: additional Class C Felony count"}', 'Most serious CSAM offense in Michigan. Life sentences available for repeat offenders. Federal prosecution under 18 U.S.C. § 2251 typically concurrent. Tier 3 sex offender registration mandatory.'),
  ('owi-minor-in-vehicle', 'MI', 'MCL 257.625(7)', 'OWI with Passenger Under 16 Years of Age', '93-day Misdemeanor (additional consecutive charge)', '0 days', '93 days', '$500', '{"Operating a motor vehicle while intoxicated","With a passenger under 16 years of age in the vehicle"}', 'None', '{"Child protective services referral mandatory","Enhanced sentence on primary OWI charge","Repeat offense: child endangerment charges possible"}', 'Separate misdemeanor charge in addition to primary OWI. Child Protective Services will be notified. License suspension includes this factor. Second offense with child present escalates severity.')
INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('dui-first-offense', 'NJ', 'N.J.S.A. 39:4-50', 'Driving While Intoxicated — First Offense', 'Traffic Offense (not classified as crime under Title 2C)', '12-48 hours (IDRC)', '30 days jail', '$400 (BAC 0.08-0.10) or $500 (BAC 0.10+)', '{"Operating a motor vehicle upon a highway or quasi-public area","While under the influence of intoxicating liquor OR with BAC of 0.08% or higher","OR with BAC of 0.10% or higher (enhanced penalties)"}', '12-48 hours in Intoxicated Driver Resource Center (IDRC); license suspension 3 months (0.08-0.10) or 7-12 months (0.10+)', '{"BAC 0.10%+: higher fine tier ($500-$1,000)","Prior DWI within 10 years: second offense penalties","Refusal to take breath test: N.J.S.A. 39:4-50.4a — concurrent suspension","School zone DWI: double minimum penalties — N.J.S.A. 39:4-50(g)"}', 'NJ uses ''Driving While Intoxicated'' (DWI). Not a Title 2C crime — handled in Municipal Court. No jail for first offense except in aggravated cases. License suspension mandatory. Surcharge: $1,000/year for 3 years (MCCA).'),
  ('dui-second-offense', 'NJ', 'N.J.S.A. 39:4-50(a)(2)', 'Driving While Intoxicated — Second Offense', 'Traffic Offense', '48 hours jail', '90 days jail', '$1,000', '{"Operating a motor vehicle while under the influence","Prior DWI conviction within 10 years"}', '48 hours jail; 30 days community service; 2-year license revocation', '{"Third offense: increased mandatory jail","School zone: double penalties","Refusal concurrent: additional suspension"}', '30 days community service (in lieu of or in addition to jail). Ignition interlock device required during and after suspension. Surcharges apply for 3 years post-conviction.'),
  ('dui-third-offense', 'NJ', 'N.J.S.A. 39:4-50(a)(3)', 'Driving While Intoxicated — Third or Subsequent Offense', 'Traffic Offense', '180 days jail', '180 days jail', '$1,000', '{"Operating a motor vehicle while under the influence","Two or more prior DWI convictions"}', '180 days incarceration (90 days credit for inpatient rehab); 10-year license revocation', '{"Prior indictable conviction for DWI: enhanced","School zone: mandatory period doubled"}', '10-year mandatory license revocation. Ignition interlock required. 90 days may be served in residential treatment program. Fourth offense also results in 10-year revocation with same jail time.'),
  ('dui-drugs', 'NJ', 'N.J.S.A. 39:4-50(a)', 'Driving Under the Influence of Drugs', 'Traffic Offense', '12-48 hours (IDRC)', '30 days jail (first offense)', '$400-$500', '{"Operating a motor vehicle","While under the influence of any narcotic, hallucinogenic, or habit-producing drug","Or with a Schedule I controlled dangerous substance (CDS) in urine"}', 'Same as alcohol DWI; IDRC attendance required', '{"Drug DWI in school zone: double penalties","Prior DWI (alcohol or drug): same escalation applies"}', 'NJ drug DWI uses same statute as alcohol DWI. Drug recognition expert (DRE) testimony used. Urine test for CDS presence. No per se level for most drugs except marijuana (still disputed).'),
  ('vehicular-homicide', 'NJ', 'N.J.S.A. 2C:11-5', 'Vehicular Homicide', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Causing the death of another person","By driving a vehicle recklessly","Including DWI as presumptive recklessness"}', 'DWI-related: mandatory 3-5 year NERA period; 180-day license suspension', '{"DWI at time of death: no probation — N.J.S.A. 2C:11-5(b)(1)","Prior DWI conviction: 1st Degree treatment — N.J.S.A. 2C:11-5(c)(2)","NERA applies: 85% of sentence without parole"}', 'DWI-related vehicular homicide presumptively reckless. No probation if DWI involved. Prior DWI conviction elevates to 1st Degree Crime (10-20 years). NERA applies to DWI vehicular homicide.'),
  ('dui-felony-injury', 'NJ', 'N.J.S.A. 2C:12-1(c)', 'Assault by Auto — DWI Causing Serious Bodily Injury', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Driving a vehicle recklessly or while intoxicated","Causing serious bodily injury to another person"}', 'If DWI: no probation; mandatory Graves Act consideration if weapon used', '{"Prior DWI: upgraded from 3rd to 2nd Degree","Bodily injury only (not serious): 3rd Degree","School zone: 4th Degree standalone or enhanced on primary"}', 'Assault by Auto is the NJ mechanism for DWI-injury cases. Seriousness of injury determines degree. Simple bodily injury is 4th Degree. Serious bodily injury is 3rd or 2nd Degree depending on DWI involvement.'),
  ('reckless-driving', 'NJ', 'N.J.S.A. 39:4-96', 'Reckless Driving', 'Traffic Offense (not Title 2C)', '0 days', '60 days jail; 3-month license suspension', '$200 (first); $500 (subsequent)', '{"Operating a vehicle heedlessly","In willful or wanton disregard of the rights or safety of others","In a manner likely to endanger a person or property"}', 'None', '{"Second offense within 5 years: $500 fine, up to 3 months jail","Causing injury: assault by auto — N.J.S.A. 2C:12-1(c)","School zone: additional penalties"}', 'Reckless driving is a motor vehicle offense handled in municipal court. Points assessed (5 points). First offense up to 60 days jail and $200 fine. Distinguished from careless driving (N.J.S.A. 39:4-97).'),
  ('driving-on-suspended', 'NJ', 'N.J.S.A. 39:3-40', 'Driving While Suspended', 'Traffic Offense', '0 days', '180 days jail', '$500 first; $750 second; $1,000 third+', '{"Operating a motor vehicle upon a public highway","While driving privileges are suspended or revoked"}', 'None (unless DWI-related suspension: 10-45 days mandatory)', '{"DWI suspension: 10-90 days mandatory jail — N.J.S.A. 39:3-40(f)","Third offense on DWI suspension: 180 days mandatory","Accident while driving suspended: additional civil liability"}', 'DWI-related suspension driving carries mandatory jail time escalating with offense number. Non-DWI suspension driving is fine/community service. Insurance surcharges apply.'),
  ('drug-possession-marijuana', 'NJ', 'N.J.S.A. 2C:35-10', 'Possession of CDS — Marijuana (Residual Amounts)', 'Disorderly Persons Offense (small amounts for those under 21 or excess amounts)', '0 days', '6 months', '$1,000', '{"Knowing possession of marijuana","In excess of 6 ounces (adults 21+) or any amount (under 21)","Without lawful purpose"}', 'None', '{"Over 6 oz but under 1 pound: Disorderly Persons","1-5 pounds: 4th Degree Crime — N.J.S.A. 2C:35-5","Distribution: separate enhanced charges"}', 'Adult recreational marijuana legalized in NJ effective April 2022 (up to 6 oz). Under-21 possession of any amount is civil violation or disorderly persons. Large quantities still criminal under distribution or trafficking statutes.'),
  ('drug-possession', 'NJ', 'N.J.S.A. 2C:35-10(a)', 'Possession of CDS — Schedule I/II (Not Marijuana)', '3rd Degree Crime (heroin, cocaine, meth, fentanyl); 4th Degree (Schedule III-IV)', '3 years (3rd Degree guidelines)', '5 years (3rd Degree); 18 months (4th Degree)', '$75,000 (3rd Degree); $10,000 (4th Degree)', '{"Knowingly and unlawfully possessing","A controlled dangerous substance (CDS)","Not pursuant to a valid prescription"}', 'None for simple possession', '{"School zone: mandatory 1-year addition — N.J.S.A. 2C:35-7","Public housing: mandatory 1-year addition","Drug-free park: mandatory addition","Prior CDS conviction: parole ineligibility period may apply"}', 'NJ''s Drug Free Zone law doubles mandatory minimums for possession within 500 feet of school or within 500 feet of public housing. School zone carries mandatory 1-year parole ineligibility. Drug courts widely available.'),
  ('drug-possession-with-intent', 'NJ', 'N.J.S.A. 2C:35-5', 'Manufacturing, Distributing, or Dispensing CDS', '1st-3rd Degree Crime (amount and substance dependent)', '10 years (1st Degree weight)', '20 years (1st Degree)', '$500,000 (1st Degree); $150,000 (2nd Degree)', '{"Knowingly or purposely manufacturing, distributing, dispensing, or possessing with intent","A controlled dangerous substance (CDS)","Without lawful authority"}', '1st Degree (5+ oz heroin/cocaine or 25+ lbs marijuana): NERA — must serve 1/3 to 1/2 before parole; School zone: additional mandatory 1-3 years', '{"Within 500 feet of school: mandatory 1-3 year consecutive — N.J.S.A. 2C:35-7","Public housing zone: mandatory addition — N.J.S.A. 2C:35-7.1","1st Degree: NERA applies (85% of sentence)","Distributing to minor: upgrade one degree — N.J.S.A. 2C:35-6","Using juvenile to distribute: 3rd Degree standalone — N.J.S.A. 2C:35-6"}', 'NJ''s primary drug distribution statute. Quantity-based degrees: 5+ oz heroin/cocaine = 1st Degree; 1/2-5 oz = 2nd Degree; smaller = 3rd Degree. School zone add-on is commonly used prosecutorial tool.'),
  ('drug-trafficking', 'NJ', 'N.J.S.A. 2C:35-3', 'Leader of Narcotics Trafficking Network', '1st Degree Crime', '25 years', 'Life imprisonment', '$750,000', '{"Conspiring with others as organizer, supervisor, or manager","Of a network of persons who engage in the production, manufacture, shipment, or distribution of CDS","Acting with respect to quantities in excess of statutory thresholds"}', '25-year mandatory minimum without parole', '{"Drug kingpin conviction: no parole for 25 years","Forfeiture of all proceeds and assets","RICO charges concurrent"}', 'New Jersey''s drug kingpin statute. 25-year mandatory without parole. Designed for leaders of drug networks. Requires proof of supervisory role and quantity thresholds. Not merged with simple distribution.'),
  ('drug-paraphernalia', 'NJ', 'N.J.S.A. 2C:36-2', 'Use or Possession with Intent to Use Drug Paraphernalia', 'Disorderly Persons Offense', '0 days', '6 months', '$1,000', '{"Possession or use of drug paraphernalia","With intent to use in connection with a controlled dangerous substance violation"}', 'None', '{"Distribution of paraphernalia to minor: 4th Degree Crime — N.J.S.A. 2C:36-3","Prior CDS conviction: sentencing enhancement"}', 'Paraphernalia charges frequently accompany CDS possession charges. Distribution of paraphernalia to person under 18 is a 4th Degree Crime.'),
  ('murder-first-degree', 'NJ', 'N.J.S.A. 2C:11-3(a)(1)-(2)', 'Murder — Purposeful or Knowing', '1st Degree Crime (special designation)', '30 years without parole', 'Life imprisonment', 'No statutory cap', '{"Purposely or knowingly causing the death of another person","OR purposely or knowingly causing serious bodily injury resulting in death"}', '30-year parole disqualifier mandatory; life possible with 30-year minimum', '{"Murder of law enforcement: mandatory life, 30-year disqualifier","Murder by hired killer: mandatory life, 30-year disqualifier","Victim under 14 — murder by parent/guardian: 30-year disqualifier","Serial murder: death penalty replaced by life without parole"}', 'NJ abolished death penalty in 2007. Maximum is Life LWOP or life with 30-year parole disqualifier. Murder is not classified as 1st or 2nd Degree in NJ Title 2C — it is ''murder'' with sentencing structure. NERA does not apply — murder has its own parole disqualifier provisions.'),
  ('murder-second-degree', 'NJ', 'N.J.S.A. 2C:11-3(a)(3)', 'Murder — Felony Murder', '1st Degree Crime', '30 years without parole', 'Life', 'No cap', '{"As principal or accomplice","During commission or attempted commission of robbery, sexual assault, arson, burglary, kidnapping, or carjacking","Causing the death of any person including co-felon"}', '30-year parole disqualifier', '{"Prior murder conviction: mandatory life","Multiple victims: multiple murder counts"}', 'NJ felony murder is still 1st Degree Crime level (murder) — does not reduce to manslaughter. NJ Supreme Court has narrowed felony murder in recent years (State v. Doolin). Accomplice liability broadly applied.'),
  ('voluntary-manslaughter', 'NJ', 'N.J.S.A. 2C:11-4(a)', 'Aggravated Manslaughter', '1st Degree Crime', '10 years', '30 years', '$200,000', '{"Recklessly causing the death of another person","Under circumstances manifesting extreme indifference to human life"}', 'NERA applies: 85% of sentence before parole eligibility', '{"Victim is law enforcement: enhanced sentencing","DWI-related: no probation","Prior violent record: extended term"}', 'NJ''s aggravated manslaughter is a 1st Degree Crime — unusual among states. NERA applies. Regular manslaughter (N.J.S.A. 2C:11-4(b)) is 2nd Degree. Passion/provocation manslaughter is also 2nd Degree.'),
  ('involuntary-manslaughter', 'NJ', 'N.J.S.A. 2C:11-5(a)', 'Vehicular Homicide — Reckless Driving', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Causing the death of another person","By driving a vehicle recklessly","On a public highway or quasi-public area"}', 'If DWI involved: no probation; NERA may apply', '{"DWI at time: no probation, 180-day license suspension — N.J.S.A. 2C:11-5(b)","Prior DWI conviction: 1st Degree Crime — N.J.S.A. 2C:11-5(c)","Fleeing scene: enhanced sentencing"}', 'NJ vehicular homicide under reckless driving is 2nd Degree. DWI-related vehicular homicide carries no probation and possible 1st Degree upgrade with prior DWI.'),
  ('simple-assault', 'NJ', 'N.J.S.A. 2C:12-1(a)', 'Simple Assault', 'Disorderly Persons Offense', '0 days', '6 months', '$1,000', '{"Attempts to cause or purposely, knowingly, or recklessly causes bodily injury to another","OR negligently causes bodily injury with a deadly weapon","OR attempts by physical menace to put another in fear of imminent serious bodily injury"}', 'None', '{"Mutual fighting: Petty Disorderly Persons (30 days)","Against law enforcement/school employee: upgrade to 3rd Degree","Domestic setting: mandatory no-drop policy"}', 'Simple assault in NJ is a disorderly persons offense (lower than crime). Mutual fighting reduces to Petty Disorderly Persons. Against certain protected victims (LEO, teacher, etc.) elevates to 3rd Degree Crime.'),
  ('aggravated-assault', 'NJ', 'N.J.S.A. 2C:12-1(b)', 'Aggravated Assault', '2nd, 3rd, or 4th Degree Crime (based on circumstances)', '18 months (4th Degree)', '10 years (2nd Degree)', '$150,000 (2nd Degree); $75,000 (3rd); $10,000 (4th)', '{"Attempting to cause or causing serious bodily injury to another","OR causing bodily injury with a deadly weapon","OR causing significant bodily injury purposely or knowingly","OR pointing a firearm at another"}', '2nd Degree: NERA applies (85% of sentence)', '{"Serious bodily injury: 2nd Degree with NERA","Firearm: 2nd Degree and Graves Act may apply","Against law enforcement: 2nd Degree","Against elderly/disabled: 2nd Degree"}', 'NJ''s aggravated assault has multiple subsets. Pointing a firearm: 4th Degree. Using firearm to cause injury: 3rd Degree. Causing serious bodily injury: 2nd Degree with NERA. Strangulation: 3rd Degree — N.J.S.A. 2C:12-1(b)(12).'),
  ('assault-with-deadly-weapon', 'NJ', 'N.J.S.A. 2C:12-1(b)(2)', 'Aggravated Assault with Deadly Weapon', '3rd Degree Crime', '3 years', '5 years', '$75,000', '{"Attempts to cause or purposely or knowingly causes","Bodily injury to another with a deadly weapon"}', 'NERA may apply if weapon is firearm and serious bodily injury resulted', '{"Serious bodily injury caused: 2nd Degree with NERA","Firearm: Graves Act may trigger mandatory minimum","Against protected victim (teacher, elderly): enhanced degree"}', '3rd Degree aggravated assault with deadly weapon. Upgraded to 2nd Degree if serious bodily injury results. Graves Act applies if firearm is used.'),
  ('robbery', 'NJ', 'N.J.S.A. 2C:15-1', 'Robbery', '2nd Degree Crime (unarmed); 1st Degree (armed or injury)', '5 years (2nd Degree)', '20 years (1st Degree)', '$200,000 (1st Degree); $150,000 (2nd Degree)', '{"In the course of committing a theft","Inflicting bodily injury or using force upon another","OR threatening another with immediate bodily injury","OR purposely putting another in fear"}', 'NERA applies to both 1st and 2nd Degree robbery (85% of sentence)', '{"Armed with deadly weapon: 1st Degree Crime","Serious bodily injury inflicted: 1st Degree Crime","Victim is 60+: presumption of 1st Degree","Graves Act: firearm triggers mandatory minimum"}', 'NERA (No Early Release Act) applies to robbery — must serve 85% of sentence. Armed robbery is 1st Degree (10-20 years with NERA). Unarmed robbery with no injury is 2nd Degree. Carjacking is separate offense under N.J.S.A. 2C:15-2.'),
  ('armed-robbery', 'NJ', 'N.J.S.A. 2C:15-1(b)', 'Robbery — First Degree (Armed)', '1st Degree Crime', '10 years', '20 years', '$200,000', '{"Robbery","While armed with a deadly weapon","OR while inflicting serious bodily injury","OR against a victim 60 years or older"}', 'NERA: 85% of sentence (no parole until 85%); Graves Act mandatory minimum if firearm', '{"Graves Act firearm: mandatory 5-year minimum without parole — N.J.S.A. 2C:43-6(c)","Prior robbery conviction: Persistent Dangerous Offender designation possible","Multiple victims: consecutive sentences"}', '1st Degree robbery carries NERA (85% served). Graves Act adds mandatory 5-year minimum if firearm is involved. Consecutive sentencing for multiple victims common. Graves Act waiver available through plea negotiation.'),
  ('kidnapping', 'NJ', 'N.J.S.A. 2C:13-1', 'Kidnapping', '1st Degree Crime', '15 years', 'Life (if victim under 16 and not released unharmed)', '$200,000', '{"Knowingly unlawfully removing another from the place where found","OR unlawfully confining another for a substantial period","With purpose to hold for ransom, use as hostage, inflict bodily injury, terrorize, or facilitate crime"}', 'NERA: 85% of sentence; 15-year parole ineligibility for crime against minor', '{"Victim under 16 not released: life with 25-year parole disqualifier","Victim is minor and sexually assaulted: enhanced — NERA minimum 25 years","Megan''s Law registration if sex offense involved"}', 'Kidnapping of a minor who is not released unharmed carries Life. NERA applies — must serve 85%. If victim is released in same or better condition, ordinary 1st Degree penalties apply. Parental kidnapping is a separate offense (N.J.S.A. 2C:13-4).'),
  ('carjacking', 'NJ', 'N.J.S.A. 2C:15-2', 'Carjacking', '1st Degree Crime', '10 years (NERA: 85%)', 'Life', '$200,000', '{"Unlawfully taking a motor vehicle from another person","While using force or threatening force","OR while the person is in or immediately entering the vehicle"}', 'NERA applies: 85% of sentence before parole; Graves Act if armed', '{"Firearm used: Graves Act — 5-year mandatory","Serious injury: enhanced sentence within 1st Degree","Multiple victims in vehicle: additional charges"}', 'Carjacking is 1st Degree with NERA (85% must be served). Distinct from robbery. Maximum is Life. Graves Act applies if firearm present. Consecutive to other charges typical.'),
  ('burglary', 'NJ', 'N.J.S.A. 2C:18-2', 'Burglary', '3rd Degree Crime (unoccupied); 2nd Degree (occupied or armed)', '3 years (3rd Degree)', '10 years (2nd Degree)', '$150,000 (2nd); $75,000 (3rd)', '{"Enters a structure","Without license or privilege to do so","With purpose to commit an offense therein"}', 'NERA may apply if 2nd Degree (occupied structure burglary)', '{"Structure occupied at time: 2nd Degree","Armed with deadly weapon: 2nd Degree","Bodily injury caused: 2nd Degree with NERA","Prior burglary: extended term"}', 'NJ burglary is 3rd Degree by default, 2nd Degree if structure is occupied or defendant is armed. NERA applies to 2nd Degree burglary. ''Structure'' broadly defined to include vehicles, watercraft.'),
  ('home-invasion', 'NJ', 'N.J.S.A. 2C:18-2(b)(1)', 'Burglary of Occupied Structure (Home Invasion)', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Burglary of a structure","At a time when the structure is occupied","OR while armed with a deadly weapon"}', 'NERA applies: 85% of sentence before parole', '{"Assault committed during burglary: aggravated assault concurrent","Firearm: Graves Act mandatory minimum","Multiple victims: enhanced sentencing"}', 'NJ uses 2nd Degree burglary for occupied structures — equivalent to home invasion. NERA mandatory. Graves Act firearm minimum of 5 years without parole if gun is involved.'),
  ('theft-larceny', 'NJ', 'N.J.S.A. 2C:20-3', 'Theft by Unlawful Taking or Disposition', '2nd-4th Degree Crime or Disorderly Persons (value-based)', '0 days (Disorderly Persons)', '10 years (2nd Degree, $75,000+)', '$150,000 (2nd Degree); $75,000 (3rd); $10,000 (4th)', '{"Purposely taking or exercising unlawful control","Over movable property of another","With purpose to deprive the owner of the property"}', 'None', '{"$75,000+: 2nd Degree","$1,000-$75,000: 3rd Degree","$500-$1,000: 4th Degree","Under $500: Disorderly Persons","From person of elderly: upgraded one degree"}', 'NJ consolidates theft offenses under N.J.S.A. 2C:20-1 et seq. All theft forms (robbery excepted) share the same grading by value. Theft of firearm: 4th Degree regardless of value.'),
  ('motor-vehicle-theft', 'NJ', 'N.J.S.A. 2C:20-3', 'Theft of a Motor Vehicle', '3rd Degree Crime ($1,000-$75,000 value range typical)', '3 years', '5 years', '$75,000', '{"Purposely taking or exercising unlawful control","Over a motor vehicle","With purpose to deprive the owner"}', 'None', '{"Use of force or threat: carjacking — N.J.S.A. 2C:15-2","Chop shop operation: 2nd Degree — N.J.S.A. 2C:20-16","Prior auto theft: extended term"}', 'Auto theft graded by value of vehicle. Most vehicles qualify as 3rd Degree. Carjacking is separate and more severe. Chop shops (N.J.S.A. 2C:20-16) carry 2nd Degree exposure.'),
  ('shoplifting', 'NJ', 'N.J.S.A. 2C:20-11', 'Shoplifting', 'Disorderly Persons to 2nd Degree Crime (value-based)', '0 days', '10 years (2nd Degree, $75,000+)', 'Varies by degree', '{"Purposely taking merchandise from a retail establishment","Without paying the full retail value","OR concealing merchandise, under-ringing, or destroying a theft detection device"}', 'None; 3rd offense: 90-day mandatory community service', '{"Organized retail theft ring: felony enhancement — N.J.S.A. 2C:20-11.3","Third offense: mandatory 90 days community service","Booster bag or device: separate charge — N.J.S.A. 2C:20-11(b)(6)"}', 'NJ shoplifting: under $200 = Disorderly Persons; $200-$500 = 4th Degree; $500-$75,000 = 3rd Degree; $75,000+ = 2nd Degree. Organized retail theft is enhanced. Third offense adds mandatory community service.'),
  ('arson', 'NJ', 'N.J.S.A. 2C:17-1', 'Arson and Related Offenses', '2nd or 3rd Degree Crime', '3 years (3rd Degree)', '10 years (2nd Degree)', '$150,000 (2nd Degree)', '{"Starting a fire or causing an explosion","That places another person in danger of death or bodily injury","OR with purpose of destroying a building or occupied structure"}', 'NERA if 2nd Degree (85% of sentence)', '{"Person present in structure: 2nd Degree — NERA","Firefighter or investigator injured: enhanced sentencing","Insurance fraud arson: concurrent fraud charges"}', 'NJ arson distinguishes reckless burning (3rd Degree) from purposeful with persons endangered (2nd Degree with NERA). Aggravated arson provisions for occupied structures. Insurance fraud arson commonly prosecuted together.'),
  ('vandalism', 'NJ', 'N.J.S.A. 2C:17-3', 'Criminal Mischief', '2nd-4th Degree Crime or Disorderly Persons (damage value-based)', '0 days (Disorderly Persons)', '10 years (2nd Degree, $75,000+)', '$150,000 (2nd Degree)', '{"Purposely or knowingly damaging tangible property of another","OR recklessly or negligently damaging property with fire, explosives, or other dangerous means"}', 'None', '{"$75,000+: 2nd Degree","$2,000-$75,000: 3rd Degree","$500-$2,000: 4th Degree","Under $500: Disorderly Persons","Bias/hate crime motivation: bias intimidation statute adds additional charge — N.J.S.A. 2C:16-1"}', 'NJ Criminal Mischief graded by value of damage. Graffiti under N.J.S.A. 2C:17-3(b). Bias-motivated vandalism triggers separate N.J.S.A. 2C:16-1 bias intimidation charge.'),
  ('domestic-violence', 'NJ', 'N.J.S.A. 2C:25-17 (Prevention of Domestic Violence Act)', 'Domestic Violence — Underlying Predicate Offenses', 'Underlying offense classification applies (Disorderly Persons to 1st Degree)', 'Underlying offense minimum', 'Underlying offense maximum', 'Underlying offense fine', '{"Commission of a predicate offense listed in N.J.S.A. 2C:25-19","Against a protected person (current or former spouse, domestic partner, household member, parent of common child)","Predicate offenses include: assault, stalking, terroristic threats, criminal mischief, trespass, burglary, harassment, sexual assault, homicide, kidnapping, bias crime"}', 'TRO/FRO issued upon arrest; no-bail warrant may issue', '{"Strangulation: 3rd Degree aggravated assault — N.J.S.A. 2C:12-1(b)(12)","FRO violation: 4th Degree Crime — N.J.S.A. 2C:29-9","Prior DV conviction: enhanced sentencing on predicate offense"}', 'NJ''s Prevention of Domestic Violence Act (PDVA) creates civil protection order framework. Criminal prosecution uses underlying predicate offense. Strangulation is specifically elevated to 3rd Degree aggravated assault.'),
  ('stalking', 'NJ', 'N.J.S.A. 2C:12-10', 'Stalking', '4th Degree Crime (first); 3rd Degree (repeat or with restraining order)', '18 months (4th Degree)', '5 years (3rd Degree)', '$75,000 (3rd Degree); $10,000 (4th Degree)', '{"Purposefully or knowingly engaging in a course of conduct","Directed at a specific person","That would cause a reasonable person to fear for safety or suffer emotional distress"}', 'None', '{"While under a restraining order: 3rd Degree","Second or subsequent conviction: 3rd Degree","Using social media or electronic communications: same statute applies — cyberstalking"}', 'NJ stalking statute covers both physical and electronic (cyber) stalking. ''Course of conduct'' requires 2+ acts. Second offense or violation of TRO/FRO elevates to 3rd Degree.'),
  ('violation-protective-order', 'NJ', 'N.J.S.A. 2C:29-9', 'Violation of Final Restraining Order (FRO)', '4th Degree Crime', '18 months', '18 months', '$10,000', '{"Existence of a valid Final Restraining Order","Defendant had knowledge of the order","Defendant purposely or knowingly violated a term of the order"}', 'None statutory; court may impose', '{"Assault committed during violation: concurrent aggravated assault","Stalking during violation: concurrent stalking charge","Multiple violations: multiple counts"}', 'Violation of NJ FRO is a 4th Degree Crime. TRO violation is a contempt matter handled civilly. Criminal violation requires a Final Restraining Order, not just TRO. Also triggers contempt proceedings.'),
  ('child-abuse', 'NJ', 'N.J.S.A. 9:6-3', 'Child Abuse — Cruelty and Neglect of Children', '4th Degree Crime (neglect); 3rd Degree Crime (abuse with injury); 2nd Degree (serious injury)', '18 months', '10 years (2nd Degree)', '$150,000', '{"Parent or person responsible for the care of a child","Inflicting physical or mental harm upon the child","OR allowing the child to be subjected to abuse"}', 'None', '{"Sexual abuse element: CSC statute concurrent","Child death: murder or aggravated manslaughter","Pattern of abuse: extended term"}', 'NJ child abuse statute under Title 9. Aggravated criminal assault of a child under N.J.S.A. 2C:12-1 also applies. Mandatory reporting law (N.J.S.A. 9:6-8.10) applies broadly. DCPP involvement concurrent.'),
  ('child-neglect', 'NJ', 'N.J.S.A. 9:6-1', 'Child Neglect', '4th Degree Crime', '18 months', '18 months', '$10,000', '{"Parent or guardian","Abandoning, refusing to provide, or failing to provide","Necessary care (food, clothing, shelter, medical care) for a child"}', 'None', '{"Serious harm results: upgraded to 3rd or 2nd Degree under N.J.S.A. 2C:24-4(a)","Death resulting: murder or manslaughter charges","Prior neglect adjudication: sentencing enhancement"}', 'NJ child endangerment under N.J.S.A. 2C:24-4(a) is the companion criminal statute. DCPP/DYFS proceedings run concurrently. Endangering welfare of children (N.J.S.A. 2C:24-4) is the more commonly used criminal charge.'),
  ('felon-in-possession', 'NJ', 'N.J.S.A. 2C:39-7', 'Certain Persons Not to Have Weapons', '2nd Degree Crime', '5 years (NERA: 85%)', '10 years', '$150,000', '{"Having been convicted of specific crimes or offenses","Possessing, owning, purchasing, or controlling a firearm","OR having been convicted of domestic violence predicate and possessing any weapon"}', 'Graves Act: 5-year mandatory minimum without parole — N.J.S.A. 2C:43-6(c)', '{"Graves Act mandatory applies to ALL prohibited persons firearm cases","Use in crime: additional concurrent charges","Prior Certain Persons conviction: extended term mandatory"}', 'NJ''s felon-in-possession equivalent. 2nd Degree Crime. Graves Act applies — mandatory 5-year minimum without parole. Also applies to persons convicted of DV predicate offenses who possess ANY weapon, not just firearms. One of the most heavily prosecuted NJ gun laws.'),
  ('concealed-carry-violation', 'NJ', 'N.J.S.A. 2C:39-5(b)', 'Unlawful Possession of a Handgun', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Carrying, possessing, or controlling a handgun","Without first having obtained a Permit to Carry a Handgun","Outside of the person''s dwelling place or place of business"}', 'Graves Act: 5-year mandatory minimum without parole', '{"Firearm is loaded: sentencing enhancement","In school zone: mandatory additional 3-5 years","Graves Act waiver available through plea to 2nd Degree without mandatory minimum"}', 'NJ had most restrictive carry laws in US before Bruen (2022). Post-Bruen, shall-issue permits available but NJ still maintains Graves Act mandatory minimum for permit-less carry. 2nd Degree with mandatory 5-year minimum under Graves Act.'),
  ('felony-firearm', 'NJ', 'N.J.S.A. 2C:43-6(c) (Graves Act)', 'Graves Act — Mandatory Minimum for Firearm Offenses', 'Mandatory minimum sentence enhancement (not standalone offense)', '5 years without parole (minimum)', 'Underlying offense maximum', 'Underlying offense fine', '{"Conviction for a Graves Act offense (firearm-related crime under N.J.S.A. 2C:39-1 et seq.)","With exception of certain non-violent possession offenses","Including unlawful possession, possession by certain persons, using firearm in commission of crime"}', '1/2 of sentence or 5 years, whichever is greater, without parole eligibility', '{"Prior Graves Act offense: mandatory term increases","Second Graves Act offense: 10-year mandatory without parole","Graves Act waiver: Prosecutor may downgrade — requires court approval"}', 'The Graves Act is NJ''s signature gun law — applies to all N.J.S.A. 2C:39-series convictions. The mandatory minimum is the GREATER of half the sentence OR 5 years. No parole during mandatory period. Waiver available but rarely granted in practice.'),
  ('assault-firearm', 'NJ', 'N.J.S.A. 2C:12-1(b)(1) and N.J.S.A. 2C:39-4', 'Aggravated Assault with Firearm / Possession of Firearm for Unlawful Purpose', '2nd Degree Crime', '5 years (NERA: 85%)', '10 years', '$150,000', '{"Attempt to cause serious bodily injury using a firearm","OR possession of a firearm with purpose to use it unlawfully against another"}', 'Graves Act: 5-year mandatory minimum; NERA: 85% of sentence', '{"Serious bodily injury inflicted: NERA in full force","Victim is law enforcement: enhanced sentencing","Prior violent felony: extended term"}', 'Both aggravated assault with firearm and possession for unlawful purpose are 2nd Degree with Graves Act mandatory and NERA. Frequently charged together. Most common felony gun charges in NJ.'),
  ('identity-theft', 'NJ', 'N.J.S.A. 2C:21-17', 'Impersonation / Identity Theft', '2nd-4th Degree Crime (harm-based)', '18 months', '10 years (2nd Degree, $75,000+ loss or 5+ victims)', '$150,000', '{"Obtaining personal identifying information of another","Without authorization","With purpose to fraudulently obtain a benefit or to injure or defraud"}', 'None', '{"5+ victims or $75,000+ loss: 2nd Degree","$500-$75,000 or 2-4 victims: 3rd Degree","Under $500 or 1 victim: 4th Degree","Victim is 62+: additional $10,000 fine"}', 'NJ identity theft tiered by number of victims and financial loss. Senior victim (62+) triggers mandatory $10,000 fine. Restitution mandatory. Impersonation using internet or computer carries additional charges.'),
  ('credit-card-fraud', 'NJ', 'N.J.S.A. 2C:21-6', 'Credit Card Fraud', '4th Degree Crime (under $75,000); 3rd Degree ($75,000+)', '18 months', '5 years (3rd Degree)', '$75,000', '{"Using a credit card with knowledge that it is stolen, revoked, or used without authorization","With intent to defraud","Obtaining money, goods, services, or anything of value"}', 'None', '{"Skimming device: additional charges — N.J.S.A. 2C:21-6.1","Identity theft component: concurrent charges","Multiple cards/victims: multiple counts"}', 'NJ credit card fraud under N.J.S.A. 2C:21-6. Skimming devices are separately criminalized under N.J.S.A. 2C:21-6.1. Restitution mandatory.'),
  ('insurance-fraud', 'NJ', 'N.J.S.A. 2C:21-4.6', 'Insurance Fraud', '4th Degree Crime (under $1,000); 3rd Degree ($1,000-$75,000); 2nd Degree ($75,000+)', '18 months', '10 years (2nd Degree)', '$150,000', '{"Knowingly making or causing to be made","A false, fictitious, fraudulent, or misleading statement","In connection with an insurance claim or application"}', 'None', '{"Personal injury fraud scheme (PIP fraud): mandatory criminal referral","Healthcare provider fraud: additional penalties — N.J.S.A. 2C:21-4.3","Organized fraud ring: 2nd Degree enhancement"}', 'NJ Insurance Fraud Prevention Act. Auto insurance (PIP/personal injury) fraud is highly prevalent and prosecuted. Healthcare provider insurance fraud has enhanced penalties. Civil enforcement also available through OIC.'),
  ('embezzlement', 'NJ', 'N.J.S.A. 2C:20-9', 'Theft by Breach of Fiduciary Duty (Embezzlement)', '2nd-4th Degree Crime or Disorderly Persons (value-based)', '18 months (4th Degree)', '10 years (2nd Degree, $75,000+)', '$150,000', '{"Being a fiduciary","Knowingly dealing with property entrusted to them","In a manner they know to be incompatible with their fiduciary duty"}', 'None', '{"Public officer or official: 2nd Degree regardless of amount — N.J.S.A. 2C:20-9(c)","Elderly victim: one degree enhanced","Organized scheme: additional conspiracy charges"}', 'NJ consolidates embezzlement under theft by breach of fiduciary duty. Public officer theft is automatically 2nd Degree. Restitution mandatory.'),
  ('csc-first-degree', 'NJ', 'N.J.S.A. 2C:14-2(a)', 'Aggravated Sexual Assault — First Degree', '1st Degree Crime', '10 years', '20 years', '$200,000', '{"Committing an act of sexual penetration","Under aggravated circumstances: victim under 13; victim 13-15 and defendant authority figure; force, coercion, or incapacitation; victim physically helpless; armed with weapon"}', 'NERA: 85% of sentence must be served before parole eligibility', '{"Victim under 13: NERA mandatory, life possible","Repeat offenders: Megan''s Law Tier 3 registration (lifetime)","Prior sex offense conviction: extended term","Predatory Sex Offenders Act: additional civil commitment"}', 'NJ uses ''aggravated sexual assault'' (1st Degree) and ''sexual assault'' (2nd Degree). NERA mandatory for 1st Degree — 85% served before parole. Megan''s Law registration required. Parole Supervision for Life (PSL) mandatory for adults.'),
  ('csc-second-degree', 'NJ', 'N.J.S.A. 2C:14-2(b)-(c)', 'Sexual Assault — Second Degree', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Sexual penetration with another person","Using physical force or coercion","OR victim is 16 or 17 and defendant has supervisory or disciplinary authority","OR victim is 13-15 and defendant is at least 4 years older"}', 'NERA: 85% of sentence; Parole Supervision for Life (PSL) mandatory', '{"Prior sex offense: extended term","Megan''s Law Tier 2 or 3 registration","Position of trust: sentencing enhancement","Special Probation (BIRIA): available in limited circumstances"}', '2nd Degree sexual assault (penetration with force or statutory age circumstances). NERA mandatory. PSL (lifetime parole supervision) required for all adults convicted of sexual assault. Megan''s Law registration mandatory.'),
  ('csc-third-degree', 'NJ', 'N.J.S.A. 2C:14-3(a)', 'Aggravated Criminal Sexual Contact — Third Degree', '3rd Degree Crime', '3 years', '5 years', '$75,000', '{"Sexual contact (not penetration)","Under aggravated circumstances (same as aggravated sexual assault but contact only)","Including force, incapacity, victim age under 13"}', 'NERA may apply depending on circumstances', '{"Prior sex offense: extended term","Megan''s Law registration required","PSL mandatory for adults"}', '3rd Degree for sexual contact under aggravated circumstances. Criminal sexual contact (4th Degree, N.J.S.A. 2C:14-3(b)) covers non-aggravated sexual contact with force.'),
  ('csc-fourth-degree', 'NJ', 'N.J.S.A. 2C:14-3(b)', 'Criminal Sexual Contact — Fourth Degree', '4th Degree Crime', '18 months', '18 months', '$10,000', '{"Sexual contact","Using physical force or coercion","Without specific aggravating circumstances of 3rd Degree"}', 'None', '{"Prior sex offense: enhanced to 3rd Degree","Megan''s Law registration required","PSL mandatory"}', 'Lowest-level NJ sex offense. 4th Degree Criminal Sexual Contact. Megan''s Law and PSL still apply despite misdemeanor-equivalent severity. Force or coercion required — not just offensive touching.'),
  ('indecent-exposure', 'NJ', 'N.J.S.A. 2C:14-4', 'Lewdness', 'Disorderly Persons Offense; 4th Degree if victim under 13', '0 days', '6 months (Disorderly Persons); 18 months (4th Degree)', '$1,000 (Disorderly); $10,000 (4th Degree)', '{"Exposing intimate parts","For the purpose of arousing or gratifying sexual desire","Under circumstances likely to cause affront or alarm"}', 'None', '{"Victim under 13: 4th Degree Crime","Online exposure/transmission: computer crime charges added","School zone: municipal ordinance may apply"}', 'NJ uses ''Lewdness'' rather than indecent exposure. Disorderly Persons for general lewdness, 4th Degree if victim is under 13. Megan''s Law registration possible for 4th Degree lewd acts against minors.'),
  ('solicitation-prostitution', 'NJ', 'N.J.S.A. 2C:34-1', 'Prostitution and Related Offenses', 'Disorderly Persons (solicitation); 4th Degree (promoting); 3rd Degree (promoting minor)', '0 days', '6 months (Disorderly Persons); 18 months (4th Degree); 5 years (3rd Degree)', '$1,000 (Disorderly); $10,000 (4th Degree)', '{"Soliciting or promoting prostitution","Engaging in sexual activity as a business for compensation","OR profiting from prostitution of another"}', 'None', '{"Promoting prostitution of minor under 18: 3rd Degree","Compelling prostitution through force: 1st Degree — N.J.S.A. 2C:13-8","Human trafficking: additional enhanced charges"}', 'NJ prostitution law under N.J.S.A. 2C:34-1. Solicitation is Disorderly Persons. Promoting is 4th Degree. Promoting minor''s prostitution is 3rd Degree. Sex trafficking of minors prosecuted under N.J.S.A. 2C:13-8.'),
  ('sex-trafficking', 'NJ', 'N.J.S.A. 2C:13-8', 'Human Trafficking — Sexual Exploitation', '1st Degree Crime', '10 years', '20 years (or Life if minor victim)', '$200,000', '{"Recruiting, luring, enticing, or harboring a person","Through force, fraud, or coercion","For the purpose of commercial sexual activity"}', 'NERA: 85% of sentence; victim under 18: no probation', '{"Victim under 18: mandatory life imprisonment or 20-year minimum","Multiple victims: consecutive sentences","Use of controlled substance to control victim: additional CDS charges"}', 'NJ Human Trafficking statute under N.J.S.A. 2C:13-8. Minors cannot consent — no defense of consent for trafficking of persons under 18. Asset forfeiture. Victim services and safe harbor provisions under N.J.S.A. 2C:13-9.'),
  ('public-intoxication', 'NJ', 'N.J.S.A. 2C:33-2(b)', 'Disorderly Conduct — Intoxication', 'Petty Disorderly Persons Offense', '0 days', '30 days', '$500', '{"Appearing in a public place","Under the influence of alcohol or a controlled substance","Manifesting a purpose to cause public inconvenience, annoyance, or alarm"}', 'None', '{"Creating serious hazard: disorderly conduct upgrade","DWI if operating a vehicle: N.J.S.A. 39:4-50"}', 'NJ does not have a standalone ''public intoxication'' statute. Charged as Disorderly Conduct (Petty Disorderly Persons) or under municipal ordinances. DWI applies when operating a vehicle.'),
  ('disorderly-conduct', 'NJ', 'N.J.S.A. 2C:33-2', 'Disorderly Conduct', 'Petty Disorderly Persons Offense', '0 days', '30 days', '$500', '{"Engaging in fighting, threatening, or violent behavior","OR creating a hazardous or physically offensive condition","OR using offensive, threatening, or abusive language in a public place"}', 'None', '{"Simple assault concurrent if physical contact","Mutual fighting: Petty Disorderly Persons (same)","Near school or public event: local ordinance may enhance"}', 'NJ disorderly conduct is Petty Disorderly Persons (30 days max). Distinguished from simple assault (Disorderly Persons, 6 months) when no physical contact occurs. Commonly used for altercations.'),
  ('trespassing', 'NJ', 'N.J.S.A. 2C:18-3', 'Criminal Trespass', '4th Degree Crime (dwelling); Disorderly Persons (other structure); Petty Disorderly (land)', '0 days', '18 months (4th Degree, dwelling)', '$10,000 (4th Degree); $1,000 (Disorderly)', '{"Entering or surreptitiously remaining in any structure","Knowing that permission has been denied","Without license, privilege, or lawful reason"}', 'None', '{"Dwelling: 4th Degree Crime","School building: 4th Degree","Other structure: Disorderly Persons","Open land: Petty Disorderly Persons"}', 'NJ trespass escalates based on type of structure. Dwelling trespass is 4th Degree Crime. Other structures are Disorderly Persons. Open land is Petty Disorderly. Defiant trespasser (refuses to leave) included.'),
  ('resisting-arrest', 'NJ', 'N.J.S.A. 2C:29-2', 'Resisting Arrest', 'Disorderly Persons Offense (no force); 3rd Degree (flight/force used)', '0 days', '6 months (no force); 5 years (flight or force — 3rd Degree)', '$1,000 (Disorderly); $75,000 (3rd Degree)', '{"Knowingly preventing or attempting to prevent a law enforcement officer","From effecting a lawful arrest","By creating a substantial risk of bodily injury or employing means requiring substantial force"}', 'None', '{"Flight: 3rd Degree","Officer injured: aggravated assault concurrent","Use of vehicle to flee: eluding — N.J.S.A. 2C:29-2(b)"}', 'NJ resisting arrest: passive resistance is Disorderly Persons; active resistance with flight or force is 3rd Degree Crime. Eluding police in vehicle is separately 2nd or 3rd Degree under N.J.S.A. 2C:29-2(b).'),
  ('obstruction-justice', 'NJ', 'N.J.S.A. 2C:29-1', 'Obstructing Administration of Law or Other Governmental Function', 'Disorderly Persons Offense; 4th Degree if force or flight', '0 days', '6 months (Disorderly); 18 months (4th Degree)', '$1,000 (Disorderly); $10,000 (4th Degree)', '{"Purposely obstructing, impairing, or perverting the administration of law","Or other governmental function","Using force, violence, physical interference, or obstacle, or an independently unlawful act"}', 'None', '{"Force used: 4th Degree","Official misconduct (official doing it): 2nd Degree — N.J.S.A. 2C:30-2","Witness tampering concurrent: N.J.S.A. 2C:28-5"}', 'NJ obstruction is broadly worded. Passive obstruction is Disorderly Persons; use of force elevates to 4th Degree. Tampering with witness/evidence are separate offenses.'),
  ('perjury', 'NJ', 'N.J.S.A. 2C:28-1', 'Perjury', '3rd Degree Crime', '3 years', '5 years', '$75,000', '{"In any official proceeding","Making a false statement under oath or affirmation","With knowledge of its falsity","With purpose to mislead a public servant in performing his official function"}', 'None', '{"False swearing (not in official proceeding): 4th Degree — N.J.S.A. 2C:28-2","False statements to police: hindering apprehension — N.J.S.A. 2C:29-3","Perjury in capital case: aggravating factor"}', 'NJ perjury is 3rd Degree Crime. ''Official proceeding'' includes trials, hearings, depositions, and administrative proceedings. Subornation of perjury is 3rd Degree under N.J.S.A. 2C:28-3.'),
  ('bribery', 'NJ', 'N.J.S.A. 2C:27-2', 'Bribery in Official and Political Matters', '3rd Degree Crime', '3 years', '5 years', '$75,000 or 3x bribe amount', '{"Offering, conferring, agreeing to confer, or soliciting, accepting, or agreeing to accept","A benefit as consideration for a vote, opinion, recommendation, decision, or exercise of discretion","By a public servant, party official, or voter"}', 'None', '{"Commercial bribery: 2nd Degree if value exceeds $200 — N.J.S.A. 2C:21-10","Receiving unlawful benefit (public servant): 2nd Degree — N.J.S.A. 2C:27-9","Official misconduct: additional 2nd Degree charge — N.J.S.A. 2C:30-2"}', 'NJ bribery covers political and official corruption. 3rd Degree for giving or receiving. Official misconduct (N.J.S.A. 2C:30-2) is a 2nd Degree parallel charge for officials acting corruptly.'),
  ('money-laundering', 'NJ', 'N.J.S.A. 2C:21-25', 'Financial Facilitation of Criminal Activity (Money Laundering)', '1st-3rd Degree Crime (amount-based)', '3 years (3rd Degree)', '20 years (1st Degree)', '$500,000 (1st Degree) or 2x proceeds laundered', '{"Knowingly engaging in a financial transaction","With proceeds derived from criminal activity","With intent to conceal or disguise the nature, location, source, ownership, or control of the proceeds"}', 'None; NERA may apply for 1st Degree', '{"$500,000+: 1st Degree","$75,000-$500,000: 2nd Degree","Under $75,000: 3rd Degree","Drug trafficking underlying: federal concurrent prosecution","Forfeiture of all proceeds"}', 'NJ money laundering under N.J.S.A. 2C:21-25. Asset forfeiture available. Federal charges under 18 U.S.C. § 1956 frequently concurrent for organized schemes.'),
  ('criminal-enterprise', 'NJ', 'N.J.S.A. 2C:41-2 (NJ RICO)', 'NJ RICO — Racketeering', '2nd Degree Crime', '5 years', '10 years', '$150,000 or 3x gain', '{"Conducting or participating in an enterprise","Through a pattern of racketeering activity","With knowledge or intent to benefit the enterprise"}', 'NERA may apply depending on predicate acts', '{"Drug trafficking predicate: enhanced penalties","Murder predicate: 1st Degree enhancement","Financial benefit forfeiture","Federal RICO concurrent: 18 U.S.C. § 1962"}', 'NJ RICO under N.J.S.A. 2C:41-1 et seq. (New Jersey Criminal Justice Act). Requires ''pattern'' of at least 2 acts within 10 years. Civil RICO available to private plaintiffs. Asset forfeiture.'),
  ('extortion', 'NJ', 'N.J.S.A. 2C:20-5', 'Theft by Extortion', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Obtaining property of another by threatening","To inflict bodily injury, commit a crime, accuse of a crime, expose secrets, or abuse official position"}', 'None', '{"Threat of bodily harm: concurrent assault charges","Use of mail or wire: federal extortion — 18 U.S.C. § 875","Organized crime context: NJ RICO charges"}', 'NJ extortion classified under theft statutes (N.J.S.A. 2C:20-5). Graded as 2nd Degree when threat involved — unlike other theft forms graded by value. Federal Hobbs Act extortion (18 U.S.C. § 1951) frequently used for organized crime.'),
  ('receiving-stolen-property', 'NJ', 'N.J.S.A. 2C:20-7', 'Receiving Stolen Property', 'Same grading as theft by value (2nd-4th Degree or Disorderly Persons)', '0 days (Disorderly Persons)', '10 years (2nd Degree)', '$150,000 (2nd Degree)', '{"Purposely receiving, retaining, or disposing of movable property of another","Knowing it has been stolen","OR believing it is probably stolen","With purpose to benefit from it or to prevent the owner from recovering it"}', 'None', '{"Motor vehicle: enhanced if chop shop operation","Jewelry, firearms: value-based grading applies","Commercial fencing: multiple counts or racketeering"}', 'NJ receiving stolen property graded same as theft by value. Knowledge of stolen status may be inferred from circumstances. Professional fencing operations subject to racketeering charges.'),
  ('forgery', 'NJ', 'N.J.S.A. 2C:21-1', 'Forgery', '3rd Degree Crime (most documents); 4th Degree (non-money instruments)', '3 years (3rd Degree)', '5 years (3rd Degree)', '$75,000', '{"Altering, completing, executing, or authenticating","Any writing or object","With purpose to defraud or injure another"}', 'None', '{"Government documents, currency: 3rd Degree","Prescription forgery: 3rd Degree with CDS concurrent","Fraudulent use of forged document: additional uttering charge — N.J.S.A. 2C:21-2"}', 'NJ forgery under N.J.S.A. 2C:21-1. Uttering forged document is separate offense under N.J.S.A. 2C:21-2. Counterfeit currency is federal offense. Check kiting has separate provisions.'),
  ('conspiracy', 'NJ', 'N.J.S.A. 2C:5-2', 'Conspiracy', 'Same as the most serious offense in the conspiracy (one degree below for non-1st Degree)', 'Varies with underlying offense', 'Varies (Life if murder conspiracy; otherwise one degree below substantive offense)', 'Same as underlying offense', '{"Agreeing with one or more persons to commit an offense","With purpose of promoting or facilitating its commission","AND an overt act in furtherance"}', 'None (follows underlying offense)', '{"Conspiracy to commit 1st Degree crime: 1st Degree conspiracy","Drug distribution conspiracy: school zone mandatory minimums may apply","Continuing conspiracy: Wharton''s Rule considerations"}', 'NJ conspiracy graded one degree below the target offense, except conspiracy to commit 1st Degree crime remains 1st Degree. Overt act required. Withdrawal defense available with proper notice.'),
  ('attempt', 'NJ', 'N.J.S.A. 2C:5-1', 'Criminal Attempt', 'One degree below the completed offense', 'Varies', 'One degree below completed offense (attempt to commit 1st Degree = 2nd Degree)', 'Same as one-degree-below offense', '{"Purposely engaging in conduct which would constitute the crime if the attendant circumstances were as a reasonable person would believe them to be","OR doing something which is a substantial step in a course of conduct planned to culminate in the crime"}', 'None (follows underlying offense)', '{"Attempt to commit murder: 1st Degree Crime","Attempt at 1st Degree: treated as 1st Degree for sentencing purposes under N.J.S.A. 2C:5-4","Substantial step must be more than mere preparation"}', 'NJ attempt graded one degree below completed offense. Attempt of 1st Degree is still 1st Degree. Abandonment is an affirmative defense if voluntary and complete. ''Substantial step'' test used.'),
  ('aiding-abetting', 'NJ', 'N.J.S.A. 2C:2-6', 'Liability for Conduct of Another (Accomplice)', 'Same as the principal offense', 'Same as principal', 'Same as principal', 'Same as principal', '{"With the purpose of promoting or facilitating the commission of the offense","Soliciting another person to commit it","OR aiding, agreeing to aid, or attempting to aid another person in planning or committing it"}', 'Same as principal (Graves Act/NERA apply equally)', '{"Active participation increases culpability","Getaway driver subject to same charges as principal","Accessory after the fact: hindering apprehension — N.J.S.A. 2C:29-3"}', 'NJ accomplice liability — same punishment as principal. Accessory after the fact is not an accomplice in NJ — charged under hindering apprehension (N.J.S.A. 2C:29-3). Graves Act and NERA apply equally to accomplices.'),
  ('hit-run-injury', 'NJ', 'N.J.S.A. 2C:12-1.1', 'Leaving the Scene of an Accident (Personal Injury)', '3rd Degree Crime', '3 years', '5 years', '$75,000', '{"Operating a motor vehicle involved in an accident resulting in injury to a person","Knowingly failing to stop","Or to provide name, address, and vehicle identification"}', 'License suspension mandatory (1-5 years)', '{"Death resulting: 2nd Degree — N.J.S.A. 2C:12-1.1","DWI concurrent: enhanced sentencing","Second offense: extended term"}', 'NJ elevated leaving the scene of injury/death to 3rd/2nd Degree indictable offense. Property damage only: Title 39 motor vehicle offense. License suspension mandatory. Restitution to victim required.'),
  ('elder-abuse', 'NJ', 'N.J.S.A. 9:6-8.84', 'Abuse, Neglect, Exploitation of Vulnerable Adults', '4th Degree Crime (neglect/emotional); 3rd Degree (physical/serious); 2nd Degree (death)', '18 months', '10 years (2nd Degree)', '$150,000', '{"Person responsible for care of a vulnerable adult","Willfully abusing, neglecting, or mistreating","OR allowing abuse, neglect, or exploitation"}', 'None', '{"Financial exploitation concurrent: N.J.S.A. 2C:21-17.1","Death resulting: aggravated manslaughter","Prior conviction: extended term"}', 'NJ Adult Protective Services Act — criminal provisions. Title 2C financial exploitation of vulnerable adult under N.J.S.A. 2C:21-17.1 runs concurrently. Mandatory reporting.'),
  ('financial-exploitation-elder', 'NJ', 'N.J.S.A. 2C:21-17.1', 'Theft or Wrongful Taking — Elderly or Vulnerable Person', '4th-2nd Degree Crime (value-based; one degree elevated from standard theft)', '18 months', '10 years (2nd Degree)', '$150,000', '{"Committing theft or unlawful taking","From a person who is 60 years of age or older","Or from a vulnerable adult (disabled/incapacitated)"}', 'None', '{"Amount over $75,000: 2nd Degree","$1,000-$75,000: 3rd Degree (standard theft 3rd would be $500-$75,000)","Financial institution employee: enhanced sentencing","Caregiver: breach of fiduciary enhancement"}', 'NJ elevates theft crimes against elderly or vulnerable adults by one degree. $1,000 threshold for 3rd Degree (vs. $500 for standard theft). Restitution mandatory. Both civil and criminal remedies available.'),
  ('terroristic-threats', 'NJ', 'N.J.S.A. 2C:12-3', 'Terroristic Threats', '3rd Degree Crime; 2nd Degree if threat to commit crime of 1st or 2nd Degree', '3 years', '10 years (2nd Degree)', '$150,000', '{"Threatening to commit any crime of violence","With purpose to terrorize another","OR threatening to commit a crime of violence in reckless disregard of the risk of causing terror"}', 'None', '{"Threat to commit 1st or 2nd Degree crime: 2nd Degree — N.J.S.A. 2C:12-3(b)","School threat: separate enhanced provisions — N.J.S.A. 2C:33-3","Online threat: same statute, computer charges may be added"}', 'NJ terroristic threats is 3rd Degree (base) or 2nd Degree (if the threatened crime is 1st or 2nd Degree). Threatening school or community is 3rd Degree under N.J.S.A. 2C:33-3. Harassment (N.J.S.A. 2C:33-4) is a lower-level alternative.'),
  ('weapons-carrying-prohibited', 'NJ', 'N.J.S.A. 2C:39-5(d)', 'Possession of Other Weapons Without License', '4th Degree Crime', '18 months', '18 months', '$10,000', '{"Having in one''s possession any weapon","Under circumstances not manifestly appropriate for such lawful uses as it may have","Without license or legal authority"}', 'None', '{"Handgun: N.J.S.A. 2C:39-5(b) — 2nd Degree with Graves Act","Prohibited weapon (switchblade, brass knuckles): additional charges — N.J.S.A. 2C:39-3","School zone: mandatory additional term — N.J.S.A. 2C:39-5(e)"}', 'NJ regulates ''weapons'' broadly. Specific prohibited weapons under N.J.S.A. 2C:39-3. Handgun possession without permit is 2nd Degree (Graves Act). School zone weapon possession carries mandatory additional sentence.'),
  ('weapons-school-zone', 'NJ', 'N.J.S.A. 2C:39-5(e)', 'Possession of Firearm in School Zone', '2nd Degree Crime (firearm); 3rd Degree (other weapon)', '5 years', '10 years (2nd Degree)', '$150,000', '{"Possessing or carrying a weapon","In or within 1,000 feet of school property or school bus","Without authorization"}', 'Graves Act applies for firearm: 5-year mandatory', '{"Firearm: 2nd Degree + Graves Act","Prior weapons conviction: extended term","During school hours: aggravating factor"}', 'NJ Gun-Free School Zone Act makes possession of firearm on school grounds a 2nd Degree Crime with Graves Act. Distance extends to 1,000 feet of school property. Both state and federal (18 U.S.C. § 922(q)) apply.'),
  ('bomb-threat', 'NJ', 'N.J.S.A. 2C:33-3', 'False Public Alarm / Bomb Threat', '4th Degree Crime (general false alarm); 3rd Degree (targeting school/mass transit)', '18 months', '5 years (3rd Degree)', '$75,000 plus restitution', '{"Initiating or circulating a report or warning","Knowing it is false or baseless","Which would prompt official emergency response or public evacuation"}', 'None; restitution mandatory for response costs', '{"School or house of worship: 3rd Degree — N.J.S.A. 2C:33-3(e)","Emergency services mobilized: mandatory restitution","Multiple threats: multiple counts"}', 'False public alarm (bomb threat) escalated to 3rd Degree for school and religious institution threats. Restitution for evacuation costs mandatory. Juvenile offenders frequently charged.'),
  ('animal-cruelty', 'NJ', 'N.J.S.A. 4:22-17', 'Cruelty to Animals', '4th Degree Crime (serious cruelty); Disorderly Persons (neglect)', '18 months (4th Degree)', '18 months (4th Degree) or 6 months (Disorderly)', '$3,000-$5,000 (4th Degree) per offense', '{"Intentionally or knowingly","Overdriving, overloading, torturing, or killing an animal","OR causing unnecessary suffering to an animal"}', 'None', '{"Multiple animals: multiple counts","Animal fighting: 4th Degree — N.J.S.A. 4:22-24","Prior conviction: extended term"}', 'NJ animal cruelty under N.J.S.A. 4:22-17 et seq. Upgraded from summary offense to 4th Degree Crime in 2016 (Jax''s Law). Animal fighting is separately criminalized. SPCA has law enforcement authority.'),
  ('probation-violation', 'NJ', 'N.J.S.A. 2C:45-3', 'Probation Violation', 'Revocation proceeding; penalty up to original term', '0 days (may continue on modified probation)', 'Remaining term or maximum of original offense', 'No additional fine', '{"Defendant on a probation term","Willfully violating a condition of probation","Established by preponderance of evidence at violation hearing"}', 'None', '{"New criminal offense while on probation: consecutive sentencing likely","Technical violations: stepped responses (community service, jail)","PSL (Parole Supervision for Life) violations: NJSP Parole Board jurisdiction"}', 'NJ probation violations heard before sentencing judge. No jury. Preponderance standard. Court may continue, modify, or revoke to impose custodial sentence up to original maximum. Drug court technical violations have their own graduated responses.'),
  ('parole-violation', 'NJ', 'N.J.S.A. 30:4-123.60', 'Parole Violation', 'Administrative proceeding', 'Varies', 'Return to prison for remainder of sentence', 'None', '{"Person on parole","Violating conditions of parole","Including new criminal conduct, technical violations, or absconding"}', 'None', '{"New crime while on parole: consecutive term likely","Absconding: warrant issued; no bail typical"}', 'NJ State Parole Board jurisdiction. Due process rights under Morrissey v. Brewer apply. Parole Supervision for Life (PSL) violations for sex offenders handled by NJ State Parole Board with more supervision.'),
  ('escape-custody', 'NJ', 'N.J.S.A. 2C:29-5', 'Escape from Custody', '3rd Degree Crime (escape from institution); 4th Degree (leave temporary release)', '3 years (3rd Degree)', '5 years (3rd Degree); 18 months (4th Degree)', '$75,000', '{"Escaping from official detention","OR using force, threat, or deception to escape","Without authorization"}', 'None', '{"Force or weapon used: additional assault charges","Injuring corrections officer: aggravated assault concurrent","Conspiracy to escape: additional charges"}', 'NJ escape is 3rd Degree for facility escape. Failure to return from furlough is 4th Degree. Sentence for escape runs consecutive to existing sentence.'),
  ('false-report', 'NJ', 'N.J.S.A. 2C:28-4', 'Falsely Reporting an Incident', '4th Degree Crime; 3rd Degree if bomb threat or mass casualty', '18 months', '5 years (3rd Degree)', '$75,000 plus restitution', '{"Knowingly giving or causing a false report to be given","To any law enforcement or civil authority","Reporting that an offense has been committed or a fire is burning"}', 'None; restitution mandatory if emergency response triggered', '{"Bomb threat or terrorist act: 3rd Degree — N.J.S.A. 2C:33-3","Emergency response costs: mandatory restitution","Prior false report: sentencing enhancement"}', 'NJ false report to law enforcement is 4th Degree. False bomb threat separately prosecuted as 3rd Degree under N.J.S.A. 2C:33-3. Restitution for response costs. Distinct from false statements in official proceedings (perjury).'),
  ('cybercrime', 'NJ', 'N.J.S.A. 2C:20-25', 'Computer Criminal Activity', '4th-2nd Degree Crime (damage/loss-based)', '18 months', '10 years (2nd Degree, $75,000+ damage)', '$150,000', '{"Purposely or knowingly and without authorization accessing","A computer system, network, or data","Altering, damaging, deleting, or obtaining data"}', 'None', '{"$75,000+ damage: 2nd Degree","$500-$75,000: 3rd Degree","Under $500: 4th Degree","Government systems: enhanced federal charges","Healthcare data breach: HIPAA federal parallel"}', 'NJ Computer Criminal Activity Act under N.J.S.A. 2C:20-23 et seq. Graded by financial damage caused. Federal CFAA (18 U.S.C. § 1030) charges frequently concurrent for interstate computer crimes.'),
  ('tax-evasion', 'NJ', 'N.J.S.A. 54:49-14', 'Tax Fraud', '3rd Degree Crime (amount-based)', '3 years', '5 years per count', '$75,000 per count', '{"Willfully failing to file a required tax return","OR willfully making or subscribing a false tax return","With intent to evade or defeat any tax"}', 'None', '{"Multiple years of non-filing: multiple counts","Sales tax fraud: N.J.S.A. 54:32B-13","Federal concurrent IRS prosecution","Offshore account concealment: additional charges"}', 'NJ Division of Taxation handles state tax fraud. Federal IRS prosecution concurrent. Sales tax fraud separately prosecuted under N.J.S.A. 54:32B-13. Restitution and interest mandatory.'),
  ('wire-fraud', 'NJ', 'N.J.S.A. 2C:21-4.3 (state) / 18 U.S.C. § 1343 (federal)', 'Scheme to Defraud / Wire Fraud', '2nd-4th Degree Crime (state, loss-based); federal: up to 20 years', '18 months (state)', '10 years (state); 20 years (federal)', '$150,000 (state); $250,000 (federal)', '{"A scheme or artifice to defraud","Using wire communications, internet, or electronic means","Obtaining money or property through false pretenses"}', 'None', '{"Financial institution victim: 30 years federal","COVID/disaster fraud: enhanced federal","Mail fraud concurrent: 18 U.S.C. § 1341"}', 'Federal wire fraud frequently charged for interstate fraud. NJ state fraud under N.J.S.A. 2C:21-4 covers scheme to defraud. Both charges often filed together.'),
  ('mortgage-fraud', 'NJ', 'N.J.S.A. 2C:21-4.5', 'Residential Mortgage Fraud', '2nd-4th Degree Crime (loss-based)', '18 months', '10 years (2nd Degree, $75,000+)', '$150,000', '{"Knowingly making false statements","In connection with a residential mortgage loan","With intent to defraud a lender, borrower, or government entity"}', 'None', '{"$75,000+ loss: 2nd Degree","Multiple loans: multiple counts","Bank fraud: federal prosecution concurrent — 18 U.S.C. § 1344","Real estate professional: licensing consequences"}', 'NJ Residential Mortgage Fraud Act under N.J.S.A. 2C:21-4.5. Federal bank fraud charges frequently concurrent. Straw buyer schemes and appraisal fraud common patterns.'),
  ('possession-child-pornography', 'NJ', 'N.J.S.A. 2C:24-4(b)(4)', 'Possession of Child Sexual Abuse Material (CSAM)', '4th Degree Crime', '18 months', '18 months', '$10,000', '{"Knowingly possessing","Any photograph, film, or other material depicting a child","In a sexually explicit manner"}', 'None; Megan''s Law registration required', '{"Distribution or showing: 3rd Degree — N.J.S.A. 2C:24-4(b)(3)","Production: 2nd Degree — N.J.S.A. 2C:24-4(b)(2)","Federal concurrent prosecution: 18 U.S.C. § 2252","Prior sex conviction: extended term"}', 'NJ CSAM possession is 4th Degree. Each image may be a separate count under N.J.S.A. 2C:24-4(b)(5) (each depicts a separate victim). Megan''s Law registration mandatory. Federal charges typical for internet-based distribution.'),
  ('production-child-pornography', 'NJ', 'N.J.S.A. 2C:24-4(b)(2)', 'Production/Creation of Child Sexual Abuse Material', '2nd Degree Crime', '5 years', '10 years', '$150,000', '{"Filming, photographing, or reproducing","A minor engaged in sexually explicit conduct","For the purpose of creating CSAM"}', 'NERA: 85% of sentence; Megan''s Law registration mandatory', '{"Child under 13: enhanced sentencing within 2nd Degree","Prior sex offense: extended term","Distribution of material: additional concurrent charges"}', '2nd Degree CSAM production in NJ — NERA applies (85% served before parole). Federal prosecution under 18 U.S.C. § 2251 typically concurrent. PSL (Parole Supervision for Life) mandatory.'),
  ('harassment', 'NJ', 'N.J.S.A. 2C:33-4', 'Harassment', 'Petty Disorderly Persons Offense; 4th Degree if pattern toward bias', '0 days', '30 days (Petty Disorderly); 18 months (4th Degree bias)', '$500 (Petty Disorderly); $10,000 (4th Degree)', '{"Making or causing to be made a communication in a manner likely to cause annoyance or alarm","OR striking, kicking, shoving, or subjecting to offensive touching","OR engaging in any other course of alarming conduct with purpose to alarm or annoy"}', 'None', '{"Bias-based harassment: 4th Degree — N.J.S.A. 2C:16-1 concurrent","Cyberstalking/electronic harassment: stalking charges may apply","Against DV protected person: predicate for FRO"}', 'NJ harassment (Petty Disorderly) is a common predicate for domestic violence FRO proceedings. 4th Degree elevation for bias-based harassment. Electronic harassment increasingly charged.'),
  ('fleeing-eluding', 'NJ', 'N.J.S.A. 2C:29-2(b)', 'Eluding an Officer', '3rd Degree Crime (default); 2nd Degree if creates risk of injury', '3 years', '10 years (2nd Degree)', '$150,000', '{"Operating a motor vehicle","After being signaled by a police officer to stop","Intentionally fleeing or attempting to elude the officer"}', 'License revocation mandatory; NERA may apply for 2nd Degree', '{"Creates risk of death or injury to another: 2nd Degree — N.J.S.A. 2C:29-2(b)","High-speed chase injuring bystander: NERA applicable","OWI concurrent: enhanced sentencing"}', 'NJ eluding is 3rd Degree by default, elevated to 2nd Degree with risk of injury (NERA). License revocation 6 months to 2 years. Consecutive to other charges arising from same incident.'),
  ('hate-crime', 'NJ', 'N.J.S.A. 2C:16-1', 'Bias Intimidation', '3rd Degree Crime (standalone); elevated by underlying offense degree', '3 years', '10 years if 2nd Degree underlying crime', '$75,000-$150,000', '{"Committing a predicate offense","Because of, or in a manner reasonably calculated to put another person in fear on account of","Race, color, religion, gender, disability, sexual orientation, gender identity, national origin, or ethnicity"}', 'None; community service often ordered', '{"If the underlying crime is 1st Degree: bias intimidation is 2nd Degree","If underlying is 2nd/3rd Degree: bias intimidation is 3rd Degree","If Disorderly Persons: bias intimidation is 4th Degree","Mandatory civil penalty to victim"}', 'NJ bias intimidation statute. Conviction elevated by one degree relative to underlying offense. Includes sexual orientation and gender identity — broader than many states. Civil penalties additionally available under LAD.'),
  ('human-trafficking', 'NJ', 'N.J.S.A. 2C:13-8(a)(1)', 'Human Trafficking — Labor Trafficking', '1st Degree Crime', '10 years', '20 years (or Life if minor victim)', '$200,000', '{"Recruiting, luring, enticing, transporting, providing, obtaining, or harboring a person","By means of force, threat of force, fraud, or coercion","For the purpose of labor or services"}', 'NERA: 85% of sentence', '{"Victim under 18: maximum Life, no consent defense","Multiple victims: consecutive sentences","Drug use to control victim: additional CDS charges"}', 'NJ Human Trafficking Act (N.J.S.A. 2C:13-8). Sex and labor trafficking both covered. Minor victims: no defense of consent. Safe harbor for victims under N.J.S.A. 2C:13-9. Asset forfeiture.'),
  ('witness-tampering', 'NJ', 'N.J.S.A. 2C:28-5', 'Tampering with Witnesses and Informants', '3rd Degree Crime; 2nd Degree if threat of force', '3 years', '10 years (2nd Degree)', '$150,000', '{"Believing that an official proceeding or investigation is pending or about to be instituted","Attempts to induce or otherwise cause a witness or informant to testify falsely","OR to withhold testimony, information, or evidence","OR flee jurisdiction to avoid testifying"}', 'None', '{"Use or threat of force: 2nd Degree — N.J.S.A. 2C:28-5(a)(3)","NERA may apply for 2nd Degree","Retaliation against witness: hindering apprehension charge concurrent"}', 'NJ witness tampering escalates to 2nd Degree if force or threats are used. NERA applies to 2nd Degree (85% served). Separate from jury tampering under N.J.S.A. 2C:29-4.'),
  ('jury-tampering', 'NJ', 'N.J.S.A. 2C:29-4', 'Tampering with a Juror or Jurors', '3rd Degree Crime', '3 years', '5 years', '$75,000', '{"Attempting to influence a juror''s vote, opinion, or action","In relation to a case or proceeding","Without official authority and otherwise than by lawful argument"}', 'None', '{"Bribery of juror: concurrent bribery charge — N.J.S.A. 2C:27-6","Force used: 2nd Degree concurrent","During capital case: aggravating factor"}', 'NJ jury tampering is 3rd Degree. Bribery of juror is separately charged under N.J.S.A. 2C:27-6 (3rd Degree). Contact with potential jurors during voir dire also covered.'),
  ('criminal-contempt', 'NJ', 'N.J.S.A. 2C:29-9', 'Contempt of Court / Violation of Court Order', '4th Degree Crime (FRO violation); contempt power for other violations', '18 months', '18 months (4th Degree)', '$10,000', '{"Willful disobedience of a court order","Including protective orders, injunctions, or other court-ordered prohibitions"}', 'None', '{"FRO violation with assault: concurrent aggravated assault","Repeat contempt: enhanced by court","Civil contempt until compliance: coercive confinement possible"}', 'FRO (Final Restraining Order) violation is 4th Degree Criminal Contempt. TRO violation handled as civil contempt. Separate statutory contempt power under Court Rules. Combined civil/criminal proceedings common.'),
  ('impersonating-officer', 'NJ', 'N.J.S.A. 2C:28-8', 'Impersonating a Public Servant', '4th Degree Crime (impersonation only); 3rd Degree (if deceiving or taking action)', '18 months', '5 years (3rd Degree)', '$75,000', '{"Pretending to be a public servant","With purpose to induce another to submit to pretended official authority","OR take or withhold action based on the impersonation"}', 'None', '{"Pretend arrest or search: 3rd Degree","Obtaining money through impersonation: fraud concurrent","Use of realistic badge, vehicle, or uniform: aggravating factor"}', 'NJ impersonating public servant. Using impersonation to commit another offense elevates to 3rd Degree. Fake traffic stops and ''cop pulls'' increasingly prosecuted. False credentials separate offense under N.J.S.A. 2C:21-17.'),
  ('gang-participation', 'NJ', 'N.J.S.A. 2C:33-29', 'Street Gang Criminality', '3rd Degree Crime (enhancement on underlying offense)', '3 years', '5 years', '$75,000', '{"Committing any crime or offense","For the benefit of, at the direction of, or in association with a criminal street gang","With knowledge that the group is a criminal street gang"}', 'None; runs consecutive to underlying offense', '{"Underlying crime is 1st or 2nd Degree: gang enhancement is 2nd Degree","Prior gang conviction: extended term","Recruitment of juvenile: additional charge"}', 'NJ street gang enhancement under N.J.S.A. 2C:33-29. Consecutive to underlying offense. Requires proving gang membership and gang-related motive. Gang recruitment of juveniles separately criminalized.'),
  ('possession-explosives', 'NJ', 'N.J.S.A. 2C:39-3(a)', 'Possession of Destructive Devices / Explosives', '3rd Degree Crime', '3 years', '5 years', '$75,000', '{"Knowingly having in possession or under control","Any destructive device, explosive device, or bomb","Without lawful authority"}', 'Graves Act may apply if used as weapon', '{"Use in or near school: mandatory additional term","Intent to terrorize: terroristic threats concurrent — N.J.S.A. 2C:12-3","Actual detonation: additional arson or assault charges"}', 'NJ destructive devices under N.J.S.A. 2C:39-3. Prohibited weapons statute. Federal prosecution under 18 U.S.C. § 844 concurrent for explosives. Manufacturing explosives is additionally charged.'),
  ('fraud-welfare', 'NJ', 'N.J.S.A. 44:10-79', 'Public Assistance Fraud', '3rd Degree Crime ($75,000+); 4th Degree ($500-$75,000); Disorderly Persons (under $500)', '18 months', '5 years (3rd Degree)', '$75,000', '{"Willfully making a false statement or misrepresentation","In connection with an application for public assistance (NJ FamilyCare, SNAP, TANF)","With intent to fraudulently obtain benefits"}', 'None', '{"SNAP/federal benefits: federal prosecution concurrent","Medicaid fraud: additional charges — N.J.S.A. 2C:51-5","Organized benefits fraud: multiple counts"}', 'NJ public assistance fraud graded by amount obtained. Medicaid fraud (N.J.S.A. 2C:51-5) carries enhanced penalties. SNAP fraud also subject to federal prosecution. Restitution and benefit disqualification mandatory.')
INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('dui-dwi', 'NC', 'N.C.G.S. § 20-138.1', 'Impaired Driving (DWI)', 'Misdemeanor (Levels I-V based on grossly aggravating/aggravating/mitigating factors); Felony (Habitual DWI)', '24 hours (Level V)', '3 years (Level I aggravated); 6 years (Aggravated Level 1)', '$10,000 (Level I); $4,000 (Level II)', '{"Defendant drove a vehicle on any highway, street, or public vehicular area","While under the influence of an impairing substance","OR with BAC of 0.08% or more (0.04% CDL holders; 0.00% under age 21 on limited permit)"}', 'Level I: 30 days jail (active); Aggravated Level 1: 12 months active minimum', '{"Grossly aggravating factors: prior DWI within 7 years, serious injury accident, child passenger, driving on revoked license for DWI","Aggravated Level 1: two or more grossly aggravating factors — mandatory 12 months minimum active","Child under 18 in vehicle: grossly aggravating factor"}', 'NC uses a tiered sentencing structure (Levels 1-5 plus Aggravated Level 1) based on aggravating and mitigating factors under § 20-179. Habitual DWI is a Class F felony.'),
  ('dui-first-offense', 'NC', 'N.C.G.S. § 20-138.1', 'Impaired Driving — First Offense', 'Misdemeanor (Level II-V typically for first offense with no aggravating factors)', '24 hours (Level V)', '12 months (Level II)', '$2,000 (Level II); $1,000 (Level III-V)', '{"First DWI within 7-year look-back for sentencing purposes","Drove a vehicle on highway, street, or public vehicular area","While under influence or with BAC 0.08%+"}', '24 hours jail (Level V minimum); 7 days (Level III)', '{"BAC 0.15% or higher: mandatory continuous alcohol monitoring (CAM)","Child passenger: grossly aggravating factor — elevates to Level I or Aggravated Level 1"}', 'Most first offenses without aggravating factors are sentenced at Level V or IV. Ignition interlock required on restoration.'),
  ('dui-repeat-offense', 'NC', 'N.C.G.S. § 20-138.1; § 20-138.5', 'Impaired Driving — Repeat Offense / Habitual DWI', 'Misdemeanor (2nd within 7 years: Level I); Felony (Habitual DWI: Class F)', '30 days active (Level I)', '12 months (Level I misdemeanor); 41 months (Class F felony Habitual DWI)', '$4,000 (Level I)', '{"Defendant has 3 or more prior DWI convictions within 10 years (Habitual DWI)","OR prior DWI within 7 years (grossly aggravating factor for Level I sentencing)","Drove while impaired as defined under § 20-138.1"}', 'Level I: 30 days active minimum; Habitual DWI: 12 months active minimum', '{"Habitual DWI (Class F felony): mandatory 12 months active no suspension","Vehicle forfeiture possible on Habitual DWI","Permanent license revocation after Habitual DWI conviction"}', '4th DWI within 10 years = Habitual DWI (Class F felony) under § 20-138.5. Permanent revocation possible.'),
  ('dui-drugs', 'NC', 'N.C.G.S. § 20-138.1(a)(3)', 'Impaired Driving — Drug Impairment', 'Misdemeanor (same tiers as alcohol DWI); Felony (Habitual DWI)', '24 hours (Level V)', '3 years (Level I aggravated)', '$4,000 (Level I)', '{"Defendant drove a vehicle","With any amount of a Schedule I controlled substance in their blood or urine","OR while impaired by any impairing substance including prescription or OTC drugs"}', 'Same as alcohol DWI tiers', '{"Schedule I substance per se: no impairment proof required","Drug paraphernalia in vehicle: additional charge under § 90-113.22"}', 'Per se provision under § 20-138.1(a)(3): any Schedule I substance in blood/urine = per se DWI. Covers marijuana metabolites.'),
  ('reckless-driving', 'NC', 'N.C.G.S. § 20-140', 'Reckless Driving', 'Class 2 Misdemeanor (basic); Class 1 Misdemeanor (reckless endangering property)', NULL, '60 days (Class 2); 120 days (Class 1)', '$1,000', '{"Defendant drove a vehicle on a highway or public vehicular area","In a careless and heedless manner in willful or wanton disregard for the rights or safety of others","OR in a manner so as to endanger or be likely to endanger any person or property"}', NULL, '{"Resulting injury or death: felony death by vehicle or serious injury by vehicle charges"}', '4 DMV points. Two types: willful/wanton disregard (§ 20-140(a)) and endangerment (§ 20-140(b)).'),
  ('hit-and-run', 'NC', 'N.C.G.S. § 20-166', 'Duty to Stop in Event of Accident — Hit and Run', 'Class F Felony (death or serious injury); Class H Felony (injury); Class 1 Misdemeanor (property only)', NULL, '41 months (Class F); 25 months (Class H); 120 days (Class 1 misdemeanor)', NULL, '{"Defendant was driving a vehicle involved in an accident","Accident resulted in death, injury, or property damage","Defendant failed to immediately stop at the scene, give information, or render aid"}', NULL, '{"DUI concurrent: aggravated sentence","Death resulting: Class F felony","Serious injury: Class H felony"}', 'Under § 20-166, driver must stop, remain, give information, and render aid. Property damage only is Class 1 misdemeanor.'),
  ('vehicular-homicide', 'NC', 'N.C.G.S. § 20-141.4', 'Felony Death by Vehicle', 'Class D Felony (impaired driving); Class E Felony (reckless); Class F Felony (other moving violation)', NULL, '204 months (Class D); 88 months (Class E); 41 months (Class F)', NULL, '{"Defendant unintentionally caused the death of another person","While violating N.C.G.S. § 20-138.1 (impaired driving) or other specified traffic law","Violation was a proximate cause of death"}', NULL, '{"DWI as predicate: Class D felony with enhanced punishment","Multiple deaths: consecutive sentences"}', 'Aggravated felony death by vehicle under § 20-141.4(a1) applies when defendant has prior DWI within 7 years.'),
  ('vehicular-manslaughter', 'NC', 'N.C.G.S. § 20-141.4(a2)', 'Misdemeanor Death by Vehicle', 'Class 1 Misdemeanor', NULL, '120 days imprisonment', NULL, '{"Defendant unintentionally caused the death of another person","While committing a moving traffic violation other than impaired driving"}', NULL, '{"Elevation to felony if defendant has prior DWI"}', 'Misdemeanor death by vehicle under § 20-141.4(a2). Moving violation as predicate.'),
  ('driving-on-suspended', 'NC', 'N.C.G.S. § 20-28', 'Driving While License Revoked', 'Class 3 Misdemeanor (basic); Class 1 Misdemeanor or Class I Felony (revoked for DWI)', NULL, '20 days (Class 3); 120 days (Class 1); 24 months (Class I felony)', '$200 (Class 3); $1,000 (Class 1)', '{"Defendant drove a motor vehicle on any street or highway","While defendant''s license was revoked, suspended, or cancelled","Defendant had knowledge of the revocation or suspension"}', NULL, '{"License revoked for DWI: Class 1 misdemeanor or Class I felony depending on circumstances","Impaired driving while revoked for DWI: vehicle forfeiture possible"}', 'If license was revoked because of an impaired driving offense, enhanced penalties apply under § 20-28(a1).'),
  ('fleeing-eluding', 'NC', 'N.C.G.S. § 20-141.5', 'Speeding to Elude Arrest', 'Class H Felony; Class F Felony (if aggravating factors present)', NULL, '39 months (Class H); 41 months (Class F)', NULL, '{"Defendant operated a motor vehicle on a street, highway, or public vehicular area","While fleeing or attempting to elude a law enforcement officer","After the officer gave a visible or audible signal to stop"}', NULL, '{"Endangering others or exceeding speed by 15+ mph: Class F felony","Death or serious injury: additional charges","Two or more aggravating factors: Class E felony"}', 'Class F felony when two or more aggravating factors (reckless driving, speed 15+ mph over limit, endangering persons). Class H felony baseline.'),
  ('open-container', 'NC', 'N.C.G.S. § 20-138.7', 'Open Container of Alcoholic Beverage in Passenger Area', 'Class 3 Misdemeanor (driver); Class 3 Misdemeanor (passenger)', NULL, '20 days imprisonment', '$200', '{"Defendant consumed alcohol or had in the passenger area an open container of alcohol","While driving a motor vehicle on a highway or public vehicular area","Container had been opened or had broken seal"}', NULL, '{}', 'Passengers also subject to charge. Vehicles for hire and recreational vehicles may have exceptions.'),
  ('refusing-breath-test', 'NC', 'N.C.G.S. § 20-16.2', 'Refusal of Chemical Analysis — Implied Consent', 'Administrative (license revocation); civil penalty', NULL, '1-year civil license revocation (1st refusal); permanent revocation (4th+)', NULL, '{"Defendant was lawfully arrested for impaired driving","Law enforcement officer informed defendant of implied consent rights","Defendant willfully refused to submit to chemical analysis"}', NULL, '{"2nd refusal within 7 years: 4-year revocation","3rd or subsequent refusal: permanent revocation"}', 'Refusal admissible at trial. NC requires Willful refusal — inadvertent or medical inability is not a refusal.'),
  ('drug-possession', 'NC', 'N.C.G.S. § 90-95(a)(3); § 90-95(d)', 'Possession of Controlled Substance', 'Class I Felony (Schedule I-II); Class 1 Misdemeanor (Schedule III-VI under threshold)', NULL, '24 months (Class I felony); 120 days (Class 1 misdemeanor)', NULL, '{"Defendant knowingly possessed a controlled substance","Substance was listed on North Carolina''s controlled substance schedules","Defendant had actual or constructive possession"}', NULL, '{"Near school, childcare center, or public park: Class E felony enhancement","Large quantity: trafficking threshold under § 90-95(h)","Prior drug felony: elevated class"}', 'Marijuana possession of 0.5 oz or less is Class 3 misdemeanor. Over 0.5 oz: Class 1 misdemeanor. Over 1.5 oz: Class I felony.'),
  ('drug-possession-marijuana', 'NC', 'N.C.G.S. § 90-95(d)(4)', 'Possession of Marijuana', 'Class 3 Misdemeanor (0.5 oz or less); Class 1 Misdemeanor (0.5-1.5 oz); Class I Felony (over 1.5 oz)', NULL, '20 days (Class 3); 120 days (Class 1); 24 months (Class I felony)', '$200 (Class 3); $1,000 (Class 1)', '{"Defendant possessed marijuana","Amount determined classification","Possession was knowing"}', NULL, '{"Over 10 lbs: marijuana trafficking — Class H or higher felony with mandatory minimums","Near school or park: Class E felony enhancement"}', 'Marijuana remains a controlled substance in NC (Schedule VI). No medical or recreational marijuana program as of 2026.'),
  ('drug-possession-cocaine', 'NC', 'N.C.G.S. § 90-95(d)(2)', 'Possession of Cocaine', 'Class I Felony', NULL, '24 months (Class I felony)', NULL, '{"Defendant knowingly possessed cocaine (Schedule II)","Amount was below 28g trafficking threshold","Possession was actual or constructive"}', NULL, '{"28g or more: cocaine trafficking — Class G felony, mandatory 35 months minimum","Near school: Class E felony enhancement"}', 'Cocaine trafficking under § 90-95(h)(3): 28g-200g = Class G (35 mo. min.); 200g-400g = Class F (70 mo. min.); 400g+ = Class D (175 mo. min.).'),
  ('drug-possession-meth', 'NC', 'N.C.G.S. § 90-95(d)(2)', 'Possession of Methamphetamine', 'Class I Felony', NULL, '24 months (Class I felony)', NULL, '{"Defendant knowingly possessed methamphetamine (Schedule II)","Amount below 28g trafficking threshold","Possession was actual or constructive"}', NULL, '{"28g or more: meth trafficking — Class F felony, mandatory 70 months minimum","200g+ meth: Class D felony mandatory 175 months"}', 'Meth trafficking thresholds: 28g-200g = Class F; 200g-400g = Class E; 400g+ = Class C under § 90-95(h)(3b).'),
  ('drug-possession-opioids', 'NC', 'N.C.G.S. § 90-95(d)(1)-(2)', 'Possession of Opioids or Narcotics', 'Class I Felony (Schedule I or II opiate)', NULL, '24 months (Class I felony)', NULL, '{"Defendant knowingly possessed an opioid or opiate controlled substance","No valid prescription or prescription was fraudulently obtained","Possession was actual or constructive"}', NULL, '{"4g or more opium/heroin: trafficking — Class F mandatory 70 months","14g+ opium: Class E mandatory 90 months","28g+: Class D mandatory 175 months"}', 'Heroin/opium trafficking under § 90-95(h)(4). Fentanyl treated as Schedule II. Distribution causing death may support murder.'),
  ('drug-possession-prescription', 'NC', 'N.C.G.S. § 90-95(d)(2)-(3)', 'Possession of Prescription Drug Without Valid Prescription', 'Class I Felony (Schedule II-III); Class 1 Misdemeanor (Schedule IV-VI)', NULL, '24 months (Class I); 120 days (Class 1 misdemeanor)', NULL, '{"Defendant possessed a prescription controlled substance","Defendant lacked a valid, current prescription","Substance was on NC controlled substance schedule"}', NULL, '{"Doctor shopping or forged prescription: prescription fraud charge under § 90-108"}', 'NC Controlled Substance Reporting System (CSRS) data used as evidence.'),
  ('drug-trafficking', 'NC', 'N.C.G.S. § 90-95(h)', 'Drug Trafficking', 'Class G, F, E, D, or C Felony depending on substance and quantity', '35 months (cocaine 28g+, Class G); 70 months (cocaine 200g+, Class F)', 'Class C: 231 months+', '$500,000 (large quantity)', '{"Defendant sold, manufactured, delivered, transported, or possessed with intent to sell or deliver a controlled substance","OR possessed any amount of a controlled substance in the trafficking quantity","Quantity met or exceeded the statutory trafficking threshold for the specific substance"}', 'Mandatory minimum active sentence varies by substance and quantity; no probation permitted on mandatory term', '{"Prior drug trafficking conviction: enhanced mandatory minimum","Conspiracy to traffic: same penalties as completed trafficking","Leadership or organizer role: enhanced sentencing"}', 'Trafficking quantities and classes vary by substance under § 90-95(h)(1)-(4). Mandatory active sentences; probation not available.'),
  ('drug-distribution', 'NC', 'N.C.G.S. § 90-95(a)(1)', 'Sale or Delivery of Controlled Substance', 'Class G Felony (Schedule I-II); Class H Felony (Schedule III-IV); Class I Felony (Schedule V-VI)', NULL, '47 months (Class G); 39 months (Class H); 24 months (Class I)', NULL, '{"Defendant sold or delivered a controlled substance","Substance was on the controlled substance schedule","Defendant acted knowingly and intentionally"}', NULL, '{"Sale within 1,000 feet of school: two-class enhancement (e.g., Class G becomes Class E)","Sale to minor: enhanced penalty","Sale to pregnant woman: enhanced penalty"}', 'School enhancement under § 90-95(e)(8) elevates offense two felony classes.'),
  ('drug-manufacturing', 'NC', 'N.C.G.S. § 90-95(a)(1)', 'Manufacturing Controlled Substance', 'Class H Felony (most drugs); Class D Felony (methamphetamine using precursors)', NULL, '39 months (Class H); 204 months (Class D meth)', NULL, '{"Defendant manufactured, produced, or processed a controlled substance","Substance was on the controlled substance schedule","Acts were knowing and intentional"}', NULL, '{"Meth manufacturing using precursors: elevated to Class D felony under § 90-95(b1)","Children present at meth lab: child endangerment charges","Trafficking quantity: trafficking charges"}', 'Manufacturing meth with precursor chemicals triggers Class D felony elevation under § 90-95(b1).'),
  ('drug-paraphernalia', 'NC', 'N.C.G.S. § 90-113.22', 'Possession of Drug Paraphernalia', 'Class 1 Misdemeanor', NULL, '120 days imprisonment', '$1,000', '{"Defendant possessed drug paraphernalia","Defendant intended to use the paraphernalia to plant, propagate, cultivate, grow, harvest, manufacture, compound, convert, produce, process, prepare, test, analyze, pack, repack, store, contain, conceal, inject, ingest, inhale, or otherwise introduce a controlled substance into the human body"}', NULL, '{"Sale of paraphernalia to minor: Class I felony under § 90-113.22A"}', 'Intent element is critical. Mere possession of an item without drug residue or proximity to drugs may be contested.'),
  ('prescription-fraud', 'NC', 'N.C.G.S. § 90-108(a)(10); § 90-113.11', 'Fraudulent Prescription / Obtaining a Controlled Substance by Fraud', 'Class I Felony', NULL, '24 months', NULL, '{"Defendant obtained or attempted to obtain a controlled substance by forgery, fraud, or deception","OR defendant used a forged or altered prescription","OR defendant used a false name or address with a practitioner"}', NULL, '{"Healthcare provider committing fraud: license revocation","Multiple fraudulent prescriptions: charges may stack"}', 'NC Controlled Substance Reporting System (CSRS) tracks prescription patterns. Doctor-shopping prosecuted under § 90-108(a)(10).'),
  ('drug-possession-with-intent', 'NC', 'N.C.G.S. § 90-95(a)(1)', 'Possession with Intent to Sell or Deliver', 'Class G Felony (Schedule I-II); Class H Felony (Schedule III-IV); Class I Felony (Schedule V-VI)', NULL, '47 months (Class G); 39 months (Class H); 24 months (Class I)', NULL, '{"Defendant possessed a controlled substance","With intent to sell or deliver","Intent inferred from quantity, packaging, scales, currency, or other evidence"}', NULL, '{"Near school or childcare center: two-class felony enhancement","With firearm: additional weapons charges","Trafficking quantity: trafficking charges"}', 'Intent proven circumstantially. Quantity alone, without other indicators, generally insufficient for intent charge.'),
  ('murder-first-degree', 'NC', 'N.C.G.S. § 14-17', 'First Degree Murder', 'Class A Felony', 'Life without parole', 'Death penalty or life without parole', NULL, '{"Defendant killed another human being","With malice, premeditation, and deliberation","OR by means of poison, lying in wait, imprisonment, starving, or torture","OR in the perpetration or attempted perpetration of a specified felony (felony murder)"}', 'Life without parole (mandatory for Class A felony)', '{"Aggravating circumstances: death penalty eligible","Law enforcement officer victim: death penalty eligible aggravating circumstance","Especially heinous, atrocious, or cruel: aggravating circumstance"}', 'NC has the death penalty. Felony murder covers killings during arson, rape, robbery, kidnapping, burglary, and other enumerated felonies.'),
  ('murder-second-degree', 'NC', 'N.C.G.S. § 14-17(b)', 'Second Degree Murder', 'Class B1 Felony (malice without premeditation); Class B2 Felony (inherently dangerous act with malice)', NULL, 'Class B1: 484 months+; Class B2: 393 months+', NULL, '{"Defendant killed another human being","With malice","But without premeditation and deliberation","OR committed an act inherently dangerous to human life in wanton disregard of consequences"}', NULL, '{"Defendant had prior murder conviction: enhanced sentence","Drug distribution causing death: second-degree murder possible"}', 'Class B1 felony — malice without premeditation. Class B2 — inherently dangerous act with reckless disregard.'),
  ('voluntary-manslaughter', 'NC', 'N.C.G.S. § 14-18', 'Voluntary Manslaughter', 'Class D Felony', NULL, '204 months', NULL, '{"Defendant killed another human being","With malice but in the heat of passion","Upon adequate provocation that would cause a reasonable person to lose self-control","No cooling-off period had elapsed"}', NULL, '{}', 'Heat-of-passion defense reduces murder to voluntary manslaughter (Class D felony). Imperfect self-defense may also result in voluntary manslaughter.'),
  ('involuntary-manslaughter', 'NC', 'N.C.G.S. § 14-18', 'Involuntary Manslaughter', 'Class F Felony', NULL, '41 months', NULL, '{"Defendant killed another human being","Without malice or intent to kill","During commission of an unlawful act not amounting to a felony","OR during a lawful act performed in a culpably negligent manner"}', NULL, '{}', 'Culpable negligence — greater than ordinary negligence. Vehicular deaths also charged under § 20-141.4.'),
  ('aggravated-assault', 'NC', 'N.C.G.S. § 14-32; § 14-32.4', 'Assault with a Deadly Weapon Inflicting Serious Injury / Assault Inflicting Serious Bodily Injury', 'Class C Felony (deadly weapon + intent to kill + serious injury); Class E Felony (serious bodily injury)', NULL, '231 months (Class C); 88 months (Class E)', NULL, '{"Defendant assaulted another person","With a deadly weapon with intent to kill","Inflicting serious injury (Class C felony)","OR inflicted serious bodily injury without deadly weapon (Class E felony)"}', NULL, '{"Law enforcement officer victim: Class F felony (assault on officer) or higher","Strangulation: Class H felony under § 14-32.4(b)","Domestic violence context: additional charges"}', 'Multiple assault statutes in NC. § 14-32 covers assault with deadly weapon. § 14-32.4 covers assault inflicting serious bodily injury.'),
  ('simple-assault', 'NC', 'N.C.G.S. § 14-33', 'Simple Assault', 'Class 2 Misdemeanor (basic); Class A1 Misdemeanor (certain victims)', NULL, '60 days (Class 2); 150 days (Class A1)', '$1,000', '{"Defendant committed a simple assault on another person","Either by an overt act creating reasonable apprehension of immediate bodily harm","OR by an actual physical act constituting battery"}', NULL, '{"Victim is female and defendant is male: Class A1 misdemeanor under § 14-33(c)(2)","Victim is child under 12: Class A1 misdemeanor","Victim is officer, teacher, healthcare worker: Class A1 misdemeanor","Domestic relationship: Class A1 misdemeanor"}', 'NC combines assault and battery into one offense. Simple assault/battery is Class 2; assault on a female or child is Class A1.'),
  ('battery', 'NC', 'N.C.G.S. § 14-33', 'Simple Assault and Battery', 'Class 2 Misdemeanor (basic); Class A1 Misdemeanor (certain circumstances)', NULL, '60 days (Class 2); 150 days (Class A1)', '$1,000', '{"Defendant intentionally made offensive, harmful, or provoking physical contact with another person","Without consent of the other person"}', NULL, '{"Serious bodily injury inflicted: Class E or C felony depending on circumstances","Domestic relationship: Class A1 misdemeanor"}', 'NC treats assault and battery as the same offense under § 14-33. Battery requires physical contact; assault may be apprehension only.'),
  ('aggravated-battery', 'NC', 'N.C.G.S. § 14-32.4', 'Assault Inflicting Serious Bodily Injury', 'Class E Felony', NULL, '88 months', NULL, '{"Defendant assaulted another person","And inflicted serious bodily injury","Serious bodily injury means injury creating substantial risk of death or causing permanent disfigurement or protracted loss or impairment of function"}', NULL, '{"Deadly weapon used: potential elevation to Class C felony","Strangulation: Class H felony under § 14-32.4(b)","Victim is officer: Class F felony"}', 'Strangulation causing physical injury separately classified as Class H felony under § 14-32.4(b).'),
  ('robbery', 'NC', 'N.C.G.S. § 14-87.1', 'Common Law Robbery', 'Class G Felony', NULL, '47 months', NULL, '{"Defendant took property from another person or their presence","By use of force or intimidation","Without consent and with intent to permanently deprive"}', NULL, '{"Armed robbery: elevated to Class D felony under § 14-87"}', 'Common law robbery under § 14-87.1 is Class G felony. Armed robbery (dangerous weapon) is Class D felony under § 14-87.'),
  ('armed-robbery', 'NC', 'N.C.G.S. § 14-87', 'Robbery with a Dangerous Weapon', 'Class D Felony', NULL, '204 months', NULL, '{"Defendant took property from another person or their presence","By use of or threatened use of a firearm or other dangerous weapon","Victim was endangered or threatened","Defendant intended to permanently deprive the victim of the property"}', NULL, '{"Serious injury inflicted: enhanced sentence","Multiple victims: consecutive sentences"}', 'Class D felony with presumptive active sentence. Dangerous weapon includes firearms, knives, and any object capable of threatening life.'),
  ('kidnapping', 'NC', 'N.C.G.S. § 14-39', 'Kidnapping', 'Class C Felony (1st degree — victim not released in safe place, or serious injury/sexual assault); Class E Felony (2nd degree)', NULL, '231 months (Class C); 88 months (Class E)', NULL, '{"Defendant unlawfully confined, restrained, or removed from one place to another any person under 16, or any person by force, threat, or deception","Without consent of the victim (or parent/guardian if minor)","For purpose of holding for ransom, facilitating felony, doing serious harm, or terrorizing victim"}', NULL, '{"Victim not released in a safe place: 1st degree (Class C)","Sexual assault or serious injury during kidnapping: 1st degree","Ransom demand: Class C"}', '1st degree (Class C) vs. 2nd degree (Class E) based on whether victim was released safely and whether sexual assault or serious injury occurred.'),
  ('arson', 'NC', 'N.C.G.S. § 14-58; § 14-58.1', 'Arson', 'Class D Felony (1st degree — occupied dwelling); Class G Felony (2nd degree — unoccupied or other structure)', NULL, '204 months (Class D); 47 months (Class G)', NULL, '{"Defendant willfully and maliciously set fire to or burned a dwelling house or other structure","Dwelling was occupied by any person (1st degree)","OR structure was not an occupied dwelling (2nd degree)"}', NULL, '{"Person present and in danger: 1st degree","Insurance fraud motive: insurance fraud charges added","Burning school, government building: enhanced under § 14-49 et seq."}', 'Common law arson definitions used. Burning of non-dwelling structures covered under § 14-62 et seq.'),
  ('attempted-murder', 'NC', 'N.C.G.S. § 14-17; § 14-2.5', 'Attempted First or Second Degree Murder', 'Class B1 Felony (attempted 1st degree murder); Class C Felony (attempted 2nd degree murder)', NULL, 'Class B1: 484 months+; Class C: 231 months', NULL, '{"Defendant took a substantial step toward committing murder","With the specific intent to kill","Act was beyond mere preparation"}', NULL, '{"Firearm used: enhanced sentencing","Victim is law enforcement: aggravating factor"}', 'NC penalizes attempt at one class below the completed offense under § 14-2.5. Attempted 1st degree murder is Class B1 (same as 2nd degree murder).'),
  ('assault-with-deadly-weapon', 'NC', 'N.C.G.S. § 14-32(b)', 'Assault with a Deadly Weapon', 'Class E Felony (deadly weapon + serious injury); Class A1 Misdemeanor (deadly weapon without serious injury)', NULL, '88 months (Class E felony); 150 days (Class A1 misdemeanor)', NULL, '{"Defendant assaulted another person","With a deadly weapon","Inflicting serious injury (felony) OR not inflicting serious injury (misdemeanor)"}', NULL, '{"With intent to kill and serious injury: Class C felony","Law enforcement victim: enhanced charge"}', 'Deadly weapon with serious injury = Class E. Deadly weapon + intent to kill + serious injury = Class C under § 14-32(a).'),
  ('theft-larceny', 'NC', 'N.C.G.S. § 14-72', 'Larceny', 'Class I Felony ($1,000+); Class 1 Misdemeanor (under $1,000)', NULL, '24 months (Class I felony); 120 days (Class 1 misdemeanor)', NULL, '{"Defendant took and carried away the personal property of another","Without consent","With intent to permanently deprive the owner"}', NULL, '{"Value $100,000+: Class C felony under § 14-72(b)(5)","From person or from fire or natural disaster victim: Class H felony","Theft of firearm: Class H felony regardless of value"}', 'Felony larceny threshold is $1,000. Larceny from the person (Class H) does not require force — that would be robbery.'),
  ('grand-theft', 'NC', 'N.C.G.S. § 14-72', 'Felony Larceny', 'Class I Felony ($1,000+); Class H Felony (larceny from person, firearm, or other specified circumstances)', NULL, '39 months (Class H); 24 months (Class I)', NULL, '{"Defendant took and carried away personal property of another","Without consent","Property value was $1,000 or more OR circumstances elevated to felony","Intent to permanently deprive"}', NULL, '{"Theft from person: Class H","Theft of firearm: Class H","Value $100,000+: Class C"}', 'NC uses ''larceny'' not ''theft.'' Felony threshold is $1,000.'),
  ('petty-theft', 'NC', 'N.C.G.S. § 14-72(a)', 'Misdemeanor Larceny', 'Class 1 Misdemeanor', NULL, '120 days imprisonment', '$1,000', '{"Defendant took and carried away personal property of another","Without consent and with intent to permanently deprive","Property value was under $1,000"}', NULL, '{"Prior larceny convictions: potential elevation to felony for repeat offenders under § 14-72(b)(3)"}', 'Third conviction for misdemeanor larceny is a Class I felony under § 14-72(b)(3).'),
  ('shoplifting', 'NC', 'N.C.G.S. § 14-72.1', 'Concealment of Merchandise', 'Class 3 Misdemeanor (1st offense); Class 2 Misdemeanor (2nd offense); Class 1 Misdemeanor (3rd offense); Class I Felony (4th+ or value over $2,000)', NULL, '24 months (Class I felony for 4th+ offense)', '$200 (Class 3); $1,000 (Class 1)', '{"Defendant concealed merchandise on the premises of a retail merchant","With intent to take possession of the merchandise without paying the merchant''s stated price","Merchandise was not yet purchased"}', NULL, '{"4th or subsequent offense: Class I felony","Value over $2,000: Class I felony regardless of prior record","Organized retail theft: Class H felony under § 14-72.12"}', 'Escalating classification for repeat offenders. Merchant detention privilege under § 14-72.1(c).'),
  ('burglary', 'NC', 'N.C.G.S. § 14-51', 'First Degree Burglary', 'Class D Felony', NULL, '204 months', NULL, '{"Defendant broke and entered a dwelling house or sleeping apartment","Dwelling was actually occupied at the time","In the nighttime","With intent to commit a felony or larceny therein"}', NULL, '{"Person present and in danger: enhanced sentence","Armed during burglary: additional weapons charges"}', '1st degree burglary (Class D) requires occupied dwelling and nighttime. 2nd degree (Class G) under § 14-51 covers daytime or unoccupied dwelling.'),
  ('residential-burglary', 'NC', 'N.C.G.S. § 14-51', 'Burglary — Residential', 'Class D Felony (1st degree, occupied nighttime); Class G Felony (2nd degree)', NULL, '204 months (Class D); 47 months (Class G)', NULL, '{"Defendant broke and entered a dwelling house","With intent to commit a felony or larceny therein","1st degree: dwelling occupied and crime committed in nighttime"}', NULL, '{"Victim present: significant sentencing factor","Prior burglary: enhanced sentence"}', 'North Carolina common law requirements for breaking and entering apply. Uninvited entry through open door may still constitute breaking.'),
  ('commercial-burglary', 'NC', 'N.C.G.S. § 14-54', 'Breaking or Entering a Building', 'Class H Felony (felonious intent); Class 1 Misdemeanor (without felonious intent)', NULL, '39 months (Class H felony); 120 days (Class 1 misdemeanor)', NULL, '{"Defendant broke or entered a building","With intent to commit any felony or larceny therein"}', NULL, '{"Person present: sentencing enhancement","Weapon possessed: additional charges"}', 'Broader than common law burglary — covers non-dwelling structures, daytime, and does not require both breaking and entering.'),
  ('motor-vehicle-theft', 'NC', 'N.C.G.S. § 20-106', 'Receiving or Transferring Stolen Vehicles', 'Class I Felony', NULL, '24 months', NULL, '{"Defendant received, transferred, possessed, concealed, or was found operating a motor vehicle","Knowing the motor vehicle was stolen","Without consent of the owner"}', NULL, '{"Carjacking: robbery or armed robbery charges","Vehicle used in commission of crime: additional charges"}', 'Vehicle larceny also prosecuted under general larceny statute § 14-72. Motor vehicle theft is Class I felony.'),
  ('receiving-stolen-property', 'NC', 'N.C.G.S. § 14-71', 'Receiving Stolen Goods', 'Class I Felony (value $1,000+); Class 1 Misdemeanor (value under $1,000)', NULL, '24 months (Class I); 120 days (Class 1)', NULL, '{"Defendant received or possessed stolen goods","Defendant knew or had reasonable grounds to believe the goods were stolen","Intent to dishonestly retain the goods"}', NULL, '{"Motor vehicle: enhanced charges under § 20-106","Value over $100,000: Class C felony"}', 'Same felony threshold as larceny: $1,000. Knowledge element — reasonable grounds to believe is an objective standard.'),
  ('vandalism', 'NC', 'N.C.G.S. § 14-127', 'Willful and Wanton Injury to Real Property', 'Class 1 Misdemeanor (value under $200); Class I Felony (value $200+) under § 14-127', NULL, '120 days (Class 1 misdemeanor); 24 months (Class I felony)', NULL, '{"Defendant willfully and wantonly damaged or destroyed real property of another","Without authority or justification","Act was intentional"}', NULL, '{"Religious or educational institution: enhanced under § 14-49.1","Hate crime motivation: enhanced under § 14-3(c)"}', 'Also see § 14-159.4 (injury to personal property). Damage to railroad property under § 14-138. Hate crime enhancement doubles maximum under § 14-3(c).'),
  ('trespassing', 'NC', 'N.C.G.S. § 14-159.12; § 14-159.13', 'First and Second Degree Trespass', 'Class 2 Misdemeanor (1st degree); Class 3 Misdemeanor (2nd degree)', NULL, '60 days (Class 2); 20 days (Class 3)', '$1,000', '{"Defendant entered or remained on the premises of another person","Without authorization after being notified not to enter or remain","OR entered an enclosed or posted property (1st degree: with intent to damage property or after notice; 2nd degree: without notice but enclosed/posted)"}', NULL, '{"Critical infrastructure trespass: Class I felony under § 14-159.12(b)","Operating chemical facility: enhanced felony"}', '1st degree (Class 2) requires notice or intent to damage. 2nd degree (Class 3) covers trespass on enclosed/posted property without notice.'),
  ('criminal-mischief', 'NC', 'N.C.G.S. § 14-127; § 14-159.4', 'Willful Injury to Real or Personal Property', 'Class 1 Misdemeanor (under $200 real property); Class I Felony (over $200); Class 2 Misdemeanor (personal property under $200)', NULL, '24 months (Class I felony)', NULL, '{"Defendant willfully and wantonly injured, damaged, or destroyed property of another"}', NULL, '{}', 'NC uses ''willful injury to property'' rather than ''criminal mischief.'' Classification depends on value and type of property.'),
  ('domestic-violence', 'NC', 'N.C.G.S. § 50B-1; § 14-33(c)(2)', 'Domestic Violence — Assault on a Female / Domestic Violence Assault', 'Class A1 Misdemeanor; Felony if serious injury', NULL, '150 days (Class A1); up to 88 months (Class E felony with serious injury)', NULL, '{"Defendant committed an assault on a current or former intimate partner, household member, or person with whom they have a child","OR defendant committed assault on a female if defendant is male (§ 14-33(c)(2))","Act was intentional"}', NULL, '{"Prior conviction of assault on female or crime of domestic violence: Class A1 misdemeanor at minimum","Strangulation: Class H felony under § 14-32.4(b)","Serious injury: escalated felony class"}', 'Domestic violence covered under Chapter 50B civil protective orders and criminal assault statutes. Strangulation is separately Class H felony.'),
  ('domestic-battery', 'NC', 'N.C.G.S. § 14-33(c)(2); § 14-32.4', 'Assault on a Female / Domestic Battery', 'Class A1 Misdemeanor', NULL, '150 days imprisonment', NULL, '{"Defendant is male","Defendant assaulted a female","Acts were intentional"}', NULL, '{"Serious bodily injury: Class E felony under § 14-32.4","Strangulation: Class H felony under § 14-32.4(b)"}', 'Assault on a female under § 14-33(c)(2) requires defendant to be male and victim female. Gender-neutral serious assault under § 14-32.4.'),
  ('child-endangerment', 'NC', 'N.C.G.S. § 14-318.2; § 14-318.4', 'Child Abuse / Contributing to the Delinquency of a Minor', 'Class 1 Misdemeanor (contributing); Class A1 Misdemeanor (child abuse by parent); Class C or D Felony (serious injury or sexual abuse)', NULL, '231 months (Class C); 150 days (Class A1)', NULL, '{"Defendant is a parent, legal guardian, or caretaker of a juvenile under 16","Defendant inflicted or allowed infliction of physical injury upon the juvenile","OR defendant committed, permitted, or encouraged acts constituting child abuse"}', NULL, '{"Serious physical injury: Class D felony","Sexual abuse of child under 13: Class C felony with mandatory registration"}', 'Child abuse with serious injury is Class D felony under § 14-318.4(a3). Sexual abuse is Class C felony.'),
  ('child-abuse', 'NC', 'N.C.G.S. § 14-318.4', 'Felony Child Abuse', 'Class D Felony (serious physical injury); Class C Felony (sexual abuse, child under 13)', NULL, '204 months (Class D); 231 months (Class C)', NULL, '{"Defendant is a parent, legal guardian, or caretaker of a child under 16","Defendant inflicted or allowed infliction of serious physical injury upon the child","OR committed sexual abuse upon a child under 13"}', NULL, '{"Pattern of abuse: aggravating factor","Death resulting: murder charges"}', 'Felony child abuse under § 14-318.4 for parents and caretakers. Strangers may be charged under assault statutes.'),
  ('violation-protective-order', 'NC', 'N.C.G.S. § 50B-4.1', 'Violation of Domestic Violence Protective Order', 'Class A1 Misdemeanor (1st offense); Class H Felony (2nd+ violation or violation with assault)', NULL, '150 days (Class A1); 39 months (Class H felony)', NULL, '{"A valid domestic violence protective order under Chapter 50B had been issued","Defendant had knowledge of the order","Defendant violated the specific terms of the order"}', NULL, '{"2nd or subsequent violation: Class H felony","Assault during violation: Class H felony on 1st offense"}', 'Violations involving assault are Class H felony on first offense. Federal firearm prohibition applies under 18 U.S.C. § 922(g)(8).'),
  ('stalking', 'NC', 'N.C.G.S. § 14-277.3A', 'Stalking', 'Class A1 Misdemeanor (1st offense); Class F Felony (2nd+ offense or violation of protective order)', NULL, '150 days (Class A1); 41 months (Class F felony)', NULL, '{"Defendant followed, was in the presence of, or contacted another person on at least two occasions","Without consent","Causing that person to reasonably fear for their safety, a family member''s safety, or to suffer substantial emotional distress","Defendant knew or should have known the conduct would cause fear or distress"}', NULL, '{"2nd conviction or violation of protective order: Class F felony","Use of electronic means: cyberstalking enhancement"}', 'Cyberstalking under § 14-196.3 separately covers electronic harassment. Two separate incidents required.'),
  ('harassment', 'NC', 'N.C.G.S. § 14-196', 'Harassing Phone Calls / Electronic Communications', 'Class 2 Misdemeanor', NULL, '60 days imprisonment', '$1,000', '{"Defendant made telephone calls or electronic communications to another person","With intent to harass, annoy, or embarrass","OR used repeated calls with no purpose of communication"}', NULL, '{"Cyberstalking: elevated charges under § 14-196.3","Threatening communications: terroristic threat charges"}', 'Cyberstalking under § 14-196.3 covers electronic harassment intended to cause fear or emotional distress.'),
  ('elder-abuse', 'NC', 'N.C.G.S. § 14-32.3', 'Domestic Abuse, Neglect, and Exploitation of Disabled or Elder Adult', 'Class H Felony (abuse/neglect); Class I Felony (exploitation)', NULL, '39 months (Class H); 24 months (Class I)', NULL, '{"Defendant was a caregiver or person responsible for a disabled or elder adult (65+)","Defendant abused, neglected, or exploited the person in their care","OR financially exploited the elder or disabled adult"}', NULL, '{"Serious physical injury: Class G or higher felony","Death resulting: murder or manslaughter charges"}', 'Financial exploitation separately addressed under § 14-32.3(b). Adult Protective Services mandatory reporting required.'),
  ('weapons-possession', 'NC', 'N.C.G.S. § 14-269', 'Carrying Concealed Weapon', 'Class 2 Misdemeanor (1st offense); Class H Felony (2nd+ offense or concealed handgun without permit)', NULL, '60 days (Class 2); 39 months (Class H felony)', '$1,000', '{"Defendant carried a concealed deadly weapon off their own premises","Without a valid concealed carry permit","With knowledge of possession"}', NULL, '{"2nd offense: Class H felony","Carrying on school premises: Class I felony under § 14-269.2","Armed during commission of felony: additional charges"}', 'NC has shall-issue CHP. Carrying without permit is Class 2 misdemeanor first offense. School property carrying is Class I felony.'),
  ('felon-in-possession', 'NC', 'N.C.G.S. § 14-415.1', 'Possession of Firearm by Felon', 'Class G Felony', NULL, '47 months', NULL, '{"Defendant was convicted of a felony","Defendant purchased, owned, possessed, or had in custody, care, or control a firearm","With knowledge of possession"}', NULL, '{"Use of firearm in commission of a crime: additional charges","Federal concurrent: 18 U.S.C. § 922(g)(1)","Prior violent felony: enhanced sentence"}', 'Class G felony. Rights restoration possible through pardon or expungement of underlying felony.'),
  ('concealed-carry-violation', 'NC', 'N.C.G.S. § 14-269(a1)', 'Carrying Concealed Handgun Without Valid Permit', 'Class 2 Misdemeanor (1st offense); Class H Felony (2nd+ offense)', NULL, '60 days (Class 2); 39 months (Class H)', '$1,000', '{"Defendant carried a concealed handgun off their own premises","Without a valid concealed handgun permit"}', NULL, '{"2nd offense: elevated to Class H felony"}', 'Handgun carry without permit escalates to Class H felony on 2nd offense. CHP available to qualifying residents.'),
  ('illegal-discharge', 'NC', 'N.C.G.S. § 14-34.1', 'Discharging a Barreled Weapon Into Occupied Property', 'Class D Felony (into occupied property); Class E Felony (into property not reasonably believed occupied)', NULL, '204 months (Class D); 88 months (Class E)', NULL, '{"Defendant willfully or wantonly discharged a firearm, barreled weapon, or other deadly weapon","Into any building, structure, or vehicle","When the property was occupied or defendant had reasonable cause to believe it was occupied"}', NULL, '{"Person injured or killed: additional charges","School or government building: enhanced sentence"}', 'Class D felony for discharge into occupied property. Reckless discharge otherwise charged under assault statutes.'),
  ('possession-prohibited-weapon', 'NC', 'N.C.G.S. § 14-288.8; § 14-409', 'Possession of Machine Gun or Sawed-Off Shotgun', 'Class I Felony', NULL, '24 months', NULL, '{"Defendant possessed, sold, or transferred a machine gun, sawed-off shotgun, or sawed-off rifle","Without NFA registration","With knowledge of the nature of the weapon"}', NULL, '{"Use in commission of a crime: additional charges","Federal NFA violation: concurrent federal charges"}', 'NFA-registered weapons are legal with proper registration. State crime for unregistered NFA items.'),
  ('identity-theft', 'NC', 'N.C.G.S. § 14-113.20', 'Identity Theft', 'Class G Felony', NULL, '47 months', NULL, '{"Defendant knowingly obtained, possessed, or used identifying information of another person","Without that person''s consent","With intent to fraudulently represent themselves as that person","For any unlawful purpose"}', NULL, '{"More than 3 victims: Class F felony","Elder victim (65+): enhanced penalty","Use of internet or electronic means: additional charges"}', 'Multiple victims enhancement under § 14-113.20A. Aggravated identity theft (3+ victims or financial institution) is Class F felony.'),
  ('embezzlement', 'NC', 'N.C.G.S. § 14-90', 'Embezzlement', 'Class H Felony (value under $100,000); Class C Felony (value $100,000+)', NULL, '39 months (Class H); 231 months (Class C)', NULL, '{"Defendant was entrusted with or had access to property belonging to another","Defendant fraudulently appropriated the property","To defendant''s own use or the use of another person not entitled to the property","With intent to defraud the owner"}', NULL, '{"Public official embezzlement: enhanced penalties","Value $100,000+: Class C felony"}', 'Embezzlement by public official may be a Class F felony under § 14-92. Financial institution embezzlement carries enhanced penalties.'),
  ('forgery', 'NC', 'N.C.G.S. § 14-119', 'Forgery of Instruments', 'Class I Felony', NULL, '24 months', NULL, '{"Defendant forged or counterfeited an instrument","With intent to defraud","Instrument could affect legal rights (checks, deeds, contracts, etc.)"}', NULL, '{"Public official''s signature forged: Class H felony","Multiple forgeries: charges may stack"}', 'Uttering forged instrument separately charged under § 14-120. Both can be charged together.'),
  ('bad-checks', 'NC', 'N.C.G.S. § 14-107', 'Worthless Checks', 'Class 3 Misdemeanor (under $2,000); Class 1 Misdemeanor ($2,000-$9,999); Class I Felony ($10,000+)', NULL, '20 days (Class 3); 120 days (Class 1); 24 months (Class I felony)', '$1,000', '{"Defendant drew, made, or delivered a check, draft, or order","Defendant knew at time of delivery that funds were insufficient or no account existed","Payee was defrauded"}', NULL, '{"Amount aggregated over multiple bad checks: may reach felony threshold"}', '10-day grace period after notice allows payment and avoids prosecution. Three-tier classification based on amount.'),
  ('fraud-general', 'NC', 'N.C.G.S. § 14-100', 'Obtaining Property by False Pretenses', 'Class H Felony (value under $100,000); Class C Felony (value $100,000+)', NULL, '39 months (Class H); 231 months (Class C)', NULL, '{"Defendant knowingly and designedly, by false pretense, obtained or attempted to obtain","From another person, property, money, valuable consideration, or other thing","With intent to cheat and defraud","The false pretense was the operating cause of the transfer"}', NULL, '{"Elder victim (65+): enhanced penalty","Internet or wire used: additional charges","Value $100,000+: Class C felony"}', 'Common fraud vehicle in NC. Represents the historical false pretenses offense.'),
  ('wire-fraud', 'NC', 'N.C.G.S. § 14-113.20; Federal: 18 U.S.C. § 1343', 'Identity Theft / Wire Fraud', 'Class G Felony (state); Federal felony', NULL, '47 months (state); 20 years (federal)', NULL, '{"Defendant used wire, radio, or television communications in interstate or foreign commerce","To execute a scheme to defraud","OR to obtain money or property by means of false pretenses or representations"}', NULL, '{"Financial institution victim: enhanced federal penalty","Large monetary loss: enhanced sentence"}', 'Wire fraud primarily prosecuted federally. NC state fraud charges typically used for local transactions.'),
  ('insurance-fraud', 'NC', 'N.C.G.S. § 58-2-161', 'Insurance Fraud', 'Class H Felony', NULL, '39 months', NULL, '{"Defendant knowingly presented false, incomplete, or misleading information to an insurer","In connection with an insurance claim, application, or transaction","With intent to defraud the insurer"}', NULL, '{"Healthcare insurance fraud: enhanced penalties under specific healthcare fraud statutes","Organized fraud ring: conspiracy charges"}', 'NC Department of Insurance investigates insurance fraud. Workers'' comp fraud separately addressed.'),
  ('money-laundering', 'NC', 'N.C.G.S. § 14-294; Federal: 18 U.S.C. § 1956', 'Money Laundering', 'Class H Felony (state)', NULL, '39 months (state); 20 years (federal)', NULL, '{"Defendant conducted a financial transaction involving proceeds of unlawful activity","With knowledge that the property was the proceeds of unlawful activity","With intent to promote or conceal the unlawful activity"}', NULL, '{"Federal parallel prosecution: 18 U.S.C. § 1956","Drug trafficking proceeds: enhanced"}', 'Most money laundering cases prosecuted federally. NC Class H felony for state prosecutions.'),
  ('disorderly-conduct', 'NC', 'N.C.G.S. § 14-132; § 14-288.4', 'Disorderly Conduct', 'Class 2 Misdemeanor', NULL, '60 days imprisonment', '$1,000', '{"Defendant acted in such a manner as to be reasonably likely to provoke a violent response from another person","OR disturbed the peace by making a loud and raucous noise","OR disrupted the orderly conduct of a lawful meeting, gathering, or procession"}', NULL, '{}', 'Disorderly conduct in a public place under § 14-132 (Class 2). Emergency management-related disorderly conduct under § 14-288.4.'),
  ('resisting-arrest', 'NC', 'N.C.G.S. § 14-223', 'Resisting, Delaying, or Obstructing a Public Officer', 'Class 2 Misdemeanor', NULL, '60 days imprisonment', '$1,000', '{"Defendant willfully and unlawfully resisted, delayed, or obstructed a public officer","Officer was discharging or attempting to discharge a duty of the officer''s office","Defendant knew or had reasonable grounds to know the person was a public officer"}', NULL, '{"Assault on officer during resistance: Class F or higher felony","Injury to officer: Class E felony"}', 'Misdemeanor for resistance alone. Assaulting an officer is separate and more serious charge under § 14-34.2.'),
  ('obstruction-justice', 'NC', 'N.C.G.S. § 14-221.1; § 14-223', 'Obstruction of Justice', 'Class H Felony (obstruction of justice); Class 2 Misdemeanor (obstructing officer)', NULL, '39 months (Class H felony)', NULL, '{"Defendant intentionally obstructed, impeded, or hindered an official proceeding or criminal investigation","Act was knowing and intentional","Act was not authorized or justified"}', NULL, '{"Evidence tampering: additional charges","Witness intimidation or retaliation: Class F or G felony under § 14-226"}', 'Obstruction of justice is a common law offense in NC, codified as Class H felony. Witness intimidation separately classified.'),
  ('contempt-of-court', 'NC', 'N.C.G.S. § 5A-11; § 5A-12', 'Criminal Contempt of Court', 'Class 1 Misdemeanor (simple criminal contempt); more severe depending on conduct', NULL, '30 days imprisonment per occurrence (simple); 120 days (Class 1 misdemeanor)', '$500', '{"Defendant willfully disobeyed a lawful court order","OR engaged in conduct that disrupted, impaired, or obstructed the administration of justice","Conduct was directly or indirectly contrary to a specific order"}', NULL, '{"Repeated contempt: consecutive penalties","Domestic violence order violation: Class A1 misdemeanor or Class H felony"}', 'Summary contempt may be imposed by judge without separate hearing for conduct in the courtroom.'),
  ('public-intoxication', 'NC', 'N.C.G.S. § 14-443', 'Intoxicated and Disruptive in Public', 'Class 3 Misdemeanor', NULL, '20 days imprisonment', '$200', '{"Defendant appeared in a public place","In an intoxicated condition","And was disruptive as indicated by boisterous and noisy conduct, threatening or fighting, or creating a hazard"}', NULL, '{}', 'Simple intoxication in public is not a crime in NC — disruptive element required. Protective custody available as alternative.'),
  ('loitering', 'NC', 'N.C.G.S. § 14-132(a)(8)', 'Loitering in Public', 'Class 2 Misdemeanor', NULL, '60 days imprisonment', '$1,000', '{"Defendant remained in a public place","For the purpose of engaging in unlawful activity or soliciting","After being asked to move along by an officer"}', NULL, '{}', 'NC loitering statutes must be applied carefully to avoid First Amendment concerns. Specific purpose element required.'),
  ('failure-to-appear', 'NC', 'N.C.G.S. § 15A-543', 'Failure to Appear', 'Class I Felony (felony underlying charge); Class 2 Misdemeanor (misdemeanor underlying charge)', NULL, '24 months (Class I felony); 60 days (Class 2 misdemeanor)', NULL, '{"Defendant was released from custody pursuant to a written promise to appear","Defendant had notice of the appearance date","Defendant failed to appear as required"}', NULL, '{"Underlying charge is violent felony: enhanced sentence","Bond forfeiture: civil consequences for surety"}', 'Order for arrest issued upon FTA. Written promise to appear required for criminal FTA charge.'),
  ('false-report', 'NC', 'N.C.G.S. § 14-225', 'Filing False Police Report', 'Class 2 Misdemeanor', NULL, '60 days imprisonment', '$1,000', '{"Defendant made a statement or report to a law enforcement officer","Defendant knew the statement was false","Statement was made in connection with a criminal investigation"}', NULL, '{"Swatting: Class H felony or Class F felony if injury results","False report causing death: enhanced charges"}', 'Separate from perjury or false swearing. Swatting addressed under § 14-225.1 as Class H felony, Class F if injury results.'),
  ('criminal-threat', 'NC', 'N.C.G.S. § 14-277.1', 'Communicating Threats', 'Class 1 Misdemeanor', NULL, '120 days imprisonment', '$1,000', '{"Defendant threatened to physically injure another person or their family members, household members, or property","The threat was communicated to that person","Defendant had the ability to carry out the threat","Recipient believed the defendant would carry out the threat"}', NULL, '{"Threat related to judicial proceedings: obstruction of justice","Bomb threat or weapon of mass destruction: Class H felony under § 14-277.1A"}', 'Bomb threats or threats involving nuclear, biological, chemical, or radiological agents: Class H or Class F felony under § 14-277.1A.'),
  ('probation-violation', 'NC', 'N.C.G.S. § 15A-1344', 'Probation Revocation', 'Depends on original underlying offense', NULL, 'Active sentence up to the original maximum', NULL, '{"Defendant was on probation","Defendant violated a condition of probation","Violation was willful or without lawful excuse"}', NULL, '{"New criminal offense: revocation plus new charges","Absconding: violation of condition warranting revocation"}', 'NC JRA (2011) limits technical revocations to 90-day jail terms on first two technical violations. Active sentence only on third violation or new offense.'),
  ('probation-violation-technical', 'NC', 'N.C.G.S. § 15A-1344(d2)', 'Technical Probation Violation', 'Administrative — limited confinement', NULL, '90 days confinement (1st technical); 90 days (2nd); active sentence (3rd)', NULL, '{"Defendant was on probation","Defendant violated a non-criminal technical condition (failure to report, failure to pay fees, positive drug test)"}', NULL, '{}', 'NC JRA 2011 limits technical revocations: 90 days for 1st and 2nd technical violations; active sentence only on 3rd or for absconding/new offense.'),
  ('probation-violation-substantive', 'NC', 'N.C.G.S. § 15A-1344', 'Substantive Probation Violation — New Criminal Offense', 'Probation revocation plus new criminal charges', NULL, 'Active sentence balance + new sentence', NULL, '{"Defendant was on probation","Defendant committed a new criminal offense while on probation","New offense constitutes a violation of probation conditions"}', NULL, '{}', 'New offense on probation triggers full revocation hearing. Court may impose active sentence up to original maximum.'),
  ('parole-violation', 'NC', 'N.C.G.S. § 15A-1371', 'Post-Release Supervision Violation / Parole Revocation', 'Administrative — return to prison', NULL, 'Return to custody; re-incarceration for balance of sentence', NULL, '{"Defendant was on post-release supervision or parole","Defendant violated conditions of supervision","Post-Release Supervision and Parole Commission determined violation warranted revocation"}', NULL, '{"New felony conviction while on supervision: mandatory revocation"}', 'NC Post-Release Supervision Commission handles revocations. Structured sentencing affects parole eligibility.'),
  ('conspiracy', 'NC', 'N.C.G.S. § 14-2.4', 'Criminal Conspiracy', 'One class below target offense felony; Class 1 Misdemeanor (if target is misdemeanor)', NULL, 'One class below the completed target offense', NULL, '{"Two or more persons agreed to commit an offense","Defendant was a party to the agreement","Each party had the intent to carry out the agreement","An overt act in furtherance not required in NC"}', NULL, '{"Drug trafficking conspiracy: same mandatory minimums as completed trafficking under § 90-95(h)","RICO-type conduct: potential enterprise liability"}', 'NC conspiracy is one class below the target offense under § 14-2.4. No overt act required. Drug trafficking conspiracy treated same as completed trafficking.'),
  ('rape', 'NC', 'N.C.G.S. § 14-27.21; § 14-27.22', 'First Degree Rape / Second Degree Rape', 'Class B1 Felony (1st degree); Class C Felony (2nd degree)', NULL, 'Class B1: 484 months+; Class C: 231 months', NULL, '{"Defendant engaged in vaginal intercourse with a victim","By force and against the will of the victim (2nd degree)","OR victim was under 13 and defendant is 12+ and at least 4 years older (1st degree)","OR defendant used or displayed a dangerous weapon, or aided by another person, or inflicted serious injury (1st degree)"}', NULL, '{"Victim under 13: mandatory sex offender registration for life","Prior sex offense: aggravated sentence"}', 'NC overhauled sexual assault statutes effective December 1, 2023. New statutes use ''rape'' for vaginal intercourse; sexual assault for other acts.'),
  ('sexual-assault', 'NC', 'N.C.G.S. § 14-27.26; § 14-27.27', 'First Degree Sexual Assault / Second Degree Sexual Assault', 'Class B1 Felony (1st degree); Class C Felony (2nd degree)', NULL, 'Class B1: 484 months+; Class C: 231 months', NULL, '{"Defendant engaged in sexual act with another person","By force and against the will of the victim (2nd degree)","OR victim was under 13 and defendant is 12+ and at least 4 years older (1st degree)","Sexual act means oral or anal sex, or penetration by object"}', NULL, '{"Use of dangerous weapon: 1st degree classification","Multiple attackers: 1st degree","Victim under 13: mandatory lifetime registration"}', '2023 NC statutory revision replaced ''sexual offense'' with ''sexual assault'' for clarity. Covers all sexual acts other than vaginal intercourse.'),
  ('indecent-exposure', 'NC', 'N.C.G.S. § 14-190.9', 'Indecent Exposure', 'Class 2 Misdemeanor (1st offense); Class H Felony (in presence of minor under 16)', NULL, '60 days (Class 2); 39 months (Class H felony)', '$1,000', '{"Defendant willfully exposed the private parts of their person","In any public place in the presence of any person other than the defendant","In a lewd and lascivious manner"}', NULL, '{"Exposure in presence of minor under 16: Class H felony","On school premises: enhanced charges"}', 'Exposure in presence of minor under 16 is automatically Class H felony with sex offender registration possible.'),
  ('statutory-rape', 'NC', 'N.C.G.S. § 14-27.23; § 14-27.24; § 14-27.25', 'Statutory Rape', 'Class B1 Felony (victim under 13, defendant 12+, 4 yrs older); Class C Felony (defendant 22+, victim 15 or younger); Class C Felony (defendant 18+, victim 13-15)', NULL, 'Class B1: 484 months+; Class C: 231 months', NULL, '{"Defendant engaged in vaginal intercourse with a person of a specific age","Defendant was the specified number of years older than the victim","Consent is not a defense"}', NULL, '{}', 'NC has tiered statutory rape: § 14-27.23 (Class B1, victim under 13); § 14-27.24 (Class C, victim 13-15, defendant 18+); § 14-27.25 (defendant 22+). Close-in-age exemption: 4-6 years depending on section.'),
  ('child-exploitation', 'NC', 'N.C.G.S. § 14-190.13; § 14-190.17', 'Sexual Exploitation of a Minor', 'Class C Felony (1st degree — production); Class E Felony (2nd degree — distribution/possession for distribution); Class H Felony (3rd degree — possession)', NULL, '231 months (Class C); 88 months (Class E); 39 months (Class H)', NULL, '{"Defendant used a minor to engage in sexual activity for a visual depiction","OR distributed, transported, exhibited, received, sold, purchased, or possessed visual depictions of minors in sexual activity","Minor was under 18"}', NULL, '{"Production: Class C felony","Distribution for profit: enhanced","Federal concurrent: 18 U.S.C. § 2252"}', 'Three-tier classification: production (Class C), distribution (Class E), possession (Class H) under § 14-190.13 et seq.'),
  ('failure-to-register', 'NC', 'N.C.G.S. § 14-208.11', 'Failure to Register as a Sex Offender', 'Class F Felony', NULL, '41 months', NULL, '{"Defendant was required to register as a sex offender under N.C.G.S. Chapter 14 Article 27A","Defendant failed to register, update registration, or comply with verification requirements","Defendant had actual knowledge of the registration requirement"}', NULL, '{"Prior registration violation: enhanced sentence","Absconding from jurisdiction: additional charges"}', 'Sex offender registration under N.C.G.S. Chapter 14, Article 27A. Lifetime registration for certain offenses.'),
  ('solicitation-prostitution', 'NC', 'N.C.G.S. § 14-204', 'Prostitution and Related Offenses', 'Class 1 Misdemeanor (prostitution/solicitation); Class G Felony (promoting/facilitating)', NULL, '120 days (Class 1); 47 months (Class G)', NULL, '{"Defendant engaged in sexual activity for hire or solicited another person to engage in sexual activity for hire","Exchange of consideration was part of the transaction"}', NULL, '{"Minor victim: sex trafficking charges under § 14-43.11","Promoting or facilitating: Class G felony","Trafficking for sexual exploitation: Class B2 to E felony under § 14-43.11"}', 'Human trafficking for sexual exploitation under § 14-43.11 is separate and carries Class B2-E felony charges.'),
  ('sex-offense-digital', 'NC', 'N.C.G.S. § 14-27.26; § 14-190.15', 'Sexual Exploitation Using Electronic Means', 'Class H Felony to Class B1 Felony depending on nature', NULL, 'Class B1: 484 months; Class H: 39 months', NULL, '{"Defendant engaged in or facilitated a sexual act or exploitation through electronic or digital means","OR used the internet to solicit or entice a minor to engage in sexual activity"}', NULL, '{"Solicitation of minor: Class H felony under § 14-202.3"}', 'Solicitation of a child by computer under § 14-202.3 is Class H or Class G felony depending on minor''s age.'),
  ('sexual-battery', 'NC', 'N.C.G.S. § 14-27.33', 'Sexual Battery', 'Class A1 Misdemeanor', NULL, '150 days imprisonment', NULL, '{"Defendant engaged in sexual contact with another person","By force and against the will of the other person","OR victim was mentally disabled or physically helpless"}', NULL, '{"Repeat offense: potential felony escalation","Victim under 13: more serious felony charge"}', 'Sexual battery under § 14-27.33 is the lowest-level sexual offense in NC. Class A1 misdemeanor.'),
  ('sex-offense-contact', 'NC', 'N.C.G.S. § 14-27.31; § 14-27.32', 'First and Second Degree Sexual Exploitation / Statutory Sexual Offense', 'Class B1 Felony (1st degree); Class C Felony (2nd degree)', NULL, 'Class B1: 484 months+; Class C: 231 months', NULL, '{"Defendant engaged in a sexual act with a person","By force and against the will of the person (2nd degree)","OR victim was under 13 and defendant was 12+ and at least 4 years older (1st degree)"}', NULL, '{}', 'NC 2023 reform renamed these offenses. Covers sexual acts (non-vaginal-intercourse) paralleling rape statutes.'),
  ('self-defense', 'NC', 'N.C.G.S. § 14-51.3; § 14-51.2', 'Defense of Self / Castle Doctrine', 'Affirmative defense — not an offense', NULL, NULL, NULL, '{"Defendant used force against another person","Defendant reasonably believed the force was necessary to prevent imminent death or serious bodily harm","Defendant was not the aggressor","Under Castle Doctrine (§ 14-51.2): presumption of reasonable fear when intruder enters home, motor vehicle, or workplace unlawfully"}', NULL, '{}', 'NC has a Castle Doctrine (§ 14-51.2) with a rebuttable presumption of reasonable fear for home intrusions. No general Stand Your Ground statute (duty to retreat eliminated inside home). Outside home, duty to retreat still applies unless Castle Doctrine triggers.'),
  ('other', 'NC', 'Various N.C.G.S. provisions', 'Miscellaneous North Carolina Criminal Offenses', 'Varies', NULL, 'Varies by specific offense and class', NULL, '{"Elements specific to each offense as defined under the North Carolina General Statutes"}', NULL, '{}', 'NC uses structured sentencing under the Fair Sentencing Act. Offense class and prior record level determine the sentencing range. Consult the specific N.C.G.S. section for elements, penalties, and prior record calculations.')
INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('dui-dwi', 'PA', '75 Pa.C.S. § 3802', 'Driving Under Influence of Alcohol or Controlled Substance', 'Summary (1st/2nd, Tier 1); Misdemeanor 1 (high BAC or 3rd offense); Felony 3 (4th+)', NULL, '90 days (summary); 2 years (M1); 7 years (F3)', '$300 (summary); $5,000 (M1); $15,000 (F3)', '{"Operated a vehicle on a highway or trafficway in this Commonwealth","While the individual''s alcohol concentration was at or above the legal limit","OR while under the influence of alcohol or controlled substance that impaired ability to safely drive"}', '72 hours (1st offense, General Impairment); 5 days (1st offense, High BAC); 10 days (1st offense, Highest BAC or drugs)', '{"Three-tier BAC system: General (0.08-0.099%), High (0.10-0.159%), Highest (0.16%+) with escalating penalties","Felony 3 for 4th+ DUI offense within 10 years","Mandatory ignition interlock for 1 year on all convictions","ARD (Accelerated Rehabilitative Disposition) available for first offenders"}', 'Pennsylvania uses a three-tier BAC system. Refusal to submit to blood alcohol testing is treated as Highest BAC tier. ARD program is unique to PA and allows first offenders to avoid conviction.'),
  ('dui-first-offense', 'PA', '75 Pa.C.S. § 3802', 'DUI — First Offense', 'Summary (General Impairment Tier 1); Misdemeanor 1 (High or Highest BAC)', NULL, '90 days (summary); 6 months (M1 High); 6 months (M1 Highest)', '$300 (summary); $2,500 (High); $5,000 (Highest)', '{"First DUI offense within 10-year look-back period","Operated vehicle while impaired"}', '72 hours (General); 48 hours (High); 72 hours (Highest)', '{"ARD program available for eligible first offenders: charges dismissed upon completion","License suspension 12 months for Highest BAC or drug DUI first offense"}', 'Pennsylvania''s 10-year look-back period applies for repeat offense enhancements. General Impairment (0.08-0.099%) first offense is a summary offense, not a misdemeanor.'),
  ('dui-repeat-offense', 'PA', '75 Pa.C.S. § 3802', 'DUI — Repeat Offense', 'Misdemeanor 1 (2nd offense); Felony 3 (4th+ offense within 10 years)', '5 days (2nd, General); 30 days (2nd, High/Highest)', '6 months (2nd, M1); 5 years (F2 if accident causing injury); 7 years (F3 4th+)', '$2,500 (2nd); $15,000 (F3)', '{"Prior DUI conviction or ARD within 10-year look-back period","Current DUI offense proven under 75 Pa.C.S. § 3802"}', '5 days (2nd offense General); 30 days (2nd offense High BAC); 90 days (3rd offense)', '{"Felony 3: 4th+ offense within 10 years","Felony 2: DUI causing serious bodily injury on 2nd+ offense","18-month license revocation for 2nd offense"}', 'Pennsylvania uses a 10-year look-back period for DUI priors, unlike Illinois which has lifetime look-back.'),
  ('dui-drugs', 'PA', '75 Pa.C.S. § 3802(d)', 'DUI — Controlled Substance', 'Misdemeanor 1 (1st offense); Felony 3 (4th+)', '72 hours (1st offense)', '6 months (M1); 7 years (F3)', '$5,000 (M1)', '{"Operated a vehicle","While there was in the individual''s blood any amount of a Schedule I controlled substance","OR a metabolite of a Schedule I controlled substance","OR while under the influence of any drug that impaired ability to drive"}', '72 hours (1st offense)', '{"Schedule I drugs: zero-tolerance, any detectable amount triggers highest-tier penalties","Prescription drug DUI: must be impaired, not merely presence of prescribed drug"}', 'Pennsylvania drug DUI is treated at Highest BAC tier regardless of impairment level for Schedule I substances.'),
  ('reckless-driving', 'PA', '75 Pa.C.S. § 3736', 'Reckless Driving', 'Summary', NULL, '90 days', '$200', '{"Drove a vehicle on a highway or trafficway","In willful or wanton disregard for the safety of persons or property"}', NULL, '{"Misdemeanor 2 if reckless driving causes death or serious bodily injury (separate charge under 75 Pa.C.S. § 3732)"}', 'Pennsylvania reckless driving is only a summary offense. Serious injury or death during reckless driving is charged as homicide by vehicle.'),
  ('hit-and-run', 'PA', '75 Pa.C.S. § 3742', 'Accidents Involving Death or Personal Injury — Duty to Stop', 'Felony 3 (injury); Felony 2 (death)', NULL, '7 years (F3); 10 years (F2)', '$15,000', '{"Driver of vehicle involved in accident resulting in injury, death, or damage to attended vehicle","Failed to immediately stop vehicle at scene","Failed to provide name, address, and vehicle registration information","Failed to render reasonable assistance to injured persons"}', NULL, '{"Felony 2 if accident resulted in death","Mandatory license revocation","Property damage only hit and run: 75 Pa.C.S. § 3743, Misdemeanor 3"}', NULL),
  ('vehicular-homicide', 'PA', '75 Pa.C.S. § 3732', 'Homicide by Vehicle', 'Felony 3', NULL, '7 years', '$15,000', '{"Operating a vehicle in reckless disregard for the safety of persons or property","Caused the death of another person"}', NULL, '{"Aggravated Assault by Vehicle (75 Pa.C.S. § 3732.1): Felony 2 for serious bodily injury","DUI-related vehicular death charged as Homicide by Vehicle While DUI (75 Pa.C.S. § 3735): Felony 2, 3-year mandatory minimum"}', 'Pennsylvania separately titles DUI-related vehicular homicide as ''Homicide by Vehicle While DUI'' (F2) with mandatory minimum.'),
  ('vehicular-manslaughter', 'PA', '75 Pa.C.S. § 3732', 'Homicide by Vehicle', 'Felony 3', NULL, '7 years', '$15,000', '{"Operating a vehicle in reckless disregard for the safety of persons or property","Caused the death of another person"}', NULL, '{"Homicide by Vehicle While DUI (75 Pa.C.S. § 3735): Felony 2 with 3-year mandatory minimum"}', 'Pennsylvania does not use the term ''vehicular manslaughter'' — the equivalent offense is Homicide by Vehicle under 75 Pa.C.S. § 3732.'),
  ('driving-on-suspended', 'PA', '75 Pa.C.S. § 1543', 'Driving While Operating Privilege is Suspended or Revoked', 'Summary (1st); Misdemeanor 3 (subsequent or DUI-related suspension)', NULL, '90 days (summary); 1 year (M3)', '$500 (summary); $2,500 (M3)', '{"Operated a motor vehicle on a highway or trafficway","While operating privilege was suspended or revoked"}', '60-day additional suspension; 90-day imprisonment if license suspended for DUI (M3)', '{"Misdemeanor 3 if license was suspended for DUI with mandatory 90-day minimum sentence","Additional suspension period added"}', NULL),
  ('fleeing-eluding', 'PA', '75 Pa.C.S. § 3733', 'Fleeing or Attempting to Elude Police Officer', 'Misdemeanor 2 (basic); Felony 3 (aggravated)', NULL, '2 years (M2); 7 years (F3)', '$5,000', '{"Driver of a motor vehicle","Willfully failed or refused to bring vehicle to a stop","When given a visual or audible signal to stop by a uniformed police officer"}', NULL, '{"Felony 3: crosses state line, involves accident, involves injury, driver has prior conviction"}', NULL),
  ('open-container', 'PA', '75 Pa.C.S. § 3809', 'Restriction on Alcoholic Beverages', 'Summary', NULL, '90 days', '$500', '{"While operating a motor vehicle on a highway","Consumed an alcoholic beverage","OR had an open alcoholic beverage container in an accessible area of the vehicle"}', NULL, '{}', NULL),
  ('refusing-breath-test', 'PA', '75 Pa.C.S. § 1547', 'Chemical Testing to Determine Amount of Alcohol or Controlled Substance — Refusal', 'Summary (civil/administrative consequence)', NULL, 'Administrative license suspension', '$500', '{"Arrested for DUI","Refused to submit to chemical testing after being advised of consequences"}', NULL, '{"1-year license suspension for first refusal","18-month suspension for second refusal","Refusal treated as Highest BAC tier for sentencing purposes in criminal DUI case"}', 'Pennsylvania treats refusal as equivalent to Highest BAC DUI tier for purposes of grading and penalties.'),
  ('drug-possession', 'PA', '35 P.S. § 780-113(a)(16)', 'Possession of Controlled Substance', 'Misdemeanor 1', NULL, '1 year (small amount); 3 years (subsequent offense)', '$5,000', '{"Knowingly or intentionally possessed a controlled substance","Without a valid prescription or other lawful authority"}', NULL, '{"Felony 3: possession within 1,000 feet of school (35 P.S. § 780-113(a)(30))","Subsequent offenses escalate penalties","PA recently enacted 35 P.S. § 780-113.1 for possession with enhanced penalties near schools"}', 'Pennsylvania does not use the Illinois felony class structure. Drug possession is a Misdemeanor 1 regardless of substance type unless enhanced.'),
  ('drug-possession-marijuana', 'PA', '35 P.S. § 780-113(a)(31)', 'Possession of Small Amount of Marijuana', 'Misdemeanor (30g or less); Misdemeanor 1 (over 30g)', NULL, '30 days (small amount); 1 year (M1)', '$500 (small amount); $5,000 (M1)', '{"Possessed marijuana","Without lawful authority under Pennsylvania law"}', NULL, '{"Felony 3 if in drug-free school zone","Possession with intent to deliver escalates to Felony 3"}', 'Pennsylvania has not legalized recreational marijuana as of 2026. Medical marijuana is legal under the Medical Marijuana Act (Act 16 of 2016). Small amount (30g or less) is a separate lower-graded misdemeanor.'),
  ('drug-possession-cocaine', 'PA', '35 P.S. § 780-113(a)(16)', 'Possession of Cocaine', 'Misdemeanor 1', NULL, '1 year', '$5,000', '{"Knowingly or intentionally possessed cocaine","Without a valid prescription or lawful authority"}', NULL, '{"Felony 3 for possession in school zone","Trafficking amounts elevate to Felony 3 or higher under 35 P.S. § 780-113(a)(30)"}', 'Pennsylvania treats all Schedule II possession as Misdemeanor 1 regardless of weight, unlike Illinois which escalates based on grams.'),
  ('drug-possession-meth', 'PA', '35 P.S. § 780-113(a)(16)', 'Possession of Methamphetamine', 'Misdemeanor 1', NULL, '1 year', '$5,000', '{"Knowingly or intentionally possessed methamphetamine","Without a valid prescription or lawful authority"}', NULL, '{"Felony 3 for possession in school zone or with intent to deliver"}', NULL),
  ('drug-possession-opioids', 'PA', '35 P.S. § 780-113(a)(16)', 'Possession of Heroin or Opioid Controlled Substance', 'Misdemeanor 1', NULL, '1 year', '$5,000', '{"Knowingly or intentionally possessed heroin, fentanyl, or opioid controlled substance","Without a valid prescription or lawful authority"}', NULL, '{"Delivery causing death: Felony 1 under 35 P.S. § 780-113.1 (Act 57 of 2014)","Fentanyl delivery causing death: Felony 1"}', 'Pennsylvania has enacted specific legislation targeting fentanyl trafficking given the overdose crisis.'),
  ('drug-possession-prescription', 'PA', '35 P.S. § 780-113(a)(14),(16)', 'Acquisition of Controlled Substance by Fraud or Without Prescription', 'Misdemeanor 1', NULL, '1 year', '$5,000', '{"Possessed a prescription controlled substance","Without a valid prescription issued in the defendant''s name","OR obtained by fraud, misrepresentation, or deception"}', NULL, '{}', NULL),
  ('drug-trafficking', 'PA', '35 P.S. § 780-113(a)(30)', 'Manufacture, Delivery, or Possession with Intent to Deliver', 'Felony 3 (small amounts); Felony 2 (larger amounts); Felony 1 (largest amounts or school zone)', NULL, '7 years (F3); 10 years (F2); 20 years (F1)', '$15,000 (F3); $25,000 (F2); $250,000 (F1)', '{"Manufactured, delivered, or possessed with intent to deliver a controlled substance","OR created, delivered, or possessed a counterfeit controlled substance"}', NULL, '{"Felony 1: delivery within 1,000 feet of school, delivery to minor, delivery causing death","Drug trafficking in volume: Felony 1 with mandatory minimum under 18 Pa.C.S. § 7508","Mandatory minimum 2 years for heroin/cocaine over threshold amounts under § 7508"}', '18 Pa.C.S. § 7508 imposes mandatory minimum sentences based on drug type and weight, though subject to constitutional challenge post-Alleyne v. United States.'),
  ('drug-distribution', 'PA', '35 P.S. § 780-113(a)(30)', 'Delivery of Controlled Substance', 'Felony 3 (small delivery); Felony 2 or higher (larger amounts)', NULL, '7 years (F3); 10 years (F2)', '$25,000', '{"Delivered a controlled substance to another person","Without lawful authority"}', NULL, '{"Delivery to minor: Felony 1","Delivery in school zone: enhanced mandatory minimums"}', NULL),
  ('drug-manufacturing', 'PA', '35 P.S. § 780-113(a)(30)', 'Manufacture of Controlled Substance', 'Felony 3 to Felony 1 depending on substance and amount', NULL, '7 years (F3); 20 years (F1)', '$250,000 (F1)', '{"Manufactured or produced a controlled substance","Without lawful authority"}', NULL, '{"Meth lab operation: additional charges under 18 Pa.C.S. § 7508.2","Near school zone or in residence: enhanced penalties"}', NULL),
  ('drug-paraphernalia', 'PA', '35 P.S. § 780-113(a)(32)', 'Use or Possession of Drug Paraphernalia', 'Misdemeanor', NULL, '1 year', '$2,500', '{"Used, possessed with intent to use, delivered, possessed with intent to deliver, or manufactured drug paraphernalia","For purpose of planting, cultivating, growing, harvesting, manufacturing, compounding, converting, producing, processing, preparing, testing, packaging, repackaging, storing, containing, concealing, or injecting a controlled substance"}', NULL, '{"Delivery of paraphernalia to minor: misdemeanor with enhanced penalty"}', NULL),
  ('prescription-fraud', 'PA', '35 P.S. § 780-113(a)(12),(14)', 'Acquisition of Controlled Substance by Fraud', 'Misdemeanor 1', NULL, '3 years', '$5,000', '{"Obtained or attempted to obtain a controlled substance by fraud, misrepresentation, or deception","OR forged or altered a prescription"}', NULL, '{"Felony 3 for large-scale prescription fraud"}', NULL),
  ('drug-possession-with-intent', 'PA', '35 P.S. § 780-113(a)(30)', 'Possession with Intent to Deliver Controlled Substance', 'Felony 3 to Felony 1', NULL, '7 years (F3); 20 years (F1)', '$250,000', '{"Possessed a controlled substance","With intent to deliver, inferred from quantity, packaging, scales, currency, or other circumstantial evidence"}', '2 years for heroin or cocaine over threshold amounts under 18 Pa.C.S. § 7508', '{"Delivery near school zone: mandatory minimum 2 to 4 years","Delivery to minor: Felony 1"}', NULL),
  ('murder-first-degree', 'PA', '18 Pa.C.S. § 2502(a)', 'Murder of the First Degree', 'Felony 1 (Murder of the First Degree — special class)', 'Life imprisonment', 'Life imprisonment or death', '$50,000', '{"Intentionally caused the death of another person","With specific intent to kill (premeditated)"}', 'Life imprisonment', '{"Death penalty available for aggravated circumstances (killing of law enforcement, multiple victims, torture, contract murder)","Mandatory life without parole if death penalty not imposed"}', 'Pennsylvania retains the death penalty. First degree murder requires specific intent to kill (premeditation). Life without parole is mandatory if death penalty not sought or imposed.'),
  ('murder-second-degree', 'PA', '18 Pa.C.S. § 2502(b)', 'Murder of the Second Degree (Felony Murder)', 'Felony 1 (Murder — second degree)', 'Life imprisonment', 'Life imprisonment', '$50,000', '{"Committed or was an accomplice in the commission of a felony","Death of another person occurred during the commission of that felony","No specific intent to kill required"}', 'Life imprisonment', '{}', 'Pennsylvania second degree murder is limited to felony murder — killing that occurs during the commission of a felony. Subject to significant post-People v. Rosemond litigation regarding accomplice liability.'),
  ('voluntary-manslaughter', 'PA', '18 Pa.C.S. § 2503', 'Voluntary Manslaughter', 'Felony 1', NULL, '20 years', '$25,000', '{"Intentionally caused the death of another person","At the time of the killing defendant acted under sudden passion or heat of blood","Passion or heat was provoked by serious provocation by the victim","OR defendant unreasonably believed circumstances required use of deadly force (imperfect self-defense)"}', NULL, '{}', 'Pennsylvania retains voluntary manslaughter as a distinct Felony 1 offense, unlike Illinois which subsumed it into second degree murder.'),
  ('involuntary-manslaughter', 'PA', '18 Pa.C.S. § 2504', 'Involuntary Manslaughter', 'Misdemeanor 1; Felony 3 (reckless driving or DUI contributing cause)', NULL, '5 years (M1); 7 years (F3)', '$10,000', '{"Caused the death of another person","As a direct result of doing an unlawful act in a reckless or grossly negligent manner","OR doing a lawful act in a reckless or grossly negligent manner"}', NULL, '{"Felony 3 if death results from victim being struck by motor vehicle while defendant was engaged in reckless driving"}', NULL),
  ('aggravated-assault', 'PA', '18 Pa.C.S. § 2702', 'Aggravated Assault', 'Felony 1 (serious bodily injury or against protected class); Felony 2 (serious bodily injury attempt or other)', NULL, '20 years (F1); 10 years (F2)', '$25,000', '{"Attempted to cause serious bodily injury to another, or caused such injury intentionally, knowingly, or recklessly under circumstances manifesting extreme indifference to human life","OR attempted to cause or intentionally, knowingly, or recklessly caused bodily injury to a law enforcement officer"}', NULL, '{"Felony 1: against law enforcement officer, teacher, transport employee","Felony 1: with deadly weapon against protected class","Use of firearm: additional mandatory minimum under 42 Pa.C.S. § 9712"}', NULL),
  ('simple-assault', 'PA', '18 Pa.C.S. § 2701', 'Simple Assault', 'Misdemeanor 2 (basic); Misdemeanor 1 (fight by mutual consent); Summary (child under 12 by adult 21+)', NULL, '2 years (M2); 5 years (M1)', '$5,000', '{"Attempted to cause or intentionally, knowingly, or recklessly caused bodily injury to another","OR negligently caused bodily injury with a deadly weapon","OR attempted by physical menace to put another in fear of imminent serious bodily injury"}', NULL, '{"Elevates to Aggravated Assault (F1 or F2) when victim is a protected class or serious injury results"}', NULL),
  ('battery', 'PA', '18 Pa.C.S. § 2701', 'Simple Assault (Pennsylvania does not use the term ''battery'')', 'Misdemeanor 2', NULL, '2 years', '$5,000', '{"Intentionally, knowingly, or recklessly caused bodily injury to another person"}', NULL, '{}', 'Pennsylvania does not have a separate ''battery'' statute. Physical contact offenses are charged as Simple Assault (18 Pa.C.S. § 2701) or Aggravated Assault (§ 2702).'),
  ('aggravated-battery', 'PA', '18 Pa.C.S. § 2702', 'Aggravated Assault', 'Felony 1 or Felony 2', NULL, '10 to 20 years', '$25,000', '{"Attempted to cause serious bodily injury, or caused such injury","Intentionally, knowingly, or recklessly under circumstances manifesting extreme indifference to human life"}', NULL, '{"42 Pa.C.S. § 9712: mandatory 5-year minimum if firearm visible during assault"}', 'Pennsylvania calls this Aggravated Assault — equivalent to aggravated battery in other states.'),
  ('robbery', 'PA', '18 Pa.C.S. § 3701', 'Robbery', 'Felony 1 (serious bodily injury threat); Felony 2 (threat of bodily injury); Felony 3 (demand by threat)', NULL, '20 years (F1); 10 years (F2); 7 years (F3)', '$25,000', '{"In the course of committing a theft","Inflicted serious bodily injury upon another, threatened another with or intentionally put another in fear of immediate serious bodily injury","OR committed or threatened immediately to commit any felony of the first or second degree"}', '42 Pa.C.S. § 9712: 5-year mandatory minimum if firearm visible', '{"Robbery of a Motor Vehicle (18 Pa.C.S. § 3702): Felony 1","Firearm visible: 5-year mandatory minimum under 42 Pa.C.S. § 9712"}', NULL),
  ('armed-robbery', 'PA', '18 Pa.C.S. § 3701; 42 Pa.C.S. § 9712', 'Robbery with Firearm', 'Felony 1', '5 years (mandatory minimum under § 9712)', '20 years', '$25,000', '{"Committed a robbery","While visibly possessing a firearm or other deadly weapon"}', '5 years under 42 Pa.C.S. § 9712 (visible firearm)', '{"10-year mandatory minimum if firearm discharged (42 Pa.C.S. § 9712.1)"}', 'Pennsylvania''s § 9712 mandatory minimums apply whenever a firearm is visible during the commission of a violent offense.'),
  ('kidnapping', 'PA', '18 Pa.C.S. § 2901', 'Kidnapping', 'Felony 1', NULL, '20 years', '$25,000', '{"Unlawfully removed another person a substantial distance from where they were found","OR unlawfully confined another person for a substantial period in a place of isolation","To hold victim for ransom, as shield or hostage, to facilitate commission of a felony, to inflict bodily injury or terrorize victim, OR to interfere with government or political functions"}', NULL, '{"Felony 1 with enhanced penalties if victim is a minor","Unlawful Restraint (18 Pa.C.S. § 2902): Felony 2 for lesser restraint"}', NULL),
  ('arson', 'PA', '18 Pa.C.S. § 3301', 'Arson and Related Offenses', 'Felony 1 (endangering persons or occupied structure); Felony 2 (property); Felony 3 (unoccupied)', NULL, '20 years (F1); 10 years (F2); 7 years (F3)', '$25,000', '{"Intentionally started a fire or caused an explosion","That endangered a person or property"}', NULL, '{"Felony 1: fire caused death or serious bodily injury, or structure was occupied","Reckless Burning (18 Pa.C.S. § 3301(d)): Misdemeanor 1 for reckless burning"}', NULL),
  ('attempted-murder', 'PA', '18 Pa.C.S. § 901; 18 Pa.C.S. § 2502', 'Criminal Attempt — Murder', 'Felony 1', NULL, '20 years', '$25,000', '{"With the intent to commit murder","Did any act which constitutes a substantial step toward commission of murder"}', '5 years if firearm visible (42 Pa.C.S. § 9712)', '{"42 Pa.C.S. § 9712: 5-year mandatory minimum if firearm visible","42 Pa.C.S. § 9712.1: 10-year mandatory minimum if firearm discharged"}', 'Criminal attempt in Pennsylvania is graded one degree below the completed offense, but murder attempt is Felony 1.'),
  ('assault-with-deadly-weapon', 'PA', '18 Pa.C.S. § 2702(a)(4)', 'Aggravated Assault with Deadly Weapon', 'Felony 2', NULL, '10 years', '$25,000', '{"Attempted to cause or intentionally or knowingly caused bodily injury","With a deadly weapon"}', '5 years if weapon was a firearm (42 Pa.C.S. § 9712)', '{"Elevates to Felony 1 if victim is a protected class (law enforcement, teacher, etc.)"}', NULL),
  ('theft-larceny', 'PA', '18 Pa.C.S. § 3921', 'Theft by Unlawful Taking or Disposition', 'Summary (under $50); Misdemeanor 3 ($50-$200); Misdemeanor 2 ($200-$2,000); Misdemeanor 1 ($2,000-$100,000); Felony 3 (over $100,000 or firearm or car)', NULL, '90 days (summary); 1 year (M3); 2 years (M2); 5 years (M1); 7 years (F3)', '$25,000', '{"Unlawfully took, or exercised unlawful control over, movable property of another","With intent to deprive the owner thereof"}', NULL, '{"Felony 3: theft of firearm or motor vehicle regardless of value","Felony 2: theft by extortion involving threat to commit violence"}', NULL),
  ('grand-theft', 'PA', '18 Pa.C.S. § 3921', 'Theft by Unlawful Taking — Felony Value', 'Misdemeanor 1 ($2,000 to $100,000); Felony 3 (over $100,000)', NULL, '5 years (M1); 7 years (F3)', '$25,000', '{"Same elements as theft","Property value exceeds $2,000 (M1) or $100,000 (F3)"}', NULL, '{}', 'Pennsylvania does not use the term ''grand theft'' — grading is based on dollar amount thresholds within the general theft statute.'),
  ('petty-theft', 'PA', '18 Pa.C.S. § 3921', 'Theft by Unlawful Taking — Summary or Misdemeanor', 'Summary (under $50); Misdemeanor 3 ($50 to $200); Misdemeanor 2 ($200 to $2,000)', NULL, '90 days (summary); 1 year (M3); 2 years (M2)', '$2,500', '{"Same elements as theft","Property value under $2,000"}', NULL, '{}', NULL),
  ('shoplifting', 'PA', '18 Pa.C.S. § 3929', 'Retail Theft', 'Summary (1st offense, under $150); Misdemeanor 2 (1st offense, $150+, or 2nd offense); Felony 3 (3rd+ offense)', NULL, '90 days (summary); 2 years (M2); 7 years (F3)', '$2,500 (M2); $15,000 (F3)', '{"Took possession of, carried away, or obtained merchandise offered for sale","Without paying the full retail value","With intent to deprive the merchant of all or part of the retail value"}', NULL, '{"Felony 3 for third or subsequent offense regardless of value","Organized retail crime: enhanced penalties"}', NULL),
  ('burglary', 'PA', '18 Pa.C.S. § 3502', 'Burglary', 'Felony 1 (occupied or adapted for overnight accommodation); Felony 2 (unoccupied structure)', NULL, '20 years (F1); 10 years (F2)', '$25,000', '{"Entered a building or occupied structure","OR separately secured portion thereof","With intent to commit a crime therein","Unless premises were open to public or actor was licensed or privileged to enter"}', '42 Pa.C.S. § 9714: 10-year mandatory minimum for second or subsequent conviction of crime of violence', '{"Felony 1 if building is adapted for overnight accommodation (whether or not anyone present)","Mandatory minimum under § 9714 for repeat violent offenders"}', 'Pennsylvania burglary grading depends on whether the structure is adapted for overnight accommodation, not whether a person is present at time of entry.'),
  ('residential-burglary', 'PA', '18 Pa.C.S. § 3502(a)(1)', 'Burglary — Occupied Residence', 'Felony 1', NULL, '20 years', '$25,000', '{"Entered a building adapted for overnight accommodation","With intent to commit a crime therein","A person was present at the time of entry"}', '5 years if firearm visible (42 Pa.C.S. § 9712)', '{"Higher mandatory minimum under § 9714 for prior crime of violence"}', NULL),
  ('commercial-burglary', 'PA', '18 Pa.C.S. § 3502(a)(4)', 'Burglary — Non-Adapted Building', 'Felony 2', NULL, '10 years', '$25,000', '{"Entered a building not adapted for overnight accommodation","With intent to commit a crime therein"}', NULL, '{}', NULL),
  ('motor-vehicle-theft', 'PA', '18 Pa.C.S. § 3928', 'Unauthorized Use of Automobiles and Other Vehicles', 'Misdemeanor 2; Felony 3 if vehicle not returned within 24 hours', NULL, '2 years (M2); 7 years (F3)', '$5,000', '{"Operated another person''s automobile, airplane, motorcycle, motorboat, or other motor-propelled vehicle","Without consent of the owner","OR knowingly received the vehicle knowing it to have been taken without consent"}', NULL, '{"Felony 3: theft of a motor vehicle under general theft statute (18 Pa.C.S. § 3921)"}', 'Pennsylvania has separate unauthorized use (M2) and theft of vehicle (F3 under general theft statute) charges.'),
  ('receiving-stolen-property', 'PA', '18 Pa.C.S. § 3925', 'Receiving Stolen Property', 'Same grading as theft based on value', NULL, '7 years (F3 if over $100,000)', '$25,000', '{"Intentionally received, retained, or disposed of movable property of another","Knowing that it had been stolen","OR believing that it had probably been stolen","Unless at the time of receiving the actor intended to restore it to the owner"}', NULL, '{}', 'Pennsylvania has a dedicated receiving stolen property statute with same grading tiers as theft.'),
  ('vandalism', 'PA', '18 Pa.C.S. § 3304', 'Criminal Mischief', 'Summary (under $150); Misdemeanor 3 ($150-$500); Misdemeanor 2 ($500-$5,000); Misdemeanor 1 ($5,000+); Felony 3 (over $5,000 by explosion, flood, or aircraft)', NULL, '90 days (summary); 1 year (M3); 2 years (M2); 5 years (M1); 7 years (F3)', '$15,000', '{"Intentionally or recklessly tampered with tangible property of another","So as to endanger person or property","OR intentionally or recklessly caused pecuniary loss to another by defrauding a public utility"}', NULL, '{"Felony 3 for destruction by explosion, flood, or aircraft causing damage over $5,000"}', 'Pennsylvania calls this ''Criminal Mischief'' not vandalism.'),
  ('trespassing', 'PA', '18 Pa.C.S. § 3503', 'Criminal Trespass', 'Felony 3 (buildings); Misdemeanor 1 (defiance of order); Misdemeanor 3 (simple trespass)', NULL, '7 years (F3); 5 years (M1); 1 year (M3)', '$15,000', '{"Knowing that not licensed or privileged to do so","Entered or remained in any place as to which notice against trespass had been given"}', NULL, '{"Felony 3: entering a building with intent to commit a crime (must be distinct from burglary) or breaking into a building"}', 'Pennsylvania Criminal Trespass is graded more seriously than many states — entering a building can be a Felony 3.'),
  ('criminal-mischief', 'PA', '18 Pa.C.S. § 3304', 'Criminal Mischief', 'Summary to Felony 3 based on damage amount', NULL, '7 years (F3)', '$15,000', '{"Intentionally or recklessly damaged tangible property of another person","OR tampered with property to endanger persons"}', NULL, '{}', 'Pennsylvania''s Criminal Mischief statute covers both vandalism and more serious property destruction.'),
  ('domestic-violence', 'PA', '18 Pa.C.S. § 2711; 23 Pa.C.S. § 6102', 'Simple Assault / Aggravated Assault — Domestic Violence', 'Misdemeanor 2 to Felony 1 depending on injury and weapon', NULL, '2 years (M2); 20 years (F1)', '$25,000', '{"Intentionally, knowingly, or recklessly caused bodily injury to a family or household member","OR placed such person in fear of imminent serious bodily injury"}', NULL, '{"Mandatory arrest (18 Pa.C.S. § 2711) when reasonable grounds to believe domestic assault occurred","Enhanced penalties for second+ offense","Protection from Abuse order available under 23 Pa.C.S. § 6101"}', 'Pennsylvania does not have a separate ''domestic violence'' crime — assault charges are used with domestic violence designation for sentencing and mandatory arrest purposes.'),
  ('domestic-battery', 'PA', '18 Pa.C.S. § 2701', 'Simple Assault — Domestic Context', 'Misdemeanor 2', NULL, '2 years', '$5,000', '{"Intentionally, knowingly, or recklessly caused bodily injury to a family or household member"}', NULL, '{"Mandatory arrest provision applies (18 Pa.C.S. § 2711)","Protection from Abuse (PFA) order typically issued"}', 'Pennsylvania calls this Simple Assault in a domestic context. Mandatory arrest applies when physical injury is visible or credibly alleged.'),
  ('child-endangerment', 'PA', '18 Pa.C.S. § 4304', 'Endangering Welfare of Children', 'Misdemeanor 1; Felony 3 (course of conduct or serious bodily injury)', NULL, '5 years (M1); 7 years (F3)', '$10,000', '{"As parent, guardian, or other person supervising child under 18","Knowingly endangered welfare of child by violating duty of care, protection, or support","OR, as adult, engaged in sexual activity or cohabited with person who committed child abuse"}', NULL, '{"Felony 3: course of conduct or child suffered serious bodily injury"}', NULL),
  ('child-abuse', 'PA', '18 Pa.C.S. § 2702(a)(1); 23 Pa.C.S. § 6303', 'Aggravated Assault / Child Abuse', 'Felony 1 (serious bodily injury); Felony 2 (serious bodily injury attempt)', NULL, '20 years (F1)', '$25,000', '{"Caused serious bodily injury to a child","Intentionally, knowingly, or recklessly under circumstances manifesting extreme indifference to child welfare"}', NULL, '{"Pennsylvania Child Protective Services Law (23 Pa.C.S. § 6301) mandates reporting","Pattern of child abuse: additional charges under § 6303"}', 'Child abuse charges prosecuted under criminal assault statutes. Child Protective Services Law governs civil reporting requirements.'),
  ('violation-protective-order', 'PA', '23 Pa.C.S. § 6114', 'Violation of Protection from Abuse Order', 'Misdemeanor 3 (1st offense); Misdemeanor 1 (2nd+); Felony 3 (weapon involved)', NULL, '1 year (M3); 5 years (M1); 7 years (F3)', '$10,000', '{"A Protection from Abuse (PFA) order was in effect","Defendant had notice of the order","Defendant violated any provision of the order"}', NULL, '{"Felony 3: violation involving use of weapon","Each violation is a separate offense"}', 'Pennsylvania PFA orders are issued under the Protection from Abuse Act (23 Pa.C.S. § 6101 et seq.).'),
  ('stalking', 'PA', '18 Pa.C.S. § 2709.1', 'Stalking', 'Misdemeanor 1 (1st offense); Felony 3 (2nd+ offense or with court order in place)', NULL, '5 years (M1); 7 years (F3)', '$10,000', '{"On more than one occasion","Engaged in a course of conduct directed at a specific person","With intent to cause substantial emotional distress to the person","OR with intent to place the person in reasonable fear of bodily injury"}', NULL, '{"Felony 3: second or subsequent offense, or defendant previously convicted of violent crime against victim"}', NULL),
  ('harassment', 'PA', '18 Pa.C.S. § 2709', 'Harassment', 'Summary; Misdemeanor 3 (repeated communications)', NULL, '90 days (summary); 1 year (M3)', '$300 (summary); $2,500 (M3)', '{"With intent to harass, annoy, or alarm another person","Struck, shoved, kicked, or otherwise subjected them to physical contact","OR followed them in public","OR engaged in a course of conduct or repeated acts which serve no legitimate purpose"}', NULL, '{"Misdemeanor 3 for course of conduct involving communication in obscene language"}', NULL),
  ('elder-abuse', 'PA', '18 Pa.C.S. § 2713', 'Neglect of Care-Dependent Person', 'Misdemeanor 2; Felony 3 (great bodily harm or pattern of conduct)', NULL, '2 years (M2); 7 years (F3)', '$5,000', '{"Knowingly endangered the welfare of a care-dependent person","By repeatedly failing to provide essential care or treatment","OR by abusing that person"}', NULL, '{"Felony 3: course of conduct or great bodily injury results","Financial exploitation: separate offense under 18 Pa.C.S. § 3922 (theft by deception)"}', 'Pennsylvania Older Adults Protective Services Act (35 P.S. § 10225.101) runs parallel to criminal prosecution.'),
  ('weapons-possession', 'PA', '18 Pa.C.S. § 6105; 18 Pa.C.S. § 6106', 'Persons Not to Possess Firearms / Carrying Firearm Without License', 'Felony 2 (persons not to possess); Felony 3 (carrying without license)', NULL, '10 years (F2); 7 years (F3)', '$25,000', '{"Possessed a firearm","While being a person prohibited from possessing firearms under 18 Pa.C.S. § 6105","OR carried a firearm in a vehicle or concealed without a valid license to carry (§ 6106)"}', NULL, '{"Mandatory minimum 42 Pa.C.S. § 9712 if firearm visible during crime"}', 'Pennsylvania requires a License to Carry Firearms (LTCF) issued by county sheriff for concealed or vehicle carry.'),
  ('felon-in-possession', 'PA', '18 Pa.C.S. § 6105', 'Persons Not to Possess, Use, Manufacture, Control, Sell or Transfer Firearms', 'Felony 2', NULL, '10 years', '$25,000', '{"Convicted of enumerated offense (including any felony, misdemeanor punishable by imprisonment over 2 years, domestic violence misdemeanor)","Possessed, used, manufactured, controlled, sold, or transferred a firearm"}', NULL, '{"Mandatory minimum under 42 Pa.C.S. § 9712 if firearm used in connection with another crime"}', 'Pennsylvania § 6105 is broader than federal law — includes persons convicted of misdemeanors punishable by over 2 years and domestic violence misdemeanants.'),
  ('concealed-carry-violation', 'PA', '18 Pa.C.S. § 6106', 'Firearms Not to Be Carried Without a License', 'Felony 3', NULL, '7 years', '$15,000', '{"Carried a firearm in a vehicle or concealed on or about person","Without a valid License to Carry Firearms (LTCF)","In any city of the first class (Philadelphia), in a vehicle, or in a place where carrying is restricted"}', NULL, '{"Misdemeanor 1 exception if person had right to possess firearm but simply lacked LTCF"}', 'Pennsylvania LTCF issued by county sheriff or chief of police. Philadelphia has additional restrictions. Open carry without LTCF is generally legal except in Philadelphia.'),
  ('illegal-discharge', 'PA', '18 Pa.C.S. § 2707.1', 'Discharge of Firearm into an Occupied Structure', 'Felony 2', NULL, '10 years', '$25,000', '{"Intentionally discharged a firearm","Into an occupied structure","Under circumstances manifesting extreme indifference to human life"}', NULL, '{"Additional charges for Reckless Endangerment (18 Pa.C.S. § 2705)"}', NULL),
  ('weapons-trafficking', 'PA', '18 Pa.C.S. § 6111', 'Sale or Transfer of Firearms', 'Felony 2 (sale to prohibited person); Misdemeanor 2 (procedural violations)', NULL, '10 years (F2)', '$25,000', '{"Sold, transferred, or delivered a firearm","To a person prohibited under 18 Pa.C.S. § 6105","OR without conducting required background check through dealer"}', NULL, '{"Straw purchase: additional federal charges often accompany state charges"}', NULL),
  ('possession-prohibited-weapon', 'PA', '18 Pa.C.S. § 908', 'Prohibited Offensive Weapons', 'Misdemeanor 1', NULL, '5 years', '$10,000', '{"Possessed, made, repaired, sold, or otherwise dealt in a prohibited offensive weapon","Including bombs, grenades, machine guns, sawed-off shotguns, blackjacks, sandbags, metal knuckles, or other weapons of destruction"}', NULL, '{}', NULL),
  ('unlawful-carry', 'PA', '18 Pa.C.S. § 6106', 'Firearms Not to Be Carried Without a License', 'Felony 3', NULL, '7 years', '$15,000', '{"Carried a firearm in a vehicle or concealed on person","In any city of the first class or while in a vehicle anywhere in Pennsylvania","Without a valid License to Carry Firearms"}', NULL, '{}', 'Same as concealed-carry-violation for Pennsylvania. Licensed to Carry Firearms (LTCF) is required for concealed carry and vehicle carry statewide.'),
  ('wire-fraud', 'PA', '18 Pa.C.S. § 3928; 18 Pa.C.S. § 4107', 'Deceptive Business Practices / Wire Fraud (state equivalent)', 'Misdemeanor 2 to Felony 3', NULL, '7 years', '$15,000', '{"Used electronic communications to further a scheme to defraud","With intent to defraud another person of money or property"}', NULL, '{}', 'Wire fraud in Pennsylvania is typically prosecuted federally under 18 U.S.C. § 1343. State-level prosecution uses theft by deception or deceptive business practices statutes.'),
  ('identity-theft', 'PA', '18 Pa.C.S. § 4120', 'Identity Theft', 'Misdemeanor 1 (under $2,000); Felony 3 ($2,000 to $100,000); Felony 2 (over $100,000 or victim 60+)', NULL, '5 years (M1); 7 years (F3); 10 years (F2)', '$25,000', '{"Possesses or uses, through any means, identifying information of another person","Without the consent of that other person","To further any unlawful purpose"}', NULL, '{"Felony 2: victim is 60 years of age or older or amount over $100,000"}', NULL),
  ('embezzlement', 'PA', '18 Pa.C.S. § 3927', 'Theft by Failure to Make Required Disposition of Funds (Embezzlement)', 'Same as theft based on amount', NULL, '7 years (F3 if over $100,000)', '$25,000', '{"Obtained property of another","Upon agreement or legal obligation to make specified payment or other disposition","Intentionally dealt with the property contrary to the agreement or legal obligation"}', NULL, '{}', 'Pennsylvania uses ''Theft by Failure to Make Required Disposition'' for the embezzlement concept.'),
  ('forgery', 'PA', '18 Pa.C.S. § 4101', 'Forgery', 'Felony 2 (currency, money, securities, postage, revenue stamps); Felony 3 (public records, government instruments); Misdemeanor 1 (other writing)', NULL, '10 years (F2); 7 years (F3); 5 years (M1)', '$25,000', '{"With intent to defraud or injure another","Altered any writing of another without authority","OR made, completed, executed, authenticated, issued, or transferred any writing purporting to be the act of another","OR uttered any writing known to be forged"}', NULL, '{}', NULL),
  ('bad-checks', 'PA', '18 Pa.C.S. § 4105', 'Bad Checks', 'Summary (under $200); Misdemeanor 2 ($200-$500); Misdemeanor 1 ($500-$75,000); Felony 3 (over $75,000)', NULL, '90 days (summary); 2 years (M2); 5 years (M1); 7 years (F3)', '$15,000', '{"Issued or passed a check or similar sight order for payment of money","When at the time of issuance the issuer did not have sufficient funds in or credit with the drawee","And the issuer knew the check would not be honored"}', NULL, '{}', NULL),
  ('insurance-fraud', 'PA', '18 Pa.C.S. § 4117', 'Insurance Fraud', 'Felony 3', NULL, '7 years', '$15,000', '{"Intentionally or knowingly presented false information to an insurance company","OR concealed information for the purpose of obtaining insurance benefits or proceeds","To which the person was not entitled"}', NULL, '{"Felony 2 if involves arson or healthcare fraud over $100,000"}', NULL),
  ('credit-card-fraud', 'PA', '18 Pa.C.S. § 4106', 'Access Device Fraud', 'Misdemeanor 1 (under $500); Felony 3 ($500-$1,000); Felony 2 (over $1,000)', NULL, '5 years (M1); 7 years (F3); 10 years (F2)', '$25,000', '{"Used an access device (credit card, debit card, account number)","To obtain money, goods, or services","Without authority of the cardholder"}', NULL, '{}', NULL),
  ('money-laundering', 'PA', '18 Pa.C.S. § 5111', 'Money Laundering', 'Felony 3 (under $100,000); Felony 2 (over $100,000)', NULL, '7 years (F3); 10 years (F2)', 'Three times the amount involved', '{"Conducted or attempted to conduct a financial transaction","Knowing the property represented proceeds of criminal activity","With intent to promote criminal activity, conceal the source or nature of proceeds, or avoid reporting requirements"}', NULL, '{}', NULL),
  ('fraud-general', 'PA', '18 Pa.C.S. § 3922', 'Theft by Deception', 'Same grading as theft based on value', NULL, '7 years (F3 over $100,000)', '$25,000', '{"Intentionally obtained property of another by deception","Created or reinforced a false impression (including false statements of fact, law, or intention)","OR prevented another from acquiring information that would have affected decision"}', NULL, '{}', 'Pennsylvania uses ''Theft by Deception'' (18 Pa.C.S. § 3922) for most general fraud conduct.'),
  ('bank-fraud', 'PA', '18 Pa.C.S. § 3922; 18 Pa.C.S. § 4106', 'Theft by Deception / Access Device Fraud — Financial Institution', 'Felony 2 to Felony 3', NULL, '10 years', '$25,000', '{"Intentionally obtained funds from a financial institution by deception or unauthorized access","With intent to defraud"}', NULL, '{}', 'Bank fraud typically prosecuted federally under 18 U.S.C. § 1344. State prosecution uses theft by deception or access device fraud.'),
  ('sexual-assault', 'PA', '18 Pa.C.S. § 3124.1', 'Sexual Assault', 'Felony 2', NULL, '10 years', '$25,000', '{"Engaged in sexual intercourse or deviate sexual intercourse with a complainant","Without the complainant''s consent"}', NULL, '{"Rape (18 Pa.C.S. § 3121): Felony 1 — forcible compulsion or threat","Aggravated Indecent Assault (18 Pa.C.S. § 3125): Felony 2"}', 'Pennsylvania has separate offense tiers: Rape (F1, with force), Sexual Assault (F2, without consent), and Aggravated Indecent Assault (F2).'),
  ('rape', 'PA', '18 Pa.C.S. § 3121', 'Rape', 'Felony 1', NULL, '20 years', '$25,000', '{"Engaged in sexual intercourse with a complainant","By forcible compulsion or threat of forcible compulsion","OR by administering a drug or intoxicant that substantially impaired ability to resist","OR complainant was unconscious or unaware intercourse was occurring","OR complainant was less than 13 years of age"}', '10 years (42 Pa.C.S. § 9718) if victim under 16', '{"Rape of child under 13: Felony 1 with 10-year mandatory minimum","SORNA registration required"}', 'Pennsylvania retains ''rape'' as a distinct offense title at Felony 1.'),
  ('indecent-exposure', 'PA', '18 Pa.C.S. § 3127', 'Indecent Exposure', 'Misdemeanor 2 (basic); Misdemeanor 1 (in presence of minor under 16)', NULL, '2 years (M2); 5 years (M1)', '$5,000', '{"Exposed genitals in any public place","OR exposed genitals in any place where there were present other persons under circumstances in which the actor knew or should have known the conduct was likely to offend, affront, or alarm"}', NULL, '{"Misdemeanor 1 if person present was under 16 years of age","SORNA registration required for second offense or if minor victim"}', NULL),
  ('solicitation-prostitution', 'PA', '18 Pa.C.S. § 5902', 'Prostitution and Related Offenses', 'Summary (patronizing a prostitute); Misdemeanor 2 (soliciting or promoting)', NULL, '90 days (summary); 2 years (M2)', '$500 (summary); $5,000 (M2)', '{"Hired a prostitute or patronized prostitution","OR offered money or consideration to engage in sexual activity"}', NULL, '{"Felony 3: patronizing a prostitute who is under 18 (trafficking provisions apply)"}', 'Pennsylvania recently revised prostitution laws to focus prosecution on traffickers and buyers rather than persons who sell sex.'),
  ('sex-offense-digital', 'PA', '18 Pa.C.S. § 6318', 'Unlawful Contact with Minor', 'Felony 3 (contact); Felony 1 or 2 if underlying sexual offense would be F1/F2', NULL, '7 years (F3); up to 20 years if underlying F1 offense', '$25,000', '{"Intentionally contacted a minor","For purpose of engaging in activity prohibited by law","Including via the internet, telephone, or any other means"}', NULL, '{"Same grade as underlying sexual offense targeted","SORNA registration required"}', NULL),
  ('child-exploitation', 'PA', '18 Pa.C.S. § 6312', 'Sexual Abuse of Children (Child Pornography)', 'Felony 3 (possession); Felony 2 (distribution); Felony 1 (production)', NULL, '7 years (F3); 10 years (F2); 20 years (F1)', '$25,000', '{"Photographed, videotaped, depicted, or recorded a minor engaging in sexual act","OR distributed or exhibited such material","OR knowingly possessed such material"}', NULL, '{"SORNA Tier III (lifetime registration) for production","Mandatory consecutive sentences for multiple victims"}', NULL),
  ('failure-to-register', 'PA', '18 Pa.C.S. § 4915.1', 'Failure to Comply with Registration of Sexual Offenders Requirements', 'Felony 3 (1st offense); Felony 2 (2nd+ offense)', NULL, '7 years (F3); 10 years (F2)', '$15,000', '{"Required to register as a sex offender under Pennsylvania''s SORNA (Subchapter H or I)","Failed to register, verify, or provide required information within required timeframe"}', NULL, '{"Felony 2 for second or subsequent failure to comply"}', 'Pennsylvania''s SORNA (Sexual Offender Registration and Notification Act) was substantially revised by Act 29 of 2018.'),
  ('statutory-rape', 'PA', '18 Pa.C.S. § 3122.1', 'Statutory Sexual Assault', 'Felony 2 (4-8 year age gap); Felony 1 (11+ year age gap)', NULL, '10 years (F2); 20 years (F1)', '$25,000', '{"Engaged in sexual intercourse with a complainant under 16 years of age","Defendant is four or more years older than the complainant","Complainant and defendant are not married to each other"}', NULL, '{"Felony 1: defendant is 11 or more years older than victim","SORNA registration required"}', 'Pennsylvania uses ''Statutory Sexual Assault'' not ''statutory rape.'' Age gap determines grading.'),
  ('sex-offense-contact', 'PA', '18 Pa.C.S. § 3125', 'Aggravated Indecent Assault', 'Felony 2 (basic); Felony 1 (victim under 13)', NULL, '10 years (F2); 20 years (F1)', '$25,000', '{"Without the complainant''s consent","Engaged in penetration, however slight, of the genitals or anus of the complainant with part of the defendant''s body"}', NULL, '{"Felony 1 if victim is under 13 years of age"}', NULL),
  ('sexual-battery', 'PA', '18 Pa.C.S. § 3126', 'Indecent Assault', 'Misdemeanor 2 (basic); Misdemeanor 1 or Felony 3 (aggravated circumstances)', NULL, '2 years (M2); 5 years (M1); 7 years (F3)', '$15,000', '{"With indecent contact with another person","Without the person''s consent","OR with person who is substantially impaired, incapacitated, or under 13"}', NULL, '{"Misdemeanor 1: indecent contact with person under 16","Felony 3: victim is under 13, or defendant previously convicted of sex offense"}', 'Pennsylvania calls this ''Indecent Assault'' — equivalent to sexual battery in other states.'),
  ('disorderly-conduct', 'PA', '18 Pa.C.S. § 5503', 'Disorderly Conduct', 'Summary; Misdemeanor 3 (intent to cause substantial harm or serious inconvenience)', NULL, '90 days (summary); 1 year (M3)', '$300 (summary); $2,500 (M3)', '{"With intent to cause public inconvenience, annoyance, or alarm, or recklessly creating risk thereof","Engaged in fighting or threatening, or in violent or tumultuous behavior","OR made unreasonable noise","OR used obscene language or made an obscene gesture","OR created hazardous or physically offensive condition"}', NULL, '{}', NULL),
  ('resisting-arrest', 'PA', '18 Pa.C.S. § 5104', 'Resisting Arrest or Other Law Enforcement', 'Misdemeanor 2', NULL, '2 years', '$5,000', '{"With the intent to prevent a public servant from effecting a lawful arrest or discharging any other duty","Created a substantial risk of bodily injury to the public servant or anyone else","OR employed means justifying or requiring substantial force to overcome the resistance"}', NULL, '{"Aggravated Assault charge (F1 or F2) if officer is injured"}', NULL),
  ('obstruction-justice', 'PA', '18 Pa.C.S. § 5101', 'Obstructing Administration of Law or Other Governmental Function', 'Misdemeanor 2', NULL, '2 years', '$5,000', '{"Intentionally obstructed, impaired, or perverted the administration of law","OR prevented or attempted to prevent a public servant from lawfully performing an official function","By means of intimidation, physical force or interference, breach of official duty, or any other unlawful act"}', NULL, '{"Tampering with Evidence (18 Pa.C.S. § 4910): Misdemeanor 2 to Felony 3","Witness Intimidation (18 Pa.C.S. § 4952): Felony 3"}', NULL),
  ('contempt-of-court', 'PA', '42 Pa.C.S. § 4131', 'Contempts', 'Misdemeanor (criminal contempt)', NULL, '6 months per count', '$1,000', '{"Misbehavior in presence of court or near thereto","Misbehavior of officers of court in official transactions","Disobedience or resistance to lawful process, judgment, decree, or order"}', NULL, '{}', 'Courts have inherent contempt power. Criminal contempt is separate from civil contempt (coercive).'),
  ('public-intoxication', 'PA', '18 Pa.C.S. § 5505', 'Public Drunkenness and Similar Misconduct', 'Summary', NULL, '90 days', '$500 (1st); $1,000 (2nd+)', '{"Appeared in a public place manifestly under the influence of alcohol or a controlled substance","To the degree that the person may endanger the person or other persons or property","OR annoy persons in the vicinity"}', NULL, '{}', 'Pennsylvania criminal public intoxication (§ 5505) is a summary offense. Unlike Illinois, Pennsylvania retains it as a criminal violation.'),
  ('loitering', 'PA', '18 Pa.C.S. § 5506', 'Loitering and Prowling at Night Time', 'Summary', NULL, '90 days', '$300', '{"Loitered or prowled in a place at a time or in a manner not usual for law-abiding individuals","Under circumstances that warrant alarm for the safety of persons or property in the vicinity"}', NULL, '{}', NULL),
  ('disturbing-peace', 'PA', '18 Pa.C.S. § 5503', 'Disorderly Conduct — Disturbing the Peace', 'Summary', NULL, '90 days', '$300', '{"Made unreasonable noise or engaged in tumultuous behavior","With intent to cause public inconvenience, annoyance, or alarm"}', NULL, '{}', 'Pennsylvania consolidates disturbing the peace under Disorderly Conduct (18 Pa.C.S. § 5503).'),
  ('failure-to-appear', 'PA', '18 Pa.C.S. § 5124', 'Default in Required Appearance', 'Misdemeanor 3 (misdemeanor underlying); Felony 3 (felony underlying)', NULL, '1 year (M3); 7 years (F3)', '$2,500', '{"Released on bail or recognizance in connection with a criminal proceeding","Failed to appear as required","Without lawful excuse"}', NULL, '{}', NULL),
  ('false-report', 'PA', '18 Pa.C.S. § 4906', 'False Reports to Law Enforcement Authorities', 'Misdemeanor 3 (basic); Misdemeanor 2 (false report of terrorism); Felony 3 (false report of terrorism causing evacuation)', NULL, '1 year (M3); 2 years (M2); 7 years (F3)', '$2,500', '{"Reported to law enforcement authorities an offense or other incident within their concern","Knowing that such offense or incident did not occur","OR provided false information to law enforcement"}', NULL, '{"Felony 3: false report causing evacuation of building or transportation vehicle"}', NULL),
  ('criminal-threat', 'PA', '18 Pa.C.S. § 2706', 'Terroristic Threats', 'Misdemeanor 1 (basic); Felony 3 (threat to commit crime of violence with intent to terrorize)', NULL, '5 years (M1); 7 years (F3)', '$10,000', '{"Communicated, directly or indirectly, a threat to","Commit any crime of violence with intent to terrorize another","OR cause evacuation of a building or place of assembly","OR otherwise cause serious public inconvenience"}', NULL, '{"Felony 3: threat causes evacuation or substantial disruption of school"}', 'Pennsylvania calls criminal threats ''Terroristic Threats.'' School threats are very aggressively prosecuted.'),
  ('probation-violation', 'PA', '42 Pa.C.S. § 9771', 'Modification or Revocation of Order of Probation', 'Dependent on underlying offense', NULL, 'Full imprisonment sentence for underlying offense', NULL, '{"Was serving a term of probation","Violated condition of probation","Court must find violation by preponderance of evidence at revocation hearing"}', NULL, '{"New criminal conviction during probation: strong presumption for revocation"}', 'Pennsylvania probation revocation hearings are before the sentencing judge. Commonwealth v. Simmons governs procedural requirements.'),
  ('probation-violation-technical', 'PA', '42 Pa.C.S. § 9771', 'Technical Violation of Probation', 'Dependent on underlying offense', NULL, 'Full probation sentence', NULL, '{"Failed to report to probation officer","Failed to pay restitution or fines","Failed to complete community service","Failed drug or alcohol test","OR other non-criminal condition violation"}', NULL, '{}', 'Pennsylvania legislature enacted Act 115 of 2019 requiring judges to consider graduated sanctions before imprisoning for technical probation violations.'),
  ('probation-violation-substantive', 'PA', '42 Pa.C.S. § 9771', 'Substantive Violation of Probation — New Offense', 'Underlying offense class', NULL, 'Full original sentence', NULL, '{"Committed a new criminal offense while on probation","New offense established by preponderance or separate criminal conviction"}', NULL, '{"Revocation and imposition of original sentence is presumptive for new felony during probation"}', NULL),
  ('parole-violation', 'PA', '61 Pa.C.S. § 6138', 'Violation of Parole', 'Administrative — Pennsylvania Board of Probation and Parole proceeding', NULL, 'Return to prison for remainder of sentence', NULL, '{"Released on parole by PBPP","Violated conditions of parole (new offense, absconder, failed drug test, etc.)"}', NULL, '{"New crime during parole: mandatory return to prison plus new sentence consecutive"}', 'Pennsylvania has a Board of Probation and Parole (PBPP) that handles state parole violations. County probation violations are handled by courts.'),
  ('supervised-release-violation', 'PA', '61 Pa.C.S. § 6138', 'Parole Violation — Supervised Release', 'Administrative proceeding before PBPP', NULL, 'Return to PDOC for balance of sentence', NULL, '{"Released on state parole or supervision","Violated conditions of supervision"}', NULL, '{}', 'Pennsylvania uses ''parole'' not ''supervised release.'' PBPP handles state-level violations.'),
  ('conspiracy', 'PA', '18 Pa.C.S. § 903', 'Criminal Conspiracy', 'Same grade as most serious offense that is object of conspiracy', NULL, 'Same as underlying offense', '$25,000', '{"With intent of promoting or facilitating commission of a crime","Agreed with another person that they or one of them would engage in conduct which constitutes such crime","OR agreed to aid such other person in the planning or commission of such crime"}', NULL, '{"Pennsylvania conspiracy is graded same as the target offense (not one class lower like Illinois)","Overt act required only if conspiracy is Misdemeanor 1 or lower"}', 'Pennsylvania conspiracy is graded the same as the underlying offense, unlike Illinois which grades it one class lower.'),
  ('rico', 'PA', '18 Pa.C.S. § 911', 'Corrupt Organizations (Pennsylvania RICO equivalent)', 'Felony 1', NULL, '20 years', '$25,000 or three times the gain from the violation', '{"Was employed by or associated with an enterprise","Conducted or participated in conduct of enterprise''s affairs","Through a pattern of racketeering activity","OR through collection of unlawful debt"}', NULL, '{"Civil forfeiture of proceeds","Federal RICO (18 U.S.C. § 1962) often charged in parallel"}', 'Pennsylvania''s Corrupt Organizations statute (18 Pa.C.S. § 911) is the state-level RICO equivalent.'),
  ('self-defense', 'PA', '18 Pa.C.S. § 505', 'Use of Force in Self-Protection — Affirmative Defense', 'Justification defense — not a criminal charge', NULL, NULL, NULL, '{"Defendant believed use of force was immediately necessary","To protect themselves against use of unlawful force by another","Belief was not reckless or negligent and force used was not excessive"}', NULL, '{}', 'Pennsylvania Castle Doctrine codified at 18 Pa.C.S. § 505(b)(2.1) — no duty to retreat in dwelling or workplace. Stand Your Ground: no duty to retreat if not the initial aggressor.'),
  ('other', 'PA', 'N/A', 'Other Pennsylvania Criminal Offense', 'Varies', NULL, 'Varies', NULL, '{}', NULL, '{}', 'Placeholder for Pennsylvania charges not covered by specific taxonomy entries. Consult 18 Pa.C.S. (Crimes Code), 35 P.S. (Drug Device and Cosmetic Act), and 75 Pa.C.S. (Vehicle Code).')
INSERT INTO jurisdiction_statutes (common_charge_slug, jurisdiction, statute_number, statute_title, offense_class, penalty_min, penalty_max, fine_max, elements, mandatory_minimum, enhancements, notes)
VALUES
  ('conspiracy', 'federal', '18 U.S.C. § 371', 'Conspiracy to Commit Offense or to Defraud United States', 'Federal Felony', NULL, '5 years imprisonment', '$250,000', '{"Agreement between two or more persons to commit a federal offense or defraud the United States","Defendant knowingly and voluntarily joined the conspiracy","At least one overt act committed in furtherance of the conspiracy"}', NULL, '{"If object offense carries higher penalty, conspiracy may carry same maximum","Sentencing Guidelines consider underlying offense level (USSG § 2X1.1)","Leadership role enhancement (+2 to +4 levels, USSG § 3B1.1)","Obstruction enhancement (+2 levels, USSG § 3C1.1)"}', 'Most versatile federal charging tool. Statute of limitations: 5 years. Pinkerton liability allows co-conspirators to be liable for substantive offenses of other members. No overt act required for drug conspiracies under 21 U.S.C. § 846.'),
  ('rico', 'federal', '18 U.S.C. § 1962', 'Racketeer Influenced and Corrupt Organizations (RICO)', 'Federal Felony', NULL, '20 years imprisonment; life if predicate involves murder or kidnapping', '$25,000 per count or twice the proceeds of the offense', '{"Enterprise affecting interstate or foreign commerce","Defendant associated with or employed by the enterprise","Defendant participated in a pattern of racketeering activity","Pattern: at least two predicate acts within 10 years","Relationship and continuity between predicate acts"}', NULL, '{"Civil forfeiture of all interests in enterprise","Criminal forfeiture of proceeds and instrumentalities","Civil RICO treble damages available to victims","USSG § 2E1.1 — base offense level is 19 or underlying offense level, whichever is greater","Leadership role enhancements (USSG § 3B1.1)"}', 'Predicate acts include mail fraud, wire fraud, extortion, drug trafficking, murder, kidnapping, bribery, and 35+ other offenses. Statute of limitations: 5 years from last predicate act. Both § 1962(c) (participation) and § 1962(d) (conspiracy) commonly charged.'),
  ('federal-drug-trafficking', 'federal', '21 U.S.C. § 841(a)(1)', 'Manufacture, Distribution, or Possession with Intent to Distribute Controlled Substances', 'Federal Felony', '5 years (threshold quantities); 10 years (higher quantities)', '40 years (threshold quantities); life (higher quantities or prior felony)', '$5,000,000 individual / $25,000,000 organization', '{"Defendant knowingly or intentionally manufactured, distributed, dispensed, or possessed with intent to distribute","A controlled substance","The substance is the type and quantity alleged"}', '5 years for Schedule I/II threshold quantities (e.g., 500g+ cocaine, 28g+ crack, 100g+ heroin, 1kg+ meth mixture); 10 years for higher quantities', '{"§ 851 prior felony drug conviction doubles mandatory minimum","Death or serious bodily injury results: 20-year mandatory minimum","Distribution to persons under 21: doubles penalties (§ 859)","Distribution near school/playground: doubles penalties (§ 860)","Use of minor in drug operation: additional 1 year consecutive (§ 861)","§ 924(c) firearm enhancement if weapon involved: +5 to 10+ years consecutive","Career offender designation under USSG § 4B1.1","Continuing criminal enterprise (CCE) under § 848: 20 years to life"}', 'Drug quantity is an element under Apprendi — must be charged and proven to jury. Safety valve (§ 3553(f)) may allow below-mandatory-minimum sentence for first-time, non-violent offenders who cooperate. Schedule I/II drugs carry the highest penalties.'),
  ('federal-firearms', 'federal', '18 U.S.C. § 922(g)', 'Unlawful Possession of a Firearm by Prohibited Person', 'Federal Felony', NULL, '15 years imprisonment (general); mandatory minimums under ACCA', '$250,000', '{"Defendant possessed a firearm or ammunition","The firearm or ammunition was in or affecting interstate commerce","Defendant knew they were a prohibited person at the time of possession","Defendant''s prohibited status (felon, domestic violence misdemeanant, drug user, illegal alien, etc.)"}', '15 years under Armed Career Criminal Act (ACCA, 18 U.S.C. § 924(e)) if 3+ prior violent felony or serious drug offense convictions', '{"ACCA enhancement: 15-year mandatory minimum for armed career criminals","§ 924(c): additional 5 years consecutive if firearm used/carried in drug crime or crime of violence","§ 924(c) second conviction: 25 years consecutive","USSG § 2K2.1 enhancements for prior convictions, number of firearms, stolen firearms, trafficking","Obliterated serial number: +2 levels (USSG § 2K2.1(b)(4))"}', 'Rehaif v. United States (2019) requires proof defendant knew of prohibited status — critical for defense. Prohibitions apply to: convicted felons, fugitives, controlled substance users, mental health adjudicatees, illegal aliens, domestic violence misdemeanants, persons under indictment. Constructive possession is sufficient.'),
  ('tax-evasion', 'federal', '26 U.S.C. § 7201', 'Attempt to Evade or Defeat Tax', 'Federal Felony', NULL, '5 years imprisonment', '$250,000 individual / $500,000 corporation', '{"Existence of a tax deficiency (unpaid tax)","Willful attempt to evade or defeat the tax","Affirmative act of evasion (beyond mere failure to file)"}', NULL, '{"Sophisticated means enhancement (USSG § 2T1.1(b)(2)): +2 levels","Tax loss determines base offense level (USSG § 2T4.1 table)","Role in offense enhancements apply","Money laundering charges commonly added when proceeds concealed","Restitution mandatory for all victims"}', 'Distinct from § 7203 (failure to file, misdemeanor) and § 7206 (filing false return). Willfulness requires specific intent to violate a known legal duty. Statute of limitations: 6 years. Civil tax liability and IRS penalties are separate from criminal exposure.'),
  ('immigration-offense', 'federal', '8 U.S.C. §§ 1325, 1326', 'Illegal Entry / Reentry of Removed Alien', 'Federal Misdemeanor (§ 1325 first offense) / Federal Felony (§ 1326)', NULL, '6 months (§ 1325 first offense); 2 years (§ 1325 second); 2 years (§ 1326 base); 10 years (prior felony removal); 20 years (prior aggravated felony removal)', '$250,000', '{"§ 1325: Alien entered or attempted to enter U.S. at unauthorized time or place, or eluded examination by immigration officers, or entered by willful misrepresentation","§ 1326: Alien was previously removed or departed while removal order pending; alien entered, attempted to enter, or was found in U.S. without permission"}', NULL, '{"Prior aggravated felony removal: 20-year maximum (§ 1326(b)(2))","Prior felony (3+ years) removal: 10-year maximum (§ 1326(b)(1))","USSG § 2L1.2: base level 8, +4 if prior felony removal, higher levels for aggravated felonies","Fast-track departures available in many districts reducing sentence","Prior § 1326 convictions may be used as aggravating factors"}', '§ 1325 was misdemeanor-ized in 2021 DOJ policy but statute unchanged. Collateral consequences include permanent bar to legal status. USSG § 2L1.2 fast-track programs reduce sentences in border districts.'),
  ('mail-fraud', 'federal', '18 U.S.C. § 1341', 'Mail Fraud', 'Federal Felony', NULL, '20 years imprisonment; 30 years if financial institution or federal disaster relief involved', '$250,000 individual / $500,000 organization', '{"Defendant devised or participated in a scheme to defraud or obtain money/property by false pretenses","Defendant acted with intent to defraud","Defendant used the U.S. mail (or private carrier) in furtherance of the scheme","The mailing was for the purpose of executing or attempting to execute the scheme"}', NULL, '{"USSG § 2B1.1: loss amount drives offense level (see loss table)","10+ victims: +2 levels; 50+ victims: +4 levels","Sophisticated means: +2 levels","Vulnerable victim: +2 levels (USSG § 3A1.1)","Often charged with wire fraud, bank fraud, money laundering as a package","Forfeiture of proceeds mandatory"}', 'Extremely broad — each mailing is a separate count. No requirement that victim actually be defrauded (attempt sufficient). Private mail carriers (FedEx, UPS) covered. Honest services fraud (§ 1346) is a subset. Statute of limitations: 5 years (10 years for financial institution fraud).'),
  ('wire-fraud', 'federal', '18 U.S.C. § 1343', 'Wire Fraud', 'Federal Felony', NULL, '20 years imprisonment; 30 years if financial institution or federal disaster relief involved', '$250,000 individual / $500,000 organization', '{"Defendant devised or participated in a scheme to defraud or obtain money/property by false or fraudulent pretenses","Defendant acted with intent to defraud","Defendant used interstate wire communications (phone, email, internet) in furtherance of the scheme","The wire transmission was for the purpose of executing or attempting to execute the scheme"}', NULL, '{"USSG § 2B1.1: loss amount drives guideline range","10+ victims: +2 levels; 50+ victims: +4 levels; 250+ victims: +6 levels","Sophisticated means: +2 levels (USSG § 2B1.1(b)(10))","Abuse of position of trust: +2 levels (USSG § 3B1.3)","Often charged alongside mail fraud, bank fraud, money laundering","Healthcare wire fraud under § 1347: up to 10 years (20 if serious bodily injury, life if death results)"}', 'Modern workhorse federal fraud statute. Each email, phone call, or wire transmission is a separate count. Honest services wire fraud (§ 1346) covers breach of fiduciary duty. Statute of limitations: 5 years (10 years if financial institution).'),
  ('bank-fraud', 'federal', '18 U.S.C. § 1344', 'Bank Fraud', 'Federal Felony', NULL, '30 years imprisonment', '$1,000,000', '{"Defendant executed or attempted to execute a scheme to defraud a federally insured financial institution","OR defendant executed a scheme to obtain money, funds, or property under the custody of a financial institution by false or fraudulent pretenses","Defendant acted with intent to defraud","The scheme involved a federally chartered or insured institution"}', NULL, '{"USSG § 2B1.1: loss table drives base offense level","Sophisticated means: +2 levels","Mass marketing fraud: +2 levels","Identity theft aggravated: +2 levels (USSG § 2B1.1(b)(11))","Mandatory restitution to financial institutions","Often accompanies money laundering (§ 1956) and aggravated identity theft (§ 1028A)"}', 'Covers virtually all federally insured banks, credit unions, and savings associations. Mortgage fraud, check kiting, loan fraud, and credit card fraud schemes all qualify. Statute of limitations: 10 years. No requirement that the institution actually lose money — attempt sufficient.'),
  ('securities-fraud', 'federal', '15 U.S.C. § 78j(b) / 18 U.S.C. § 1348', 'Securities Fraud / Securities Exchange Act Fraud', 'Federal Felony', NULL, '20 years imprisonment (§ 1348 Sarbanes-Oxley provision); 25 years for corporate fraud (§ 1350)', '$5,000,000 individual / $25,000,000 entity', '{"In connection with the purchase or sale of securities","Defendant employed a device, scheme, or artifice to defraud, OR made materially false statements or omissions, OR engaged in any act constituting fraud or deceit","Intent to defraud","Use of interstate commerce, mail, or a national securities exchange"}', NULL, '{"USSG § 2B1.1: loss amount determines base offense level","Securities offense enhancement: +4 levels (USSG § 2B1.1(b)(20))","Sophisticated means: +2 levels","250+ victims: +6 levels","Obstruction of SEC investigation: +2 levels","Civil SEC disgorgement and penalties are separate from criminal exposure","SEC may also pursue administrative bar from securities industry"}', 'Rule 10b-5 (17 C.F.R. § 240.10b-5) is the primary implementing regulation. Insider trading charged under this provision. Statute of limitations: 5 years from offense. Both DOJ (criminal) and SEC (civil) may prosecute — parallel proceedings common.'),
  ('money-laundering', 'federal', '18 U.S.C. § 1956', 'Laundering of Monetary Instruments', 'Federal Felony', NULL, '20 years imprisonment', '$500,000 or twice the amount laundered, whichever is greater', '{"Defendant conducted or attempted a financial transaction","The transaction involved the proceeds of specified unlawful activity (SUA)","Defendant knew the property represented proceeds of some unlawful activity","Defendant acted with intent to promote the SUA, OR knew the transaction was designed to conceal the nature, location, source, ownership, or control of the proceeds, OR transaction was designed to evade reporting requirements"}', NULL, '{"§ 1956(h) conspiracy: same 20-year maximum","§ 1957 (transactions in criminally derived property over $10,000): additional 10 years","USSG § 2S1.1: offense level from underlying offense + 1 level; conviction under § 1956: +2 levels","Sophisticated laundering: +2 levels","Forfeiture of all laundered funds and facilitating property mandatory (§ 982)","Multiple counts: each transaction is a separate offense"}', 'Three theories: (1) promotion, (2) concealment, (3) sting. Over 250 predicate ''specified unlawful activities.'' § 1957 (spending criminally derived funds) has lower intent requirement. Extraterritorial jurisdiction for international transactions.'),
  ('felon-in-possession', 'federal', '18 U.S.C. § 922(g)(1)', 'Felon in Possession of Firearm or Ammunition', 'Federal Felony', NULL, '15 years imprisonment; 15-year mandatory minimum under ACCA', '$250,000', '{"Defendant was previously convicted of a crime punishable by imprisonment for more than one year","Defendant knowingly possessed a firearm or ammunition","The firearm or ammunition had previously moved in or affected interstate commerce","Defendant knew of their prior conviction at the time of possession (Rehaif requirement)"}', '15 years under ACCA (18 U.S.C. § 924(e)) for defendants with 3+ prior violent felony or serious drug offense convictions', '{"ACCA: 15-year mandatory minimum for 3+ qualifying prior convictions","§ 924(c): consecutive 5-30 years if firearm used in crime of violence or drug trafficking","USSG § 2K2.1: prior convictions, stolen firearm, number of firearms, trafficking","Career offender (USSG § 4B1.1) if prior violent felony or drug trafficking conviction"}', 'Rehaif v. United States, 139 S. Ct. 2191 (2019): government must prove defendant knew of disqualifying status. Constructive and joint possession both cognizable. Expunged state convictions may still qualify under § 922(g).'),
  ('weapons-trafficking', 'federal', '18 U.S.C. §§ 922(a), 933', 'Illegal Firearms Trafficking / Dealing Without License', 'Federal Felony', NULL, '5 years (unlicensed dealing); 15 years (firearms trafficking under § 933)', '$250,000', '{"Defendant engaged in the business of dealing firearms","Without a Federal Firearms License (FFL)","OR transferred firearms to prohibited persons (straw purchases, § 932)","OR transported or received firearms with intent to transfer to prohibited persons","Knowledge or willfulness requirement depending on subsection"}', NULL, '{"USSG § 2K2.1(b)(5): +4 levels for trafficking 3+ firearms","§ 2K2.1(b)(6): +4 levels if firearm used/intended for another felony","Stolen firearms: +2 levels (§ 2K2.1(b)(4))","§ 933 firearms trafficking (Bipartisan Safer Communities Act 2022): up to 15 years","§ 932 straw purchasing: up to 15 years","Number of firearms directly affects offense level"}', 'Bipartisan Safer Communities Act (2022) added § 932 (straw purchasing) and § 933 (firearms trafficking) as standalone felonies. Ghost guns (unserialized) increasingly charged. ATF Form 4473 false statements: § 922(a)(6), up to 10 years.'),
  ('child-exploitation', 'federal', '18 U.S.C. § 2252', 'Certain Activities Relating to Material Involving Sexual Exploitation of Minors', 'Federal Felony', '5 years (possession first offense); 10 years (distribution/receipt first offense)', '20 years (possession); 20 years (distribution/receipt); 40 years (repeat offender)', '$250,000', '{"Defendant knowingly transported, shipped, received, distributed, reproduced, or possessed","Visual depiction","Depicting a minor (under 18) engaged in sexually explicit conduct","Using any means or facility of interstate or foreign commerce, or affecting interstate commerce","Defendant knew the material contained a visual depiction of a minor in sexually explicit conduct"}', '5 years (possession); 10 years (production under § 2251); 15 years (distribution with prior)', '{"§ 2252A covers child pornography involving digital/computer content","USSG § 2G2.2: numerous specific offense characteristics","Sadomasochistic or infant images: +4 levels","Distribution for value: +5 levels","Images depicting violence: +4 levels","Pattern of sexual abuse: +5 levels","Use of computer: +2 levels","100-999 images: +2; 300-599: +3; 600+: +4 levels","Sex Offender Registration (SORNA) mandatory — lifetime in many states"}', '§ 2252A is the broader provision covering digital content. Production under § 2251 carries mandatory 15-30 year minimums. PROTECT Act (2003) eliminated certain defenses. Affirmative defense available for possessors who promptly reported to law enforcement.'),
  ('sex-offense-digital', 'federal', '18 U.S.C. § 2422', 'Coercion and Enticement of Minors', 'Federal Felony', '10 years', 'Life imprisonment', '$250,000', '{"Defendant knowingly persuaded, induced, enticed, or coerced","A minor (under 18) to engage in any sexual activity","Using the mail, any facility of interstate or foreign commerce, or any means or facility of interstate commerce","The sexual activity would constitute a criminal offense under federal, state, or local law"}', '10 years', '{"§ 2422(b) attempt: same 10-year mandatory minimum applies","USSG § 2G1.3: prior sex offense conviction, use of computer, vulnerable victim","Use of computer or internet: +2 levels","Unduly influencing minor: +2 levels","Pattern of activity: +5 levels","Sex Offender Registration (SORNA) mandatory","Often charged alongside § 2252 (child pornography) and § 2423 (travel with intent)"}', '§ 2422(b) (inducing minor via internet) is the primary online enticement statute. Government need not prove actual minor involved — adult decoy in sting operation sufficient. Travel to commit sexual act with minor charged under § 2423.'),
  ('drug-trafficking', 'federal', '21 U.S.C. § 841(b)', 'Controlled Substance Trafficking — Penalty Provisions', 'Federal Felony', '5 years (threshold quantities)', 'Life imprisonment (large quantities or death results)', '$10,000,000 individual / $50,000,000 organization', '{"Defendant knowingly or intentionally distributed, dispensed, or possessed with intent to distribute","A controlled substance","Quantity meets or exceeds the threshold for enhanced penalties","Type of controlled substance as alleged"}', '5 years for Schedule I/II threshold quantities; 10 years for high-quantity thresholds (e.g., 5kg+ cocaine, 280g+ crack, 1kg+ heroin, 5g+ pure meth, 1000kg+ marijuana)', '{"Prior felony drug conviction (§ 851 notice): doubles mandatory minimums","Two or more prior felony drug convictions: mandatory life","Death or serious bodily injury results: 20-year mandatory minimum","Drug kingpin (§ 848 CCE): 20 years to life, $4M fine","§ 924(c) firearm: consecutive 5-10 years","School zone (§ 860): doubles penalties","Importation: additional penalties under § 952","Leader/organizer: +4 levels (USSG § 3B1.1)"}', 'Drug type and quantity are elements under Apprendi/Alleyne — must be submitted to jury and proven beyond reasonable doubt. Safety valve (USSG § 5C1.2) available only for first-time, nonviolent offenders with limited criminal history who cooperate. Fentanyl enhancements significantly increased post-2018.'),
  ('drug-possession', 'federal', '21 U.S.C. § 844', 'Simple Possession of Controlled Substance', 'Federal Misdemeanor (first offense) / Federal Felony (repeat)', NULL, '1 year (first offense misdemeanor); 2 years (if prior drug offense); up to 3 years for cocaine base', '$1,000 (individual first offense) to $5,000', '{"Defendant knowingly or intentionally possessed","A controlled substance","Without a valid prescription or legal authorization"}', NULL, '{"Prior drug conviction: elevated to felony with 2-year maximum","Two+ prior drug convictions: 3-year maximum","Special cocaine base provision: up to 3 years regardless of prior history","USSG § 2D2.1: base level 4-8 depending on substance","Deferred prosecution/diversion available for first offenders (§ 844(b))"}', 'First Offense Act (§ 3607) allows probation and expungement for first offenders. Federal simple possession charges are relatively rare — most federal drug cases involve trafficking. The FIRST STEP Act (2018) reduced sentencing disparities for crack cocaine.'),
  ('drug-manufacturing', 'federal', '21 U.S.C. § 841(a)(1)', 'Manufacture of Controlled Substance', 'Federal Felony', '5 years if threshold quantity involved', 'Life imprisonment for large quantities', '$10,000,000 individual', '{"Defendant knowingly or intentionally manufactured","A controlled substance","The type and quantity alleged in the indictment"}', 'Same as distribution: 5 years for threshold quantities under § 841(b)(1)(A) and (B)', '{"Methamphetamine lab: chemical disposal costs recoverable","Endangering human life while manufacturing: additional 10 years (§ 858)","Manufacturing near schools or playgrounds: doubles penalties (§ 860)","§ 924(c) if firearm present at manufacturing site","Precursor chemical offenses under §§ 841(c), 843"}', 'Manufacture, distribute, and possess-with-intent all charge under § 841(a)(1) — penalties identical. Precursor chemical tracking under Combat Methamphetamine Epidemic Act (2005). ''Manufacturing'' includes producing, preparing, propagating, and processing.'),
  ('drug-possession-with-intent', 'federal', '21 U.S.C. § 841(a)(1)', 'Possession with Intent to Distribute Controlled Substance', 'Federal Felony', '5 years for threshold quantities', 'Life imprisonment for large quantities or repeat offenders', '$10,000,000 individual', '{"Defendant knowingly or intentionally possessed","A controlled substance","With intent to distribute it","Type and quantity of substance as alleged"}', 'Same mandatory minimums as distribution: 5-10 years depending on drug type and quantity', '{"§ 851 prior conviction notice doubles mandatory minimum","§ 924(c) if firearm present: consecutive 5-10 years","Drug quantity above thresholds triggers § 841(b)(1)(A) or (B) enhancements","Multiple packaging consistent with distribution: circumstantial evidence of intent","Scales, cutting agents, large cash: used to prove intent","Safety valve: available for qualifying first offenders"}', 'Intent to distribute proven circumstantially through quantity, packaging, scales, ledgers, communications, and cash. Constructive possession sufficient. Drug type and quantity must be charged in indictment and proven to jury under Apprendi. Often charged alongside § 846 conspiracy.'),
  ('kidnapping', 'federal', '18 U.S.C. § 1201', 'Kidnapping (Federal)', 'Federal Felony', '20 years if victim under 18 and not parent', 'Life imprisonment; death if victim dies', '$250,000', '{"Defendant unlawfully seized, confined, inveigled, decoyed, kidnapped, abducted, or carried away","Another person","Held for ransom, reward, or otherwise","Using interstate or foreign commerce, or the victim was transported across state lines or international borders, OR defendant is a federal employee/official, OR victim is a federal employee/official"}', '20 years if victim is under 18 and perpetrator is not the parent', '{"Death results: life imprisonment or death penalty","Victim under 18: 20-year mandatory minimum","Sexual abuse of victim during kidnapping: additional charges and enhancements","Use of firearm: § 924(c) consecutive term","USSG § 2A4.1: starts at level 32 with numerous specific offense characteristics"}', 'Federal jurisdiction triggered by interstate transportation OR 24-hour presumption (Lindbergh Law). Parental kidnapping is a separate offense under § 1204. Hostage taking (§ 1203) and carjacking (§ 2119) are related charges. FBI has primary jurisdiction.'),
  ('arson', 'federal', '18 U.S.C. § 844(f),(h),(i)', 'Federal Arson', 'Federal Felony', '5 years (§ 844(f)); 7 years minimum for § 844(h) (using fire in violent crime)', '20 years; 40 years if serious bodily injury; life if death results', '$250,000', '{"§ 844(f): Maliciously damaged or destroyed by fire or explosive any building or property owned/possessed/used by the U.S. government or a federally-funded organization","§ 844(i): Maliciously damaged or destroyed, or attempted to damage or destroy, by means of fire or explosives, any building or property used in interstate commerce or in activity affecting interstate commerce","Defendant acted with malice (intentionally or recklessly)"}', '5 years (§ 844(f) government property); 7 years consecutive (§ 844(h) use of fire to commit felony)', '{"§ 844(h): using fire or explosive to commit any federal felony: additional 10 years consecutive","Serious bodily injury results: 7-40 years","Death results: 20 years to life","§ 844(o): civil rights arson (church burning): enhanced penalties","USSG § 2K1.4: base level varies 2-24 based on circumstances"}', '§ 844(i) has broad interstate commerce nexus — virtually any commercial building qualifies (Russell v. United States). § 844(h) consecutive term for using fire/explosive to commit another federal felony creates powerful prosecutorial leverage. State arson charges often run parallel.'),
  ('robbery', 'federal', '18 U.S.C. § 1951', 'Interference with Commerce by Robbery (Hobbs Act Robbery)', 'Federal Felony', NULL, '20 years imprisonment', '$250,000', '{"Defendant obstructed, delayed, or affected commerce","By robbery or extortion, or attempted or conspired to do so","Robbery: unlawful taking or obtaining of property from person or presence of another by actual or threatened force, violence, or fear of injury","The robbery had at least a de minimis effect on interstate commerce"}', NULL, '{"§ 924(c): 7 years consecutive if firearm brandished; 10 years if discharged","§ 924(c) second count: mandatory 25 years consecutive","USSG § 2B3.1: robbery base level 20 with numerous enhancements","Injury to victim: +2 to +6 levels","Carjacking (§ 2119): 15-25 years minimum if death results","Bank robbery (§ 2113): separate statute, up to 20 years"}', 'De minimis commerce nexus required — courts have found nexus from a single convenience store robbery. Hobbs Act extortion and robbery are distinct theories under § 1951. § 924(c) stacking with Hobbs Act robberies is a major sentencing driver.'),
  ('identity-theft', 'federal', '18 U.S.C. § 1028A', 'Aggravated Identity Theft', 'Federal Felony', '2 years consecutive (general offenses); 5 years consecutive (terrorism-related offenses)', '2 years consecutive (added to underlying offense); 5 years consecutive for terrorism', '$250,000', '{"Defendant knowingly transferred, possessed, or used","Without lawful authority","A means of identification of another person","During and in relation to a predicate felony enumerated in § 1028A(c)"}', '2 years consecutive to any other term of imprisonment', '{"Sentence CANNOT run concurrently — always 2 years consecutive (Flores-Figueroa v. United States, 2009)","Multiple counts: each use of different victims'' identity is a separate count","§ 1028 (identity document fraud): up to 15 years for underlying identity document crime","USSG § 2B1.6: offense level = level from underlying predicate offense","Terrorism-related: 5 years consecutive"}', 'Flores-Figueroa v. United States (2009): government must prove defendant knew the means of identification belonged to a real, actual person. § 1028A(c) lists over 50 predicate offenses. Restitution to victims mandatory. Distinct from § 1028 (fraud related to identity documents).'),
  ('counterfeiting', 'federal', '18 U.S.C. § 471', 'Counterfeiting Obligations or Securities of the United States', 'Federal Felony', NULL, '20 years imprisonment', '$250,000', '{"Defendant falsely made, forged, counterfeited, or altered","Any obligation or other security of the United States","With intent to defraud"}', NULL, '{"§ 472: passing/uttering counterfeit obligations: up to 20 years","§ 473: dealing in counterfeit obligations: up to 20 years","§ 474: plates/stones used for counterfeiting: up to 25 years","USSG § 2B5.1: counterfeit value determines offense level","Secret Service has primary investigative jurisdiction"}', 'Covers currency, bonds, Treasury securities, postage stamps, and other government obligations. § 510 covers counterfeit U.S. government checks. Counterfeit access devices (credit cards): § 1029. Secret Service and Treasury have primary jurisdiction.'),
  ('obstruction-justice', 'federal', '18 U.S.C. § 1503', 'Influencing or Injuring Officer or Juror Generally (Obstruction of Justice)', 'Federal Felony', NULL, '10 years imprisonment; life if obstruction related to murder or attempted murder', '$250,000', '{"There was a pending federal judicial proceeding","Defendant knew of the proceeding","Defendant corruptly endeavored to influence, obstruct, or impede the due administration of justice"}', NULL, '{"§ 1512 (tampering with witnesses): up to 30 years if involving killing/attempted killing","§ 1519 (destruction of records): up to 20 years — covers document shredding during investigation","§ 1001 (false statements to federal agents): up to 5 years","USSG § 3C1.1: +2 levels for obstruction of this case being sentenced","§ 1512(c)(2): broader corrupt obstruction provision","Martha Stewart rule: lying to federal investigators is a separate federal crime under § 1001"}', 'Omnibus clause of § 1503 broadly covers corrupt influence of any judicial proceeding. § 1519 (Sarbanes-Oxley) covers document destruction even before formal proceedings begin. Each obstructive act can be a separate count.'),
  ('supervised-release-violation', 'federal', '18 U.S.C. § 3583(e)', 'Supervised Release Violation', 'Federal (administrative hearing, results in imprisonment)', NULL, 'Revocation: Class A felony: up to 5 years; Class B: up to 3 years; Class C/D: up to 2 years; Class E/misdemeanor: up to 1 year', NULL, '{"Defendant was serving a term of supervised release","Defendant violated a condition of supervised release","Violation proven by preponderance of the evidence (not beyond reasonable doubt)","Court determines appropriate response: modification, continued supervision, or revocation"}', NULL, '{"Mandatory revocation for: possession of controlled substance, possession of dangerous weapon, new felony conviction","Grade A violation (new felony with 1+ year sentence): revocation mandatory","Grade B violation (other new felony or high-level misdemeanor): court discretion","Grade C violation (low-level misdemeanor or technical): modification usually preferred","Prior revocations: USSG Chapter 7 increases revocation sentence","New federal crime during supervision: prosecution for new offense PLUS revocation"}', 'Supervised release imposed at sentencing under § 3583(a) — mandatory for felonies. Violation hearings under Fed. R. Crim. P. 32.1 — lower burden than trial. USSG Chapter 7 provides policy statements (not binding guidelines). Modification, termination, or revocation are all options.'),
  ('contempt-of-court', 'federal', '18 U.S.C. § 401', 'Power of Court — Contempt', 'Federal (summary or criminal contempt — no fixed offense class)', NULL, 'No statutory maximum for criminal contempt (judge''s discretion); 6 months for petty contempt', 'Court''s discretion', '{"A lawful court order existed","Defendant had knowledge of the order","Defendant willfully violated or disobeyed the order, or misbehaved in presence of court, or disobeyed process"}', NULL, '{"Civil contempt: coercive (continues until compliance) — different from criminal contempt","Criminal contempt: punitive (fixed punishment for past violation)","Summary contempt (§ 401(1)): immediate for in-court behavior","Indirect contempt requires notice and hearing (Fed. R. Crim. P. 42)","Jury trial right for sentences of 6+ months"}', '§ 401 governs criminal contempt of federal court. Civil contempt is not § 401 — it is coercive via court''s equitable power. Failure to comply with grand jury subpoena charged as contempt. § 401 sentences run independently from other criminal sentences.'),
  ('possession-prohibited-weapon', 'federal', '26 U.S.C. § 5861', 'Prohibited Acts — National Firearms Act (NFA) Violations', 'Federal Felony', NULL, '10 years imprisonment', '$250,000', '{"Defendant possessed, transferred, or made","A firearm as defined under the National Firearms Act (machine gun, silencer/suppressor, short-barreled rifle/shotgun, destructive device, ''any other weapon'')","Without proper NFA registration or in violation of NFA tax requirements","The NFA requires a $200 tax, registration, and ATF approval for all NFA items"}', NULL, '{"§ 924(c): additional consecutive sentence if NFA weapon used in crime of violence or drug trafficking","USSG § 2K2.1: higher base offense level for NFA weapons (level 18 for silencer/machine gun)","Machine gun conversion: automatic weapon conversion device carries same penalties","§ 922(o): separate prohibition on machine gun transfers/possession","Criminal forfeiture of any property used to facilitate offense"}', 'NFA (26 U.S.C. § 5801 et seq.) regulates machine guns, suppressors, short-barreled rifles (barrel under 16 inches), short-barreled shotguns (barrel under 18 inches), destructive devices, and ''any other weapons.'' Garland v. Cargill (2024): bump stocks are NOT machine guns. Glock auto switches (machine gun conversion devices) are a major enforcement priority.'),
  ('healthcare-fraud', 'federal', '18 U.S.C. § 1347', 'Healthcare Fraud', 'Federal Felony', NULL, '10 years; 20 years if serious bodily injury results; life or death penalty if death results', '$250,000 individual / $500,000 organization', '{"Defendant knowingly and willfully executed or attempted to execute a scheme or artifice","To defraud any healthcare benefit program","OR to obtain money or property from a healthcare benefit program by false or fraudulent pretenses, representations, or promises","In connection with the delivery of or payment for healthcare benefits, items, or services"}', NULL, '{"Anti-Kickback Statute (42 U.S.C. § 1320a-7b): up to 10 years for kickbacks for Medicare/Medicaid referrals","False Claims Act civil liability: treble damages plus $15,000+ per claim","USSG § 2B1.1: loss amount drives offense level","OIG mandatory exclusion from federal healthcare programs","Often charged alongside wire fraud (§ 1343) and money laundering (§ 1956)"}', 'False billing, upcoding, unbundling, phantom billing, kickbacks for referrals, and unnecessary procedures all qualify. HHS-OIG/FBI/DOJ Medicare Fraud Strike Force actively prosecutes.'),
  ('false-statement', 'federal', '18 U.S.C. § 1001', 'False Statements to Federal Officials', 'Federal Felony', NULL, '5 years imprisonment (general); 8 years if related to terrorism or sex offense', '$250,000', '{"Defendant made a false statement, representation, or certification","OR concealed or covered up a material fact","In a matter within the jurisdiction of any branch of the U.S. government","The statement was material (capable of influencing the government''s action)","Defendant acted knowingly and willfully"}', NULL, '{"Terrorism connection: 8-year maximum","Often charged alongside conspiracy (§ 371) for making false statements in furtherance of scheme","USSG § 3C1.1 obstruction enhancement may apply to underlying offense","Each individual false statement may be charged as a separate count"}', 'Brogan v. United States (1998): no ''exculpatory no'' doctrine — simple denial to federal agent is a federal crime. No requirement that government be actually deceived. Covers false statements to any agency (FBI, IRS, DHS, EPA, etc.). Famous use: Martha Stewart, Michael Flynn, Roger Stone prosecutions.'),
  ('perjury', 'federal', '18 U.S.C. § 1621', 'Perjury', 'Federal Felony', NULL, '5 years imprisonment', '$250,000', '{"Defendant took an oath to testify truthfully before a competent tribunal or officer","Defendant willfully stated as true something they believed to be false","The false statement was material to the proceeding"}', NULL, '{"§ 1623 (false declarations before grand jury/court): same penalty, but two-witness rule does not apply","§ 1622 (subornation of perjury): inducing another to commit perjury: same 5-year maximum","Often charged alongside obstruction of justice (§ 1503) and false statements (§ 1001)","USSG § 2J1.3: base level 14 for perjury","Recantation defense: § 1623(d) — false statement retracted before it substantially affects the proceeding"}', 'Two-witness rule under § 1621: the falsity must be proven by two witnesses or one witness plus corroborating evidence. § 1623 eliminates the two-witness rule. Materiality is an element under United States v. Gaudin (1995) — must go to jury.'),
  ('bribery', 'federal', '18 U.S.C. § 201', 'Bribery of Public Officials', 'Federal Felony', NULL, '15 years imprisonment (bribery); 2 years (illegal gratuity)', 'Three times the monetary equivalent of the thing of value / $250,000', '{"§ 201(b) Bribery: Defendant directly or indirectly gave, offered, or promised a thing of value","To a public official (or one selected to be an official)","With intent to influence an official act, cause the official to act contrary to duty, or induce the official to commit fraud on the United States","§ 201(c) Illegal Gratuity: Thing of value given for or because of official act (no quid pro quo required)"}', NULL, '{"USSG § 2C1.1: offense level 12 base; numerous enhancements for value of bribes, role","More than one bribe: +2 levels","High-level official: +4 levels","Honest services fraud (§ 1346) commonly charged alongside § 201","Hobbs Act extortion (§ 1951) for extortion under color of official right","Forfeiture of bribe proceeds mandatory"}', 'McDonnell v. United States (2016) narrowed ''official act'' — must be formal exercise of official power, not mere meetings or calls. Federal program bribery under § 666 covers recipients of $10K+ in federal funds. Foreign Corrupt Practices Act (15 U.S.C. § 78dd-1) covers bribing foreign officials.'),
  ('extortion', 'federal', '18 U.S.C. § 875 / § 1951', 'Interstate Extortion / Hobbs Act Extortion', 'Federal Felony', NULL, '2 years (§ 875 threatening communications); 20 years (Hobbs Act § 1951)', '$250,000', '{"§ 875: Defendant transmitted in interstate commerce a communication containing a threat to kidnap, injure, or demand ransom, with intent to extort money or valuable consideration","§ 1951 (Hobbs Act): Defendant induced victim to part with property","Using actual or threatened force, violence, fear of injury, OR under color of official right","Affecting interstate commerce"}', NULL, '{"§ 879: threatening the President/Vice President: up to 5 years","Hobbs Act conspiracy (§ 1951(a)): same 20-year maximum","USSG § 2B3.2: base level 18 for extortion; numerous victim harm enhancements","§ 924(c) if firearm involved in Hobbs Act","Often charged with wire fraud when electronic communications used"}', 'Hobbs Act extortion under color of official right is the primary mechanism for prosecuting public corruption involving payment demands. § 875 targets threatening communications including email and social media.'),
  ('cybercrime', 'federal', '18 U.S.C. § 1030', 'Computer Fraud and Abuse Act (CFAA)', 'Federal Felony / Misdemeanor', NULL, '1 year (simple unauthorized access misdemeanor); 5 years (first felony offense); 10 years (second offense); 20 years if reckless damage; life if death results', '$250,000', '{"Defendant intentionally or knowingly accessed a protected computer","Without authorization OR exceeding authorized access","With intent to defraud, obtain information, cause damage, or extort (depending on subsection charged)","Protected computer: any computer used in interstate commerce, connected to internet, or used by U.S. government/financial institution"}', NULL, '{"National security or government computers: enhanced penalties","Financial damage exceeding $5,000 triggers felony threshold","Conspiracy under § 1030(b): same penalties as underlying offense","USSG § 2B1.1 or § 2M3.2 depending on computer type accessed","Civil cause of action under § 1030(g) for victims"}', 'Van Buren v. United States (2021) narrowly construed ''exceeds authorized access.'' § 1030(a)(2) (obtaining information), § 1030(a)(4) (fraud), § 1030(a)(5) (damage) are most common. Ransomware attacks prosecuted under § 1030.'),
  ('human-trafficking', 'federal', '18 U.S.C. § 1591', 'Sex Trafficking of Children or by Force, Fraud, or Coercion', 'Federal Felony', '10 years; 15 years if victim 14-17; mandatory life if victim under 14', 'Life imprisonment', '$250,000 or more', '{"Defendant knowingly recruited, enticed, harbored, transported, provided, obtained, advertised, maintained, patronized, or solicited","Another person","Knowing or in reckless disregard of the fact that the person would be caused to engage in a commercial sex act","By force, fraud, or coercion, OR victim was under 18 years of age"}', '10 years (adult victim); 15 years (victim 14-17); life (victim under 14)', '{"§ 1589 (forced labor trafficking): up to 20 years; life if death or kidnapping occurs","§ 1592 (document servitude): up to 5 years","TVPA civil cause of action for victims (§ 1595)","Restitution mandatory to all victims","SORNA sex offender registration for sex trafficking convictions","USSG § 2G1.1: offense level 34 base for sex trafficking"}', 'Trafficking Victims Protection Act (TVPA). Strict liability as to victim''s age if victim is under 18. FOSTA-SESTA (2018) added § 2421A prohibiting internet promotion of prostitution.'),
  ('carjacking', 'federal', '18 U.S.C. § 2119', 'Motor Vehicle Theft (Carjacking)', 'Federal Felony', NULL, '15 years; 25 years if serious bodily injury; life or death if death results or kidnapping occurs', '$250,000', '{"Defendant took a motor vehicle","From the person or presence of another person","By force and violence or by intimidation","With intent to cause death or serious bodily harm","The motor vehicle had been transported, shipped, or received in interstate commerce"}', NULL, '{"§ 924(c) firearm: additional 7 years consecutive if firearm brandished","§ 924(c): 10 years consecutive if firearm discharged","Serious bodily injury to victim: up to 25 years","Death or kidnapping: life or death penalty","USSG § 2B3.1: base level 20 with carjacking-specific enhancements","Injury enhancements: +1 to +6 levels depending on severity"}', 'Federal jurisdiction requires the vehicle to have moved in interstate commerce (virtually all modern vehicles qualify). Holloway v. United States (1999): conditional intent to use force if victim resists satisfies the intent element. Often charged alongside § 924(c) for armed carjacking.'),
  ('drug-conspiracy', 'federal', '21 U.S.C. § 846', 'Attempt and Conspiracy to Distribute Controlled Substances', 'Federal Felony', 'Same as underlying completed offense', 'Same maximum as underlying completed offense under § 841', 'Same as underlying completed offense', '{"Agreement between two or more persons to violate federal drug laws","Defendant knowingly and voluntarily joined the conspiracy","NOTE: No overt act required for drug conspiracies (unlike general conspiracy under § 371)"}', 'Same mandatory minimums as substantive offense (5-10 years for threshold quantities)', '{"§ 851 prior drug conviction: doubles mandatory minimums","Same enhancements as § 841(b) apply based on drug type and quantity","Leader/organizer of conspiracy: +4 levels","Pinkerton liability: co-conspirators liable for foreseeable acts of other members","Safety valve: available for qualifying first-time offenders","Continuing criminal enterprise (§ 848): 20 years to life if supervisor of 5+ persons"}', 'Unlike § 371 (general conspiracy), § 846 does not require an overt act — the agreement itself is the crime. Drug quantity attributed based on reasonably foreseeable quantities handled by entire conspiracy (USSG § 1B1.3). Withdrawal defense: must take affirmative steps to withdraw and communicate to co-conspirators before arrest.'),
  ('environmental-crime', 'federal', '33 U.S.C. § 1319 / 42 U.S.C. § 6928', 'Clean Water Act / RCRA Criminal Violations', 'Federal Felony / Misdemeanor', NULL, '3-6 years (negligent violations); 3-15 years (knowing violations); 15-35 years (knowing endangerment)', '$10,000 to $50,000 per day of violation; $250,000 individual / $1,000,000 organization', '{"Defendant discharged pollutants into waters of the U.S. (CWA) OR disposed of hazardous waste (RCRA)","Without a permit or in violation of a permit","Negligently, knowingly, or with knowing endangerment","The substance qualifies as a pollutant or regulated hazardous waste"}', NULL, '{"Knowing endangerment: highest tier, up to 15 years under CWA","Second offense: doubled penalties","False statements in permit applications: § 1001 charges","Civil EPA penalties run parallel to criminal prosecution","Responsible corporate officer doctrine: executives personally liable without direct knowledge","USSG § 2Q1.2 (hazardous waste) and § 2Q1.3 (environmental permitting)"}', 'Responsible Corporate Officer (RCO) doctrine (United States v. Park, 1975): executives can be convicted without proof of direct involvement if they had authority to prevent violations. Clean Air Act (42 U.S.C. § 7413) and CERCLA have parallel criminal provisions.'),
  ('public-corruption', 'federal', '18 U.S.C. § 666', 'Theft or Bribery Concerning Programs Receiving Federal Funds', 'Federal Felony', NULL, '10 years imprisonment', '$250,000', '{"Agent of an organization or state/local government receiving more than $10,000 in federal benefits in a one-year period","Defendant embezzled, stole, or obtained by fraud $5,000 or more in property","OR defendant intentionally misapplied $5,000 or more of funds of the organization","OR defendant corruptly solicited/accepted something of value intending to be influenced in connection with a transaction worth $5,000 or more"}', NULL, '{"Often charged alongside honest services fraud (§ 1346 / §§ 1341/1343)","§ 201 federal bribery charges may be added if federal official","USSG § 2C1.1: offense level based on value of bribes/misappropriated funds","Fiduciary/position of trust enhancement: +2 levels","Forfeiture of proceeds"}', 'Extremely broad — covers virtually all state and local government officials due to federal grant funding. Salinas v. United States (1997): § 666 does not require proof of connection between bribe and federal funds. Often paired with honest services wire/mail fraud in public corruption cases.'),
  ('mortgage-fraud', 'federal', '18 U.S.C. § 1344 / § 1014', 'Mortgage Fraud / False Statements to Financial Institution', 'Federal Felony', NULL, '30 years (§ 1344 bank fraud); 30 years (§ 1014 false statements to FDIC-insured institution)', '$1,000,000', '{"§ 1014: Defendant knowingly made a false statement or report for the purpose of influencing the action of any federally insured financial institution","In connection with a loan, credit, or other extension of credit","§ 1344: Defendant executed or attempted to execute a scheme to defraud or obtain money from a federally insured financial institution under false pretenses"}', NULL, '{"Often charged in conjunction with wire fraud (§ 1343) and mail fraud (§ 1341)","Aggravated identity theft (§ 1028A): additional 2 years consecutive","Money laundering (§ 1956) charges if proceeds concealed","USSG § 2B1.1: loss amount drives offense level","Financial industry insider: potential abuse of trust enhancement"}', 'FBI and HUD-OIG have primary jurisdiction. Mortgage fraud includes straw buyer schemes, appraisal fraud, loan application fraud, property flipping with inflated appraisals, and builder bailout schemes. 10-year statute of limitations. Restitution to lenders mandatory.'),
  ('embezzlement', 'federal', '18 U.S.C. § 666 / § 641', 'Embezzlement of Government Funds / Theft of Federal Property', 'Federal Felony', NULL, '10 years (§ 666 federal program funds); 10 years (§ 641 property over $1,000); 1 year (§ 641 property under $1,000)', '$250,000', '{"§ 641: Defendant embezzled, stole, purloined, or knowingly converted to their use","Money, property, or records belonging to the United States or any U.S. agency","OR received, concealed, or retained such property knowing it to be stolen","Value of property determines felony/misdemeanor classification"}', NULL, '{"§ 666: federal program funds over $5,000 in organizations receiving $10,000+ federal funds","Position of trust: +2 levels (USSG § 3B1.3)","Amount stolen drives offense level under USSG § 2B1.1","Restitution mandatory","Often charged alongside money laundering when proceeds laundered"}', '§ 641 covers theft of any federal government property. § 666 covers embezzlement from any organization receiving federal funding (states, cities, universities, nonprofits). Bank employee embezzlement: § 656 (up to 30 years for federally insured institution).'),
  ('witness-tampering', 'federal', '18 U.S.C. § 1512', 'Tampering with a Witness, Victim, or Informant', 'Federal Felony', NULL, '30 years (if killing or attempting to kill witness); 20 years (if using force/threats); 10 years (if harassing or intimidating); 3 years (corrupt persuasion)', '$250,000', '{"Defendant knowingly used intimidation, threats, corrupt persuasion, or misleading conduct","Toward another person","With intent to influence, delay, or prevent the testimony of the person in an official proceeding","OR with intent to cause the person to withhold testimony, records, or documents"}', NULL, '{"§ 1512(a): killing or attempting to kill to prevent testimony: up to 30 years","§ 1512(b): threats and corrupt persuasion: up to 20 years","§ 1512(c)(2): corrupt obstruction of official proceeding (broad): up to 20 years","§ 1513 (retaliating against witness): additional charges, up to 30 years if killing","USSG § 3C1.1: +2 levels for obstruction in current case","No requirement that official proceeding be pending — ''contemplated'' proceedings covered"}', '§ 1512(c)(2) was used in January 6 prosecutions. United States v. Fischer (2024) narrowed § 1512(c)(2) to require evidence impairment. § 1512 has no pending proceeding requirement — covers actions taken before any formal proceeding begins.'),
  ('drug-import-export', 'federal', '21 U.S.C. § 952 / § 960', 'Importation / Exportation of Controlled Substances', 'Federal Felony', '5 years for threshold quantities; 10 years for higher quantities', 'Life imprisonment for large quantities', '$10,000,000 individual', '{"Defendant knowingly or intentionally imported or exported","A controlled substance","Into or out of the United States","Without legal authorization","Drug type and quantity as alleged"}', 'Same tiered structure as § 841(b): 5 years for threshold quantities, 10 years for higher quantities', '{"§ 851 prior drug conviction doubles mandatory minimum","Death or serious bodily injury: 20-year mandatory minimum","§ 963 conspiracy to import/export: same penalties as underlying offense","Organizational leaders: +4 levels","§ 960a: drug offenses benefiting terrorist organizations: 20 years to life"}', 'DEA and CBP have joint jurisdiction. § 963 drug importation conspiracy does not require an overt act. Fentanyl importation is a top enforcement priority. Constructive importation when defendant knew contraband was in shipment they controlled.'),
  ('money-laundering-conspiracy', 'federal', '18 U.S.C. § 1956(h)', 'Conspiracy to Launder Money', 'Federal Felony', NULL, '20 years imprisonment', '$500,000 or twice the amount laundered, whichever is greater', '{"Agreement between two or more persons to commit money laundering under §§ 1956 or 1957","Defendant knowingly and intentionally joined the conspiracy","NOTE: No overt act required for § 1956(h) money laundering conspiracy"}', NULL, '{"No overt act required — the agreement itself constitutes the offense","USSG § 2S1.1: same as substantive money laundering; +2 levels for § 1956 conviction","Underlying specified unlawful activity drives base offense level","Forfeiture of all funds involved in the conspiracy","Often charged with underlying predicate crimes (drug trafficking, fraud, etc.)"}', '§ 1956(h) conspiracy does not require an overt act — broader than § 371 conspiracy. Enormously powerful because it sweeps in financial institutions and their employees. Kingpin-style prosecutions routinely add § 1956(h) alongside § 846 drug conspiracy. Statute of limitations: 5 years.'),
  ('federal-other', 'federal', 'Various', 'Other Federal Offenses', 'Federal Felony or Misdemeanor', NULL, 'Varies by statute', 'Varies by statute', '{"Varies by specific charge","Must be a federal crime with a federal nexus (interstate commerce, federal property, federal official, etc.)"}', NULL, '{"Varies by specific offense","U.S. Sentencing Guidelines apply to all federal felony and Class A misdemeanor offenses","Recidivism enhancements under USSG Chapter 4","Role in offense adjustments under USSG Chapter 3B"}', 'Catch-all category for federal offenses not listed above. Common examples: Title 18 civil rights violations (§ 241, § 242), Espionage Act (§ 793), Foreign Agents Registration Act (§ 612), election interference offenses (§ 594-611), food and drug misbranding (21 U.S.C. § 333), bankruptcy fraud (§ 157), market manipulation. Consult federal statutory index for specific statutes.')
